function normalizeRealjejuNonnegativeCount(value)
{
	const count = Number(value);
	return Number.isFinite(count) ? Math.max(0, Math.trunc(count)) : 0;
}

const globalBrandLink = document.querySelector('.global-brand');
if (globalBrandLink) {
	globalBrandLink.addEventListener('click', (event) => {
		event.preventDefault();
		if (/^https?:$/.test(window.location.protocol)
			&& window.realjejuRouter
			&& typeof window.realjejuRouter.navigate === "function") {
			window.realjejuRouter.navigate("/?landing=1");
			return;
		}
		const landingUrl = new URL(window.location.href);
		if (/^https?:$/.test(window.location.protocol)) landingUrl.pathname = "/";
		landingUrl.search = "?landing=1";
		landingUrl.hash = "";
		window.location.assign(landingUrl.href);
	});
}

/* PC 부동산 홈·필지분석·동네업체·전기차의 왼쪽 메뉴를 같은 컨트롤로 접고 펼친다. */
(function initDesktopSideNavToggle()
{
	const button = document.getElementById("realjejuSideNavToggle");
	const storageKey = "realjeju.desktopSideNavCollapsed.v1";
	const desktopQuery = window.matchMedia("(min-width: 901px)");
	let relayoutTimer = 0;

	function isCollapsed()
	{
		return !!document.body?.classList.contains("realjeju-side-nav-collapsed");
	}

	function canShowSideNavToggle(category)
	{
		const nextCategory = String(category || "").trim();
		return nextCategory === "realestate"
			|| nextCategory === "parcel"
			|| nextCategory === "local-business"
			|| nextCategory === "ev-charger";
	}

	function shouldShowSideNavToggle()
	{
		return desktopQuery.matches
			&& canShowSideNavToggle(document.body?.dataset?.globalCategory);
	}

	function syncButton()
	{
		if (!button) return;
		const shouldShow = shouldShowSideNavToggle();
		button.hidden = !shouldShow;
		if (!shouldShow) return;
		const collapsed = isCollapsed();
		const icon = button.querySelector("i");
		const label = button.querySelector("span");
		button.setAttribute("aria-expanded", collapsed ? "false" : "true");
		button.setAttribute("aria-label", collapsed ? "왼쪽 메뉴 펴기" : "왼쪽 메뉴 접기");
		if (icon) {
			icon.classList.toggle("fa-chevron-left", !collapsed);
			icon.classList.toggle("fa-chevron-right", collapsed);
		}
		if (label) label.textContent = collapsed ? "펴기" : "접기";
	}

	function persist(collapsed)
	{
		try {
			window.localStorage.setItem(storageKey, collapsed ? "1" : "0");
		} catch (error) {}
	}

	function scheduleSingleMapRelayout()
	{
		window.clearTimeout(relayoutTimer);
		relayoutTimer = window.setTimeout(() => {
			relayoutTimer = 0;
			if (state?.map && typeof state.map.relayout === "function") state.map.relayout();
			if (typeof drawParcelTradeCanvas === "function"
				&& typeof isParcelTradeCanvasModeActive === "function"
				&& isParcelTradeCanvasModeActive()) {
				drawParcelTradeCanvas();
				if (typeof requestAnimationFrame === "function") requestAnimationFrame(drawParcelTradeCanvas);
			}
			if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") window.realjejuSyncTopbarFilterSafeLeft();
			if (typeof syncMapFilterScrollControls === "function") syncMapFilterScrollControls();
		}, 110);
	}

	if (button) {
		button.addEventListener("click", () => {
			if (!desktopQuery.matches
				|| !document.body
				|| !canShowSideNavToggle(document.body.dataset.globalCategory)) return;
			const collapsed = !isCollapsed();
			document.body.classList.toggle("realjeju-side-nav-collapsed", collapsed);
			persist(collapsed);
			syncButton();
			if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") window.realjejuSyncTopbarFilterSafeLeft();
			if (typeof window.realjejuSyncTopbarPageTabsOffset === "function") window.realjejuSyncTopbarPageTabsOffset();
			scheduleSingleMapRelayout();
		});
	}

	window.realjejuSyncDesktopSideNavToggle = syncButton;
	window.addEventListener("resize", syncButton, { passive: true });
	syncButton();
})();

/* REALJEJU 6.273: 모바일 왼쪽 메뉴는 지도 위 버튼으로 여는 공통 서랍입니다. */
(function initMobileSideNavDrawer6211()
{
  if (window.__realjejuMobileSideNavDrawerDelegated) {
    if (typeof window.realjejuSyncMobileSideNavDrawer === "function") window.realjejuSyncMobileSideNavDrawer();
    return;
  }

  const mobileQuery = window.matchMedia("(max-width: 850px)");

  function getElements()
  {
    return {
      sideNav: document.getElementById("realjejuSideNav"),
      trigger: document.getElementById("realjejuMobileSideNavTrigger"),
      backdrop: document.getElementById("realjejuMobileSideNavBackdrop"),
      closeButton: document.getElementById("realjejuMobileSideNavClose")
    };
  }

  function shouldShowTrigger()
  {
    if (!mobileQuery.matches || !document.body) return false;
    const category = String(document.body.dataset.globalCategory || "realestate");
    return !document.body.classList.contains("main-landing-page-open")
      && ["realestate", "parcel", "local-business", "ev-charger"].includes(category);
  }

  function setOpen(open)
  {
    const { sideNav, trigger, backdrop } = getElements();
    if (!document.body || !sideNav || !trigger || !backdrop) return false;
    const nextOpen = Boolean(open) && shouldShowTrigger();
    document.body.classList.toggle("realjeju-mobile-side-nav-open", nextOpen);
    trigger.setAttribute("aria-expanded", nextOpen ? "true" : "false");
    sideNav.setAttribute("aria-hidden", nextOpen ? "false" : "true");
    backdrop.hidden = !nextOpen;
    return true;
  }

  function syncDrawer()
  {
    const { sideNav, trigger, backdrop, closeButton } = getElements();
    if (!document.body || !sideNav || !trigger || !backdrop) return false;

    if (mobileQuery.matches) {
      const visible = shouldShowTrigger();
      trigger.hidden = !visible;
      if (closeButton) closeButton.hidden = !visible;
      if (visible) {
        sideNav.setAttribute(
          "aria-hidden",
          document.body.classList.contains("realjeju-mobile-side-nav-open") ? "false" : "true"
        );
      } else {
        setOpen(false);
      }
    } else {
      document.body.classList.remove("realjeju-mobile-side-nav-open");
      trigger.hidden = true;
      backdrop.hidden = true;
      if (closeButton) closeButton.hidden = true;
      sideNav.removeAttribute("aria-hidden");
    }
    return true;
  }

  document.addEventListener("click", (event) =>
  {
    const target = event.target;
    if (!target || typeof target.closest !== "function") return;

    if (target.closest("#realjejuMobileSideNavTrigger")) {
      event.preventDefault();
      setOpen(!document.body.classList.contains("realjeju-mobile-side-nav-open"));
      return;
    }
    if (target.closest("#realjejuMobileSideNavBackdrop, #realjejuMobileSideNavClose")) {
      event.preventDefault();
      setOpen(false);
      return;
    }

    const sideNav = document.getElementById("realjejuSideNav");
    if (
      mobileQuery.matches
      && sideNav
      && sideNav.contains(target)
      && target.closest("[data-side-nav-action], .realjeju-side-admin-tab[data-admin-tab]")
    ) {
      window.requestAnimationFrame(() => setOpen(false));
    }

    const categoryTarget = target.closest("[data-global-category]");
    if (mobileQuery.matches && categoryTarget && categoryTarget !== document.body) setOpen(false);
  });

  document.addEventListener("keydown", (event) =>
  {
    if (event.key === "Escape") setOpen(false);
  });
  window.addEventListener("resize", syncDrawer, { passive: true });

  window.__realjejuMobileSideNavDrawerDelegated = true;
  window.realjejuSyncMobileSideNavDrawer = syncDrawer;
  window.realjejuCloseMobileSideNavDrawer = () => setOpen(false);

  const initialObserver = new MutationObserver(() =>
  {
    if (syncDrawer()) initialObserver.disconnect();
  });
  initialObserver.observe(document.documentElement, { childList: true, subtree: true });

  if (!syncDrawer()) {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", () =>
      {
        if (syncDrawer()) initialObserver.disconnect();
      }, { once: true });
    }
    window.addEventListener("load", () =>
    {
      if (syncDrawer()) initialObserver.disconnect();
    }, { once: true });
  }
})();

/* REALJEJU 5.405: 스크롤 영역에서 주소의 실제 하단에 탭 바를 연속 고정합니다. */
(function bindParcelStickyAddressAndTabs5308()
{
  if (window.__realjejuParcelStickyAddressAndTabs5308) return;
  window.__realjejuParcelStickyAddressAndTabs5308 = true;

  function getTopAddress(panel)
  {
    return Array.from(panel.children).find(function(child) {
      return child.classList && child.classList.contains("parcel-land-info-address");
    }) || panel.querySelector(".parcel-land-info-address");
  }

  function sync(panel)
  {
    if (!panel || !panel.isConnected) return;
    const address = getTopAddress(panel);
    const tabs = panel.querySelector(".parcel-property-tabs");
    const scrollHost = panel.closest(".property-list") || document.getElementById("propertyList");
    if (!address || !tabs || !scrollHost) return;
    const hostRect = scrollHost.getBoundingClientRect();
    const addressRect = address.getBoundingClientRect();
    const tabsTop = Math.max(0, Math.round(addressRect.bottom - hostRect.top));
    panel.style.setProperty("--parcel-sticky-tabs-top", tabsTop + "px");
  }

  function bind(panel)
  {
    if (!panel || panel.dataset.parcelSticky5308 === "1") return;
    panel.dataset.parcelSticky5308 = "1";
    const scrollHost = panel.closest(".property-list") || document.getElementById("propertyList");
    const requestSync = function() { requestAnimationFrame(function() { sync(panel); }); };
    if (scrollHost) scrollHost.addEventListener("scroll", requestSync, { passive: true });
    window.addEventListener("resize", requestSync, { passive: true });
    if (typeof ResizeObserver !== "undefined") {
      const resizeObserver = new ResizeObserver(requestSync);
      const address = getTopAddress(panel);
      if (address) resizeObserver.observe(address);
      resizeObserver.observe(panel);
      panel.__parcelStickyResizeObserver5308 = resizeObserver;
    }
    requestSync();
  }

  function bindAll()
  {
    document.querySelectorAll(".parcel-land-info-panel").forEach(bind);
  }

  if (document.body && typeof MutationObserver !== "undefined") {
    const observer = new MutationObserver(bindAll);
    observer.observe(document.body, { childList: true, subtree: true });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", bindAll, { once: true });
  else bindAll();
})();

