function openRealjejuPartTimePage()
{
	const panel = document.getElementById("partTimePagePanel");
	if (!panel || !document.body) return Promise.resolve(false);
	if (typeof closeRightMapToolPanels === "function") closeRightMapToolPanels();
	if (typeof closeRealjejuTermsFullPageForNavigation === "function") closeRealjejuTermsFullPageForNavigation();
	if (typeof closeRealjejuCompanyFullPageForNavigation === "function") closeRealjejuCompanyFullPageForNavigation();
	resetRealjejuPageStateBeforePartTime();
	document.body.classList.remove(
		"payment-page-open", "myinfo-page-open", "profile-edit-page-open",
		"broker-office-info-page-open", "broker-office-apply-page-open", "broker-office-edit-page-open", "profile-page-open",
		"broker-home-page-open", "admin-page-open", "operator-page-open",
		"property-register-page-open", "my-suite-page-open", "notice-page-open",
		"auth-page-open", "part-time-register-page-open", "my-suite-favorites-tab-open",
		"account-inquiries-page-open", "realjeju-account-page-open"
	);
	document.body.classList.add(
		"sidebar-list-collapsed",
		"global-category-nonrealestate-mode",
		"realjeju-document-page-open",
		"part-time-page-open"
	);
	["noticePagePanel", "mySuitePanel", "paymentPagePanel", "myInfoPagePanel", "profileEditPagePanel", "brokerOfficeInfoPagePanel", "brokerOfficeApplyPagePanel", "brokerOfficeEditPagePanel", "brokerHomePanel", "adminPagePanel", "propertyRegisterPage"].forEach((id) => {
		const el = document.getElementById(id);
		if (el) {
			el.setAttribute("aria-hidden", "true");
			el.classList.remove("open", "active", "is-open");
			el.style.display = "";
			el.style.zIndex = "";
		}
	});
	panel.setAttribute("aria-hidden", "false");
	window.scrollTo({ top: 0, left: 0, behavior: "auto" });
	realjejuPartTimeTrashMode = false;
	bindRealjejuPartTimePage();
	syncRealjejuPartTimeTrashButton();
	renderRealjejuPartTimeJobs();
	const jobsReady = loadRealjejuPartTimeDbJobs().then(() => {
		if (document.body
			&& document.body.classList.contains("part-time-page-open")
			&& document.body.dataset.globalCategory === "part-time") {
			renderRealjejuPartTimeJobs();
		}
		return true;
	});
	if (typeof syncRealjejuPageTopbarSearchLabels === "function") syncRealjejuPageTopbarSearchLabels();
	if (typeof scheduleRealjejuGlobalCategoryMenuPosition === "function") scheduleRealjejuGlobalCategoryMenuPosition();
	return jobsReady;
}

