const DETAIL_QUERY_KEY = "id";
const REALJEJU_RECENT_LISTINGS_KEY = "realjeju_recent_viewed_listings";
const REALJEJU_RECENT_LISTINGS_LIMIT = 5;
const REALJEJU_RECENT_CATEGORY_STORAGE_KEYS = {
	realestate: REALJEJU_RECENT_LISTINGS_KEY,
	"local-business": "realjeju_recent_viewed_local_business",
	"ev-charger": "realjeju_recent_viewed_ev_chargers",
	"part-time": "realjeju_recent_viewed_part_time",
	"used-market": "realjeju_recent_viewed_used_market",
	car: "realjeju_recent_viewed_car",
	meetup: "realjeju_recent_viewed_meetup",
	parcel: "realjeju_recent_viewed_parcels"
};
const REALJEJU_RECENT_CATEGORY_EMPTY_TEXT = {
	realestate: "최근 조회한 매물이 없습니다.",
	"local-business": "최근 조회한 업체가 없습니다.",
	"ev-charger": "최근 조회한 충전소 정보가\n없습니다.",
	"part-time": "최근 조회한 알바가 없습니다.",
	"used-market": "최근 조회한 중고거래가 없습니다.",
	car: "최근 조회한 차량이 없습니다.",
	meetup: "최근 조회한 모임이 없습니다.",
	parcel: "최근 조회한 필지가 없습니다."
};
let realjejuRecentViewedListings = [];
const realjejuRecentCategoryCache = new Map();

function getCurrentSideRecentCategory()
{
	// SPA 내부 전환 직후 주소가 잠시 /properties로 남아 있어도,
	// 실제 화면의 카테고리를 우선해 업체 클릭을 최근 조회에 즉시 반영한다.
	const bodyCategory = String(
		document.body && document.body.dataset
			? document.body.dataset.globalCategory || ""
			: ""
	).trim();
	if (
		bodyCategory
		&& bodyCategory !== "realestate"
		&& REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[bodyCategory]
	) {
		return bodyCategory;
	}
	const routeCategory = getSideRecentRouteCategory();
	if (routeCategory !== "realestate") return routeCategory;
	const pathname = String(window.location && window.location.pathname || "").replace(/\/+$/, "") || "/";
	if (
		pathname === "/"
		|| /^\/properties(?:\/|$)/i.test(pathname)
		|| /^\/(?:admin|mypage|notices)(?:\/|$)/i.test(pathname)
	) {
		return "realestate";
	}
	const category = bodyCategory || routeCategory;
	return REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[category] ? category : "realestate";
}

function getSideRecentRouteCategory()
{
	const pathname = String(window.location && window.location.pathname || "").replace(/\/+$/, "") || "/";
	const routeCategories = {
		"/companies": "local-business",
		"/ev-chargers": "ev-charger",
		"/jobs": "part-time",
		"/used": "used-market",
		"/cars": "car",
		"/meetups": "meetup"
	};
	return routeCategories[pathname] || "realestate";
}

// getSideRecentListElement: 해당 기능을 수행한다.
function getSideRecentListElement()
{
	return document.getElementById("realjejuSideRecentList");
}

// getSideRecentEmptyElement: 해당 기능을 수행한다.
function getSideRecentEmptyElement()
{
	return document.getElementById("realjejuSideRecentEmpty");
}

// normalizeRecentValueText: 해당 기능을 수행한다.
function normalizeRecentValueText(value)
{
	if (value === null || value === undefined) return "";
	const text = String(value).trim();
	if (!text) return "";
	const compact = text
		.replace(/[·|]/g, " ")
		.replace(/[\u00b7\-\s]+/g, " ")
		.trim()
		.toLowerCase();
	if (!compact) return "";
	if (!/[\uac00-\ud7a3a-z0-9]/i.test(compact)) {
		if (/^(null|undefined|nan|none|없음|정보없음|미제공|미입력|-+)$/i.test(compact)) return "";
		return "";
	}
	const tokens = compact.split(/\s+/)
		.map(token => token.replace(/[()·|,]/g, "").trim())
		.filter(Boolean);
	if (!tokens.length) return "";
	const invalidToken = /^(null|undefined|nan|none|없음|정보없음|미제공|미입력|-+)$/i;
	const filtered = tokens.filter((token) => !invalidToken.test(token));
	if (!filtered.length) return "";
	if (filtered.length === tokens.length) return text;
	return filtered.join(" ");
}


function trimRecentListEllipsisText(value)
{
	const text = normalizeRecentValueText(value);
	if (!text) return "";
	return text.replace(/(?:\.{3,}|…).*$/g, "").trim();
}

function getRecentListCompactTitle(value)
{
	return trimRecentListEllipsisText(value)
		.replace(/\s+/g, " ")
		.trim();
}

function getRecentJejuAddressDisplayText(value)
{
	const address = getRecentListCompactTitle(value);
	if (!address) return "";
	const withoutProvince = address.replace(/^제주특별자치도(?:\s+|$)/, "").trim();
	return withoutProvince || address;
}

const REALJEJU_RECENT_TEXT_FIT_SELECTOR = ".realjeju-side-recent-item-title, .realjeju-side-recent-item-sub";

function measureRecentTextInElement(element, value)
{
	const previousText = element.textContent;
	element.textContent = String(value || "");
	let width = 0;
	if (typeof document.createRange === "function") {
		const range = document.createRange();
		range.selectNodeContents(element);
		width = range.getBoundingClientRect().width;
		if (typeof range.detach === "function") range.detach();
	}
	element.textContent = previousText;
	return width;
}

function fitRecentTitleAtNaturalBoundary(source, fittedText, element, measureText, maxWidth)
{
	const fitted = String(fittedText || "").trim();
	if (!fitted || !element.classList.contains("realjeju-side-recent-item-title")) return fitted;
	const minNaturalWidth = maxWidth * 0.42;
	const isWideEnough = (candidate) => !!candidate && measureText(candidate) >= minNaturalWidth;
	const trimTrailingCategory = (candidate) => {
		const categoryMatch = candidate.match(/(?:^|\s)(상가|토지|아파트|주택|빌라|오피스텔|원룸|투룸|사무실|공장|창고|임대|매매)$/);
		if (!categoryMatch) return candidate;
		const beforeCategory = candidate.slice(0, categoryMatch.index).trim();
		return isWideEnough(beforeCategory) ? beforeCategory : candidate;
	};
	const slashCount = (source.match(/\//g) || []).length;

	// 여러 옵션이 /로 이어진 제목은 옵션을 반쯤 붙이지 않고 제목 본문까지만 표시한다.
	if (slashCount >= 2) {
		const headline = source.slice(0, source.indexOf("/")).trim();
		if (measureText(headline) <= maxWidth && isWideEnough(headline)) return headline;
	}

	// 괄호 설명이 화면 밖으로 이어지면 열린 괄호 앞에서 끊는다.
	const openParenthesisIndex = fitted.lastIndexOf("(");
	if (openParenthesisIndex > 0 && fitted.indexOf(")", openParenthesisIndex) === -1) {
		const beforeParenthesis = fitted.slice(0, openParenthesisIndex).trim();
		if (isWideEnough(beforeParenthesis)) return beforeParenthesis;
	}

	// | 단위의 다음 설명이 전부 들어오지 않으면 마지막 완성 구분자까지만 표시한다.
	const lastPipeIndex = fitted.lastIndexOf("|");
	if (lastPipeIndex >= 0 && source.length > lastPipeIndex + 1) {
		const pipeCandidate = fitted.slice(0, lastPipeIndex + 1).trim();
		if (isWideEnough(pipeCandidate)) return pipeCandidate;
	}

	if (source.length > fitted.length) {
		const categoryTrimmedFitted = trimTrailingCategory(fitted);
		if (categoryTrimmedFitted !== fitted) return categoryTrimmedFitted;
	}

	const fittedCharacters = Array.from(fitted);
	const sourceCharacters = Array.from(source);
	const nextCharacter = sourceCharacters[fittedCharacters.length] || "";
	if (!nextCharacter || /[\s|/·,;:()\[\]]/.test(nextCharacter)) {
		return fitted.replace(/\/+$/, "").trim();
	}

	let naturalEnd = -1;
	fittedCharacters.forEach((character, index) => {
		if (/\s/.test(character) || character === "/" || character === "(") naturalEnd = index;
		else if (/[|·,;:]/.test(character)) naturalEnd = index + 1;
	});
	if (naturalEnd > 0) {
		const naturalCandidate = fittedCharacters.slice(0, naturalEnd).join("").trim().replace(/\/+$/, "").trim();
		const categoryTrimmedCandidate = trimTrailingCategory(naturalCandidate);
		if (isWideEnough(categoryTrimmedCandidate)) return categoryTrimmedCandidate;
	}
	return fitted;
}

function fitRecentListTextToElement(text, element)
{
	const source = String(text || "").replace(/\s+/g, " ").trim();
	const isRealEstateTitle = element.classList.contains("realjeju-side-recent-item-title")
		&& !!element.closest('.realjeju-side-recent-item[data-recent-category="realestate"]');
	const elementWidth = Math.floor(element.clientWidth || element.getBoundingClientRect().width || 0);
	const maxWidth = Math.max(0, elementWidth - 3);
	if (!source || maxWidth <= 0) return source;
	const measureText = (candidate) => measureRecentTextInElement(element, candidate);
	if (measureText(source) <= maxWidth) return source;

	const ellipsis = "…";
	let fitted = "";
	for (const character of Array.from(source)) {
		const next = `${fitted}${character}`;
		if (measureText(`${next}${ellipsis}`) > maxWidth) break;
		fitted = next;
	}
	const natural = fitRecentTitleAtNaturalBoundary(source, fitted, element, measureText, maxWidth)
		.replace(/[\s/]+$/, "")
		.trim();
	if (!natural) return isRealEstateTitle ? fitted.trim() : ellipsis;
	if (isRealEstateTitle) return natural;
	return `${natural}${ellipsis}`;
}

function fitSideRecentListText()
{
	const listEl = getSideRecentListElement();
	if (!listEl) return;
	listEl.querySelectorAll(REALJEJU_RECENT_TEXT_FIT_SELECTOR).forEach((element) => {
		const fullText = element.dataset.recentFullText || element.textContent || "";
		element.textContent = fitRecentListTextToElement(fullText, element);
	});
}

function scheduleSideRecentListTextFit()
{
	if (typeof requestAnimationFrame === "function") {
		requestAnimationFrame(fitSideRecentListText);
		return;
	}
	setTimeout(fitSideRecentListText, 0);
}

// normalizeRecentViewedListing: 해당 기능을 수행한다.
function normalizeRecentViewedListing(item)
{
	const id = normalizeItemId(item && item.id);
	if (!id) return null;
	const address = normalizeRecentValueText(getPublicListingDisplayAddress(item || {}));
	const type = normalizeRecentValueText(item && (item.type || item.property_type || item.property_type_label || item.propertyType || item.propertyTypeLabel || ""));
	const dealType = normalizeRecentValueText(item && item.dealType);
	const price = normalizeRecentValueText(item && item.price);
	const titleCandidate = normalizeRecentValueText(sanitizePublicListingText(item && item.title, item || {}));
	const displayName = titleCandidate || address || type || "매물";
	const summary = [
		type,
		dealType && price ? `${dealType} ${price}` : (dealType || price)
	].filter(Boolean).join(" · ");
	const listingNo = normalizePropertyListingNoCandidate(String(item && (item.listingNo || item.listing_no || "")).trim());
	const fallbackTitle = listingNo ? `매물 ${listingNo}` : "매물 조회";
	return {
		id,
		listingNo,
		dealType,
		propertyType: type,
		title: displayName || fallbackTitle,
		price,
		summary,
		address: address || "",
		updatedAt: Date.now()
	};
}

// parseRecentViewedListings: 해당 기능을 수행한다.
function parseRecentViewedListings(raw)
{
	try {
		const parsed = JSON.parse(String(raw || ""));
		if (!Array.isArray(parsed)) return [];
		return parsed.map(normalizeRecentViewedListing).filter(Boolean);
	} catch (error) {
		return [];
	}
}

// loadRecentViewedListings: 해당 기능을 수행한다.
function loadRecentViewedListings()
{
	if (!window.localStorage) return [];
	const saved = window.localStorage.getItem(REALJEJU_RECENT_LISTINGS_KEY);
	if (!saved) return [];
	const parsed = parseRecentViewedListings(saved);
	return parsed
		.sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0))
		.slice(0, REALJEJU_RECENT_LISTINGS_LIMIT);
}

function isValidLocalBusinessRecentItem(item)
{
	const action = String(item && item.action || "").trim();
	const markerKey = String(item && item.markerKey || "").trim();
	return Boolean(markerKey) && (action === "business-card" || action === "map-marker");
}

function isValidEvChargerRecentItem(item)
{
	const action = String(item && item.action || "").trim();
	const lat = Number(item && item.lat);
	const lng = Number(item && item.lng);
	return action === "charger-roadview" && Number.isFinite(lat) && Number.isFinite(lng);
}

function normalizeSideCategoryRecentItem(category, item)
{
	const nextCategory = REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[category] ? category : "realestate";
	if (nextCategory === "local-business" && !isValidLocalBusinessRecentItem(item)) return null;
	if (nextCategory === "ev-charger" && !isValidEvChargerRecentItem(item)) return null;
	const id = String(item && (item.id ?? item.key ?? item.markerKey) || "").trim();
	if (!id) return null;
	const rawTitle = item && (item.title || item.name || item.label || "");
	const normalizeJejuAddress = nextCategory === "parcel" || nextCategory === "local-business" || nextCategory === "ev-charger";
	const title = normalizeJejuAddress
		? getRecentJejuAddressDisplayText(rawTitle)
		: getRecentListCompactTitle(rawTitle);
	if (!title) return null;
	const rawSummary = item && (item.summary || item.subtitle || item.address || item.pay || "");
	const summary = nextCategory === "local-business" || nextCategory === "ev-charger"
		? getRecentJejuAddressDisplayText(rawSummary)
		: trimRecentListEllipsisText(rawSummary);
	return {
		id,
		category: nextCategory,
		title,
		summary,
		action: String(item && item.action || "category-home").trim() || "category-home",
		markerKey: String(item && item.markerKey || "").trim(),
		regNo: String(item && (item.regNo || item.office_reg_no || item.registration_no || item.reg_no || item.license_no) || "").trim(),
		phone: String(item && item.phone || "").trim(),
		lat: item && item.lat != null ? item.lat : "",
		lng: item && item.lng != null ? item.lng : "",
		updatedAt: Number(item && item.updatedAt) || Date.now()
	};
}

function loadSideCategoryRecentItems(category)
{
	const nextCategory = REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[category] ? category : "realestate";
	if (nextCategory === "realestate") return realjejuRecentViewedListings;
	if (realjejuRecentCategoryCache.has(nextCategory)) return realjejuRecentCategoryCache.get(nextCategory);
	let rows = [];
	try {
		const raw = window.localStorage ? window.localStorage.getItem(REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[nextCategory]) : "";
		const parsed = raw ? JSON.parse(raw) : [];
		if (Array.isArray(parsed)) {
			rows = parsed
				.map((item) => normalizeSideCategoryRecentItem(nextCategory, item))
				.filter(Boolean)
				.sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0))
				.slice(0, REALJEJU_RECENT_LISTINGS_LIMIT);
		}
	} catch (error) {
		rows = [];
	}
	if (nextCategory === "local-business" || nextCategory === "ev-charger") {
		try {
			window.localStorage.setItem(REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[nextCategory], JSON.stringify(rows));
		} catch (error) {}
	}
	realjejuRecentCategoryCache.set(nextCategory, rows);
	return rows;
}

function saveSideCategoryRecentItems(category, items)
{
	const storageKey = REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[category];
	if (!storageKey || category === "realestate" || !window.localStorage) return;
	try {
		window.localStorage.setItem(storageKey, JSON.stringify(items));
	} catch (error) {}
}

function upsertSideCategoryRecentItem(category, item)
{
	const nextCategory = String(category || "").trim();
	if (!REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[nextCategory] || nextCategory === "realestate") return;
	const next = normalizeSideCategoryRecentItem(nextCategory, item);
	if (!next) return;
	const current = loadSideCategoryRecentItems(nextCategory);
	const rows = [next, ...current.filter((row) => String(row && row.id || "") !== next.id)]
		.slice(0, REALJEJU_RECENT_LISTINGS_LIMIT);
	realjejuRecentCategoryCache.set(nextCategory, rows);
	saveSideCategoryRecentItems(nextCategory, rows);
	if (getCurrentSideRecentCategory() === nextCategory) renderSideRecentViewedList();
}

function recordEvChargerRoadviewRecent(item)
{
	const bodyCategory = String(document.body && document.body.dataset ? document.body.dataset.globalCategory || "" : "").trim();
	if (bodyCategory !== "ev-charger" || getCurrentSideRecentCategory() !== "ev-charger") return;
	const lat = Number(item && item.lat);
	const lng = Number(item && item.lng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
	const title = String(item && (item.title || item.name) || "전기차 충전소").trim() || "전기차 충전소";
	const id = String(item && item.id || `ev:${title}:${lat.toFixed(6)},${lng.toFixed(6)}`).trim();
	upsertSideCategoryRecentItem("ev-charger", {
		id,
		title,
		summary: String(item && (item.summary || item.address) || "").trim(),
		action: "charger-roadview",
		markerKey: id,
		lat,
		lng,
		updatedAt: Date.now()
	});
}

// getCurrentMainActionForRecentViewed: 최근 조회 이동 전 현재 메뉴 상태를 판별한다.
function getCurrentMainActionForRecentViewed()
{
	// 최근 조회에서 상세를 열기 전에, 현재 어떤 상단 뷰에 머물러 있는지 확인해
	// home이 아닌 화면에서는 홈으로 복귀 후 목록/상세 오픈 동작을 맞춘다.
	if (document.body.classList.contains("admin-page-open")) return "admin";
	if (document.body.classList.contains("broker-home-page-open")) return "broker-home";
	if (document.body.classList.contains("property-register-page-open")) return "register";
	if (document.body.classList.contains("notice-page-open")) return "notice";
	if (document.body.classList.contains("my-suite-page-open")) {
		const activeMySuiteTab = document.querySelector(".my-suite-tab.active");
		return activeMySuiteTab && activeMySuiteTab.dataset.mySuiteTab === "favorites" ? "favorites" : "";
	}
	if (document.body.classList.contains("presale-page-open")) return "presale";
	return "home";
}

realjejuRecentViewedListings = loadRecentViewedListings();
renderSideRecentViewedList();

window.addEventListener("resize", scheduleSideRecentListTextFit);
if (document.fonts && document.fonts.ready && typeof document.fonts.ready.then === "function") {
	document.fonts.ready.then(scheduleSideRecentListTextFit).catch(() => {});
}

// saveRecentViewedListings: 해당 기능을 수행한다.
function saveRecentViewedListings(listings)
{
	if (!window.localStorage) return;
	try {
		window.localStorage.setItem(REALJEJU_RECENT_LISTINGS_KEY, JSON.stringify(listings));
	} catch (error) {}
}

// renderSideRecentViewedList: 해당 기능을 수행한다.
function renderSideRecentViewedList()
{
	const listEl = getSideRecentListElement();
	const emptyEl = getSideRecentEmptyElement();
	if (!listEl || !emptyEl) return;
	const recentCategory = getCurrentSideRecentCategory();
	const recentItems = recentCategory === "realestate"
		? realjejuRecentViewedListings
		: loadSideCategoryRecentItems(recentCategory);
	listEl.dataset.recentCategory = recentCategory;
	emptyEl.textContent = REALJEJU_RECENT_CATEGORY_EMPTY_TEXT[recentCategory] || REALJEJU_RECENT_CATEGORY_EMPTY_TEXT.realestate;
	if (!recentItems.length) {
		emptyEl.hidden = false;
		emptyEl.style.display = "block";
		listEl.hidden = true;
		listEl.style.display = "none";
		listEl.innerHTML = "";
		return;
	}

	emptyEl.hidden = true;
	emptyEl.style.display = "none";
	listEl.hidden = false;
	listEl.style.removeProperty("display");
	listEl.innerHTML = recentItems.map((entry) => {
		const id = escapeHtml(entry.id);
		const rawTitleText = getRecentListCompactTitle(entry.title);
		const titleText = escapeHtml(rawTitleText || (recentCategory === "realestate" ? "매물 조회" : "최근 조회"));
		let summaryLine = trimRecentListEllipsisText(entry.summary);
		if (recentCategory === "realestate") {
			const propertyTypeText = trimRecentListEllipsisText(entry.propertyType || entry.type || entry.property_type || entry.property_type_label || entry.propertyTypeLabel || entry.summaryType || "");
			const priceText = trimRecentListEllipsisText(entry.price);
			const normalizedSummary = trimRecentListEllipsisText(entry.summary);
			// 부동산 두 번째 줄은 "매물유형 + 가격"을 우선한다.
			summaryLine = [
				propertyTypeText && priceText ? `${propertyTypeText} ${priceText}` : "",
				priceText && !propertyTypeText ? priceText : "",
				normalizedSummary
			]
				.map((value) => String(value || "").trim())
				.filter(Boolean)[0] || "";
		}
		const summaryFullText = escapeHtml(summaryLine);
		const summaryText = summaryLine ? `<div class="realjeju-side-recent-item-sub" data-recent-full-text="${summaryFullText}">${summaryFullText}</div>` : "";
		const listingAttribute = recentCategory === "realestate" ? ` data-recent-listing-id="${id}"` : "";
		return `
			<button type="button" class="realjeju-side-recent-item" data-recent-category="${escapeHtml(recentCategory)}" data-recent-item-id="${id}"${listingAttribute} title="${titleText}">
				<div class="realjeju-side-recent-item-title" data-recent-full-text="${titleText}">${titleText}</div>
				${summaryText}
			</button>
		`;
	}).join("");
	scheduleSideRecentListTextFit();
}

window.realjejuRenderSideRecentViewedList = renderSideRecentViewedList;
window.realjejuRecordCategoryRecent = upsertSideCategoryRecentItem;

// upsertRecentViewedListing: 해당 기능을 수행한다.
function upsertRecentViewedListing(item)
{
	const next = normalizeRecentViewedListing(item);
	if (!next) return;
	const byId = normalizeItemId(next.id);
	realjejuRecentViewedListings = [next, ...realjejuRecentViewedListings.filter((row) => normalizeItemId(row && row.id) !== byId)]
		.slice(0, REALJEJU_RECENT_LISTINGS_LIMIT);
	saveRecentViewedListings(realjejuRecentViewedListings);
	renderSideRecentViewedList();
}

// findRealJejuListingById: 해당 기능을 수행한다.
function findRealJejuListingById(id)
{
	const normalizedId = normalizeItemId(id);
	if (!normalizedId) return null;
	if (!state || !state.all) return null;
	const pools = [state.leftListItems, state.filtered, state.all].filter(Array.isArray);
	for (const pool of pools) {
		const found = pool.find((item) => normalizeItemId(item && item.id) === normalizedId);
		if (found) return found;
	}
	return null;
}

// openRecentViewedListingById: 해당 기능을 수행한다.
async function openRecentViewedListingById(listingId)
{
	// 최근 조회 카드에서 받은 id를 화면 처리에 쓰기 전에 항상 정규화한다.
	const normalizedId = normalizeItemId(listingId);
	if (!normalizedId) return;
	let listing = findRealJejuListingById(normalizedId);
	const cachedRecent = realjejuRecentViewedListings.find((row) => normalizeItemId(row && row.id) === normalizedId) || null;
	// 목록에서 id를 찾지 못한 경우 서버/캐시된 최근조회 데이터로 최소 표시 정보를 구성해
	// 뒤늦은 상세 데이터 로딩 실패 시에도 상세 영역을 비정상 종료시키지 않는다.
	if (!listing) {
		const dbItem = await resolveDetailDataFromDatabase({ id: normalizedId });
		if (dbItem && normalizeItemId(dbItem.id) === normalizedId) {
			listing = dbItem;
		}
	}
	if (!listing) {
		listing = {
			id: normalizedId,
			title: cachedRecent && (cachedRecent.title || cachedRecent.address || cachedRecent.summary) ? normalizeRecentValueText(cachedRecent.title || cachedRecent.address || cachedRecent.summary) : "매물 조회",
			listingNo: cachedRecent ? normalizePropertyListingNoCandidate(String(cachedRecent.listingNo || "").trim()) : "",
			type: cachedRecent ? normalizeRecentValueText(cachedRecent.propertyType || cachedRecent.type || cachedRecent.property_type || cachedRecent.property_type_label || cachedRecent.propertyTypeLabel || "") : "",
			dealType: cachedRecent ? cachedRecent.dealType : "",
			price: cachedRecent ? cachedRecent.price : "",
			address: cachedRecent ? cachedRecent.address : "",
			summary: cachedRecent ? cachedRecent.summary : ""
		};
	}
	if (!listing) return;

	const normalizedTargetId = normalizeItemId(listing && listing.id);
	if (normalizedTargetId) {
		const patchListingInPlace = (list) => {
			// 최근 조회로 연 경우에도 좌측 목록/필터 정렬을 건드리지 않도록
			// 기존 순서는 유지하고 항목 데이터만 최신값으로 갱신한다.
			const source = Array.isArray(list) ? [...list] : [];
			const index = source.findIndex(candidate => normalizeItemId(candidate && candidate.id) === normalizedTargetId);
			if (index >= 0) {
				source[index] = { ...source[index], ...listing };
			}
			return source;
		};
		state.all = patchListingInPlace(state.all);
		state.filtered = patchListingInPlace(state.filtered);
	}

	// 홈이 아니면 먼저 홈 이동 후 최근조회 상세 모드로 진입해
	// 사이드 바/필터 상태가 다른 화면 규칙에 의해 꼬이지 않도록 처리한다.
	const sideNavAction = getCurrentMainActionForRecentViewed();
	if (sideNavAction !== "home") {
		if (typeof window.realjejuGoHome === "function") {
			const homeResult = window.realjejuGoHome({ resetDetail: true });
			if (homeResult && typeof homeResult.then === "function") {
				await homeResult.catch(() => {});
			}
		}
		await new Promise((resolve) => setTimeout(resolve, 0));
	}

	// 공유형 최근조회 상세 모드 클래스는 목록-필터바 폭 조정 및 오른쪽 상세 패널 표시 계산의 기준점이다.
		const detailPanel = document.getElementById("sidebarDetailPanel");
		closeEducationFacilityDetailForPropertyInteraction();
		if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
			await closeRoadviewPanelForPropertyInteraction();
		} else if (typeof hideRoadview === "function") {
			await hideRoadview();
		}
	document.body.classList.remove("detail-page-panel-open", "direct-detail-list-mode", "list-shared-detail-mode", "map-panels-collapsed", "map-detail-panel-active");
	document.body.classList.add("shared-detail-mode");
	document.body.classList.add("recent-shared-detail-mode");
	document.body.classList.remove("sidebar-list-collapsed");
	state.isListOpen = true;
	state.selectionMode = "single";
	state.selectedClusterKey = null;
	state.selectedMarkerId = normalizedTargetId;
	state.selectedMarkerIds = new Set([normalizedTargetId]);
	lockListToItems([listing]);
	updateMarkerSelection(normalizedTargetId, [normalizedTargetId]);
	if (detailPanel) {
		detailPanel.style.display = "block";
		detailPanel.style.opacity = "";
		detailPanel.style.visibility = "";
		detailPanel.style.pointerEvents = "";
	}
	// 최근 조회 상세 오픈 직후에도 필터바를 좌측 오프셋 계산 대상으로 잡도록
	
	setSharedDetailMode(true);
	if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
		window.realjejuSyncTopbarFilterSafeLeft();
	}

	allowDetailOpenFromListClick = true;
	let detailOpenError;
	try {
		// 최근 조회 메뉴 클릭은 최근조회 패널 정렬에만 영향을 주지 않도록, 조회 이력 업서트는 건너뛴다.
		await openDetailPanel(listing, {
			syncUrl: false,
			forceOpen: true,
			overlayPage: false,
			sharedMode: true,
			skipRecentViewTracking: true
		});
		if (sidebar) sidebar.classList.add("expanded");
		state.isListOpen = true;
		updateSidebarWidth();
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
			window.realjejuSyncTopbarFilterSafeLeft();
		}
		if (typeof refreshMapLayout === "function") {
			refreshMapLayout();
			setTimeout(refreshMapLayout, 120);
		}
	} catch (error) {
		detailOpenError = error;
		console.error("최근 조회 상세 패널 열기 실패:", error);
	} finally {
		allowDetailOpenFromListClick = false;
	}
	if (detailOpenError) {
		throw detailOpenError;
	}
	syncDetailUrl(listing.id);
	await focusProperty(normalizedTargetId || listing.id);
	await focusRecentViewedListingOnMap(currentDetailItem || listing, normalizedTargetId || listing.id);

	setTimeout(() => {
		state.isListOpen = true;
		updateSidebarWidth();
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
			window.realjejuSyncTopbarFilterSafeLeft();
		}
		refreshClusterBadges();
	}, 0);
}

async function activateSideRecentCategory(category)
{
	const nextCategory = REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[category] ? category : "realestate";
	const currentCategory = getCurrentSideRecentCategory();
	if (currentCategory === nextCategory) return;
	const categoryButton = document.querySelector(`.global-category-item[data-global-category="${CSS.escape(nextCategory)}"]`);
	if (categoryButton) categoryButton.click();
	await new Promise((resolve) => setTimeout(resolve, nextCategory === "local-business" ? 260 : (nextCategory === "parcel" ? 80 : 0)));
}

async function openPartTimeRecentItem(itemId)
{
	for (let attempt = 0; attempt < 12; attempt += 1) {
		const job = typeof findRealjejuPartTimeJobById === "function" ? findRealjejuPartTimeJobById(itemId) : null;
		if (job && typeof openPartTimeDetailPanel === "function") {
			openPartTimeDetailPanel(itemId);
			return true;
		}
		await new Promise((resolve) => setTimeout(resolve, 160));
	}
	return false;
}

async function openSideRecentMarker(markerKey, options = {})
{
	if (!markerKey) return false;
	for (let attempt = 0; attempt < 12; attempt += 1) {
		const marker = document.querySelector(`[data-category-recent-key="${CSS.escape(markerKey)}"]`);
		if (marker && typeof marker.click === "function") {
			if (options && options.tooltipOnly) {
				if (typeof marker.focus === "function") marker.focus({ preventScroll: true });
				marker.dispatchEvent(new MouseEvent("mouseenter", { bubbles: true, cancelable: true }));
				marker.classList.add("realjeju-side-recent-marker-focus");
				setTimeout(() => marker.classList.remove("realjeju-side-recent-marker-focus"), 900);
				return true;
			}
			marker.click();
			return true;
		}
		await new Promise((resolve) => setTimeout(resolve, 180));
	}
	return false;
}

function focusLocalBusinessRecentMapPosition(row)
{
	const position = normalizeJejuLatLngPair(row && row.lat, row && row.lng);
	if (!position || !state.map || !window.kakao || !kakao.maps) return false;
	const latLng = new kakao.maps.LatLng(position.lat, position.lng);
	if (typeof state.map.panTo === "function") state.map.panTo(latLng);
	else if (typeof state.map.setCenter === "function") state.map.setCenter(latLng);
	if (typeof state.map.getLevel === "function" && typeof state.map.setLevel === "function" && state.map.getLevel() > 5) {
		state.map.setLevel(5, { anchor: latLng });
	}
	return true;
}

function getBrokerOfficeRecentMarkerKey(office)
{
	if (!office || typeof getBrokerOfficeOverlayKey !== "function") return "";
	return `broker:${getBrokerOfficeOverlayKey(office)}`;
}

async function findBrokerOfficeForRecentMarkerKey(markerKey)
{
	const key = String(markerKey || "").trim();
	if (!key || !key.startsWith("broker:")) return null;
	let rows = Array.isArray(state.brokerOfficeRows) && state.brokerOfficeRows.length
		? state.brokerOfficeRows
		: [];
	if (!rows.length && typeof fetchBrokerOfficeMapRows === "function") {
		try {
			rows = await fetchBrokerOfficeMapRows();
		} catch (error) {
			rows = [];
		}
	}
	const candidates = [];
	(Array.isArray(rows) ? rows : []).forEach((office) => {
		if (!office) return;
		candidates.push(office);
		if (Array.isArray(office.offices)) office.offices.forEach((item) => item && candidates.push(item));
	});
	return candidates.find((office) => getBrokerOfficeRecentMarkerKey(office) === key) || null;
}

function getLocalBusinessRecentCardLayer()
{
	let layer = document.getElementById("localBusinessRecentCardLayer");
	if (layer) return layer;
	const mapWrap = document.querySelector(".map-wrap") || document.body;
	layer = document.createElement("aside");
	layer.id = "localBusinessRecentCardLayer";
	layer.className = "local-business-recent-card-layer";
	layer.setAttribute("aria-live", "polite");
	layer.hidden = true;
	mapWrap.appendChild(layer);
	return layer;
}

function hideLocalBusinessRecentCard()
{
	const layer = document.getElementById("localBusinessRecentCardLayer");
	if (!layer) return;
	layer.hidden = true;
	layer.classList.remove("open");
	layer.innerHTML = "";
	if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
		window.realjejuSyncTopbarFilterSafeLeft();
	}
}

function isLocalBusinessRecentCardOpen()
{
	const layer = document.getElementById("localBusinessRecentCardLayer");
	return !!(layer && !layer.hidden && layer.classList.contains("open"));
}

function isLocalBusinessMapCardOpen()
{
	const layer = document.getElementById("localBusinessRecentCardLayer");
	const card = layer && layer.__realjejuLocalBusinessCard;
	return !!(
		isLocalBusinessRecentCardOpen()
		&& card
		&& (card.type === "broker" || card.type === "professional")
	);
}

function getBrokerOfficePanelHeaderTitle(officeName, listingCount)
{
	const name = String(officeName || "").trim();
	if (!name) return "매물 목록";
	return name;
}

function buildLocalBusinessCardDataFromBrokerOffice(office, recentItem = null)
{
	const fallbackTitle = String(recentItem && recentItem.title || "").trim();
	const fallbackAddress = String(recentItem && recentItem.summary || "").trim();
	const fallbackRegNo = String(recentItem && (recentItem.regNo || recentItem.office_reg_no || recentItem.registration_no || recentItem.reg_no || recentItem.license_no) || "").trim();
	const baseCard = buildBrokerOfficeAgentCard(office || {
		officeName: fallbackTitle,
		address: fallbackAddress,
		regNo: fallbackRegNo
	}) || {};
	const listingCard = buildLocalBusinessBrokerCardFromListingItems(office, baseCard);
	const card = mergeSidebarAgentCards(baseCard, listingCard);
	return {
		type: "broker",
		categoryLabel: "공인중개사",
		publicId: normalizeRealjejuAgencyPublicId(card.publicId || office && (office.publicId || office.public_id) || ""),
		name: String(card.name || "").trim(),
		title: String(card.title || "대표").trim(),
		office: String(card.office || fallbackTitle || "중개업체").trim(),
		phone: String(card.phone || "").trim(),
		phoneLink: String(card.phoneLink || card.phone || "").trim(),
		address: String(card.address || fallbackAddress || "").trim(),
		regNo: String(card.regNo || fallbackRegNo || "").trim(),
		image: String(card.image || "").trim(),
		listingCount: getBrokerOfficeListingCount(office),
		sourceOffice: office || null,
		showListingsAction: true
	};
}

function buildLocalProfessionalBusinessCardData(business)
{
	return {
		type: "professional",
		categoryLabel: String(business.categoryLabel || "전문업체").trim(),
		headerTitle: String(business.officeName || "동네업체").trim(),
		name: String(business.ownerName || "").trim(),
		title: String(business.professionalTitle || "").trim(),
		office: String(business.officeName || "").trim(),
		phone: String(business.phone || "").trim(),
		phoneLink: String(business.phone || "").trim(),
		address: String(business.address || "").trim(),
		regNo: "",
		image: "",
		listingCount: 0,
		sourceOffice: null,
		sourceProfessional: business,
		showListingsAction: false
	};
}

function buildLocalBusinessBrokerCardFromListingItems(office, baseCard = {})
{
	const filter = buildBrokerOfficeAgentFilter(office);
	if (!filter) return null;
	const pools = [
		state.leftListItems,
		state.filtered,
		state.all
	].filter(Array.isArray);
	let bestCard = null;
	let bestScore = -1;
	pools.forEach((items) => {
		items.forEach((item) => {
			const mergedItem = typeof mergeCachedLeftListDetailItem === "function" ? mergeCachedLeftListDetailItem(item) : item;
			if (!itemMatchesAgentListFilter(mergedItem, filter)) return;
			const nextCard = buildAgentListCardFromItem(mergedItem);
			const score = getSidebarAgentCardScore(nextCard);
			if (score > bestScore) {
				bestScore = score;
				bestCard = nextCard;
			}
		});
	});
	return bestCard ? mergeSidebarAgentCards(baseCard, bestCard) : null;
}

function renderLocalBusinessRecentCard(card)
{
	if (!card) return "";
	const agentCardHtml = typeof renderSidebarAgentCard === "function" ? renderSidebarAgentCard(card) : "";
	const headerTitle = String(card.headerTitle || "").trim()
		|| getBrokerOfficePanelHeaderTitle(card.office, card.listingCount);
	return ''
		+ '<div class="local-business-recent-card" role="dialog" aria-label="' + escapeHtml(card.categoryLabel || "동네업체") + ' 정보">'
		+ '<div class="sidebar-list-header local-business-recent-card-header">'
		+ '<strong class="is-agent-office-title">' + escapeHtml(headerTitle) + '</strong>'
		+ '<div class="sidebar-list-actions">'
		+ '<button type="button" class="sidebar-list-share-btn" data-local-business-card-share aria-label="공유하기" title="공유하기"><i class="fa-solid fa-arrow-up-from-bracket" aria-hidden="true"></i></button>'
		+ '</div>'
		+ '<button type="button" class="sidebar-list-close-btn" data-local-business-card-close aria-label="닫기"><i class="fa-solid fa-xmark" aria-hidden="true"></i></button>'
		+ '</div>'
		+ agentCardHtml
		+ '</div>';
}

async function ensureLocalBusinessCardPublicId(card)
{
	if (!card) return "";
	if (card.type === "professional") return "";
	const office = card.sourceOffice || null;
	let publicId = normalizeRealjejuAgencyPublicId(card.publicId || office && (office.publicId || office.public_id) || "");
	const agencyId = normalizeItemId(office && office.agencyId || "");
	if (!publicId && agencyId) publicId = await resolveRealjejuAgencyPublicIdByAgencyId(agencyId);
	if (publicId) {
		card.publicId = publicId;
		if (office) office.publicId = publicId;
	}
	return publicId;
}

function getLocalBusinessCardShareUrl(card)
{
	const currentCard = card || {};
	if (currentCard.type === "professional" && currentCard.sourceProfessional) {
		const url = new URL("/companies", window.location.origin);
		url.searchParams.set("professional", currentCard.sourceProfessional.id);
		return url.href;
	}
	const publicId = normalizeRealjejuAgencyPublicId(currentCard.publicId || "");
	if (publicId) return getRealjejuAgencyPublicUrl(publicId).href;
	const office = currentCard.sourceOffice || null;
	const filter = buildBrokerOfficeAgentFilter(office) || {};
	return buildLegacySidebarAgentListShareUrl(filter, currentCard);
}

function showLocalBusinessRecentCard(card)
{
	const layer = getLocalBusinessRecentCardLayer();
	cancelBrokerOfficeMapTooltipHide();
	hideBrokerOfficeMapTooltip();
	layer.__realjejuLocalBusinessCard = card || null;
	layer.innerHTML = renderLocalBusinessRecentCard(card);
	layer.hidden = false;
	layer.classList.add("open");
	if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
		window.realjejuSyncTopbarFilterSafeLeft();
	}
	const closeBtn = layer.querySelector("[data-local-business-card-close]");
	if (closeBtn) closeBtn.addEventListener("click", hideLocalBusinessRecentCard);
	const shareBtn = layer.querySelector("[data-local-business-card-share]");
	if (shareBtn) {
		shareBtn.addEventListener("click", async (event) => {
			event.preventDefault();
			event.stopPropagation();
			const currentCard = layer.__realjejuLocalBusinessCard || card || {};
			await ensureLocalBusinessCardPublicId(currentCard);
			const title = [currentCard.office || currentCard.name || "공인중개사", currentCard.categoryLabel || ""].filter(Boolean).join(" · ");
			const description = [
				currentCard.name && currentCard.title ? `${currentCard.name} ${currentCard.title}` : currentCard.name,
				currentCard.phone,
				currentCard.address
			].filter(Boolean).join(" · ");
			const shareUrl = getLocalBusinessCardShareUrl(currentCard);
			const payload = {
				title,
				description,
				text: [`[REALJEJU.APP] ${title}`, description, shareUrl].filter(Boolean).join("\n"),
				url: shareUrl,
				imageUrl: String(currentCard.image || "").trim()
			};
			if (typeof window.openDetailShareMenuForPayload === "function") {
				window.openDetailShareMenuForPayload(payload, shareBtn);
			} else if (typeof copyTextWithFallback === "function") {
				copyTextWithFallback(payload.text || payload.url || "");
			}
		});
	}
	const phoneBtn = layer.querySelector("[data-local-business-card-phone]");
	if (phoneBtn) {
		phoneBtn.addEventListener("click", (event) => {
			event.preventDefault();
			event.stopPropagation();
			const phone = String(phoneBtn.dataset.localBusinessCardPhone || "").trim();
			if (phone) window.location.href = "tel:" + phone;
		});
	}
	const sidebarAgentPhoneBtn = layer.querySelector("[data-sidebar-agent-phone]");
	if (sidebarAgentPhoneBtn) {
		sidebarAgentPhoneBtn.addEventListener("click", (event) => {
			event.preventDefault();
			event.stopPropagation();
			const phone = String(sidebarAgentPhoneBtn.dataset.sidebarAgentPhone || "").trim();
			if (phone) window.location.href = "tel:" + phone;
		});
	}
	const sidebarAgentKakaoBtn = layer.querySelector("[data-sidebar-agent-kakao]");
	if (sidebarAgentKakaoBtn) {
		sidebarAgentKakaoBtn.addEventListener("click", (event) => {
			event.preventDefault();
			event.stopPropagation();
			const url = String(sidebarAgentKakaoBtn.dataset.sidebarAgentKakao || "").trim();
			if (url) window.open(url, "_blank", "noopener,noreferrer");
		});
	}
	const listingBtn = layer.querySelector("[data-local-business-card-listings]");
	if (listingBtn) {
		listingBtn.addEventListener("click", async (event) => {
			event.preventDefault();
			event.stopPropagation();
			const currentCard = layer.__realjejuLocalBusinessCard || card;
			const office = currentCard && currentCard.sourceOffice;
			if (office) {
				await ensureLocalBusinessCardPublicId(currentCard);
				hideLocalBusinessRecentCard();
				await openBrokerOfficeListingPanel(office, { preserveBrokerLayer: false });
				const targetUrl = getLocalBusinessCardShareUrl(currentCard);
				try {
					const url = new URL(targetUrl);
					window.history.pushState({}, "", `${url.pathname}${url.search}${url.hash}`);
				} catch (error) {}
			}
		});
	}
}

function isLocalBusinessPageActive()
{
	return !!(document.body && document.body.dataset && document.body.dataset.globalCategory === "local-business");
}

// recordBrokerOfficeLocalBusinessRecent:
// 동네업체 카드가 실제로 열린 공통 지점에서 최근 조회를 즉시 갱신한다.
// 지도 뱃지, 툴팁 행, 최근 조회 재클릭 등 진입 경로별 중복 저장을 만들지 않는다.
function recordBrokerOfficeLocalBusinessRecent(office, recentItem = null)
{
	if (!office) return;
	const markerKey = `broker:${getBrokerOfficeOverlayKey(office)}`;
	upsertSideCategoryRecentItem("local-business", {
		id: markerKey,
		title: office.officeName || recentItem && recentItem.title || "중개업체",
		summary: office.address || recentItem && recentItem.summary || "",
		action: "business-card",
		markerKey,
		regNo: office.regNo || recentItem && recentItem.regNo || "",
		lat: office.lat || recentItem && recentItem.lat || "",
		lng: office.lng || recentItem && recentItem.lng || ""
	});
}

// recordLocalProfessionalBusinessRecent:
// 법무사ㆍ회계사 카드도 중개사 카드와 동일하게 카드 오픈 즉시 최근 조회에 반영한다.
function recordLocalProfessionalBusinessRecent(business)
{
	if (!business) return;
	const markerKey = getLocalProfessionalBusinessMarkerKey(business);
	upsertSideCategoryRecentItem("local-business", {
		id: markerKey,
		title: business.officeName || business.name || business.categoryLabel || "동네업체",
		summary: business.address || "",
		action: "business-card",
		markerKey,
		phone: business.phone || "",
		lat: business.lat || "",
		lng: business.lng || ""
	});
}

async function showBrokerOfficeLocalBusinessCard(office, recentItem = null, options = {})
{
	if (!office) return false;
	await loadBrokerOfficeListingCountsForOffices([office]);
	if (!options.preserveMapPosition) focusLocalBusinessRecentMapPosition(office);
	hideBrokerOfficeMapTooltip();
	recordBrokerOfficeLocalBusinessRecent(office, recentItem);
	showLocalBusinessRecentCard(buildLocalBusinessCardDataFromBrokerOffice(office, recentItem));
	return true;
}

async function showLocalProfessionalBusinessCard(business)
{
	if (!business) return false;
	hideBrokerOfficeMapTooltip();
	recordLocalProfessionalBusinessRecent(business);
	showLocalBusinessRecentCard(buildLocalProfessionalBusinessCardData(business));
	return true;
}

async function showBrokerOfficeRecentCard(recentItem)
{
	const markerKey = String(recentItem && recentItem.markerKey || "").trim();
	if (markerKey.startsWith("professional:")) {
		const business = findLocalProfessionalBusinessById(markerKey.slice("professional:".length));
		return business ? showLocalProfessionalBusinessCard(business) : false;
	}
	if (!markerKey.startsWith("broker:")) return false;
	const fallbackOfficeName = String(recentItem && recentItem.title || "").trim();
	const fallbackAddress = String(recentItem && recentItem.summary || "").trim();
	if (fallbackOfficeName) {
		showLocalBusinessRecentCard(buildLocalBusinessCardDataFromBrokerOffice({
			officeName: fallbackOfficeName,
			address: fallbackAddress
		}, recentItem));
		focusLocalBusinessRecentMapPosition(recentItem);
	}
	const office = await findBrokerOfficeForRecentMarkerKey(markerKey);
	if (office) {
		await showBrokerOfficeLocalBusinessCard(office, recentItem);
		return true;
	}
	if (!fallbackOfficeName) return false;
	return true;
}

async function openParcelRecentItem(recentItem)
{
	const position = normalizeJejuLatLngPair(recentItem && recentItem.lat, recentItem && recentItem.lng);
	if (!position || !state.map || !window.kakao || !kakao.maps) return false;
	const latLng = new kakao.maps.LatLng(position.lat, position.lng);
	if (typeof state.map.relayout === "function") state.map.relayout();
	if (typeof state.map.getLevel === "function" && typeof state.map.setLevel === "function" && state.map.getLevel() > 5) {
		state.map.setLevel(5, { anchor: latLng, __allowClusterRestore: true });
	}
	if (typeof state.map.setCenter === "function") state.map.setCenter(latLng, { __allowClusterRestore: true });
	else if (typeof state.map.panTo === "function") state.map.panTo(latLng);
	return await showParcelBoundaryForSearchLocation(position.lat, position.lng, {
		openLandInfoPanel: true,
		fromRecentParcel: true
	});
}

async function openSideCategoryRecentItem(category, itemId)
{
	const nextCategory = REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[category] ? category : "realestate";
	if (nextCategory === "realestate") {
		await openRecentViewedListingById(itemId);
		return;
	}
	const recentItem = loadSideCategoryRecentItems(nextCategory)
		.find((item) => String(item && item.id || "") === String(itemId || ""));
	await activateSideRecentCategory(nextCategory);
	if (!recentItem) return;
	if (recentItem.action === "charger-roadview" && nextCategory === "ev-charger") {
		const lat = Number(recentItem.lat);
		const lng = Number(recentItem.lng);
		if (Number.isFinite(lat) && Number.isFinite(lng) && typeof showRoadview === "function") {
			showRoadview(lat, lng, { evChargerRecent: recentItem });
		}
		return;
	}
	if (recentItem.action === "part-time-detail") {
		await openPartTimeRecentItem(recentItem.id);
		return;
	}
	if (recentItem.action === "parcel-info" && nextCategory === "parcel") {
		await openParcelRecentItem(recentItem);
		return;
	}
	// 동네업체 최근 조회는 업체 카드를 기록한 것과 같은 공통 카드 경로로 다시 연다.
	// 저장 action이 business-card인 항목을 map-marker 분기에만 맡기면 클릭해도 카드가 복원되지 않는다.
	if (recentItem.action === "business-card" && nextCategory === "local-business") {
		const opened = await showBrokerOfficeRecentCard(recentItem);
		if (opened) return;
		// 저장 항목에 markerKey가 지워진 경우에도 지도 위치/마커 경로로 복구한다.
		if (nextCategory === "local-business") {
			focusLocalBusinessRecentMapPosition(recentItem);
		}
		await openSideRecentMarker(recentItem.markerKey, {
			tooltipOnly: nextCategory === "local-business"
		});
		return;
	}
	if (recentItem.action === "map-marker") {
		if (nextCategory === "local-business"
			&& /^(broker|professional):/.test(String(recentItem.markerKey || ""))) {
			const opened = await showBrokerOfficeRecentCard(recentItem);
			if (opened) return;
		}
		if (nextCategory === "local-business") {
			focusLocalBusinessRecentMapPosition(recentItem);
		}
		await openSideRecentMarker(recentItem.markerKey, {
			tooltipOnly: nextCategory === "local-business"
		});
		return;
	}
	if (typeof window.realjejuOpenCustomCategoryRecentItem === "function") {
		await window.realjejuOpenCustomCategoryRecentItem(nextCategory, recentItem);
	}
}

async function focusRecentViewedListingOnMap(listing, listingId)
{
	if (!state.map || !window.kakao || !kakao.maps) return false;
	const normalizedId = normalizeItemId(listingId || (listing && listing.id));
	const candidates = [
		listing,
		currentDetailItem,
		findRealJejuListingById(normalizedId)
	];
	[state.filtered, state.all, state.leftListItems].forEach((list) => {
		if (!Array.isArray(list)) return;
		const found = list.find((item) => normalizeItemId(item && item.id) === normalizedId);
		if (found) candidates.push(found);
	});
	let position = null;
	for (const candidate of candidates) {
		if (!candidate) continue;
		const payload = candidate.payload && typeof candidate.payload === "object" ? candidate.payload : {};
		position = normalizeJejuLatLngPair(
			candidate.lat ?? candidate.latitude ?? payload.lat ?? payload.latitude,
			candidate.lng ?? candidate.longitude ?? payload.lng ?? payload.longitude
		);
		if (position) break;
	}
	if (!position) return false;

	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}
	const latLng = new kakao.maps.LatLng(position.lat, position.lng);
	const move = () => {
		if (!state.map) return;
		if (typeof state.map.relayout === "function") state.map.relayout();
		if (typeof state.map.setCenter === "function") {
			state.map.setCenter(latLng, { __allowClusterRestore: true });
		} else if (typeof state.map.panTo === "function") {
			state.map.panTo(latLng);
		}
	};
	move();
	if (typeof requestAnimationFrame === "function") requestAnimationFrame(move);
	setTimeout(move, 80);
	setTimeout(move, 240);
	return true;
}

async function openListSharedDetailFromItem(item)
{
	if (!item) return;
	const normalizedId = normalizeItemId(item.id);
	if (!normalizedId) return;

	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}
	document.body.classList.remove(
		"detail-page-panel-open",
		"direct-detail-list-mode",
		"recent-shared-detail-mode",
		"map-panels-collapsed",
		"map-detail-panel-active"
	);
	document.body.classList.add("shared-detail-mode", "list-shared-detail-mode");
	document.body.classList.remove("sidebar-list-collapsed");
	state.isListOpen = true;
	state.selectionMode = "single";
	state.selectedClusterKey = null;
	state.selectedMarkerId = normalizedId;
	state.selectedMarkerIds = new Set([normalizedId]);
	// REALJEJU 6.648: 상세를 열어도 현재 매물 목록 문맥을 유지한다.
	highlightCard(normalizedId);
	updateMarkerSelection(normalizedId, [normalizedId]);

	if (detailScroll) detailScroll.scrollTop = 0;
	allowDetailOpenFromListClick = true;
	let detailOpenError;
	try {
		await openDetailPanel(item, {
			syncUrl: false,
			forceOpen: true,
			overlayPage: false,
			sharedMode: true
		});
		document.body.classList.add("list-shared-detail-mode");
		document.body.classList.remove("sidebar-list-collapsed");
		if (sidebar) sidebar.classList.add("expanded");
		state.isListOpen = true;
		updateSidebarWidth();
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
			window.realjejuSyncTopbarFilterSafeLeft();
		}
		if (typeof refreshMapLayout === "function") {
			refreshMapLayout();
			setTimeout(refreshMapLayout, 120);
		}
	} catch (error) {
		detailOpenError = error;
		console.error("목록 상세 패널 열기 실패:", error);
	} finally {
		allowDetailOpenFromListClick = false;
	}

	syncDetailUrl(item.id);
	if (detailScroll) detailScroll.scrollTop = 0;
	await focusProperty(item.id);
	await focusRecentViewedListingOnMap(currentDetailItem || item, item.id);
	setTimeout(() => {
		document.body.classList.add("list-shared-detail-mode");
		document.body.classList.remove("sidebar-list-collapsed");
		highlightCard(normalizedId);
		refreshClusterBadges();
		if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
			window.realjejuSyncTopbarFilterSafeLeft();
		}
	}, 0);

	if (detailOpenError) throw detailOpenError;
}

/* Property detail IDs share /properties with named subroutes. */
const REALJEJU_PROPERTY_SUBROUTE_SEGMENTS = new Set([
	"favorites",
	"presales",
	"broker",
	"register"
]);

function isRealjejuPropertySubrouteSegment(value)
{
	let normalized = String(value || "").trim().toLowerCase();
	try {
		normalized = decodeURIComponent(normalized);
	} catch (error) {}
	return REALJEJU_PROPERTY_SUBROUTE_SEGMENTS.has(normalized);
}

function getDetailIdFromLocation()
{
	const pathname = String(window.location.pathname || "");
	const pathMatch = pathname.match(/^\/properties\/([^/]+)\/?$/i);
	if (pathMatch && pathMatch[1] && !isRealjejuPropertySubrouteSegment(pathMatch[1])) {
		try {
			return normalizeItemId(decodeURIComponent(pathMatch[1]));
		} catch (error) {
			return normalizeItemId(pathMatch[1]);
		}
	}
	const acceptsLegacyQuery = pathname === "/"
		|| pathname === "/properties"
		|| pathname === "/properties/"
		|| /^\/properties\/index\.html$/i.test(pathname)
		|| /^\/(?:index|realjeju_\d+\.\d+)\.html$/i.test(pathname);
	if (!acceptsLegacyQuery) return "";
	const params = new URLSearchParams(String(window.location.search || ""));
	return normalizeItemId(params.get(DETAIL_QUERY_KEY));
}

function getDetailUrlById(id)
{
	const normalizedId = normalizeItemId(id);
	const url = new URL(window.location.href);
	const canUseStaticRoutePath = /^(?:https?):$/.test(String(window.location.protocol || ""));
	if (canUseStaticRoutePath) {
		url.pathname = "/properties";
		if (normalizedId) url.searchParams.set(DETAIL_QUERY_KEY, normalizedId);
		else url.searchParams.delete(DETAIL_QUERY_KEY);
	} else if (normalizedId) {
		url.searchParams.set(DETAIL_QUERY_KEY, normalizedId);
	} else {
		url.searchParams.delete(DETAIL_QUERY_KEY);
	}
	return url;
}

function syncDetailUrl(id, { replace = false } = {})
{
	const url = getDetailUrlById(id);
	const nextUrl = `${url.pathname}${url.search}${url.hash}`;
	const currentUrl = `${window.location.pathname}${window.location.search}${window.location.hash}`;
	if (nextUrl === currentUrl) return;
	const method = replace ? "replaceState" : "pushState";
	window.history[method]({}, "", nextUrl);
}

function clearDetailUrl(options = {})
{
	if (window.realjejuRouteApplying === true && options.allowDuringRoute !== true) return;
	syncDetailUrl("", options);
}

function setSharedDetailMode(enabled)
{
	document.body.classList.toggle("shared-detail-mode", !!enabled);
	if (!enabled) {
		document.body.classList.remove("list-shared-detail-mode", "recent-shared-detail-mode");
	}
	if (enabled) {
		sidebar.classList.add("expanded");
		const panel = document.getElementById('sidebarDetailPanel');
		if (panel) {
			panel.style.display = 'block';
			panel.style.opacity = '';
			panel.style.pointerEvents = '';
			panel.style.visibility = '';
		}
	}
	updateSidebarWidth();
	refreshMapLayout();
	if (typeof window.realjejuSyncGlobalDetailSurfaceState === "function") {
		window.realjejuSyncGlobalDetailSurfaceState();
	}
}

function shouldUseSharedDetailMode()
{
	return false;
}

function normalizeItemId(value)
{
	if (value == null) return "";
	return String(value).trim();
}

