function getViewCountKey(value)
{
	return String(value || "").trim();
}

function getItemViewKey(item)
{
	if (!item || typeof item !== "object") return "";
	return getViewCountKey(item.id || item.listingNo || "");
}

function getListingViewKey(item)
{
	if (!item || typeof item !== "object") return "";
	const payload = item.payload && typeof item.payload === "object" ? item.payload : {};
	return getViewCountKey(item.listingNo || item.listing_no || payload.listing_no || payload.listingNo || item.id || "");
}

function getViewCountListIds(items)
{
	return [...new Set((items || []).map(item => getListingViewKey(item)).filter(Boolean))];
}

function getViewCountListCacheKey(ids)
{
	return (ids || []).map(getViewCountKey).filter(Boolean).sort().join("|");
}

function clearViewCountListCache()
{
	viewCountListCache.clear();
	viewCountListInflight.clear();
}

function readFreshViewCountListCache(cacheKey)
{
	const cached = cacheKey ? viewCountListCache.get(cacheKey) : null;
	if (!cached || Date.now() - Number(cached.fetchedAt || 0) > VIEW_COUNT_LIST_CACHE_MS) return null;
	return cached.counts && typeof cached.counts === "object" ? { ...cached.counts } : {};
}

function rememberViewCountListCache(cacheKey, counts)
{
	if (!cacheKey) return;
	viewCountListCache.set(cacheKey, {
		fetchedAt: Date.now(),
		counts: counts && typeof counts === "object" ? { ...counts } : {}
	});
}

function formatDetailSummaryDate(value)
{
	const raw = String(value || "").trim();
	if (!raw) return "-";
	if (/^-?\d{10,}(\.\d+)?$/.test(raw)) {
		const numberDate = Number(raw);
		if (Number.isFinite(numberDate)) {
			const dateFromNumber = new Date(numberDate);
			if (!Number.isNaN(dateFromNumber.getTime())) {
				const yyyy = dateFromNumber.getFullYear();
				const mm = String(dateFromNumber.getMonth() + 1).padStart(2, "0");
				const dd = String(dateFromNumber.getDate()).padStart(2, "0");
				return `${yyyy}-${mm}-${dd}`;
			}
		}
	}
	const dateOnlyMatch = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
	if (dateOnlyMatch) return `${dateOnlyMatch[1]}-${dateOnlyMatch[2]}-${dateOnlyMatch[3]}`;
	const date = new Date(raw);
	if (Number.isNaN(date.getTime())) return "-";
	try {
		const parts = new Intl.DateTimeFormat("en-US", {
			timeZone: "Asia/Seoul",
			year: "numeric",
			month: "2-digit",
			day: "2-digit"
		}).formatToParts(date).reduce((acc, part) => {
			acc[part.type] = part.value;
			return acc;
		}, {});
		if (parts.year && parts.month && parts.day) return `${parts.year}-${parts.month}-${parts.day}`;
	} catch (_) {}
	const yyyy = date.getFullYear();
	const mm = String(date.getMonth() + 1).padStart(2, "0");
	const dd = String(date.getDate()).padStart(2, "0");
	return `${yyyy}-${mm}-${dd}`;
}

function getDetailCountValue(item, keys)
{
	for (const key of keys) {
		const value = item && item[key];
		const numberValue = Number(value);
		if (Number.isFinite(numberValue)) return numberValue;
	}
	return 0;
}

function getDetailViewCount(item)
{
	const key = getListingViewKey(item);
	const mappedCount = Number(viewMap[getViewCountKey(key)]);
	if (Number.isFinite(mappedCount)) return mappedCount;
	return getDetailCountValue(item, ["viewCount", "view_count", "views", "readCount", "read_count"]);
}

function getDetailFavoriteCount(item)
{
	const key = getItemViewKey(item);
	const mappedCount = Number(favoriteCountMap[getViewCountKey(key)]);
	if (Number.isFinite(mappedCount)) return mappedCount;
	return getDetailCountValue(item, ["favoriteCount", "favorite_count", "wishCount", "wish_count"]);
}

function getFavoriteCountRelatedKeys(listingId)
{
	const sourceKey = getViewCountKey(listingId);
	const keys = new Set();
	if (sourceKey) keys.add(sourceKey);
	const addItemKeys = (item) => {
		if (!item || typeof item !== "object") return;
		const itemKey = getViewCountKey(getItemViewKey(item));
		const listingKey = getViewCountKey(getListingViewKey(item));
		if (itemKey) keys.add(itemKey);
		if (listingKey) keys.add(listingKey);
	};
	const matchesSource = (item) => {
		if (!sourceKey || !item || typeof item !== "object") return false;
		const itemKeys = [
			getItemViewKey(item),
			getListingViewKey(item),
			item.id,
			item.listingNo,
			item.listing_no,
			item.payload && item.payload.listing_no,
			item.payload && item.payload.listingNo
		].map(getViewCountKey).filter(Boolean);
		return itemKeys.includes(sourceKey);
	};
	if (currentDetailItem && matchesSource(currentDetailItem)) addItemKeys(currentDetailItem);
	[state.all, state.filtered, state.leftListItems].forEach((items) => {
		(Array.isArray(items) ? items : []).forEach((item) => {
			if (matchesSource(item)) addItemKeys(item);
		});
	});
	return [...keys].filter(Boolean);
}

function setFavoriteCountForRelatedKeys(listingId, count)
{
	const normalizedCount = Math.max(0, Number.isFinite(Number(count)) ? Number(count) : 0);
	const keys = getFavoriteCountRelatedKeys(listingId);
	keys.forEach((key) => {
		favoriteCountMap[key] = normalizedCount;
		detailEngagementFetchedAtMap.set(key, Date.now());
		updateCardFavoriteCountElementsForKey(key, normalizedCount);
	});
	if (currentDetailItem) {
		const detailKeys = getFavoriteCountRelatedKeys(getItemViewKey(currentDetailItem));
		if (detailKeys.some((key) => keys.includes(key))) renderDetailSummaryMeta(currentDetailItem);
	}
}

function applyFavoriteCountChange(listingId, shouldFavorite, wasFavorite)
{
	const keys = getFavoriteCountRelatedKeys(listingId);
	if (!keys.length || shouldFavorite === wasFavorite) return null;
	const currentCount = keys.map((key) => Number(favoriteCountMap[key])).find(Number.isFinite);
	const detailKey = currentDetailItem ? getViewCountKey(getItemViewKey(currentDetailItem)) : "";
	const detailListingKey = currentDetailItem ? getViewCountKey(getListingViewKey(currentDetailItem)) : "";
	const fallbackCount = currentDetailItem && (keys.includes(detailKey) || keys.includes(detailListingKey))
		? getDetailCountValue(currentDetailItem, ["favoriteCount", "favorite_count", "wishCount", "wish_count"])
		: 0;
	const baseCount = Number.isFinite(currentCount) ? currentCount : fallbackCount;
	const nextCount = Math.max(0, baseCount + (shouldFavorite ? 1 : -1));
	setFavoriteCountForRelatedKeys(listingId, nextCount);
	return nextCount;
}

async function syncFavoriteCountFromStoredDb(client, listingId, expectedCount = null)
{
	const key = getViewCountKey(listingId);
	if (!client || !key) return false;
	const optimisticCount = Number(expectedCount);
	try {
		if (typeof client.rpc === "function") {
			try {
				await client.rpc("refresh_property_engagement_count_for_listing", { p_listing_id: key });
			} catch (refreshError) {
				if (!isMissingRpcError(refreshError)) console.warn("관심수 저장 카운트 갱신 실패:", refreshError);
			}
			const { data, error } = await client.rpc("get_property_engagement_counts", {
				p_listing_ids: [key]
			});
			if (error) throw error;
			const row = Array.isArray(data) ? data[0] : null;
			const favoriteCount = Number(row && row.favorites);
			const storedId = getViewCountKey(row && row.listing_id) || key;
			if (Number.isFinite(favoriteCount)) {
				// 클릭 직전 표시값을 기준으로 계산한 수를 구형 DB 재집계 결과가 덮지 않게 한다.
				const resolvedCount = Number.isFinite(optimisticCount) ? optimisticCount : favoriteCount;
				setFavoriteCountForRelatedKeys(key, resolvedCount);
				setFavoriteCountForRelatedKeys(storedId, resolvedCount);
				return true;
			}
		}
	} catch (error) {
		if (isMissingRpcError(error)) return false;
		console.warn("관심수 저장 카운트 불러오기 실패:", error);
	}
	return false;
}

function getDetailInquiryCount(item)
{
	const key = getItemViewKey(item);
	const mappedCount = Number(inquiryCountMap[getViewCountKey(key)]);
	if (Number.isFinite(mappedCount)) return mappedCount;
	return getDetailCountValue(item, ["inquiryCount", "inquiry_count", "contactCount", "contact_count"]);
}

function getDetailSummaryMetaText(item)
{
	let dateText = formatDetailSummaryDate(getListingRegistrationDateSource(item));
	if (dateText === "-") {
		const rawFallback = [
			item?.dateLabel,
			item?.date,
			item?.payload?.last_relisted_at,
			item?.payload?.created_at,
			item?.payload?.updated_at,
			item?.createdAt,
			item?.updatedAt,
			item?.created_at,
			item?.updated_at
		].find((value) => String(value || "").trim());
		dateText = formatDetailSummaryDate(rawFallback);
	}
	const inquiryCount = getDetailInquiryCount(item);
	const favoriteCount = getDetailFavoriteCount(item);
	const viewCount = getDetailViewCount(item);
	return `등록일 ${dateText} · 문의 ${inquiryCount} · 관심 ${favoriteCount} · 조회 ${viewCount}`;
}

function renderDetailSummaryMeta(item)
{
	const detailSummaryAddress = document.getElementById("detailSummaryAddress");
	if (!detailSummaryAddress) return;
	detailSummaryAddress.textContent = getDetailSummaryMetaText(item);
}

function updateViewCountElements(viewKey, count)
{
	const key = getViewCountKey(viewKey);
	if (!key) return;
	const normalizedCount = Number.isFinite(Number(count)) ? Math.max(0, Math.trunc(Number(count))) : 0;
	document.querySelectorAll(`.card-date[data-view-key="${key}"]`).forEach(el => {
		el.textContent = `조회 ${normalizedCount}`;
	});
	document.querySelectorAll(".broker-listing-view-value[data-listing-view-key]").forEach((el) => {
		if (getViewCountKey(el.dataset.listingViewKey) !== key) return;
		el.textContent = normalizedCount.toLocaleString("ko-KR");
	});
	if (currentDetailItem && getListingViewKey(currentDetailItem) === key) {
		renderDetailSummaryMeta(currentDetailItem);
	}
}

function shouldUseListViewCounts()
{
	return !viewCountRpcDisabled && !!(state && state.isListOpen && !document.body.classList.contains("sidebar-list-collapsed"));
}

function isMissingRpcError(error)
{
	const message = String(error && (error.message || error.details || "") || "");
	return error && (error.code === "PGRST202" || message.includes("Could not find the function"));
}

function isViewIncrementRpcDefinitionError(error)
{
	const message = String(error && (error.message || error.details || "") || "");
	const details = String(error && error.details || "");
	return isMissingRpcError(error)
		|| error?.code === "42702"
		|| error?.code === "42883"
		|| error?.code === "42P13"
		|| message.includes("increment_listing_view")
		|| message.includes("ambiguous")
		|| details.includes("PL/pgSQL variable or a table column");
}

function disableViewCountRpc(error)
{
	if (!isMissingRpcError(error)) return false;
	viewCountRpcDisabled = true;
	return true;
}

async function incrementListingViewDirect(client, key)
{
	if (!client || !key) return null;
	const { data: currentRow, error: selectError } = await client
		.from("listing_views")
		.select("listing_no, views")
		.eq("listing_no", key)
		.maybeSingle();
	if (selectError) throw selectError;

	const currentViews = Number(currentRow && currentRow.views);
	const nextViews = Math.max(0, Number.isFinite(currentViews) ? currentViews : 0) + 1;
	const payload = {
		listing_no: key,
		views: nextViews,
		updated_at: new Date().toISOString()
	};
	const { data, error } = await client
		.from("listing_views")
		.upsert(payload, { onConflict: "listing_no" })
		.select("views")
		.maybeSingle();
	if (error) throw error;
	const storedViews = Number(data && data.views);
	const finalViews = Number.isFinite(storedViews) ? storedViews : nextViews;
	viewMap[key] = finalViews;
	clearViewCountListCache();
	updateViewCountElements(key, finalViews);
	return finalViews;
}

async function fetchViewCounts(items, options = {})
{
	if (!options.force && !shouldUseListViewCounts()) return {};
	const ids = getViewCountListIds(items);
	if (!ids.length) return {};
	const cacheKey = getViewCountListCacheKey(ids);
	const cachedCounts = readFreshViewCountListCache(cacheKey);
	if (cachedCounts) return cachedCounts;
	if (cacheKey && viewCountListInflight.has(cacheKey)) return viewCountListInflight.get(cacheKey);

	const fetchPromise = (async () => {
		try {
			await loadSupabaseScript();
			const client = getMapListingsSupabaseClient();
			if (!client) return {};
			const chunks = [];
			for (let index = 0; index < ids.length; index += VIEW_COUNT_FETCH_CHUNK_SIZE) {
				chunks.push(ids.slice(index, index + VIEW_COUNT_FETCH_CHUNK_SIZE));
			}
			const results = await Promise.all(chunks.map(async (chunk) => {
				const { data, error } = await client
					.from("listing_views")
					.select("listing_no, views")
					.in("listing_no", chunk);
				if (error) throw error;
				return Array.isArray(data) ? data : [];
			}));
			const next = {};
			results.flat().forEach(row => {
				const key = getViewCountKey(row && row.listing_no);
				const views = Number(row && row.views);
				if (key && Number.isFinite(views)) next[key] = views;
			});
			return next;
		} catch (err) {
			if (disableViewCountRpc(err)) return {};
			console.warn("조회수 불러오기 실패:", err);
			return {};
		}
	})().then(counts => {
		rememberViewCountListCache(cacheKey, counts);
		return counts;
	}).finally(() => {
		if (cacheKey) viewCountListInflight.delete(cacheKey);
	});
	if (cacheKey) viewCountListInflight.set(cacheKey, fetchPromise);
	return fetchPromise;
}

async function refreshCardViewCounts(items)
{
	if (!shouldUseListViewCounts()) return;
	const renderSeq = ++state.viewRenderSeq;
	const fetched = await fetchViewCounts(items);
	if (renderSeq !== state.viewRenderSeq) return;
	viewMap = { ...viewMap, ...fetched };
	Object.entries(fetched).forEach(([viewKey, count]) => {
		updateViewCountElements(viewKey, count);
	});
}

function updateCardFavoriteCountElementsForKey(listingId, count)
{
	const key = getViewCountKey(listingId);
	if (!key) return;
	const numericCount = Number(count);
	const normalizedCount = Math.max(0, Math.trunc(Number.isFinite(numericCount) ? numericCount : 0));
	document.querySelectorAll(".card-favorite-count[data-favorite-count-key]").forEach((element) => {
		if (getViewCountKey(element.dataset.favoriteCountKey) !== key) return;
		element.hidden = normalizedCount < 1;
		element.setAttribute("aria-label", `찜 ${normalizedCount.toLocaleString("ko-KR")}명`);
		const valueElement = element.querySelector(".card-favorite-count-value");
		if (valueElement) valueElement.textContent = normalizedCount.toLocaleString("ko-KR");
	});
}

function updateCardFavoriteCountElements(items)
{
	(Array.isArray(items) ? items : []).forEach((item) => {
		const key = getViewCountKey(getItemViewKey(item));
		if (!key) return;
		updateCardFavoriteCountElementsForKey(key, getDetailFavoriteCount(item));
	});
}

async function fetchCardFavoriteCounts(items)
{
	if (engagementCountRpcDisabled) return false;
	const now = Date.now();
	const ids = [...new Set(
		(Array.isArray(items) ? items : [])
			.map(getItemViewKey)
			.map(getViewCountKey)
			.filter(Boolean)
	)];
	const pendingIds = ids.filter((key) => {
		const count = Number(favoriteCountMap[key]);
		const fetchedAt = Number(detailEngagementFetchedAtMap.get(key) || 0);
		return !Number.isFinite(count) || now - fetchedAt >= DETAIL_ENGAGEMENT_CACHE_MS;
	});
	if (!pendingIds.length) return false;

	const requestKey = pendingIds.slice().sort().join("|");
	if (cardFavoriteCountInflight.has(requestKey)) return cardFavoriteCountInflight.get(requestKey);

	const request = (async () => {
		try {
			await loadSupabaseScript();
			const client = getMapListingsSupabaseClient();
			if (!client || typeof client.rpc !== "function") return false;
			const { data, error } = await client.rpc("get_property_engagement_counts", {
				p_listing_ids: pendingIds
			});
			if (error) throw error;

			const rowMap = new Map((Array.isArray(data) ? data : []).map((row) => [
				getViewCountKey(row && row.listing_id),
				row
			]));
			const fetchedAt = Date.now();
			pendingIds.forEach((key) => {
				const row = rowMap.get(key);
				const views = Number(row && row.views);
				const favorites = Number(row && row.favorites);
				const inquiries = Number(row && row.inquiries);
				if (Number.isFinite(views)) viewMap[key] = views;
				if (Number.isFinite(inquiries)) inquiryCountMap[key] = inquiries;
				const currentCount = Number(favoriteCountMap[key]);
				setFavoriteCountForRelatedKeys(
					key,
					Number.isFinite(favorites) ? favorites : (Number.isFinite(currentCount) ? currentCount : 0)
				);
				detailEngagementFetchedAtMap.set(key, fetchedAt);
			});
			return true;
		} catch (error) {
			if (isMissingRpcError(error)) {
				engagementCountRpcDisabled = true;
				return false;
			}
			console.warn("매물 목록 찜 수 불러오기 실패:", error);
			return false;
		}
	})().finally(() => cardFavoriteCountInflight.delete(requestKey));

	cardFavoriteCountInflight.set(requestKey, request);
	return request;
}

async function refreshCardFavoriteCounts(items)
{
	updateCardFavoriteCountElements(items);
	if (state.agentListFilter) return;
	const renderSeq = ++state.favoriteRenderSeq;
	await fetchCardFavoriteCounts(items);
	if (renderSeq !== state.favoriteRenderSeq) return;
	updateCardFavoriteCountElements(items);
}

async function incrementViewCount(viewKey)
{
	const key = getViewCountKey(viewKey);
	if (!key) return null;
	const now = Date.now();
	const lastIncrementedAt = Number(recentViewIncrementMap.get(key) || 0);
	if (now - lastIncrementedAt < VIEW_INCREMENT_DEDUPE_MS) {
		const cachedCount = Number(viewMap[key]);
		return Number.isFinite(cachedCount) ? cachedCount : null;
	}
	recentViewIncrementMap.set(key, now);
	try {
		await loadSupabaseScript();
		const client = getMapListingsSupabaseClient();
		if (!client) return null;
		if (!viewIncrementRpcDisabled && typeof client.rpc === "function") {
			const { data, error } = await client.rpc("increment_listing_view", {
				p_listing_no: key
			});
			if (error) {
				if (isViewIncrementRpcDefinitionError(error)) {
					viewIncrementRpcDisabled = true;
					return await incrementListingViewDirect(client, key);
				}
				throw error;
			}
			const row = Array.isArray(data) ? data[0] : data;
			const nextCount = Number(row && typeof row === "object" ? row.views : data);
			if (!Number.isFinite(nextCount)) return null;
			viewMap[key] = nextCount;
			clearViewCountListCache();
			updateViewCountElements(key, nextCount);
			return nextCount;
		}
		return await incrementListingViewDirect(client, key);
	} catch (err) {
		recentViewIncrementMap.delete(key);
		if (isViewIncrementRpcDefinitionError(err)) {
			viewIncrementRpcDisabled = true;
			console.warn("조회수 직접 저장 실패:", err);
			return null;
		}
		console.warn("조회수 증가 실패:", err);
		return null;
	}
}

function isMissingColumnError(error, columnName)
{
	const message = String(error && (error.message || error.details || "") || "");
	return message.includes(columnName) || message.includes(`'${columnName}'`) || message.includes(`"${columnName}"`);
}

async function refreshDetailEngagementCounts(item)
{
	const key = getItemViewKey(item);
	const viewKey = getListingViewKey(item) || key;
	if (!key && !viewKey) return;
	const hasCachedCounts = [viewMap[viewKey], favoriteCountMap[key], inquiryCountMap[key]]
		.some(value => Number.isFinite(Number(value)));
	const fetchedAt = Number(detailEngagementFetchedAtMap.get(key || viewKey) || 0);
	if (hasCachedCounts && Date.now() - fetchedAt < DETAIL_ENGAGEMENT_CACHE_MS) {
		if (currentDetailItem && getItemViewKey(currentDetailItem) === key) renderDetailSummaryMeta(currentDetailItem);
		return;
	}
	const seq = ++detailEngagementCountSeq;
	try {
		await loadSupabaseScript();
		const client = getMapListingsSupabaseClient();
		if (!client) return;

		if (!engagementCountRpcDisabled && typeof client.rpc === "function") {
			try {
				const { data, error } = await client.rpc("get_property_engagement_counts", {
					p_listing_ids: [key]
				});
				if (error) throw error;
				const row = Array.isArray(data) ? data.find(item => getViewCountKey(item && item.listing_id) === key) : null;
				if (row) {
					const views = Number(row.views);
					const favorites = Number(row.favorites);
					const inquiries = Number(row.inquiries);
					if (Number.isFinite(views)) viewMap[viewKey] = views;
					if (Number.isFinite(favorites)) favoriteCountMap[key] = favorites;
					if (Number.isFinite(inquiries)) inquiryCountMap[key] = inquiries;
					detailEngagementFetchedAtMap.set(key || viewKey, Date.now());
					if (seq === detailEngagementCountSeq && currentDetailItem && getItemViewKey(currentDetailItem) === key) {
						renderDetailSummaryMeta(currentDetailItem);
					}
					return;
				}
			} catch (engagementError) {
				if (isMissingRpcError(engagementError)) {
					engagementCountRpcDisabled = true;
				} else {
					console.warn("상세 서버 집계 불러오기 실패:", engagementError);
				}
			}
		}

		if (!viewCountRpcDisabled && viewKey) {
			try {
				const { data, error } = await client
					.from("listing_views")
					.select("listing_no, views")
					.eq("listing_no", viewKey)
					.maybeSingle();
				if (error) throw error;
				const count = Number(data && data.views);
				if (Number.isFinite(count)) viewMap[viewKey] = count;
			} catch (viewError) {
				if (!disableViewCountRpc(viewError)) console.warn("상세 조회수 불러오기 실패:", viewError);
			}
		}

		try {
			const { data, error } = await client
				.from("property_engagement_counts")
				.select("listing_id, views, favorites, inquiries")
				.eq("listing_id", key)
				.maybeSingle();
			if (error) throw error;
			const storedViews = Number(data && data.views);
			const storedFavorites = Number(data && data.favorites);
			const storedInquiries = Number(data && data.inquiries);
			if (Number.isFinite(storedViews)) viewMap[viewKey] = storedViews;
			if (Number.isFinite(storedFavorites)) favoriteCountMap[key] = storedFavorites;
			if (Number.isFinite(storedInquiries)) inquiryCountMap[key] = storedInquiries;
		} catch (favoriteError) {
			console.warn("상세 저장 카운트 불러오기 실패:", favoriteError);
		}

		if (DETAIL_INQUIRY_COUNT_ENABLED) {
			try {
				const { data, error } = await client
					.from("support_inquiries")
					.select("listing_id")
					.eq("listing_id", key);
				if (error) throw error;
				inquiryCountMap[key] = Array.isArray(data) ? data.length : 0;
			} catch (inquiryError) {
				if (isMissingColumnError(inquiryError, "listing_id")) {
					inquiryCountMap[key] = 0;
				} else {
					console.warn("상세 문의수 불러오기 실패:", inquiryError);
				}
			}
		}

		if (seq === detailEngagementCountSeq && currentDetailItem && getItemViewKey(currentDetailItem) === key) {
			detailEngagementFetchedAtMap.set(key || viewKey, Date.now());
			renderDetailSummaryMeta(currentDetailItem);
		}
	} catch (err) {
		console.warn("상세 집계 불러오기 실패:", err);
	}
}

