function getLocalBusinessPlaceSearchCacheKey(category)
{
	if (!category || !state.map || typeof state.map.getBounds !== "function") return "";
	const bounds = state.map.getBounds();
	const sw = bounds && typeof bounds.getSouthWest === "function" ? bounds.getSouthWest() : null;
	const ne = bounds && typeof bounds.getNorthEast === "function" ? bounds.getNorthEast() : null;
	if (!sw || !ne || typeof sw.getLat !== "function" || typeof sw.getLng !== "function" || typeof ne.getLat !== "function" || typeof ne.getLng !== "function") return "";
	const level = typeof state.map.getLevel === "function" ? Number(state.map.getLevel()) : "";
	const values = [sw.getLat(), sw.getLng(), ne.getLat(), ne.getLng()].map((value) => Number(value).toFixed(4));
	return [category, Number.isFinite(level) ? level : "", ...values].join("|");
}

function cloneLocalBusinessRows(rows)
{
	return (Array.isArray(rows) ? rows : []).map(row => ({ ...row }));
}

function getLocalBusinessPlaceSearchCache(cache, cacheKey)
{
	if (!cache || !cacheKey || typeof cache.get !== "function") return null;
	const entry = cache.get(cacheKey);
	if (!entry || Date.now() - Number(entry.time || 0) > LOCAL_BUSINESS_PLACE_SEARCH_CACHE_MS) {
		if (entry) cache.delete(cacheKey);
		return null;
	}
	return cloneLocalBusinessRows(entry.rows);
}

function setLocalBusinessPlaceSearchCache(cache, cacheKey, rows)
{
	if (!cache || !cacheKey || typeof cache.set !== "function") return;
	cache.set(cacheKey, { time: Date.now(), rows: cloneLocalBusinessRows(rows) });
}
