function ensureFacilityMapVisibleLevel(targetLevel = FACILITY_MAP_VISIBLE_LEVEL)
{
	if (!state.map || typeof state.map.getLevel !== "function" || typeof state.map.setLevel !== "function") return false;
	const requestedLevel = Number(targetLevel);
	const visibleLevel = Number.isFinite(requestedLevel) ? requestedLevel : FACILITY_MAP_VISIBLE_LEVEL;
	const currentLevel = Number(state.map.getLevel());
	if (!Number.isFinite(currentLevel) || currentLevel <= visibleLevel) return false;
	state.map.setLevel(visibleLevel, { animate: { duration: 300 }, __allowClusterRestore: true });
	return true;
}

function getFacilityOverlayZIndex(layer)
{
	if (state.localBusinessAutoMapMode) {
		return layer === "broker" ? FACILITY_OVERLAY_Z_INDEX_TOP : FACILITY_OVERLAY_Z_INDEX_BASE;
	}
	return state.topFacilityOverlayLayer === layer ? FACILITY_OVERLAY_Z_INDEX_TOP : FACILITY_OVERLAY_Z_INDEX_BASE;
}

