/* ========================================================================
	PARCEL BOUNDARY 모듈 - 시작
	- 시작: 상수/캐시/상태 선언
	- 구현: 파서/조회/정규화/렌더
	- 로직: 지도 클릭 이벤트 반응
	- 종료: 정리/외부 노출 */

/* 1) 시작 - 상수/상태 선언 */
const PARCEL_BOUNDARY_ENDPOINT = "/api/parcel-boundary-by-point";
const PARCEL_BOUNDARY_PRODUCTION_ENDPOINT = "https://realjeju.app/api/parcel-boundary-by-point";
const PARCEL_BOUNDARY_LOOKUP_TIMEOUT_MS = 14000;
const PARCEL_BOUNDARY_STROKE_COLOR = "#00B8D9";
const PARCEL_BOUNDARY_STROKE_OPACITY = 0.94;
const PARCEL_BOUNDARY_STROKE_STYLE = "shortdash";
const PARCEL_BOUNDARY_FILL_COLOR = "#00B8D9";
const PARCEL_BOUNDARY_FILL_OPACITY = 0.10;
const ADMIN_BOUNDARY_STROKE_STYLE = "shortdash";
const PARCEL_BOUNDARY_ACTIVE_Z_INDEX = 4;
const PARCEL_BOUNDARY_COORD_PRECISION = 6;
const PARCEL_BOUNDARY_MAX_FETCH_CACHE = 100;
const PARCEL_BOUNDARY_JEJU_QUERY_BOUNDS = Object.freeze({
	minLng: 125.75,
	maxLng: 127.35,
	minLat: 32.85,
	maxLat: 34.25
});
const PARCEL_BOUNDARY_DISPLAY_CALIBRATION_DEFAULT = Object.freeze({
	scale: 1,
	rotationDeg: 0,
	offsetEastMeters: 0,
	offsetNorthMeters: 0
});
let parcelBoundaryRequestToken = 0;
let parcelBoundaryLoading = false;
let parcelBoundaryPolygonOverlays = [];
let parcelBoundaryFeature = null;
let parcelBoundaryRenderError = "";
let parcelBoundaryAbortController = null;
let parcelAreaMeasureActive = false;
