function resolveRealjejuLocalAssetUrl(sourceUrl)
{
	const source = String(sourceUrl || "").trim();
	if (!source) return "";
	try {
		return new URL(source, document.baseURI || window.location.href).toString();
	} catch (error) {
		return source;
	}
}

function decodeRealjejuPolygonBinary(arrayBuffer)
{
	if (!(arrayBuffer instanceof ArrayBuffer)) throw new Error("이진 폴리곤 자료 형식 오류");
	const view = new DataView(arrayBuffer);
	let offset = 0;
	const ensureBytes = (length) => {
		if (offset + length > view.byteLength) throw new Error("이진 폴리곤 자료가 잘렸습니다.");
	};
	const readUint8 = () => {
		ensureBytes(1);
		return view.getUint8(offset++);
	};
	const readInt32 = () => {
		ensureBytes(4);
		const value = view.getInt32(offset, true);
		offset += 4;
		return value;
	};
	const readUint32 = () => {
		ensureBytes(4);
		const value = view.getUint32(offset, true);
		offset += 4;
		return value;
	};
	const readVarUint = () => {
		let value = 0;
		let shift = 0;
		for (;;) {
			const byte = readUint8();
			value += (byte & 0x7f) * (2 ** shift);
			if ((byte & 0x80) === 0) return value;
			shift += 7;
			if (shift > 49) throw new Error("이진 폴리곤 정수 범위 오류");
		}
	};
	const readVarInt = () => {
		const encoded = readVarUint();
		return encoded % 2 === 0 ? encoded / 2 : -((encoded + 1) / 2);
	};
	ensureBytes(4);
	const magic = String.fromCharCode(readUint8(), readUint8(), readUint8(), readUint8());
	if (magic !== "RJPG") throw new Error("지원하지 않는 이진 폴리곤 자료입니다.");
	const formatVersion = readUint8();
	if (formatVersion !== 2) throw new Error(`지원하지 않는 이진 폴리곤 버전: ${formatVersion}`);
	const precision = readUint8();
	const scale = 10 ** precision;
	const originX = readInt32();
	const originY = readInt32();
	const groupCount = readUint32();
	const features = [];
	for (let groupIndex = 0; groupIndex < groupCount; groupIndex += 1) {
		const classCode = readVarUint();
		const polygonCount = readVarUint();
		const polygons = [];
		for (let polygonIndex = 0; polygonIndex < polygonCount; polygonIndex += 1) {
			const ringCount = readVarUint();
			const rings = [];
			for (let ringIndex = 0; ringIndex < ringCount; ringIndex += 1) {
				const pointCount = readVarUint();
				if (pointCount < 3) throw new Error("이진 폴리곤 좌표 수 오류");
				let x = originX + readVarInt();
				let y = originY + readVarInt();
				const ring = [[x / scale, y / scale]];
				for (let pointIndex = 1; pointIndex < pointCount; pointIndex += 1) {
					x += readVarInt();
					y += readVarInt();
					ring.push([x / scale, y / scale]);
				}
				ring.push(ring[0].slice());
				rings.push(ring);
			}
			polygons.push(rings);
		}
		features.push({
			type: "Feature",
			properties: { binaryClass: classCode },
			geometry: { type: "MultiPolygon", coordinates: polygons }
		});
	}
	if (offset !== view.byteLength) throw new Error("이진 폴리곤 자료 끝 위치 오류");
	return {
		type: "FeatureCollection",
		metadata: { format: "RJPG", formatVersion, precision },
		features
	};
}

async function loadRealjejuPolygonBinary(dataUrls, cacheName, label)
{
	let responseCache = null;
	if (window.caches && window.isSecureContext) {
		try {
			responseCache = await window.caches.open(cacheName);
		} catch (error) {
			responseCache = null;
		}
	}
	let lastError = null;
	for (const url of dataUrls) {
		if (responseCache) {
			try {
				const cachedResponse = await responseCache.match(url);
				if (cachedResponse) return decodeRealjejuPolygonBinary(await cachedResponse.arrayBuffer());
			} catch (error) {
				lastError = error;
			}
		}
		try {
			const response = await fetch(url, { cache: "no-cache" });
			if (!response.ok) throw new Error(`${label} 자료 로드 실패: ${response.status}`);
			const cacheResponse = responseCache ? response.clone() : null;
			const data = decodeRealjejuPolygonBinary(await response.arrayBuffer());
			if (responseCache && cacheResponse) {
				try {
					await responseCache.put(url, cacheResponse);
				} catch (error) {}
			}
			return data;
		} catch (error) {
			lastError = error;
		}
	}
	throw lastError || new Error(`${label} 자료를 불러오지 못했습니다.`);
}
