function isCurrentUserDetailListingOwner(item)
{
	const user = typeof getBrokerMapCurrentUser === "function" ? getBrokerMapCurrentUser() : (window.realjejuCurrentAuthUser || null);
	const userId = normalizeItemId(user && (user.id || user.user_id));
	if (!userId || !item) return false;
	const identity = typeof getBrokerListingIdentity === "function" ? getBrokerListingIdentity(item) : { userId: normalizeItemId(item.userId || item.user_id) };
	return !!(identity && identity.userId && identity.userId === userId);
}

function syncDetailEditButton(item)
{
	if (!detailEditBtn) return;
	const canEdit = isCurrentUserDetailListingOwner(item);
	detailEditBtn.hidden = !canEdit;
	detailEditBtn.setAttribute("aria-hidden", canEdit ? "false" : "true");
	detailEditBtn.tabIndex = canEdit ? 0 : -1;
}

function isMySuiteFavoritesReturnContextOpen()
{
	if (!document.body.classList.contains("my-suite-page-open")) return false;
	const activeMySuiteTab = document.querySelector(".my-suite-tab.active[data-my-suite-tab='favorites']");
	return !!activeMySuiteTab;
}

		function openCurrentDetailListingEdit()
		{
			const item = currentDetailItem;
			if (!item || !isCurrentUserDetailListingOwner(item)) return;
			const listingId = normalizeItemId(item.id || item.listing_id || item.listingId);
		if (!listingId) return;
			const shouldReturnToAdminListings = document.body.classList.contains("admin-page-open")
				&& document.body.classList.contains("admin-listings-tab-open");
			const shouldReturnToMySuiteFavorites = isMySuiteFavoritesReturnContextOpen();
			const shouldReturnToBrokerHome = document.body.classList.contains("broker-home-page-open");
			if (typeof closeShareMenu === "function") closeShareMenu();
			closeDetailPanel({ preserveMapFilterDropdowns: true });
			if (typeof window.realjejuOpenBrokerListingEdit === "function") {
				// 상세 패널의 수정 버튼은 열린 출발 화면으로 돌아가야 한다.
				window.realjejuOpenBrokerListingEdit(
					listingId,
					shouldReturnToAdminListings
						? { returnTo: "admin-listings" }
						: (shouldReturnToMySuiteFavorites
							? { returnTo: "my-suite-favorites" }
							: (shouldReturnToBrokerHome ? { returnTo: "broker-home" } : { returnTo: "map-home" }))
				);
				return;
			}
	if (typeof openAuthErrorModal === "function") {
		openAuthErrorModal("매물 수정 화면을 아직 열 수 없습니다.\n페이지를 새로고침한 뒤 다시 시도해 주세요.", "매물 수정", null);
	}
}

