function positionMapTypePopover()
{
	if (!mapTypePopover || !mapTypeMenuBtn || !mapTypePopover.classList.contains("open")) return;
	const rect = mapTypeMenuBtn.getBoundingClientRect();
	const mapToolGroup = mapTypeMenuBtn.closest ? mapTypeMenuBtn.closest(".map-map-tool-group") : null;
	const groupRect = mapToolGroup ? mapToolGroup.getBoundingClientRect() : null;
	mapTypePopover.style.height = "auto";
	const popoverRect = mapTypePopover.getBoundingClientRect();
	const targetHeight = popoverRect.height;
	const left = Math.max(8, rect.left - popoverRect.width - 8);
	const preferredTop = groupRect ? groupRect.top : rect.top;
	const top = Math.min(Math.max(8, preferredTop), Math.max(8, window.innerHeight - targetHeight - 8));
	mapTypePopover.style.position = "fixed";
	mapTypePopover.style.left = left + "px";
	mapTypePopover.style.top = top + "px";
	mapTypePopover.style.height = "auto";
	mapTypePopover.style.right = "auto";
}

let mapToolPanelResizeFrame = 0;
let mapViewportLayoutSyncTimer = 0;
let mapViewportLayoutSyncRequest = 0;

function repositionOpenMapToolPanels()
{
	if (typeof positionMapTypePopover === "function") positionMapTypePopover();
	if (typeof positionEducationFacilityFilterPanel === "function" && isEducationFacilityFilterPanelOpen()) positionEducationFacilityFilterPanel();
	if (typeof positionConvenienceFacilityFilterPanel === "function" && isConvenienceFacilityFilterPanelOpen()) positionConvenienceFacilityFilterPanel();
	if (typeof positionDevelopmentFacilityFilterPanel === "function" && isDevelopmentFacilityFilterPanelOpen()) positionDevelopmentFacilityFilterPanel();
	if (typeof positionBrokerOfficeFilterPanel === "function" && isBrokerOfficeFilterPanelOpen()) positionBrokerOfficeFilterPanel();
	if (typeof positionMapSettingsFilterPanel === "function" && isMapSettingsFilterPanelOpen()) positionMapSettingsFilterPanel();
	if (typeof positionPropertyBadgeStyleEditorPopover === "function" && isPropertyBadgeStyleEditorPopoverOpen()) positionPropertyBadgeStyleEditorPopover();
	if (typeof positionLifeSafetyLegend === "function") positionLifeSafetyLegend();
}

function scheduleOpenMapToolPanelReposition()
{
	const raf = typeof requestAnimationFrame === "function" ? requestAnimationFrame : (callback) => setTimeout(callback, 16);
	const caf = typeof cancelAnimationFrame === "function" ? cancelAnimationFrame : clearTimeout;
	if (mapToolPanelResizeFrame) caf(mapToolPanelResizeFrame);
	mapToolPanelResizeFrame = raf(() => {
		mapToolPanelResizeFrame = 0;
		repositionOpenMapToolPanels();
	});
}

/* 브라우저 폭 변경이 끝난 뒤 지도 타일과 열린 오른쪽 도구 패널을 같은 최종 폭으로 맞춘다. */
function scheduleViewportMapLayoutSync()
{
	scheduleOpenMapToolPanelReposition();
	const requestId = ++mapViewportLayoutSyncRequest;
	window.clearTimeout(mapViewportLayoutSyncTimer);
	mapViewportLayoutSyncTimer = window.setTimeout(() => {
		mapViewportLayoutSyncTimer = 0;
		const raf = typeof requestAnimationFrame === "function" ? requestAnimationFrame : (callback) => setTimeout(callback, 16);
		raf(() => raf(() => {
			if (requestId !== mapViewportLayoutSyncRequest) return;
			if (state?.map && typeof state.map.relayout === "function") state.map.relayout();
			repositionOpenMapToolPanels();
			if (typeof syncMapFilterScrollControls === "function") syncMapFilterScrollControls();
		}));
	}, 80);
}

