function isSatelliteLabelControlAvailable()
{
	const category = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: String(document.body?.dataset?.globalCategory || "realestate");
	return category === "parcel"
		|| (typeof isGlobalRealestateCategory === "function"
			? isGlobalRealestateCategory(category)
			: category === "realestate");
}

function shouldShowSatelliteLabelsForCurrentService()
{
	const category = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: (document.body && document.body.dataset
			? String(document.body.dataset.globalCategory || "realestate")
			: "realestate");
	return isMapSatelliteLabelsVisible && (
		category === "parcel"
		|| (typeof isGlobalRealestateCategory === "function"
			? isGlobalRealestateCategory(category)
			: category === "realestate")
	);
}

let satelliteLabelServiceObserver = null;

function observeSatelliteLabelServiceChanges()
{
	if (satelliteLabelServiceObserver || !document.body || typeof MutationObserver !== "function") return;
	satelliteLabelServiceObserver = new MutationObserver((records) => {
		if (!records.some((record) => record.attributeName === "data-global-category")) return;
		if (currentMapTypeMode === "satellite") applyMapTypeMode("satellite");
	});
	satelliteLabelServiceObserver.observe(document.body, {
		attributes: true,
		attributeFilter: ["data-global-category"]
	});
}

function applyMapTypeMode(mode)
{
	if (!state.map || !window.kakao || !kakao.maps) return;
	const normalizedMode = mode === "satellite" || mode === "terrain" ? mode : "roadmap";
	const useSatelliteLabels = normalizedMode === "satellite"
		&& shouldShowSatelliteLabelsForCurrentService()
		&& !!kakao.maps.MapTypeId.HYBRID;
	const desiredMapTypeId = normalizedMode === "satellite"
		? (useSatelliteLabels ? kakao.maps.MapTypeId.HYBRID : kakao.maps.MapTypeId.SKYVIEW)
		: kakao.maps.MapTypeId.ROADMAP;
	const activeMapTypeId = typeof state.map.getMapTypeId === "function"
		? state.map.getMapTypeId()
		: null;
	const alreadyApplied = currentMapTypeMode === normalizedMode
		&& activeMapTypeId === desiredMapTypeId;
	currentMapTypeMode = normalizedMode;
	if (alreadyApplied) {
		updateMapTypeButtons();
		syncPickaxeMode();
		return;
	}

	try {
		state.map.removeOverlayMapTypeId(kakao.maps.MapTypeId.TERRAIN);
	} catch (e) {}
	try {
		if (kakao.maps.MapTypeId.HYBRID) state.map.removeOverlayMapTypeId(kakao.maps.MapTypeId.HYBRID);
	} catch (e) {}

	if (normalizedMode === "satellite") {
		state.map.setMapTypeId(desiredMapTypeId);
	} else if (normalizedMode === "terrain") {
		state.map.setMapTypeId(kakao.maps.MapTypeId.ROADMAP);
		if (kakao.maps.MapTypeId.TERRAIN) state.map.addOverlayMapTypeId(kakao.maps.MapTypeId.TERRAIN);
	} else {
		state.map.setMapTypeId(kakao.maps.MapTypeId.ROADMAP);
	}

	syncMapCadastralOverlay();
	updateMapTypeButtons();
	syncPickaxeMode();
}


