async function loadParcelRegionTradeStatsPanel(meta, selection)
{
	selection = normalizeParcelRegionTradeSelection(selection);
	parcelRegionTradeSelection = selection;
	const requestToken = ++parcelRegionTradeStatsRequestToken;
	renderParcelRegionTradeStatsPanel(meta, selection);
	try {
		const data = await fetchParcelRegionTradeStats(meta, selection);
		if (requestToken !== parcelRegionTradeStatsRequestToken || state.leftListDetailMode !== "parcel-region-stats") return;
		renderParcelRegionTradeStatsPanel(meta, selection, data);
	} catch (error) {
		if (requestToken !== parcelRegionTradeStatsRequestToken || state.leftListDetailMode !== "parcel-region-stats") return;
		console.error("[realjeju parcel region trade stats]", error);
		renderParcelRegionTradeStatsPanel(meta, selection, null, "실거래 통계를 불러오지 못했습니다.");
	}
}

async function openParcelRegionTradeStatsForFeature(regionFeature, parcelFeature = null, selectionSnapshot = parcelRegionTradeSelection, options = {})
{
	const featureRequestGeneration = Number.isFinite(Number(options?.zoomSyncToken))
		? Number(options.zoomSyncToken)
		: parcelRegionTradeZoomSyncToken;
	const featureRequestIsCurrent = () => featureRequestGeneration === parcelRegionTradeZoomSyncToken;
	if (!featureRequestIsCurrent()) return false;
	selectionSnapshot = normalizeParcelRegionTradeSelection(selectionSnapshot);
	const shouldRenderBoundary = options?.renderBoundary !== false;
	const allowsBadgeSelection = options?.source === "badge";
	const badgeRegionKey = allowsBadgeSelection ? String(options?.regionKey || "") : "";
	if ((!allowsBadgeSelection && !shouldUseParcelAdminBoundaryPresentation()) || !regionFeature || !propertyList) return false;
	regionFeature = await resolveParcelRegionTradeFeatureForCurrentLevel(regionFeature);
	if (!featureRequestIsCurrent()) return false;
	if (!regionFeature || (!allowsBadgeSelection && !shouldUseParcelAdminBoundaryPresentation())) return false;
	// Render the selected administrative boundary before metadata and statistics work.
    selectedAdminBoundaryFeature = shouldRenderBoundary ? regionFeature : null;
    if (shouldRenderBoundary) renderAdminBoundaryOverlay({
		preferredFeature: regionFeature,
		source: allowsBadgeSelection ? "parcel-badge" : "parcel-map"
	});
    else clearAdminBoundaryOverlay();
	const meta = await buildParcelRegionTradeMeta(regionFeature, parcelFeature);
	if (!featureRequestIsCurrent()) return false;
	if (!meta.regionCode) return false;
	const regionAnchorPoint = getParcelRegionTradeFeatureInteriorPoint(regionFeature);
	if (regionAnchorPoint) parcelRegionTradeStatsAnchorPoint = regionAnchorPoint.slice(0, 2);
	closeParcelRegionTradePickerSurface();
	if (typeof hardCloseDetailPanel === "function") hardCloseDetailPanel();
	if (typeof clearAgentListFilter === "function") clearAgentListFilter();
	if (typeof clearListLock === "function") clearListLock();
	if (typeof resetLeftListPagination === "function") resetLeftListPagination([]);
	if (!featureRequestIsCurrent()) return false;
	if (badgeRegionKey) selectedPropertyRegionCountKey = badgeRegionKey;
	state.leftListDetailMode = "parcel-region-stats";
	state.leftListTitle = "부동산 통계";
	state.isListOpen = true;
	selectedPropertyRegionBoundaryFeature = shouldRenderBoundary ? regionFeature : null;
	selectedAdminBoundaryFeature = shouldRenderBoundary ? regionFeature : null;
	adminBoundarySelectedPoint = shouldRenderBoundary ? regionAnchorPoint : null;
	// 기존 개별필지 패널이 남아 있는 상태에서 제목을 먼저 동기화하면
	// syncSidebarListTitle이 모드를 parcel-land-info로 되돌려 통계 응답을 폐기한다.
	// 통계 패널을 먼저 확정한 뒤 제목과 목록 상태를 동기화한다.
	void loadParcelRegionTradeStatsPanel(meta, selectionSnapshot);
	syncSidebarListTitle();
	openSidebarList();
	if (shouldRenderBoundary) void renderAdminBoundaryOverlay({
		preferredFeature: regionFeature,
		source: allowsBadgeSelection ? "parcel-badge" : "parcel-map"
	});
	else clearAdminBoundaryOverlay();
	return true;
}

async function openParcelRegionTradeStatsAtPoint(lat, lng, selectionSnapshot = parcelRegionTradeSelection, options = {})
{
	selectionSnapshot = normalizeParcelRegionTradeSelection(selectionSnapshot);
	if (!shouldUseParcelAdminBoundaryPresentation()) return false;
	const expectedZoomSyncToken = Number(options?.zoomSyncToken);
	if (Number.isFinite(expectedZoomSyncToken) && expectedZoomSyncToken !== parcelRegionTradeZoomSyncToken) return false;
	const regionFeature = await resolveParcelRegionTradeFeatureByPoint(lat, lng);
	if (Number.isFinite(expectedZoomSyncToken) && expectedZoomSyncToken !== parcelRegionTradeZoomSyncToken) return false;
	if (!regionFeature || !shouldUseParcelAdminBoundaryPresentation()) return false;
	parcelRegionTradeStatsAnchorPoint = [Number(lng), Number(lat)];
	return openParcelRegionTradeStatsForFeature(regionFeature, null, selectionSnapshot, options);
}

function cancelParcelRegionTradeStatsAfterZoom()
{
	parcelRegionTradeZoomSyncToken += 1;
	if (parcelRegionTradeZoomSyncTimer) {
		clearTimeout(parcelRegionTradeZoomSyncTimer);
		parcelRegionTradeZoomSyncTimer = null;
	}
	if (parcelRegionTradeZoomIdleHandler && state.map && window.kakao?.maps?.event) {
		kakao.maps.event.removeListener(state.map, "idle", parcelRegionTradeZoomIdleHandler);
	}
	parcelRegionTradeZoomIdleHandler = null;
}

function teardownParcelAnalysisSession() {
  cancelParcelRegionTradeStatsAfterZoom();
  parcelRegionTradeStatsAnchorPoint = null;
  selectedPropertyRegionBoundaryFeature = null;
  adminBoundarySelectedPoint = null;
  clearParcelBoundaryRenderState();
}

function scheduleParcelRegionTradeStatsAfterZoom(point, selectionSnapshot, options = {})
{
	if (!Array.isArray(point) || point.length < 2) return;
	cancelParcelRegionTradeStatsAfterZoom();
	const syncToken = parcelRegionTradeZoomSyncToken;
	let completed = false;
	let opening = false;
	let idleHandler = null;
	const cleanup = () => {
		if (parcelRegionTradeZoomSyncTimer) clearTimeout(parcelRegionTradeZoomSyncTimer);
		parcelRegionTradeZoomSyncTimer = null;
		if (parcelRegionTradeZoomIdleHandler === idleHandler && state.map && window.kakao?.maps?.event) {
			kakao.maps.event.removeListener(state.map, "idle", idleHandler);
			parcelRegionTradeZoomIdleHandler = null;
		}
	};
	const run = async () => {
		if (completed || opening || syncToken !== parcelRegionTradeZoomSyncToken) return;
		const currentCategory = typeof getCurrentRealjejuGlobalCategoryKey === "function"
			? getCurrentRealjejuGlobalCategoryKey()
			: String(document.body?.dataset?.globalCategory || "realestate");
		if (currentCategory !== "parcel" || !shouldUseParcelAdminBoundaryPresentation()) return;
		opening = true;
		let opened = false;
		try {
			opened = await openParcelRegionTradeStatsAtPoint(
				point[1],
				point[0],
				selectionSnapshot,
				{ ...options, zoomSyncToken: syncToken }
			);
		} catch (error) {
			console.warn("[realjeju parcel region stats] 확대·축소 자동 조회 실패:", error);
		} finally {
			opening = false;
		}
		if (!opened || syncToken !== parcelRegionTradeZoomSyncToken) return;
		completed = true;
		cleanup();
	};
	idleHandler = () => { void run(); };
	parcelRegionTradeZoomIdleHandler = idleHandler;
	if (state.map && window.kakao?.maps?.event) {
		kakao.maps.event.addListener(state.map, "idle", parcelRegionTradeZoomIdleHandler);
	}
	parcelRegionTradeZoomSyncTimer = setTimeout(() => {
		parcelRegionTradeZoomSyncTimer = null;
		void run();
	}, 0);
}

function getAdminBoundaryRingPath(ring)
{
	if (!Array.isArray(ring)) return [];
	return ring
	.map(point => Array.isArray(point) ? new kakao.maps.LatLng(Number(point[1]), Number(point[0])) : null)
	.filter(Boolean);
}

function getAdminBoundaryFeatureName(feature)
{
	const props = feature && feature.properties ? feature.properties : {};
	return (String(props.name || props.A5 || props.A4 || props.A2 || "행정구역").trim() || "행정구역").replace(/^제주도\s+/, "");
}

