	function getOrderedTypeFilterLabels()
	{
		const typeOrder = [
			"아파트",
			"오피스텔",
			"원룸 / 투룸",
			"빌라",
			"단독주택",
			"다가구주택",
			"호텔",
			"펜션",
			"상가",
			"사무실",
			"건물",
			"토지",
			"공장 / 창고",
			"생활형숙박시설"
		];
		const selectedTypeSet = selectedType instanceof Set ? selectedType : new Set();
		const labels = typeOrder.filter(type => selectedTypeSet.has(type));
		selectedTypeSet.forEach((type) => {
			if (!typeOrder.includes(type)) labels.push(type);
		});
		return labels;
	}

	function getAllFilterActiveDealLabels()
	{
		const selectedDealSet = selectedDeal instanceof Set ? selectedDeal : new Set();
		const labels = [];
		const ordered = ["매매", "전세", "월세", "년세"];
		ordered.forEach((deal) => {
			if (selectedDealSet.has(deal) || (deal === "년세" && selectedDealSet.has("연세"))) {
				labels.push(deal);
			}
		});
		selectedDealSet.forEach((deal) => {
			if (!ordered.includes(deal) && deal !== "연세") labels.push(deal);
		});
		return labels;
	}

	function getAllFilterCombinedPriceSummary()
	{
		const selectedDeals = getAllFilterActiveDealLabels();
		if (!selectedDeals.length) return "전체";
		const labels = selectedDeals
			.map((deal) => getAllFilterPriceConfig(deal))
			.filter((config) => config && config.key)
			.map((config) => `${config.label} ${getAllFilterPriceSummary(config)}`);
		return labels.length ? labels.join(", ") : "전체";
	}

	function getAllFilterRoomBathSummary()
	{
		const roomSet = selectedRoomFilter instanceof Set ? selectedRoomFilter : new Set();
		const bathSet = selectedBathFilter instanceof Set ? selectedBathFilter : new Set();
		const roomLabels = Array.from(roomSet).map((v) => {
			const label = ROOM_BATH_FILTER_LABELS[v];
			return label ? `방 ${label}` : "";
		}).filter(Boolean);
		const bathLabels = Array.from(bathSet).map((v) => {
			const label = ROOM_BATH_FILTER_LABELS[v];
			return label ? `욕실 ${label}` : "";
		}).filter(Boolean);
		const labels = [...roomLabels, ...bathLabels];
		return labels.length ? labels.join(", ") : "선택 없음";
	}

	function getAllFilterFloorDirectionSummary()
	{
		const floorSet = selectedFloorFilter instanceof Set ? selectedFloorFilter : new Set();
		const directionSet = selectedDirectionFilter instanceof Set ? selectedDirectionFilter : new Set();
		const floorLabels = Array.from(floorSet).map((v) => FLOOR_FILTER_LABELS[v]).filter(Boolean);
		const directionLabels = Array.from(directionSet).map((v) => DIRECTION_FILTER_LABELS[v]).filter(Boolean);
		const labels = [...floorLabels, ...directionLabels];
		return labels.length ? labels.join(", ") : "선택 없음";
	}

