function syncParcelTradeFilterControlVisibility()
{
	const leftToolStack = ensureParcelTradeLeftToolStack();
	const control = ensureParcelTradeFilterControl();
	const badgeVisibilityControl = ensureParcelTradeBadgeVisibilityControl();
	const satelliteControl = ensureParcelTradeSatelliteControl();
	const priceModeControl = ensureParcelTradePriceModeControl();
	const category = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: String(document.body?.dataset?.globalCategory || "realestate");
	const parcelControlsVisible = category === "parcel";
	const sharedControlsVisible = parcelControlsVisible || category === "realestate";
	const parcelAnalysisToolsEnabled = isParcelAreaMeasureVisibleLevel();
	const parcelAnalysisGroup = document.getElementById("mapParcelAnalysisToolGroup");
	const parcelAreaToolButton = document.getElementById("mapParcelAreaToolBtn");
	if (leftToolStack) leftToolStack.hidden = !sharedControlsVisible;
	if (control) control.hidden = !sharedControlsVisible;
	if (badgeVisibilityControl) badgeVisibilityControl.hidden = !sharedControlsVisible;
	if (satelliteControl) satelliteControl.hidden = !sharedControlsVisible;
	if (priceModeControl) priceModeControl.hidden = !parcelControlsVisible;
	if (parcelAnalysisGroup) parcelAnalysisGroup.hidden = !parcelControlsVisible;
	if (parcelAreaToolButton)
	{
		parcelAreaToolButton.disabled = !parcelAnalysisToolsEnabled;
		parcelAreaToolButton.setAttribute("aria-disabled", parcelAnalysisToolsEnabled ? "false" : "true");
	}
	syncParcelRoadContactButton();
	updateParcelTradeFilterControl();
	syncParcelTradeBadgeVisibilityControl();
	if (sharedControlsVisible) scheduleParcelTradeLeftToolStackPosition();
	if (!parcelControlsVisible) closeParcelTradeFilterModal();
	return sharedControlsVisible;
}

function isParcelTradeCanvasModeActive()
{
	const category = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: String(document.body?.dataset?.globalCategory || "realestate");
	const level = state.map && typeof state.map.getLevel === "function" ? Number(state.map.getLevel()) : NaN;
	return category === "parcel" && Number.isFinite(level) && level >= 1 && level <= 5;
}

function getParcelTradeCanvasMapElement()
{
	return document.getElementById("map");
}

function getParcelTradeCanvasBoundsGridSize()
{
	const bounds = state.map && typeof state.map.getBounds === "function" ? state.map.getBounds() : null;
	const sw = bounds?.getSouthWest?.();
	const ne = bounds?.getNorthEast?.();
	if (!sw || !ne) return PARCEL_TRADE_CANVAS_BOUNDS_GRID_MIN_DEG;

	const latSpan = Math.abs(Number(ne.getLat()) - Number(sw.getLat()));
	const lngSpan = Math.abs(Number(ne.getLng()) - Number(sw.getLng()));
	const span = Math.max(latSpan, lngSpan);
	if (!Number.isFinite(span) || span <= 0) return PARCEL_TRADE_CANVAS_BOUNDS_GRID_MIN_DEG;

	const level = Number(state.map && typeof state.map.getLevel === "function" ? state.map.getLevel() : NaN);
	const spanGrid = span / 12;
	if (level <= 2) return Math.max(spanGrid, 0.005);
	if (level === 3) return Math.max(spanGrid, 0.003);
	if (level === 4) return Math.max(spanGrid, 0.0015);
	if (level === 5) return Math.max(spanGrid, 0.0008);
	return Math.max(spanGrid, PARCEL_TRADE_CANVAS_BOUNDS_GRID_MIN_DEG);
}

function getParcelTradeCanvasGridAlignedValue(value, gridSize)
{
	return (Math.floor(Number(value) / gridSize) * gridSize).toFixed(PARCEL_TRADE_CANVAS_BOUNDS_GRID_DECIMALS);
}

function getParcelTradeCanvasBoundsKey()
{
	const bounds = state.map && typeof state.map.getBounds === "function" ? state.map.getBounds() : null;
	const sw = bounds?.getSouthWest?.();
	const ne = bounds?.getNorthEast?.();
	if (!sw || !ne) return "";
	const gridSize = getParcelTradeCanvasBoundsGridSize();
	return [
		getParcelTradeCanvasGridAlignedValue(sw.getLat(), gridSize),
		getParcelTradeCanvasGridAlignedValue(sw.getLng(), gridSize),
		getParcelTradeCanvasGridAlignedValue(ne.getLat(), gridSize),
		getParcelTradeCanvasGridAlignedValue(ne.getLng(), gridSize)
	]
		.join(":");
}

function normalizeParcelTradeCanvasRow(row)
{
	const lat = Number(row?.lat);
	const lng = Number(row?.lng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
	return {
		tradeId: String(row?.trade_id || ""),
		pnu: String(row?.pnu || ""),
		lat,
		lng,
		dealDate: String(row?.deal_date || ""),
		dealKind: String(row?.deal_kind || ""),
		tradeKind: String(row?.trade_kind || row?.trade_type || row?.rent_type || ""),
		serviceType: String(row?.service_type || ""),
		propertyType: String(row?.property_type || ""),
		propertyName: String(row?.property_name || ""),
		amountManWon: Number(row?.amount_man_won),
		depositManWon: Number(row?.deposit_man_won),
		monthlyRentManWon: Number(row?.monthly_rent_man_won),
		areaM2: Number(row?.area_m2),
		address: String(row?.address || ""),
		umdName: String(row?.umd_name || ""),
		jibun: String(row?.jibun || ""),
		priceLabel: String(row?.price_label || ""),
		colorKey: Number(row?.color_key)
	};
}

function getParcelTradeCanvasDistanceMeters(lat1, lng1, lat2, lng2)
{
	const toRadians = (value) => Number(value) * Math.PI / 180;
	const dLat = toRadians(Number(lat2) - Number(lat1));
	const dLng = toRadians(Number(lng2) - Number(lng1));
	const firstLat = toRadians(lat1);
	const secondLat = toRadians(lat2);
	const haversine = Math.sin(dLat / 2) ** 2
		+ Math.cos(firstLat) * Math.cos(secondLat) * Math.sin(dLng / 2) ** 2;
	return 6371000 * 2 * Math.atan2(Math.sqrt(haversine), Math.sqrt(Math.max(0, 1 - haversine)));
}

window.__realjejuGetParcelTradeCanvasNearbyRows = function(options)
{
	const source = options && typeof options === "object" ? options : {};
	const lat = Number(source.lat);
	const lng = Number(source.lng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return [];
	const radiusMeters = Math.min(5000, Math.max(1, Number(source.radiusMeters) || 500));
	const limit = Math.min(200, Math.max(1, Number(source.limit) || 100));
	const excludePnu = String(source.excludePnu || "").replace(/\D/g, "");
	return parcelTradeCanvasRows
		.filter((row) => !excludePnu || String(row?.pnu || "").replace(/\D/g, "") !== excludePnu)
		.map((row) => ({
			...row,
			amountManWon: getParcelTradeCanvasAmountManWon(row),
			distance: getParcelTradeCanvasDistanceMeters(lat, lng, row.lat, row.lng)
		}))
		.filter((row) => Number.isFinite(row.distance) && row.distance <= radiusMeters)
		.sort((left, right) => left.distance - right.distance
			|| String(right.dealDate || "").localeCompare(String(left.dealDate || "")))
		.slice(0, limit);
};

function formatParcelTradeCanvasAmount(value)
{
	const amount = Number(value);
	if (!Number.isFinite(amount) || amount <= 0) return "-";
	if (amount >= 10000) {
		const eok = amount / 10000;
		return `${eok >= 10 ? eok.toFixed(1) : eok.toFixed(2)}`.replace(/\.0+$|(?<=\.[0-9])0$/g, "") + "억";
	}
	return Math.round(amount).toLocaleString("ko-KR") + "만";
}

function getParcelTradeCanvasAmountManWon(row)
{
	const directAmount = Number(row?.amountManWon);
	if (Number.isFinite(directAmount) && directAmount > 0) return directAmount;
	const label = String(row?.priceLabel || "").replace(/\s+/g, "").replace(/원/g, "");
	if (!label) return 0;
	const parseNumber = (value) => Number(String(value || "").replace(/,/g, ""));
	const eokMatch = label.match(/([\d,.]+)억/);
	let totalManWon = 0;
	if (eokMatch) {
		const eok = parseNumber(eokMatch[1]);
		if (Number.isFinite(eok) && eok > 0) totalManWon += eok * 10000;
	}
	const trailingSource = eokMatch ? label.slice(label.indexOf(eokMatch[0]) + eokMatch[0].length) : label;
	const manMatch = trailingSource.match(/([\d,.]+)(?:만)?$/);
	if (manMatch) {
		const manWon = parseNumber(manMatch[1]);
		if (Number.isFinite(manWon) && manWon > 0) totalManWon += manWon;
	}
	return totalManWon;
}

function getParcelTradeCanvasPriceLabel(row)
{
	if (row.dealKind === "rent") {
		const deposit = formatParcelTradeCanvasAmount(row.depositManWon);
		const monthly = Number(row.monthlyRentManWon);
		return monthly > 0 ? `${deposit}/${Math.round(monthly).toLocaleString("ko-KR")}` : deposit;
	}
	const areaM2 = Number(row.areaM2);
	const amountManWon = getParcelTradeCanvasAmountManWon(row);
	if (parcelTradePriceMode === "unit") {
		if (Number.isFinite(areaM2) && areaM2 > 0 && Number.isFinite(amountManWon) && amountManWon > 0) {
			const areaByUnit = globalAreaUnit === "py" ? areaM2 / 3.305785 : areaM2;
			return formatParcelTradeCanvasAmount(amountManWon / areaByUnit);
		}
		return "-";
	}
	if (row.priceLabel) return row.priceLabel;
	return formatParcelTradeCanvasAmount(amountManWon);
}

function getParcelTradeCanvasDateLabel(row)
{
	const match = String(row.dealDate || "").match(/^(\d{4})-(\d{2})/);
	return match ? `'${match[1].slice(2)}.${match[2]}` : "";
}

function getParcelTradeCanvasColor(row)
{
	const filterKey = getParcelTradeFilterKey(row);
	const option = PARCEL_TRADE_FILTER_OPTIONS.find((item) => item.key === filterKey);
	return option?.color || "#6268F2";
}
function ensureParcelTradeLoadButton()
{
	if (parcelTradeLoadButton && parcelTradeLoadButton.isConnected) parcelTradeLoadButton.remove();
	parcelTradeLoadButton = null;
	return null;
}

function updateParcelTradeLoadButton()
{
	ensureParcelTradeLoadButton();
}

function ensureParcelTradeCanvas()
{
	if (parcelTradeCanvas && parcelTradeCanvas.isConnected) return parcelTradeCanvas;
	const host = getParcelTradeCanvasMapElement();
	if (!host) return null;
	const canvas = document.createElement("canvas");
	canvas.className = "parcel-trade-marker-canvas";
	canvas.setAttribute("aria-hidden", "true");
	host.appendChild(canvas);
	parcelTradeCanvas = canvas;
	parcelTradeCanvasContext = canvas.getContext("2d");
	return canvas;
}

function drawRoundedCanvasRect(ctx, x, y, width, height, radius)
{
	const r = Math.max(0, Math.min(radius, width / 2, height / 2));
	ctx.beginPath();
	ctx.moveTo(x + r, y);
	ctx.arcTo(x + width, y, x + width, y + height, r);
	ctx.arcTo(x + width, y + height, x, y + height, r);
	ctx.arcTo(x, y + height, x, y, r);
	ctx.arcTo(x, y, x + width, y, r);
	ctx.closePath();
}

function syncParcelTradeCanvasVisibility()
{
	const canvas = ensureParcelTradeCanvas();
	const hidden = !isParcelTradeCanvasModeActive()
		|| !!document.body?.classList?.contains("parcel-region-trade-badges-hidden");
	if (canvas) canvas.hidden = hidden;
	if (!hidden) drawParcelTradeCanvas();
}

let parcelMapLevelPresentationMode = "";
let parcelMapLevelInteractionMode = "";
let parcelMapLevelPresentationSyncToken = 0;

async function syncParcelMapLevelPresentation(options = {})
{
	const syncToken = ++parcelMapLevelPresentationSyncToken;
	const category = typeof getCurrentRealjejuGlobalCategoryKey === "function"
		? getCurrentRealjejuGlobalCategoryKey()
		: String(document.body?.dataset?.globalCategory || "realestate");
	const level = state.map && typeof state.map.getLevel === "function"
		? Number(state.map.getLevel())
		: NaN;

	if (category !== "parcel" || !Number.isFinite(level)) {
		document.body?.classList?.remove("parcel-individual-trade-level");
		parcelMapLevelPresentationMode = "";
		parcelMapLevelInteractionMode = "";
		syncParcelTradeCanvasVisibility();
		syncParcelTradeFilterControlVisibility();
		return false;
	}

	const nextProfile = getParcelMapLevelProfile(level);
	const nextMode = nextProfile.presentationMode;
	const nextInteractionMode = nextProfile.clickMode;
	const previousMode = parcelMapLevelPresentationMode;
	const previousInteractionMode = parcelMapLevelInteractionMode;
	const usesIndividualTradeBadges = level >= 1 && level <= 5;
	document.body?.classList?.toggle("parcel-individual-trade-level", usesIndividualTradeBadges);
	parcelMapLevelPresentationMode = nextMode;
	parcelMapLevelInteractionMode = nextInteractionMode;
	propertyMapPresentationMode = nextMode;
	syncParcelTradeFilterControlVisibility();

	if (usesIndividualTradeBadges) {
		// 5.995: 1~5레벨에서는 진행 중인 행정구역 통계 요청까지 무조건 폐기한다.
		propertyRegionCountRenderToken += 1;
		parcelRegionTradeBadgeRenderedSignature = "";
		// 5.995: 취소된 local-counts 요청을 6레벨이 재사용하지 않도록 진행 중 키도 제거한다.
		parcelRegionTradeBadgeRenderInFlight.clear();
		clearPropertyRegionCountOverlays();
		syncParcelTradeCanvasVisibility();
		if (options.loadInitial === true) {
			await loadParcelTradeCanvasRowsForCurrentViewport({ source: options.source || "level-router" });
		}
		return syncToken === parcelMapLevelPresentationSyncToken;
	}

	syncParcelTradeCanvasVisibility();
	if (!shouldRenderParcelRegionTradeMapBadges(nextMode)) return true;

	const modeChanged = previousMode !== nextMode
		|| previousInteractionMode !== nextInteractionMode;
	if (modeChanged) {
		propertyRegionCountRenderToken += 1;
		// 기존 네모 뱃지는 새 단계가 준비될 때까지 유지한다.
		if (previousMode !== nextMode) parcelRegionTradeBadgeRenderedSignature = "";
	}
	if (modeChanged || !propertyRegionCountOverlays.length) {
		await renderPropertyRegionCountOverlays(nextMode);
	}
	return syncToken === parcelMapLevelPresentationSyncToken;
}

function getParcelTradeCanvasViewportLimit()
{
	const level = Number(state.map?.getLevel?.());
	if (Number.isFinite(level) && level <= 1) return 2000;
	if (Number.isFinite(level) && level <= 2) return 1200;
	if (Number.isFinite(level) && level <= 3) return 800;
	if (Number.isFinite(level) && level <= 4) return 500;
	return 300;
}

function getParcelTradeCanvasBadgeLimit()
{
	const level = Number(state.map?.getLevel?.());
	if (Number.isFinite(level) && level <= 1) return 250;
	if (Number.isFinite(level) && level <= 2) return 180;
	if (Number.isFinite(level) && level <= 3) return 120;
	if (Number.isFinite(level) && level <= 4) return 80;
	return 50;
}

function startParcelTradeCanvasReveal()
{
	if (parcelTradeCanvasRevealFrame && typeof cancelAnimationFrame === "function") {
		cancelAnimationFrame(parcelTradeCanvasRevealFrame);
	}
	parcelTradeCanvasRevealFrame = 0;
	const reduceMotion = typeof window.matchMedia === "function"
		&& window.matchMedia("(prefers-reduced-motion: reduce)").matches;
	parcelTradeCanvasRevealStartedAt = reduceMotion ? 0 : performance.now();
	drawParcelTradeCanvas();
}

function getRealjejuCanvasUiFontFamily()
{
	return '"Paperlogy", "Pretendard Variable", Pretendard, sans-serif';
}

function getParcelTradeCanvasTypeOption(row)
{
	const filterKey = getParcelTradeFilterKey(row);
	return PARCEL_TRADE_FILTER_OPTIONS.find((item) => item.key === filterKey)
		|| PARCEL_TRADE_FILTER_OPTIONS[0];
}

function expandParcelTradeCanvasPriceLabel(value)
{
	const label = String(value || "-").trim();
	const eokMatch = label.match(/^([\d,.]+)억$/);
	if (eokMatch) {
		const totalManWon = Math.round(Number(eokMatch[1].replaceAll(",", "")) * 10000);
		if (Number.isFinite(totalManWon)) {
			const eok = Math.floor(totalManWon / 10000);
			const manWon = totalManWon % 10000;
			return eok + "억" + (manWon ? " " + manWon.toLocaleString("ko-KR") + "만원" : "원");
		}
	}
	if (/만$/.test(label)) return label + "원";
	return label;
}

function getParcelTradeCanvasDetailAmountLabel(row)
{
	const compactLabel = String(getParcelTradeCanvasPriceLabel(row) || row?.priceLabel || "-");
	if (parcelTradePriceMode === "unit" && row?.dealKind !== "rent") return compactLabel;
	if (compactLabel.includes("/")) {
		const [deposit, monthly] = compactLabel.split("/", 2);
		return "월세 " + expandParcelTradeCanvasPriceLabel(deposit) + "/" + String(monthly || "-") + "만원";
	}
	const tradeKind = row?.dealKind === "rent" ? "전세" : "매매";
	return tradeKind + " " + expandParcelTradeCanvasPriceLabel(compactLabel);
}

function getParcelTradeCanvasDetailAreaLabel(row, typeOption)
{
	const areaM2 = Number(row?.areaM2);
	if (!Number.isFinite(areaM2) || areaM2 <= 0) return "면적 -";
	const areaValue = globalAreaUnit === "py" ? areaM2 / 3.305785 : areaM2;
	const unit = globalAreaUnit === "py" ? "평" : "m²";
	const roundedArea = areaValue >= 100 ? Math.round(areaValue).toLocaleString("ko-KR") : areaValue.toFixed(1).replace(/\.0$/, "");
	return (typeOption?.key === "land" ? "토지 " : "면적 ") + roundedArea + unit;
}

function drawSelectedParcelTradeCanvasBadge(ctx, row, point, viewportWidth)
{
	const typeOption = getParcelTradeCanvasTypeOption(row);
	const typeColor = typeOption.color;
	const amountLabel = getParcelTradeCanvasDetailAmountLabel(row);
	const areaLabel = getParcelTradeCanvasDetailAreaLabel(row, typeOption);
	const dateLabel = "계약일 " + getParcelTradeCanvasDateLabel(row);
	const leftWidth = 54;
	const rightPadding = 8;
	ctx.font = '550 14.5px ' + getRealjejuCanvasUiFontFamily();
	ctx.letterSpacing = '0px';
	const amountWidth = ctx.measureText(amountLabel).width;
	ctx.letterSpacing = '0px';
	ctx.font = '400 12.5px ' + getRealjejuCanvasUiFontFamily();
	const areaWidth = ctx.measureText(areaLabel).width;
	ctx.font = '400 12.5px ' + getRealjejuCanvasUiFontFamily();
	const dateWidth = ctx.measureText(dateLabel).width;
	const metaWidth = Math.max(areaWidth, dateWidth);
	ctx.font = '600 10.5px "Paperlogy", "Pretendard Variable", Pretendard, sans-serif';
	const typeWidth = ctx.measureText(typeOption.label).width + 12;
	const rightWidth = Math.ceil(Math.max(amountWidth, metaWidth, typeWidth) + rightPadding * 2);
	const badgeWidth = leftWidth + rightWidth;
	const badgeHeight = 76;
	const tailHeight = 7;
	const unclampedLeft = Math.round(point.x - badgeWidth / 2);
	const left = Math.max(4, Math.min(unclampedLeft, Math.max(4, viewportWidth - badgeWidth - 4)));
	const top = Math.round(point.y - badgeHeight - tailHeight);
	const anchorX = Math.max(left + 12, Math.min(point.x, left + badgeWidth - 12));

	ctx.save();
	ctx.fillStyle = "rgba(255,255,255,.98)";
	drawRoundedCanvasRect(ctx, left, top, badgeWidth, badgeHeight, 8);
	ctx.fill();
	ctx.shadowColor = "transparent";
	ctx.save();
	drawRoundedCanvasRect(ctx, left, top, badgeWidth, badgeHeight, 8);
	ctx.clip();
	ctx.fillStyle = "#1764FF";
	ctx.fillRect(left, top, leftWidth, badgeHeight);
	ctx.restore();

	ctx.fillStyle = typeColor;
	ctx.beginPath();
	ctx.arc(point.x, point.y, 4, 0, Math.PI * 2);
	ctx.fill();
	ctx.fillStyle = "rgba(255,255,255,.98)";
	ctx.beginPath();
	ctx.moveTo(anchorX - 5, top + badgeHeight - 1);
	ctx.lineTo(anchorX + 5, top + badgeHeight - 1);
	ctx.lineTo(point.x, point.y);
	ctx.closePath();
	ctx.fill();

	ctx.save();
	ctx.globalAlpha = 1;
	ctx.strokeStyle = "#E3E3E3";
	ctx.lineWidth = 0.8;
	drawRoundedCanvasRect(ctx, left, top, badgeWidth, badgeHeight, 8);
	ctx.stroke();
	ctx.beginPath();
	ctx.moveTo(anchorX - 5, top + badgeHeight - 0.5);
	ctx.lineTo(point.x, point.y);
	ctx.lineTo(anchorX + 5, top + badgeHeight - 0.5);
	ctx.stroke();
	ctx.restore();
	ctx.save();
	ctx.fillStyle = "rgba(255,255,255,.98)";
	ctx.fillRect(anchorX - 5.2, top + badgeHeight - 1.5, 10.4, 2.8);
	ctx.restore();

	ctx.textAlign = "center";
	ctx.fillStyle = "#FFFFFF";
	ctx.font = '600 13px "Paperlogy", "Pretendard Variable", Pretendard, sans-serif';
	ctx.fillText("실거래", left + leftWidth / 2, top + badgeHeight / 2 + 1);

	const contentLeft = left + leftWidth + rightPadding;
	ctx.textAlign = "left";
	ctx.font = '600 10.5px "Paperlogy", "Pretendard Variable", Pretendard, sans-serif';
	const pillWidth = Math.ceil(ctx.measureText(typeOption.label).width + 12);
	ctx.fillStyle = typeColor;
	drawRoundedCanvasRect(ctx, contentLeft, top + 8, pillWidth, 14, 7);
	ctx.fill();
	ctx.fillStyle = "#FFFFFF";
	ctx.fillText(typeOption.label, contentLeft + 6, top + 15.5);

	ctx.fillStyle = typeColor;
	ctx.font = '550 14.5px ' + getRealjejuCanvasUiFontFamily();
	ctx.letterSpacing = '0px';
	ctx.fillText(amountLabel, contentLeft, top + 33);
	ctx.letterSpacing = '0px';
	ctx.fillStyle = "#4B5563";
	ctx.font = '400 12.5px ' + getRealjejuCanvasUiFontFamily();
	ctx.fillText(areaLabel, contentLeft, top + 49);
	ctx.fillStyle = "#4B5563";
	ctx.font = '400 12.5px ' + getRealjejuCanvasUiFontFamily();
	ctx.fillText(dateLabel, contentLeft, top + 64);
	ctx.restore();
	return { left, top, right: left + badgeWidth, bottom: point.y + 4 };
}

function drawParcelTradeCanvas()
{
	const canvas = ensureParcelTradeCanvas();
	const host = getParcelTradeCanvasMapElement();
	const ctx = parcelTradeCanvasContext;
	parcelTradeCanvasHitBoxes = [];
	if (!canvas || !host || !ctx || !state.map || !isParcelTradeCanvasModeActive()) {
		if (canvas && ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
		return;
	}
	const width = Math.max(1, host.clientWidth);
	const height = Math.max(1, host.clientHeight);
	const dpr = Math.min(2, Math.max(1, Number(window.devicePixelRatio) || 1));
	if (canvas.width !== Math.round(width * dpr) || canvas.height !== Math.round(height * dpr)) {
		canvas.width = Math.round(width * dpr);
		canvas.height = Math.round(height * dpr);
		canvas.style.width = width + "px";
		canvas.style.height = height + "px";
	}
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	ctx.clearRect(0, 0, width, height);
	const projection = typeof state.map.getProjection === "function" ? state.map.getProjection() : null;
	if (!projection || typeof projection.containerPointFromCoords !== "function") return;
	ctx.textAlign = "center";
	ctx.textBaseline = "middle";
	const selectedMarker = window.__realjejuSelectedParcelTradeMarker || null;
	const isSelectedRow = (row) => {
		if (!selectedMarker) return false;
		if (selectedMarker.tradeId && row.tradeId) return String(selectedMarker.tradeId) === String(row.tradeId);
		return !!selectedMarker.pnu && String(selectedMarker.pnu) === String(row.pnu);
	};
	const visibleCandidates = parcelTradeCanvasRows
		.filter(isParcelTradeRowFilterVisible)
		.map((row) => ({
			row,
			point: projection.containerPointFromCoords(new kakao.maps.LatLng(row.lat, row.lng))
		}))
		.filter((candidate) => candidate.point
			&& candidate.point.x >= -80
			&& candidate.point.y >= -80
			&& candidate.point.x <= width + 80
			&& candidate.point.y <= height + 80)
		.sort((left, right) => {
			const leftSelected = isSelectedRow(left.row);
			const rightSelected = isSelectedRow(right.row);
			if (leftSelected !== rightSelected) return leftSelected ? 1 : -1;
			return String(right.row.dealDate || "").localeCompare(String(left.row.dealDate || ""));
		});
	// 모든 실거래 필지는 말풍선 배치 여부와 관계없이 색상 점을 유지합니다.
	for (const candidate of visibleCandidates) {
		const { row, point } = candidate;
		ctx.save();
		ctx.fillStyle = getParcelTradeCanvasColor(row);
		ctx.beginPath();
		ctx.arc(point.x, point.y, 3, 0, Math.PI * 2);
		ctx.fill();
		ctx.restore();
	}
	const occupiedRects = [];
	const hasSelectedCandidate = visibleCandidates.some((candidate) => isSelectedRow(candidate.row));
	const badgeLimit = getParcelTradeCanvasBadgeLimit();
	const maximumNormalBadges = Math.max(1, badgeLimit - (hasSelectedCandidate ? 1 : 0));
	for (const candidate of visibleCandidates) {
		const { row, point } = candidate;
		const isSelectedBadge = isSelectedRow(row);
		if (!isSelectedBadge && parcelTradeCanvasHitBoxes.length >= maximumNormalBadges) continue;
		if (isSelectedBadge) {
			const selectedHitBox = drawSelectedParcelTradeCanvasBadge(ctx, row, point, width);
			parcelTradeCanvasHitBoxes.push({ ...selectedHitBox, row });
			continue;
		}
		const amountLabel = getParcelTradeCanvasPriceLabel(row);
		const dateLabel = getParcelTradeCanvasDateLabel(row);
		ctx.font = '500 14px ' + getRealjejuCanvasUiFontFamily();
	ctx.letterSpacing = '0px';
		const amountTextWidth = ctx.measureText(amountLabel).width;
	ctx.letterSpacing = '0px';
		ctx.font = '400 12px ' + getRealjejuCanvasUiFontFamily();
		const dateTextWidth = ctx.measureText(dateLabel).width;
		const badgeWidth = Math.max(44, Math.ceil(Math.max(amountTextWidth, dateTextWidth) + 20));
		const badgeHeight = 37;
		const tailHeight = 6;
		const left = Math.round(point.x - badgeWidth / 2);
		const top = Math.round(point.y - badgeHeight - tailHeight);
		const collisionMargin = 2;
		const collisionRect = {
			left: left - collisionMargin,
			top: top - collisionMargin,
			right: left + badgeWidth + collisionMargin,
			bottom: point.y + collisionMargin
		};
		const overlaps = occupiedRects.some((rect) => !(collisionRect.right <= rect.left
			|| collisionRect.left >= rect.right
			|| collisionRect.bottom <= rect.top
			|| collisionRect.top >= rect.bottom));
		if (overlaps) continue;
		occupiedRects.push(collisionRect);

		ctx.save();
		ctx.fillStyle = "rgba(255,255,255,0.99)";
		ctx.shadowColor = "rgba(15,23,42,0.30)";
		ctx.shadowBlur = 12;
		ctx.shadowOffsetX = 3;
		ctx.shadowOffsetY = 5;
		drawRoundedCanvasRect(ctx, left, top, badgeWidth, badgeHeight, 18);
		ctx.fill();
		ctx.shadowColor = "transparent";
		ctx.fillStyle = getParcelTradeCanvasColor(row);
		ctx.beginPath();
		ctx.arc(point.x, point.y, 3.5, 0, Math.PI * 2);
		ctx.fill();
		ctx.fillStyle = "rgba(255,255,255,0.99)";
		ctx.beginPath();
		ctx.moveTo(point.x - 4.5, top + badgeHeight - 1);
		ctx.lineTo(point.x + 4.5, top + badgeHeight - 1);
		ctx.lineTo(point.x, point.y);
		ctx.closePath();
		ctx.fill();
		ctx.fillStyle = "rgba(255,255,255,0.99)";
		drawRoundedCanvasRect(ctx, left, top, badgeWidth, badgeHeight, 18);
		ctx.fill();

		ctx.font = '500 14px ' + getRealjejuCanvasUiFontFamily();
	ctx.letterSpacing = '0px';
		const sharedBadgeBorderStyle = getPropertyBadgeStyle();
		ctx.save();
		ctx.shadowColor = "transparent";
		ctx.strokeStyle = "rgba(148,163,184,0.78)";
		ctx.lineWidth = 0.8;
		drawRoundedCanvasRect(ctx, left, top, badgeWidth, badgeHeight, 18);
		ctx.stroke();
		ctx.beginPath();
		ctx.moveTo(point.x - 5, top + badgeHeight - 0.4);
		ctx.lineTo(point.x, point.y);
		ctx.lineTo(point.x + 5, top + badgeHeight - 0.4);
		ctx.stroke();
		ctx.fillStyle = "rgba(255,255,255,.96)";
		ctx.fillRect(point.x - 5.2, top + badgeHeight - 1.5, 10.4, 2.8);
		ctx.restore();
		ctx.fillStyle = getParcelTradeCanvasColor(row);
		ctx.fillText(amountLabel, point.x, top + 13.5);
	ctx.letterSpacing = '0px';
		ctx.fillStyle = "#4B5563";
		ctx.font = '400 12px ' + getRealjejuCanvasUiFontFamily();
		ctx.fillText(dateLabel, point.x, top + 27.5);
		ctx.restore();
		parcelTradeCanvasHitBoxes.push({
			left,
			top,
			right: left + badgeWidth,
			bottom: point.y + 4,
			row
		});
	}
	parcelTradeCanvasRevealStartedAt = 0;
}

function getParcelTradeCanvasHit(mouseEvent)
{
	if (!isParcelTradeCanvasModeActive() || !mouseEvent?.latLng) return null;
	const projection = state.map?.getProjection?.();
	const point = projection?.containerPointFromCoords?.(mouseEvent.latLng);
	if (!point) return null;
	for (let index = parcelTradeCanvasHitBoxes.length - 1; index >= 0; index -= 1) {
		const box = parcelTradeCanvasHitBoxes[index];
		if (point.x >= box.left && point.x <= box.right && point.y >= box.top && point.y <= box.bottom) return box.row;
	}
	return null;
}

async function handleParcelTradeCanvasMapClick(mouseEvent)
{
	const row = getParcelTradeCanvasHit(mouseEvent);
	if (!row) return false;
	if (window.kakao?.maps?.event && typeof kakao.maps.event.preventMap === "function") kakao.maps.event.preventMap();
	const selectedMarker = window.__realjejuSelectedParcelTradeMarker || null;
	const isSameSelectedMarker = selectedMarker
		&& ((selectedMarker.tradeId && row.tradeId && String(selectedMarker.tradeId) === String(row.tradeId))
			|| (!selectedMarker.tradeId && selectedMarker.pnu && String(selectedMarker.pnu) === String(row.pnu)));
	if (isSameSelectedMarker) {
		window.__realjejuSelectedParcelTradeMarker = null;
		drawParcelTradeCanvas();
		return true;
	}
	window.__realjejuSelectedParcelTradeMarker = { ...row };
	drawParcelTradeCanvas();
	await showParcelBoundaryForSearchLocation(row.lat, row.lng, {
		openLandInfoPanel: true,
		pnu: row.pnu,
		tradeId: row.tradeId,
		fromTradeMarker: true
	});
	return true;
}

async function loadParcelTradeCanvasRowsForCurrentViewport(options = {})
{
	if (!isParcelTradeCanvasModeActive() || !state.map) return false;
	const bounds = state.map.getBounds?.();
	const sw = bounds?.getSouthWest?.();
	const ne = bounds?.getNorthEast?.();
	const markerLimit = getParcelTradeCanvasViewportLimit();
	const viewportBoundsKey = getParcelTradeCanvasBoundsKey();
	const boundsKey = viewportBoundsKey ? viewportBoundsKey + ":" + markerLimit : "";
	if (!sw || !ne || !boundsKey) return false;
	const cached = parcelTradeViewportCache.get(boundsKey);
	if (cached) {
		parcelTradeCanvasRows = cached;
		parcelTradeCanvasLoadedBoundsKey = boundsKey;
		parcelTradeCanvasInitialLoaded = true;
		startParcelTradeCanvasReveal();
		updateParcelTradeLoadButton();
		return true;
	}
	const ongoingRequest = parcelTradeViewportRequests.get(boundsKey);
	if (ongoingRequest) return await ongoingRequest;

	const requestToken = ++parcelTradeCanvasRequestToken;
	parcelTradeCanvasLoading = true;
	updateParcelTradeLoadButton();

	const requestPromise = (async () => {
		try {
			let client = getMapListingsSupabaseClient();
			if (!client && typeof loadSupabaseScript === "function") {
				await loadSupabaseScript();
				client = getMapListingsSupabaseClient();
			}
			if (!client) throw new Error("실거래 DB에 연결하지 못했습니다.");
			const { data, error } = await client.rpc(PARCEL_TRADE_MARKER_RPC, {
				p_south: Number(sw.getLat()),
				p_west: Number(sw.getLng()),
				p_north: Number(ne.getLat()),
				p_east: Number(ne.getLng()),
				p_limit: markerLimit
			});
			if (error) throw error;
			if (requestToken !== parcelTradeCanvasRequestToken || !isParcelTradeCanvasModeActive()) return false;
			const rows = (Array.isArray(data) ? data : []).map(normalizeParcelTradeCanvasRow).filter(Boolean);
			parcelTradeViewportCache.set(boundsKey, rows);
			while (parcelTradeViewportCache.size > PARCEL_TRADE_CANVAS_VIEWPORT_CACHE_MAX) {
				parcelTradeViewportCache.delete(parcelTradeViewportCache.keys().next().value);
			}
			parcelTradeCanvasRows = rows;
			parcelTradeCanvasLoadedBoundsKey = boundsKey;
			parcelTradeCanvasInitialLoaded = true;
			startParcelTradeCanvasReveal();
			return true;
		} catch (error) {
			if (requestToken === parcelTradeCanvasRequestToken) console.warn("현재 화면 실거래 조회 실패:", error);
			return false;
		} finally {
			if (requestToken === parcelTradeCanvasRequestToken) {
				parcelTradeCanvasLoading = false;
				updateParcelTradeLoadButton();
			}
			if (parcelTradeViewportRequests.get(boundsKey) === requestPromise) {
				parcelTradeViewportRequests.delete(boundsKey);
			}
		}
	})();
	parcelTradeViewportRequests.set(boundsKey, requestPromise);
	return await requestPromise;
}

function hideParcelTradeCanvasForZoom()
{
	if (!isParcelTradeCanvasModeActive()) return;
	if (parcelTradeCanvas) parcelTradeCanvas.style.visibility = "hidden";
	if (parcelTradeCanvasMoveFrame && typeof cancelAnimationFrame === "function") {
		cancelAnimationFrame(parcelTradeCanvasMoveFrame);
	}
	parcelTradeCanvasMoveFrame = 0;
}

function bindParcelTradeCanvasMapEvents()
{
	if (parcelTradeCanvasMapBound || !state.map || !window.kakao?.maps?.event) return;
	parcelTradeCanvasMapBound = true;
	parcelTradeCanvasStableLevel = Number(state.map?.getLevel?.());
	kakao.maps.event.addListener(state.map, "zoom_start", hideParcelTradeCanvasForZoom);
	const parcelCanvasMapHost = getParcelTradeCanvasMapElement();
	if (parcelCanvasMapHost) {
		parcelCanvasMapHost.addEventListener("wheel", (event) => {
			const level = Number(state.map?.getLevel?.());
			if (Number.isFinite(level) && level <= 1 && Number(event.deltaY) < 0) return;
			hideParcelTradeCanvasForZoom();
		}, { capture: true, passive: true });
		parcelCanvasMapHost.addEventListener("dblclick", () => {
			const level = Number(state.map?.getLevel?.());
			if (Number.isFinite(level) && level <= 1) return;
			hideParcelTradeCanvasForZoom();
		}, { capture: true, passive: true });
		parcelCanvasMapHost.addEventListener("touchmove", (event) => {
			if (event.touches && event.touches.length > 1) hideParcelTradeCanvasForZoom();
		}, { capture: true, passive: true });
	}
	kakao.maps.event.addListener(state.map, "center_changed", () => {
		if (!isParcelTradeCanvasModeActive()) return;
		const movingLevel = Number(state.map?.getLevel?.());
		if (!Number.isFinite(parcelTradeCanvasStableLevel) || movingLevel !== parcelTradeCanvasStableLevel) {
			hideParcelTradeCanvasForZoom();
			return;
		}
		if (parcelTradeCanvasMoveFrame || typeof requestAnimationFrame !== "function") return;
		parcelTradeCanvasMoveFrame = requestAnimationFrame(() => {
			parcelTradeCanvasMoveFrame = 0;
			drawParcelTradeCanvas();
		});
	});
	kakao.maps.event.addListener(state.map, "dragstart", () => {
		if (parcelTradeCanvas) parcelTradeCanvas.style.visibility = "";
	});
	kakao.maps.event.addListener(state.map, "dragend", async () => {
		if (parcelTradeCanvas) parcelTradeCanvas.style.visibility = "";
		updateParcelTradeLoadButton();
		if (isParcelTradeCanvasModeActive()) {
			const loaded = await loadParcelTradeCanvasRowsForCurrentViewport({ source: "drag-final-viewport" });
			if (!loaded) drawParcelTradeCanvas();
		}
	});
	kakao.maps.event.addListener(state.map, "zoom_changed", async () => {
		parcelTradeCanvasStableLevel = NaN;
		hideParcelTradeCanvasForZoom();
		await syncParcelMapLevelPresentation({ loadInitial: false, source: "zoom-level-change" });
		if (!isParcelTradeCanvasModeActive()) {
			if (parcelTradeCanvas) parcelTradeCanvas.style.visibility = "";
			const settledLevel = Number(state.map?.getLevel?.());
			const settledMode = getParcelMapLevelProfile(settledLevel).presentationMode;
			if (getCurrentRealjejuGlobalCategoryKey() === "parcel"
				&& Number.isFinite(settledLevel)
				&& settledLevel >= 6
				&& shouldRenderParcelRegionTradeMapBadges(settledMode)
				&& !propertyRegionCountOverlays.length) {
				// 5.995: 5→6 전환의 첫 요청이 취소됐으면 클릭을 기다리지 않고 즉시 다시 확정한다.
				parcelRegionTradeBadgeRenderInFlight.clear();
				parcelRegionTradeBadgeRenderedSignature = "";
				await renderPropertyRegionCountOverlays(settledMode);
			}
			return;
		}
		// 5.995: idle 이벤트를 뒤늦게 기다리지 않고 확대·축소 완료 시점에 바로 복구한다.
		await loadParcelTradeCanvasRowsForCurrentViewport({ source: "zoom-final-viewport" });
		parcelTradeCanvasStableLevel = Number(state.map?.getLevel?.());
		if (parcelTradeCanvas) parcelTradeCanvas.style.visibility = "";
		drawParcelTradeCanvas();
	});
	kakao.maps.event.addListener(state.map, "mousemove", (mouseEvent) => {
		const host = getParcelTradeCanvasMapElement();
		if (host && isParcelTradeCanvasModeActive()) host.style.cursor = getParcelTradeCanvasHit(mouseEvent) ? "pointer" : "";
	});
	window.addEventListener("resize", drawParcelTradeCanvas, { passive: true });
}

async function syncParcelTradeCanvasForCategory(category, options = {})
{
	ensureParcelTradeCanvas();
	ensureParcelTradeLoadButton();
	bindParcelTradeCanvasMapEvents();
	if (category === "parcel" && !parcelTradeSatelliteInitializedForSession) {
		parcelTradeSatelliteInitializedForSession = true;
		propertyHomeMapTypeInitializedForSession = false;
		applyMapTypeMode("satellite");
	} else if (category === "realestate" && !propertyHomeMapTypeInitializedForSession) {
		propertyHomeMapTypeInitializedForSession = true;
		parcelTradeSatelliteInitializedForSession = false;
		applyMapTypeMode("roadmap");
	} else if (category !== "parcel" && category !== "realestate") {
		parcelTradeSatelliteInitializedForSession = false;
		propertyHomeMapTypeInitializedForSession = false;
	}
	return await syncParcelMapLevelPresentation({
		loadInitial: category === "parcel",
		source: "category-entry"
	});
}

function clearParcelTradeCanvasSession()
{
	parcelTradeSatelliteInitializedForSession = false;
	if (parcelTradeCanvasViewportIdleHandler && state.map && window.kakao?.maps?.event) {
		kakao.maps.event.removeListener(state.map, "idle", parcelTradeCanvasViewportIdleHandler);
	}
	parcelTradeCanvasViewportIdleHandler = null;
	parcelTradeCanvasStableLevel = NaN;
	if (parcelTradeCanvasMoveFrame && typeof cancelAnimationFrame === "function") {
		cancelAnimationFrame(parcelTradeCanvasMoveFrame);
	}
	parcelTradeCanvasMoveFrame = 0;
	if (parcelTradeCanvasRevealFrame && typeof cancelAnimationFrame === "function") {
		cancelAnimationFrame(parcelTradeCanvasRevealFrame);
	}
	parcelTradeCanvasRevealFrame = 0;
	parcelTradeCanvasRevealStartedAt = 0;
	parcelTradeCanvasRequestToken += 1;
	parcelTradeCanvasRows = [];
	parcelTradeCanvasHitBoxes = [];
	parcelTradeCanvasLoadedBoundsKey = "";
	parcelTradeCanvasInitialLoaded = false;
	parcelTradeCanvasLoading = false;
	parcelTradeViewportRequests.clear();
	window.__realjejuSelectedParcelTradeMarker = null;
	parcelTradeViewportCache.clear();
	if (parcelTradeCanvasContext && parcelTradeCanvas) parcelTradeCanvasContext.clearRect(0, 0, parcelTradeCanvas.width, parcelTradeCanvas.height);
	if (parcelTradeCanvas) parcelTradeCanvas.hidden = true;
	if (parcelTradeLoadButton) parcelTradeLoadButton.hidden = true;
}

function initRoadview()
{
	if (roadviewClient && roadviewOverlay && roadview) return true;
	if (
		!window.kakao
		|| !kakao.maps
		|| typeof kakao.maps.Roadview !== "function"
		|| typeof kakao.maps.RoadviewClient !== "function"
	) {
		return false;
	}

	roadviewClient = new kakao.maps.RoadviewClient();

	const roadviewContainer = document.createElement("div");
	roadviewContainer.id = "roadviewPanel";
	roadviewContainer.className = "roadview-overlay";

	const closeBtn = document.createElement("button");
	closeBtn.type = "button";
	closeBtn.className = "roadview-close-btn";
	closeBtn.setAttribute("aria-label", "로드뷰 닫기");
	closeBtn.innerHTML = '<i class="fa-solid fa-xmark" aria-hidden="true"></i>';

	const fullscreenBtn = document.createElement("button");
	fullscreenBtn.type = "button";
	fullscreenBtn.className = "roadview-fullscreen-btn";
	fullscreenBtn.setAttribute("aria-label", "로드뷰 전체화면");
	fullscreenBtn.title = "전체화면";
	fullscreenBtn.innerHTML = '<i class="fa-solid fa-expand" aria-hidden="true"></i>';

	const inner = document.createElement("div");
	inner.id = "roadviewInner";
	inner.className = "roadview-inner";

	closeBtn.addEventListener("click", async () => {
		await closeRoadviewPanel();
	});

	fullscreenBtn.addEventListener("click", async () => {
		try {
			if (!document.fullscreenElement) {
				await roadviewContainer.requestFullscreen();
			} else {
				await document.exitFullscreen();
			}
		} catch (err) {
			console.error("전체화면 전환 실패:", err);
		}
	});

	document.addEventListener("fullscreenchange", () => {
		if (!roadviewFullscreenBtn) return;
		const isFullscreen = document.fullscreenElement === roadviewOverlay;
		roadviewFullscreenBtn.innerHTML = isFullscreen
			? '<i class="fa-solid fa-compress" aria-hidden="true"></i>'
			: '<i class="fa-solid fa-expand" aria-hidden="true"></i>';
		roadviewFullscreenBtn.setAttribute("aria-label", isFullscreen ? "로드뷰 전체화면 해제" : "로드뷰 전체화면");
		roadviewFullscreenBtn.title = isFullscreen ? "전체화면 해제" : "전체화면";
	});

	roadviewContainer.appendChild(closeBtn);
	roadviewContainer.appendChild(fullscreenBtn);
	roadviewContainer.appendChild(inner);
	getRoadviewHost().appendChild(roadviewContainer);

	roadview = new kakao.maps.Roadview(inner);
	kakao.maps.event.addListener(roadview, "position_changed", function () {
		if (!isRoadviewPanelOpen()) return;
		if (!roadview || typeof roadview.getPosition !== "function") return;
		clearRoadviewPickOverlay();
		const useDetailLeftRoadview = !!(roadviewOverlay && roadviewOverlay.classList.contains("detail-left-roadview"));
		syncRoadviewPositionOnMap(roadview.getPosition(), useDetailLeftRoadview ? { centerOnPosition: true } : { keepVisible: true });
	});
	kakao.maps.event.addListener(roadview, "viewpoint_changed", function () {
		if (!isRoadviewPanelOpen()) return;
		if (!roadview || typeof roadview.getPosition !== "function") return;
		clearRoadviewPickOverlay();
		syncRoadviewDirectionOnMap(roadview.getPosition());
	});
	roadviewOverlay = roadviewContainer;
	roadviewFullscreenBtn = fullscreenBtn;
	return true;
}

function showRoadview(lat, lng, options = {})
{
	if ((!roadviewClient || !roadviewOverlay || !roadview) && !initRoadview()) {
		alert("로드뷰가 초기화되지 않았습니다.");
		return;
	}
	if (document.body?.dataset?.globalCategory === "local-business" && typeof hideLocalBusinessRecentCard === "function") {
		hideLocalBusinessRecentCard();
	}
	if (options && options.clearEducationFacilityDetail && typeof clearEducationFacilityDetailRoadviewBlocker === "function") {
		clearEducationFacilityDetailRoadviewBlocker();
	}

	const position = new kakao.maps.LatLng(lat, lng);
	const searchRadius = Math.max(100, Number(options && options.radius) || 100);
	const mapWrap = document.querySelector(".map-wrap");
	const roadviewHost = getRoadviewHost();
	const useDetailLeftRoadview = !(options && options.forceSplitRoadview) && shouldShowRoadviewBesideDetailPanel();

	roadviewClient.getNearestPanoId(position, searchRadius, function (panoId) {
		if (!panoId) {
			alert("이 위치 주변에는 로드뷰가 없습니다.");
			return;
		}
		if (options && options.evChargerRecent && document.body && document.body.dataset && document.body.dataset.globalCategory === "ev-charger") {
			recordEvChargerRoadviewRecent(options.evChargerRecent);
		}
		if (options && options.clearEducationFacilityDetail && typeof clearEducationFacilityDetailRoadviewBlocker === "function") {
			clearEducationFacilityDetailRoadviewBlocker();
		}
		clearRoadviewPickOverlay();
		if (typeof closeMapFilterDropdownsExcept === "function") closeMapFilterDropdownsExcept(null);
		if (typeof closeAllFilterHelp === "function") closeAllFilterHelp();
		if (typeof closeRightMapToolPanels === "function") closeRightMapToolPanels();

		if (useDetailLeftRoadview) {
			document.body.classList.add("roadview-detail-left-open");
			document.body.classList.remove("roadview-split-open");
			roadviewOverlay.classList.remove("detail-panel-roadview");
			roadviewOverlay.classList.add("detail-left-roadview");
			if (roadviewOverlay.parentElement !== document.body) document.body.appendChild(roadviewOverlay);
			if (mapWrap) mapWrap.classList.remove("is-roadview-open");
		} else {
			if (
				(document.body.classList.contains("detail-page-panel-open") || document.body.classList.contains("shared-detail-mode"))
				&& typeof hardCloseDetailPanel === "function"
			) {
				hardCloseDetailPanel();
			}
			document.body.classList.remove("detail-page-panel-open", "shared-detail-mode", "list-shared-detail-mode", "roadview-detail-left-open");
			document.body.classList.add("roadview-split-open");
			roadviewOverlay.classList.remove("detail-panel-roadview", "detail-left-roadview");
			if (roadviewHost && roadviewOverlay.parentElement !== roadviewHost) roadviewHost.appendChild(roadviewOverlay);
			if (mapWrap) {
				mapWrap.classList.add("is-roadview-open");
			}
		}
		restoreRoadviewOverlayForRoadviewOpen();
		roadviewOverlay.classList.add("open");
		if (typeof updateMapPanelToggleState === "function") updateMapPanelToggleState();
		syncRoadviewTopbarVisibility();
		requestAnimationFrame(syncRoadviewTopbarVisibility);
		setTimeout(syncRoadviewTopbarVisibility, 80);
		clearRoadviewPickOverlay();
		const syncOptions = useDetailLeftRoadview ? { centerOnPosition: true } : { keepVisible: true };
		roadview.setPanoId(panoId, position);
		clearRoadviewPickOverlay();
		refreshRoadviewSplitLayout({ preserveMapCenter: false });
		syncRoadviewPositionOnMap(position, syncOptions);
		setTimeout(() => syncRoadviewPositionOnMap(roadview.getPosition ? roadview.getPosition() : position, syncOptions), 40);
		setTimeout(() => syncRoadviewPositionOnMap(roadview.getPosition ? roadview.getPosition() : position, syncOptions), 140);
	});
}

function clearMapObjects(options = {})
{
	if (state.clusterer) {
		state.clusterer.clear();
	}
	if (options.preserveParcelBoundary !== true) clearParcelBoundaryOverlays();

	state.markers.forEach(marker => marker.setMap(null));
	state.markers = [];
	state.markerRenderSignature = "";
}

function highlightCard(id)
{
	document.querySelectorAll(".card").forEach(card => {
		card.classList.toggle("active", normalizeItemId(card.dataset.id) === normalizeItemId(id));
	});
}



function clearBrokerOfficeOverlays()
{
	hideBrokerOfficeMapTooltip();
	const overlays = state.brokerOfficeOverlayMap instanceof Map
		? Array.from(state.brokerOfficeOverlayMap.values())
		: (state.brokerOfficeOverlays || []);
	overlays.forEach((overlay) => {
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	state.brokerOfficeOverlays = [];
	state.brokerOfficeTopListingCrownKeys = new Set();
}

function normalizeJejuLatLngPair(latValue, lngValue)
{
	const lat = Number(latValue);
	const lng = Number(lngValue);
	if (Number.isFinite(lat) && Number.isFinite(lng)
		&& lat >= 32.8 && lat <= 34.1
		&& lng >= 125.8 && lng <= 127.2) {
		return { lat, lng };
	}
	if (Number.isFinite(lat) && Number.isFinite(lng)
		&& lng >= 32.8 && lng <= 34.1
		&& lat >= 125.8 && lat <= 127.2) {
		return { lat: lng, lng: lat };
	}
	return null;
}

function normalizeBrokerOfficeMapRow(row, options = {})
{
	if (!row) return null;
	const address = String(row.office_address || "").trim();
	const officeName = String(row.office_name || "공인중개사무소").trim();
	const normalizedPosition = normalizeJejuLatLngPair(row.lat, row.lng);
	if (!address || !officeName) return null;
	if (options.requireCoordinates !== false && !normalizedPosition) return null;
	return {
		id: normalizeItemId(row.id || row.user_id || officeName),
		agencyId: normalizeItemId(row.agency_id || ""),
		publicId: normalizeRealjejuAgencyPublicId(row.public_id || ""),
		userId: normalizeItemId(row.user_id || ""),
		officeName,
		ownerName: String(row.broker_name || row.owner_name || "").trim(),
		address,
		phone: String(row.phone || "").trim(),
		regNo: String(row.office_reg_no || row.registration_no || row.reg_no || row.license_no || "").trim(),
		kakaoUrl: String(row.kakao_url || row.kakaoUrl || row.kakao || row.kakao_open_chat || row.kakao_open_chat_url || row.open_chat_url || "").trim(),
		profileImage: getBrokerOfficeProfileImageCandidate(row),
		lat: normalizedPosition ? normalizedPosition.lat : null,
		lng: normalizedPosition ? normalizedPosition.lng : null
	};
}

function getBrokerOfficeProfileImageCandidate(source)
{
	if (!source || typeof source !== "object") return "";
	const payload = source.payload && typeof source.payload === "object" ? source.payload : {};
	const registrant = payload.registrant && typeof payload.registrant === "object" ? payload.registrant : {};
	const profile = source.profile && typeof source.profile === "object" ? source.profile : {};
	const candidates = [
		source.profileImage,
		source.profile_image,
		source.profile_photo,
		source.profileImageUrl,
		source.profile_image_url,
		source.agent_image,
		source.agentImage,
		source.avatar_url,
		source.picture,
		profile.profile_image,
		profile.profile_photo,
		profile.avatar_url,
		payload.agent_image,
		payload.agentImage,
		payload.profile_image,
		payload.profileImage,
		registrant.agent_image,
		registrant.agentImage,
		registrant.profile_image,
		registrant.profileImage,
		registrant.avatar_url
	];
	for (const value of candidates) {
		const image = String(value || "").trim();
		if (isUsableBrokerOfficeProfileImageUrl(image)) return image;
	}
	return "";
}

function formatBrokerOfficeDisplayAddress(value)
{
	const address = String(value || "").replace(/\s+/g, " ").trim();
	if (!address) return "";
	return address
		.replace(/^(?:제주특별자치도|제주도)\s+(?=(?:제주시|서귀포시)(?:\s|$))/, "")
		.trim();
}

function normalizeAgencyBrokerOfficeSeedRow(row)
{
	if (!row || row.deleted_at) return null;
	const status = getBrokerOfficeRowStatus(row);
	if (status !== "active") return null;
	const officeName = String(row.office_name || "").trim();
	const address = String(row.office_address || row.address || row.office_addr || "").trim();
	const normalizedPosition = normalizeJejuLatLngPair(
		row.lat ?? row.latitude ?? row.office_lat,
		row.lng ?? row.longitude ?? row.office_lng
	);
	if (!officeName || !address) return null;
	return {
		id: normalizeItemId(row.id || row.user_id || officeName),
		agencyId: normalizeItemId(row.id || ""),
		publicId: normalizeRealjejuAgencyPublicId(row.public_id || ""),
		userId: normalizeItemId(row.user_id || ""),
		officeName,
		ownerName: String(row.owner_name || "").trim(),
		address,
		phone: String(row.phone || "").trim(),
		regNo: String(row.office_reg_no || row.registration_no || row.reg_no || row.license_no || "").trim(),
		kakaoUrl: String(row.kakao_url || row.kakaoUrl || row.kakao || row.kakao_open_chat || row.kakao_open_chat_url || row.open_chat_url || "").trim(),
		profileImage: getBrokerOfficeProfileImageCandidate(row),
		lat: normalizedPosition ? normalizedPosition.lat : null,
		lng: normalizedPosition ? normalizedPosition.lng : null,
		sourceTable: "agencies"
	};
}

async function fetchAgencyRowsForBrokerOfficeMap(client, selectFields)
{
	if (!client) return { data: [], error: null };
	return client
		.from("agencies")
		.select(selectFields)
		.is("deleted_at", null)
		.order("updated_at", { ascending: false });
}

function isMissingAgencyLatLngColumnError(error)
{
	const message = String(error && (error.message || error.details || "") || "");
	return /column\s+agencies\.(lat|lng)\s+does\s+not\s+exist/i.test(message)
		|| /Could not find the '(lat|lng)' column of 'agencies'/i.test(message);
}

async function fetchBrokerOfficeSeedRowsFromAgencies(client)
{
	if (!client) return [];
	const legacyBaseFields = "id,user_id,office_name,owner_name,office_reg_no,office_address,phone,kakao_url,status,deleted_at,updated_at";
	const fieldAttempts = [
		legacyBaseFields + ",lat,lng",
		legacyBaseFields
	];
	let data = [];
	let error = null;
	for (const fields of fieldAttempts) {
		({ data, error } = await fetchAgencyRowsForBrokerOfficeMap(client, fields));
		if (!error) break;
		if (!isMissingAgencyLatLngColumnError(error)) break;
	}
	if (error) {
		console.warn("기존 중개사무소 초기 동기화 조회 실패:", error);
		return [];
	}
	return (Array.isArray(data) ? data : []).map(normalizeAgencyBrokerOfficeSeedRow).filter(Boolean);
}

function getBrokerOfficeMergeKey(office)
{
	if (!office) return "";
	const agencyId = normalizeItemId(office.agencyId || "");
	const userId = normalizeItemId(office.userId || "");
	const officeName = normalizeAgentOfficeKey(office.officeName || "");
	const addressKey = getBrokerOfficeBaseAddressKey(office.address || "");
	if (agencyId) return `agency:${agencyId}`;
	if (userId) return `user:${userId}`;
	if (officeName && addressKey) return `office:${officeName}:${addressKey}`;
	if (officeName) return `office:${officeName}`;
	return "";
}

function mergeBrokerOfficeMapRows(locationRows, agencyRows)
{
	const merged = new Map();
	const fillMissingBrokerOfficeFields = (current, next) => {
		const output = { ...(current || {}) };
		const source = next || {};
		[
			"id",
			"agencyId",
			"publicId",
			"userId",
			"officeName",
			"ownerName",
			"address",
			"phone",
			"regNo",
			"kakaoUrl",
			"profileImage",
			"sourceTable"
		].forEach((key) => {
			if (!String(output[key] ?? "").trim() && String(source[key] ?? "").trim()) {
				output[key] = source[key];
			}
		});
		const currentPosition = normalizeJejuLatLngPair(output.lat, output.lng);
		const nextPosition = normalizeJejuLatLngPair(source.lat, source.lng);
		if (!currentPosition && nextPosition) {
			output.lat = nextPosition.lat;
			output.lng = nextPosition.lng;
		}
		return output;
	};
	const put = (office, preferExisting = true) => {
		if (!office) return;
		const key = getBrokerOfficeMergeKey(office);
		if (!key) return;
		const current = merged.get(key);
		if (!current || !preferExisting) {
			merged.set(key, office);
			return;
		}
		const currentHasPosition = !!normalizeJejuLatLngPair(current.lat, current.lng);
		const nextHasPosition = !!normalizeJejuLatLngPair(office.lat, office.lng);
		const nextIsAgencyWithPosition = office.sourceTable === "agencies" && nextHasPosition;
		if ((!currentHasPosition && nextHasPosition) || nextIsAgencyWithPosition) {
			merged.set(key, fillMissingBrokerOfficeFields({ ...current, ...office }, current));
			return;
		}
		merged.set(key, fillMissingBrokerOfficeFields(current, office));
	};
	(locationRows || []).forEach(office => put(office, true));
	(agencyRows || []).forEach(office => put(office, true));
	return Array.from(merged.values());
}

async function fetchBrokerOfficeMapRows(options = {})
{
	if (typeof shouldLoadBrokerOfficeMapDataForCurrentPage === "function" && !shouldLoadBrokerOfficeMapDataForCurrentPage()) return [];
	const previousRows = Array.isArray(state.brokerOfficeRows) ? state.brokerOfficeRows : [];
	if (!options.force && !previousRows.length && Date.now() < Number(state.brokerOfficeRowsEmptyRetryAt || 0)) return previousRows;
	const profileImagesHydratedRecently = Date.now() - Number(state.brokerOfficeProfileImagesHydratedAt || 0) < 60000;
	const hasMissingProfileImage = previousRows.some(office => !getBrokerOfficeProfileImageCandidate(office || {}));
	if (!options.force && previousRows.length && (!hasMissingProfileImage || profileImagesHydratedRecently)) return previousRows;
	if (!options.force && state.brokerOfficeRowsLoadPromise) return state.brokerOfficeRowsLoadPromise;
	const loadPromise = (async () => {
		let client = getRealjejuSupabaseClient();
		if (!client && typeof loadSupabaseScript === "function") {
			try {
				await loadSupabaseScript();
				client = getRealjejuSupabaseClient();
			} catch (error) {
				console.warn("중개사무소 지도 데이터 연결 준비 실패:", error);
			}
		}
		if (!client) {
			state.brokerOfficeRowsEmptyRetryAt = Date.now() + 3000;
			return previousRows;
		}
		const { data, error } = await client
			.from("broker_office_locations")
			.select("id,user_id,agency_id,broker_name,office_name,office_reg_no,phone,office_address,kakao_url,profile_image,lat,lng,updated_at")
			.order("updated_at", { ascending: false });
		if (error) {
			console.warn("중개사무소 지도 표시 조회 실패:", error);
			const fallbackRows = await hydrateBrokerOfficeRowsWithProfileImages(client, previousRows);
			const committedRows = commitBrokerOfficeProfileImageRows(fallbackRows);
			state.brokerOfficeRowsEmptyRetryAt = committedRows.length ? 0 : Date.now() + 3000;
			return committedRows;
		}
		const agencyRows = await fetchBrokerOfficeSeedRowsFromAgencies(client);
		const activeAgencyIds = new Set(agencyRows.map(office => normalizeItemId(office && office.agencyId)).filter(Boolean));
		const activeUserIds = new Set(agencyRows.map(office => normalizeItemId(office && office.userId)).filter(Boolean));
		const normalizedLocationRows = (Array.isArray(data) ? data : []).map(row => {
			const office = normalizeBrokerOfficeMapRow(row, { requireCoordinates: false });
			return office ? { ...office, sourceTable: "broker_office_locations" } : null;
		}).filter(Boolean);
		if (normalizedLocationRows.length && !agencyRows.length) {
			if (!previousRows.length) state.brokerOfficeRows = null;
			return previousRows;
		}
		const locationRows = normalizedLocationRows.filter(office => {
			if (!office) return false;
			const agencyId = normalizeItemId(office.agencyId || "");
			const userId = normalizeItemId(office.userId || "");
			return (agencyId && activeAgencyIds.has(agencyId)) || (userId && activeUserIds.has(userId));
		});
		const rows = await hydrateBrokerOfficeRowsWithProfileImages(client, mergeBrokerOfficeMapRows(locationRows, agencyRows));
		if (rows.length) {
			state.brokerOfficeRowsEmptyRetryAt = 0;
			return commitBrokerOfficeProfileImageRows(rows);
		}
		if (!previousRows.length) state.brokerOfficeRows = null;
		state.brokerOfficeRowsEmptyRetryAt = Date.now() + 3000;
		return previousRows;
	})();
	state.brokerOfficeRowsLoadPromise = loadPromise;
	try {
		return await loadPromise;
	} finally {
		if (state.brokerOfficeRowsLoadPromise === loadPromise) state.brokerOfficeRowsLoadPromise = null;
	}
}

async function enrichBrokerOfficeRowsWithProfileImages(client, rows)
{
	const sourceRows = Array.isArray(rows) ? rows : [];
	const profileUserIds = [...new Set(sourceRows
		.filter(office => office)
		.map(office => normalizeItemId(office.userId))
		.filter(Boolean))];
	if (!client) return sourceRows;
	if (!profileUserIds.length) return enrichBrokerOfficeRowsWithListingProfileImages(client, sourceRows);
	try {
		const profileByUserId = new Map();
		profileUserIds.forEach((userId) => {
			const cachedProfile = mapListingOwnerCache && mapListingOwnerCache.profilesByUserId
				? mapListingOwnerCache.profilesByUserId.get(userId)
				: null;
			if (cachedProfile) profileByUserId.set(userId, cachedProfile);
		});
		const missingProfileUserIds = profileUserIds.filter(userId => !profileByUserId.has(userId));
		if (missingProfileUserIds.length) {
			const { data, error } = await client
				.from("profiles")
				.select("id, profile_image, role_request")
				.in("id", missingProfileUserIds);
			if (error) {
				console.warn("중개사 지도 프로필 사진 조회 실패:", error);
			} else {
				(Array.isArray(data) ? data : []).forEach((profile) => {
					const key = normalizeItemId(profile && profile.id);
					if (!key) return;
					profileByUserId.set(key, profile || {});
					if (typeof cacheMapListingProfile === "function") cacheMapListingProfile(profile);
				});
			}
		}
		const profileEnrichedRows = sourceRows.map(office => {
			const userId = normalizeItemId(office && office.userId);
			const profile = userId ? profileByUserId.get(userId) : null;
			const image = getBrokerOfficeProfileImageCandidate(profile || {});
			return image && !getBrokerOfficeProfileImageCandidate(office || {}) ? { ...office, profileImage: image } : office;
		});
		return enrichBrokerOfficeRowsWithListingProfileImages(client, profileEnrichedRows);
	} catch (error) {
		console.warn("중개사 지도 프로필 사진 조회 오류:", error);
		return enrichBrokerOfficeRowsWithListingProfileImages(client, sourceRows);
	}
}

function getBrokerOfficeProfileImageLookupKeys(office)
{
	if (!office) return [];
	return [
		normalizeItemId(office.agencyId || office.agency_id),
		normalizeItemId(office.userId || office.user_id),
		normalizeAgentOfficeKey(office.officeName || office.office_name || office.rawOfficeName)
	].filter(Boolean);
}

function buildBrokerOfficeListingProfileImageMap(rows)
{
	const map = new Map();
	(Array.isArray(rows) ? rows : []).forEach((row) => {
		if (!row) return;
		const image = getBrokerOfficeProfileImageCandidate({
			agent_image: row.payload_agent_image,
			agentImage: row.payload_agent_image_camel,
			payload: {
				registrant: {
					agent_image: row.payload_registrant_agent_image,
					agentImage: row.payload_registrant_agent_image_camel,
					profile_image: row.payload_registrant_profile_image,
					profileImage: row.payload_registrant_profile_image_camel
				}
			}
		});
		if (!image) return;
		[
			normalizeItemId(row.agency_id),
			normalizeItemId(row.user_id),
			normalizeAgentOfficeKey(row.payload_registrant_office_name || "")
		].filter(Boolean).forEach((key) => {
			if (!map.has(key)) map.set(key, image);
		});
	});
	return map;
}

async function fetchBrokerOfficeListingProfileImageRows(client, fieldName, values)
{
	const keys = [...new Set((values || []).map(value => String(value || "").trim()).filter(Boolean))];
	if (!client || !fieldName || !keys.length) return [];
	const rows = [];
	const selectFields = [
		"id",
		"user_id",
		"agency_id",
		"updated_at",
		"payload_agent_image:payload->>agent_image",
		"payload_agent_image_camel:payload->>agentImage",
		"payload_registrant_agent_image:payload->registrant->>agent_image",
		"payload_registrant_agent_image_camel:payload->registrant->>agentImage",
		"payload_registrant_profile_image:payload->registrant->>profile_image",
		"payload_registrant_profile_image_camel:payload->registrant->>profileImage",
		"payload_registrant_office_name:payload->registrant->>office_name"
	].join(",");
	for (let index = 0; index < keys.length; index += 20) {
		const chunk = keys.slice(index, index + 20);
		const { data, error } = await client
			.from("property_listings")
			.select(selectFields)
			.eq("status", "published")
			.in(fieldName, chunk)
			.order("updated_at", { ascending: false })
			.limit(1000);
		if (error) throw error;
		rows.push(...(Array.isArray(data) ? data : []));
	}
	return rows;
}

async function enrichBrokerOfficeRowsWithListingProfileImages(client, rows)
{
	const sourceRows = Array.isArray(rows) ? rows : [];
	const missingRows = sourceRows.filter(office => !getBrokerOfficeProfileImageCandidate(office || {}));
	if (!client || !missingRows.length) return sourceRows;
	const agencyIds = [...new Set(missingRows.map(office => normalizeItemId(office && office.agencyId)).filter(Boolean))];
	const userIds = [...new Set(missingRows.map(office => normalizeItemId(office && office.userId)).filter(Boolean))];
	try {
		const listingRows = [
			...(agencyIds.length ? await fetchBrokerOfficeListingProfileImageRows(client, "agency_id", agencyIds) : []),
			...(userIds.length ? await fetchBrokerOfficeListingProfileImageRows(client, "user_id", userIds) : [])
		];
		const imageByKey = buildBrokerOfficeListingProfileImageMap(listingRows);
		if (!imageByKey.size) return sourceRows;
		return sourceRows.map((office) => {
			if (getBrokerOfficeProfileImageCandidate(office || {})) return office;
			const image = getBrokerOfficeProfileImageLookupKeys(office).map(key => imageByKey.get(key)).find(Boolean) || "";
			return image ? { ...office, profileImage: image } : office;
		});
	} catch (error) {
		console.warn("중개사 지도 매물 프로필 사진 보강 실패:", error);
		return sourceRows;
	}
}

async function enrichBrokerOfficeRowsWithStoredProfileImages(rows)
{
	const sourceRows = Array.isArray(rows) ? rows : [];
	const missingUserIds = [...new Set(sourceRows
		.filter(office => office && !getBrokerOfficeProfileImageCandidate(office))
		.map(office => normalizeItemId(office.userId || office.user_id))
		.filter(Boolean))];
	if (!missingUserIds.length) return sourceRows;

	const imageByUserId = new Map();
	let cursor = 0;
	const workerCount = Math.min(8, missingUserIds.length);
	const workers = Array.from({ length: workerCount }, async () => {
		while (cursor < missingUserIds.length) {
			const userId = missingUserIds[cursor++];
			const imageUrl = await resolveLatestBrokerProfileImageFromStorage(userId);
			if (imageUrl) imageByUserId.set(userId, imageUrl);
		}
	});
	await Promise.all(workers);
	if (!imageByUserId.size) return sourceRows;

	return sourceRows.map((office) => {
		if (!office || getBrokerOfficeProfileImageCandidate(office)) return office;
		const userId = normalizeItemId(office.userId || office.user_id);
		const profileImage = userId ? imageByUserId.get(userId) : "";
		return profileImage ? { ...office, profileImage, profile_image: profileImage } : office;
	});
}

async function hydrateBrokerOfficeRowsWithProfileImages(client, rows)
{
	const profileRows = await enrichBrokerOfficeRowsWithProfileImages(client, rows);
	return enrichBrokerOfficeRowsWithStoredProfileImages(profileRows);
}

function commitBrokerOfficeProfileImageRows(rows)
{
	const nextRows = Array.isArray(rows) ? rows : [];
	if (!nextRows.length) return nextRows;
	state.brokerOfficeRows = nextRows;
	state.brokerOfficeProfileImagesHydratedAt = Date.now();
	if (state.localBusinessAutoRows && Array.isArray(state.localBusinessAutoRows.brokerOffice)) {
		state.localBusinessAutoRows.brokerOffice = cloneLocalBusinessAutoRows(nextRows);
	}
	return nextRows;
}

async function geocodeBrokerOfficeAddress(geocoder, office)
{
	const existingPosition = normalizeJejuLatLngPair(office.lat, office.lng);
	if (existingPosition) return { ...office, ...existingPosition };
	const queries = buildSubAddressSearchQueries(office.address);
	const applyFoundPosition = (found) => {
		const normalized = normalizeJejuLatLngPair(found && found.y, found && found.x);
		if (!normalized) return null;
		return { ...office, ...normalized };
	};
	for (const q of queries) {
		const found = await searchAddressByGeocoder(geocoder, q);
		const next = applyFoundPosition(found);
		if (next) return next;
	}
	if (kakao.maps.services.Places) {
		const places = new kakao.maps.services.Places();
		for (const q of queries) {
			const found = await searchAddressByKeyword(places, q);
			const next = applyFoundPosition(found);
			if (next) return next;
		}
	}
	const fallbackPosition = getBrokerOfficeListingFallbackPosition(office);
	if (fallbackPosition) return { ...office, ...fallbackPosition };
	console.warn("중개사무소 주소 좌표 변환 실패:", office.officeName, office.address);
	return null;
}

function buildBrokerOfficeAgentFilter(office)
{
	if (!office) return null;
	const officeName = String(office.officeName || "공인중개사").trim();
	return {
		agencyId: normalizeItemId(office.agencyId || ""),
		publicId: normalizeRealjejuAgencyPublicId(office.publicId || office.public_id || ""),
		userId: normalizeItemId(office.userId || ""),
		officeName: normalizeAgentOfficeKey(officeName),
		rawOfficeName: officeName,
		label: officeName
	};
}

function buildBrokerOfficeAgentCard(office)
{
	if (!office) return null;
	return {
		name: String(office.ownerName || "").trim(),
		title: "대표",
		office: String(office.officeName || "").trim(),
		phone: String(office.phone || "").trim(),
		phoneLink: String(office.phone || "").trim(),
		address: String(office.address || "").trim(),
		regNo: String(office.regNo || office.office_reg_no || office.registration_no || office.reg_no || office.license_no || "").trim(),
		image: getBrokerOfficeListingProfileImage(office) || String(office.profileImage || "").trim(),
		userId: normalizeItemId(office.userId || office.user_id),
		kakaoUrl: String(office.kakaoUrl || "").trim(),
		publicId: normalizeRealjejuAgencyPublicId(office.publicId || office.public_id || "")
	};
}

async function openBrokerOfficeListingPanel(office, options = {})
{
	const filter = buildBrokerOfficeAgentFilter(office);
	if (!filter) return;
	const preserveBrokerLayer = options.preserveBrokerLayer !== false;
	const brokerLayerState = {
		visible: !!state.isBrokerOfficesVisible,
		filter: state.brokerOfficeMapFilter || "none"
	};
	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForMapOverlayPanelSwitch === "function") {
		await closeRoadviewPanelForMapOverlayPanelSwitch();
	} else if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}
	// 4.924: 동네업체 중개사 클릭 시 전체 공개 매물을 먼저 내려받지 않는다.
	hideBrokerOfficeMapTooltip();
	await showAgentListingList(filter, buildBrokerOfficeAgentCard(office), {
		clearMapMarkerSelection: true,
		preserveMapMarkerAppearance: options.preserveMapMarkers === true
	});
	if (options.preserveMapMarkers !== true) refreshViewportList();
	state.isBrokerOfficesVisible = preserveBrokerLayer ? brokerLayerState.visible : false;
	state.brokerOfficeMapFilter = preserveBrokerLayer ? brokerLayerState.filter : "none";
	if (state.isBrokerOfficesVisible) {
		bringFacilityOverlayLayerToFront("broker");
		await renderBrokerOfficeOverlays();
	} else {
		clearBrokerOfficeOverlays();
	}
	updateBrokerOfficeToolActiveState();
}

function getWeeklySpecialistBrokerDateKey(date = new Date())
{
	try {
		return new Intl.DateTimeFormat("sv-SE", {
			timeZone: "Asia/Seoul",
			year: "numeric",
			month: "2-digit",
			day: "2-digit"
		}).format(date);
	} catch (error) {
		const fallback = new Date(date.getTime() + (9 * 60 * 60 * 1000));
		return fallback.toISOString().slice(0, 10);
	}
}

function isWeeklySpecialistBrokerDismissedToday()
{
	try {
		return localStorage.getItem(WEEKLY_SPECIALIST_BROKER_HIDE_DATE_KEY) === getWeeklySpecialistBrokerDateKey();
	} catch (error) {
		return false;
	}
}

function setWeeklySpecialistBrokerDismissedToday()
{
	try {
		localStorage.setItem(WEEKLY_SPECIALIST_BROKER_HIDE_DATE_KEY, getWeeklySpecialistBrokerDateKey());
	} catch (error) {
		// localStorage 차단 환경에서는 이번 세션 표시 상태만 사용한다.
	}
}

function hideWeeklySpecialistBrokerPanel(options = {})
{
	if (state.weeklySpecialistBrokerRenderTimer) {
		clearTimeout(state.weeklySpecialistBrokerRenderTimer);
		state.weeklySpecialistBrokerRenderTimer = null;
	}
	if (options.dismissToday) setWeeklySpecialistBrokerDismissedToday();
	if (weeklySpecialistBrokerHideTodayCheck) weeklySpecialistBrokerHideTodayCheck.checked = isWeeklySpecialistBrokerDismissedToday();
	if (!weeklySpecialistBrokerPanel) return;
	weeklySpecialistBrokerPanel.style.display = "none";
	weeklySpecialistBrokerPanel.setAttribute("aria-hidden", "true");
}

function canShowWeeklySpecialistBrokerPanel()
{
	if (!ENABLE_WEEKLY_SPECIALIST_BROKER_PANEL) return false;
	if (!weeklySpecialistBrokerPanel || !weeklySpecialistBrokerList || isWeeklySpecialistBrokerDismissedToday()) return false;
	if (typeof isMapHomeWorkspaceVisible === "function" && !isMapHomeWorkspaceVisible()) return false;
	if (!document.body) return true;
	if (state && state.isListOpen) return false;
	if (document.body.classList.contains("map-panels-collapsed")) return false;
	if (document.body.classList.contains("detail-page-panel-open")) return false;
	if (document.body.classList.contains("map-detail-panel-active")) return false;
	return true;
}

function positionWeeklySpecialistBrokerPanel()
{
	if (!weeklySpecialistBrokerPanel) return;
	const parent = weeklySpecialistBrokerPanel.offsetParent || document.body;
	const parentRect = parent && parent.getBoundingClientRect ? parent.getBoundingClientRect() : { left: 0, top: 0, width: window.innerWidth };
	const filterTrigger = document.getElementById("mapRegionFilterTrigger")
		|| document.querySelector(".global-topbar-menu.has-map-filters .map-region-filter-trigger")
		|| document.querySelector(".map-filter-bar .extra-filter-trigger");
	const unitTool = document.getElementById("areaUnitToolGroup") || document.getElementById("areaUnitToggleBtn");
	const computed = window.getComputedStyle ? window.getComputedStyle(weeklySpecialistBrokerPanel) : null;
	const cssPanelWidth = computed ? Number.parseFloat(computed.getPropertyValue("--weekly-specialist-panel-width")) : 0;
	const panelWidth = weeklySpecialistBrokerPanel.offsetWidth || cssPanelWidth || 236;
	if (filterTrigger && filterTrigger.getBoundingClientRect) {
		const rect = filterTrigger.getBoundingClientRect();
		const maxLeft = Math.max(0, (parentRect.width || window.innerWidth) - panelWidth - 12);
		const left = Math.max(12, Math.min(Math.round(rect.left - parentRect.left), maxLeft));
		weeklySpecialistBrokerPanel.style.setProperty("--weekly-specialist-panel-left", left + "px");
	}
	const topAnchor = unitTool && unitTool.getBoundingClientRect ? unitTool : filterTrigger;
	if (topAnchor && topAnchor.getBoundingClientRect) {
		const rect = topAnchor.getBoundingClientRect();
		const top = Math.max(12, Math.round(rect.bottom - parentRect.top));
		weeklySpecialistBrokerPanel.style.setProperty("--weekly-specialist-panel-top", top + "px");
	}
}

function getWeeklySpecialistBrokerOption(key)
{
	return BROKER_OFFICE_MAP_FILTER_OPTIONS.find(option => option.key === key) || null;
}

function getWeeklySpecialistBrokerStatCount(stat, key)
{
	return Math.max(0, Number(stat && stat.counts && stat.counts[key]) || 0);
}

function isWeeklySpecialistBrokerStatEligible(stat, key)
{
	const count = getWeeklySpecialistBrokerStatCount(stat, key);
	if (count <= 0) return false;
	if (stat && stat.specialtyFlags && stat.specialtyFlags[key]) return true;
	const total = Math.max(0, Number(stat && stat.total) || 0);
	const savedRatio = Number(stat && stat.ratios && stat.ratios[key]);
	const ratio = Number.isFinite(savedRatio) && savedRatio > 0 ? savedRatio : (total > 0 ? count / total : 0);
	return count >= BROKER_SPECIALTY_MIN_LISTINGS && ratio >= BROKER_SPECIALTY_RATIO;
}

function buildWeeklySpecialistStatsFromBrokerOffices(officeRows)
{
	return (Array.isArray(officeRows) ? officeRows : []).map((office) => {
		const stats = getBrokerOfficeSpecialtyStats(office);
		const total = Math.max(0, Number(stats && stats.total) || 0);
		if (!total) return null;
		const counts = {};
		const ratios = {};
		const specialtyFlags = {};
		BROKER_SPECIALTY_STAT_KEYS.forEach((key) => {
			const count = Math.max(0, Number(stats && stats.counts && stats.counts[key]) || 0);
			const ratio = total > 0 ? count / total : 0;
			counts[key] = count;
			ratios[key] = ratio;
			specialtyFlags[key] = count > 0 && count >= BROKER_SPECIALTY_MIN_LISTINGS && ratio >= BROKER_SPECIALTY_RATIO;
		});
		const agencyId = normalizeItemId(office && (office.agencyId || office.agency_id));
		const userId = normalizeItemId(office && (office.userId || office.user_id));
		const officeName = String(office && (office.officeName || office.office_name || office.rawOfficeName) || "").trim();
		const officeNameKey = normalizeBrokerSpecialtyOfficeKey(officeName);
		const statKey = agencyId ? "agency:" + agencyId : (officeNameKey ? "office:" + officeNameKey : (userId ? "user:" + userId : ""));
		return {
			statKey,
			agencyId,
			userId,
			officeName,
			officeNameKey,
			total,
			counts,
			ratios,
			specialtyFlags,
			source: "office"
		};
	}).filter(stat => stat && stat.statKey);
}

function getWeeklySpecialistBrokerOffice(stat, officeRows)
{
	const sourceRows = Array.isArray(officeRows) ? officeRows : [];
	const statAgencyId = normalizeItemId(stat && stat.agencyId);
	const statUserId = normalizeItemId(stat && stat.userId);
	const statOfficeName = String(stat && (stat.officeName || stat.officeNameKey) || "").trim();
	const found = sourceRows.find((office) => {
		if (!office) return false;
		const agencyId = normalizeItemId(office.agencyId || office.agency_id);
		const userId = normalizeItemId(office.userId || office.user_id);
		const officeName = office.officeName || office.office_name || office.rawOfficeName;
		return !!(
			(statAgencyId && agencyId && statAgencyId === agencyId)
			|| (statUserId && userId && statUserId === userId)
			|| (statOfficeName && officeName && brokerSpecialtyOfficeNamesMatch(statOfficeName, officeName))
		);
	});
	if (found) return found;
	return {
		agencyId: statAgencyId,
		userId: statUserId,
		officeName: statOfficeName || "공인중개사",
		rawOfficeName: statOfficeName || "공인중개사",
		ownerName: "",
		address: "",
		phone: "",
		regNo: "",
		profileImage: ""
	};
}

function getWeeklySpecialistBrokerSections(statsRows, officeRows)
{
	const rows = Array.isArray(statsRows) ? statsRows : [];
	return BROKER_SPECIALTY_STAT_KEYS.map((key) => {
		const option = getWeeklySpecialistBrokerOption(key);
		if (!option) return null;
		const entries = rows
			.filter(stat => isWeeklySpecialistBrokerStatEligible(stat, key))
			.sort((a, b) => {
				const awardDiff = getBrokerSpecialtyAwardCount(b, key) - getBrokerSpecialtyAwardCount(a, key);
				if (awardDiff) return awardDiff;
				const countDiff = getWeeklySpecialistBrokerStatCount(b, key) - getWeeklySpecialistBrokerStatCount(a, key);
				if (countDiff) return countDiff;
				return (Number(b.total) || 0) - (Number(a.total) || 0);
			})
			.slice(0, WEEKLY_SPECIALIST_BROKER_LIMIT_PER_CATEGORY)
			.map((stat) => ({
				key,
				option,
				stat,
				office: getWeeklySpecialistBrokerOffice(stat, officeRows),
				listingCount: getWeeklySpecialistBrokerStatCount(stat, key),
				awardCount: Math.max(1, getBrokerSpecialtyAwardCount(stat, key) || 1)
			}));
		return entries.length ? { key, option, entries } : null;
	}).filter(Boolean);
}

function renderWeeklySpecialistBrokerStars(count)
{
	const safeCount = Math.max(1, Number(count) || 1);
	const bigCount = Math.floor(safeCount / 5);
	const smallCount = safeCount % 5;
	const pieces = [];
	for (let i = 0; i < bigCount; i += 1) {
		pieces.push('<i class="fa-solid fa-star weekly-specialist-star big" aria-hidden="true"></i>');
	}
	for (let i = 0; i < smallCount; i += 1) {
		pieces.push('<i class="fa-solid fa-star weekly-specialist-star" aria-hidden="true"></i>');
	}
	return pieces.join("");
}

function getWeeklySpecialistBrokerDisplayName(name)
{
	const source = String(name || "").trim();
	const cleaned = source
		.replace(/\s*(?:공인중개사사무소|공인중개사무소|공인중개사|부동산중개법인|부동산중개|중개법인|중개사무소|사무소)\s*$/g, "")
		.replace(/\s+/g, " ")
		.trim();
	return cleaned || source || "공인중개사";
}

function renderWeeklySpecialistBrokerCard(entry, index)
{
	const office = entry && entry.office ? entry.office : {};
	const officeName = String(office.officeName || office.office_name || office.rawOfficeName || "공인중개사").trim();
	const displayOfficeName = getWeeklySpecialistBrokerDisplayName(officeName);
	const profileImage = getBrokerOfficeListingProfileImage(office);
	const brokerUserId = normalizeItemId(office.userId || office.user_id);
	const iconHtml = profileImage
		? '<img class="broker-office-map-marker-photo" src="' + escapeHtml(profileImage) + '" data-broker-user-id="' + escapeHtml(brokerUserId) + '" alt="" decoding="async">'
		: '<i class="fa-solid fa-user-tie" aria-hidden="true"></i>';
	const countText = Math.max(0, Number(entry && entry.listingCount) || 0).toLocaleString("ko-KR");
	return '<button type="button" class="weekly-specialist-broker-card" data-weekly-specialist-index="'
		+ index
		+ '" aria-label="'
		+ escapeHtml(officeName)
		+ ' 매물 목록 보기">'
		+ '<span class="broker-office-map-marker weekly-specialist-broker-marker" aria-hidden="true">'
		+ '<span class="broker-office-map-marker-badge">'
		+ '<span class="broker-office-map-marker-icon">'
		+ iconHtml
		+ '</span><span class="broker-office-map-marker-count">매물 '
		+ countText
		+ '</span></span></span>'
		+ '<span class="weekly-specialist-broker-name">'
		+ escapeHtml(displayOfficeName)
		+ '</span><span class="weekly-specialist-stars" aria-label="선정 '
		+ Math.max(1, Number(entry && entry.awardCount) || 1)
		+ '회">'
		+ renderWeeklySpecialistBrokerStars(entry && entry.awardCount)
		+ '</span></button>';
}

function renderWeeklySpecialistBrokerSection(section, startIndex)
{
	const title = section.option && section.option.label ? section.option.label : "";
	return '<section class="weekly-specialist-broker-section">'
		+ '<h3>'
		+ escapeHtml(title)
		+ '</h3><div class="weekly-specialist-broker-grid">'
		+ section.entries.map((entry, offset) => renderWeeklySpecialistBrokerCard(entry, startIndex + offset)).join("")
		+ '</div></section>';
}

function bindWeeklySpecialistBrokerPanelEvents()
{
	if (weeklySpecialistBrokerPanel && !weeklySpecialistBrokerPanel.__realjejuWeeklySpecialistBound) {
		weeklySpecialistBrokerPanel.__realjejuWeeklySpecialistBound = true;
		weeklySpecialistBrokerPanel.addEventListener("click", async (event) => {
			const card = event.target.closest("[data-weekly-specialist-index]");
			if (!card) return;
			event.preventDefault();
			event.stopPropagation();
			const index = Number(card.dataset.weeklySpecialistIndex);
			const entry = state.weeklySpecialistBrokerItems[index];
			if (!entry || !entry.office) return;
			hideWeeklySpecialistBrokerPanel();
			await openBrokerOfficeListingPanel(entry.office);
		});
	}
	if (weeklySpecialistBrokerCloseBtn && !weeklySpecialistBrokerCloseBtn.__realjejuWeeklySpecialistBound) {
		weeklySpecialistBrokerCloseBtn.__realjejuWeeklySpecialistBound = true;
		weeklySpecialistBrokerCloseBtn.addEventListener("click", (event) => {
			event.preventDefault();
			event.stopPropagation();
			hideWeeklySpecialistBrokerPanel();
		});
	}
	if (weeklySpecialistBrokerHideTodayCheck && !weeklySpecialistBrokerHideTodayCheck.__realjejuWeeklySpecialistBound) {
		weeklySpecialistBrokerHideTodayCheck.__realjejuWeeklySpecialistBound = true;
		weeklySpecialistBrokerHideTodayCheck.addEventListener("change", () => {
			if (weeklySpecialistBrokerHideTodayCheck.checked) hideWeeklySpecialistBrokerPanel({ dismissToday: true });
		});
	}
}

async function renderWeeklySpecialistBrokerPanel(options = {})
{
	if (!canShowWeeklySpecialistBrokerPanel()) {
		hideWeeklySpecialistBrokerPanel();
		return;
	}
	if (state.weeklySpecialistBrokerRenderPromise && !options.force) return state.weeklySpecialistBrokerRenderPromise;
	const promise = (async () => {
		try {
			const [loadedStatsRows, officeRows] = await Promise.all([
				loadBrokerSpecialtyStats({ force: !!options.force }),
				fetchBrokerOfficeMapRows({ force: !!options.force }),
				loadBrokerSpecialtyAwardCounts({ force: !!options.force })
			]).then(values => [values[0], values[1]]);
			if (!canShowWeeklySpecialistBrokerPanel()) {
				hideWeeklySpecialistBrokerPanel();
				return;
			}
			const statsRows = Array.isArray(loadedStatsRows) && loadedStatsRows.length
				? loadedStatsRows
				: buildWeeklySpecialistStatsFromBrokerOffices(officeRows);
			const sections = getWeeklySpecialistBrokerSections(statsRows, officeRows);
			const items = [];
			const html = sections.map((section) => {
				const startIndex = items.length;
				items.push(...section.entries);
				return renderWeeklySpecialistBrokerSection(section, startIndex);
			}).join("");
			state.weeklySpecialistBrokerItems = items;
			if (!items.length) {
				weeklySpecialistBrokerList.innerHTML = '<p class="weekly-specialist-empty">전문중개사 집계 데이터가 없습니다.</p>';
				if (weeklySpecialistBrokerHideTodayCheck) weeklySpecialistBrokerHideTodayCheck.checked = false;
				bindWeeklySpecialistBrokerPanelEvents();
				weeklySpecialistBrokerPanel.style.display = "block";
				positionWeeklySpecialistBrokerPanel();
				weeklySpecialistBrokerPanel.setAttribute("aria-hidden", "false");
				return;
			}
			weeklySpecialistBrokerList.innerHTML = html;
			attachBrokerOfficeMarkerImageFallback(weeklySpecialistBrokerList);
			if (weeklySpecialistBrokerHideTodayCheck) weeklySpecialistBrokerHideTodayCheck.checked = false;
			bindWeeklySpecialistBrokerPanelEvents();
			weeklySpecialistBrokerPanel.style.display = "block";
			positionWeeklySpecialistBrokerPanel();
			weeklySpecialistBrokerPanel.setAttribute("aria-hidden", "false");
		} finally {
			state.weeklySpecialistBrokerRenderPromise = null;
		}
	})();
	state.weeklySpecialistBrokerRenderPromise = promise;
	return promise;
}

function scheduleWeeklySpecialistBrokerPanelRender(delay = 180, options = {})
{
	if (!ENABLE_WEEKLY_SPECIALIST_BROKER_PANEL) {
		hideWeeklySpecialistBrokerPanel();
		return;
	}
	if (state.weeklySpecialistBrokerRenderTimer) {
		clearTimeout(state.weeklySpecialistBrokerRenderTimer);
		state.weeklySpecialistBrokerRenderTimer = null;
	}
	state.weeklySpecialistBrokerRenderTimer = setTimeout(() => {
		state.weeklySpecialistBrokerRenderTimer = null;
		renderWeeklySpecialistBrokerPanel(options);
	}, delay);
}

if (typeof document !== "undefined") {
	if (document.readyState === "loading") {
		document.addEventListener("DOMContentLoaded", () => scheduleWeeklySpecialistBrokerPanelRender(900), { once: true });
	} else {
		scheduleWeeklySpecialistBrokerPanelRender(900);
	}
}

if (typeof window !== "undefined") {
	window.addEventListener("resize", () => scheduleWeeklySpecialistBrokerPanelRender(240), { passive: true });
}

function getBrokerOfficeBaseAddressKey(address)
{
	const text = String(address || "")
		.replace(/\([^)]*\)/g, " ")
		.replace(/,/g, " ")
		.replace(/\s+/g, " ")
		.trim();
	const match = text.match(/(?:제주특별자치도\s*)?(?:제주시\s*)?(.+?(?:로|길)\s*\d+(?:-\d+)?)/);
	const keyText = match && match[1] ? match[1] : text;
	return normalizeAgentOfficeKey(keyText).replace(/\s+/g, "");
}

function getBrokerOfficeInfoScore(office)
{
	if (!office) return 0;
	return (String(office.profileImage || "").trim() ? 100 : 0)
		+ (String(office.regNo || "").trim() ? 20 : 0)
		+ (String(office.kakaoUrl || "").trim() ? 15 : 0)
		+ (String(office.phone || "").trim() ? 5 : 0)
		+ (String(office.ownerName || "").trim() ? 3 : 0);
}

function getUniqueBrokerOfficeList(offices)
{
	const unique = new Map();
	(offices || []).forEach((office) => {
		const agencyId = normalizeItemId(office && office.agencyId);
		const userId = normalizeItemId(office && office.userId);
		const id = normalizeItemId(office && office.id);
		const nameKey = normalizeAgentOfficeKey(office && office.officeName);
		const addressKey = getBrokerOfficeBaseAddressKey(office && office.address);
		const key = agencyId
			? `agency:${agencyId}`
			: userId
				? `user:${userId}`
				: id
					? `id:${id}`
					: nameKey
						? `office:${nameKey}:${addressKey}`
						: "";
		if (!key) return;
		const current = unique.get(key);
		if (!current || getBrokerOfficeInfoScore(office) > getBrokerOfficeInfoScore(current)) {
			unique.set(key, office);
		}
	});
	return Array.from(unique.values());
}

// 
// 7. 중개사/전문중개사 지도 레이어
// 

let brokerOfficeMapTooltipLayer = null;
let brokerOfficeMapTooltipHideTimer = null;

function cancelBrokerOfficeMapTooltipHide()
{
	if (!brokerOfficeMapTooltipHideTimer) return;
	clearTimeout(brokerOfficeMapTooltipHideTimer);
	brokerOfficeMapTooltipHideTimer = null;
}

function hideBrokerOfficeMapTooltip()
{
	if (!brokerOfficeMapTooltipLayer) return;
	brokerOfficeMapTooltipLayer.classList.remove("open");
	brokerOfficeMapTooltipLayer.style.visibility = "hidden";
	brokerOfficeMapTooltipLayer.style.pointerEvents = "none";
	brokerOfficeMapTooltipLayer.__brokerOffices = [];
	brokerOfficeMapTooltipLayer.__professionalBusiness = null;
	brokerOfficeMapTooltipLayer.innerHTML = "";
}

function scheduleBrokerOfficeMapTooltipHide()
{
	cancelBrokerOfficeMapTooltipHide();
	brokerOfficeMapTooltipHideTimer = setTimeout(hideBrokerOfficeMapTooltip, 140);
}

function ensureBrokerOfficeMapTooltipLayer()
{
	if (brokerOfficeMapTooltipLayer) return brokerOfficeMapTooltipLayer;
	brokerOfficeMapTooltipLayer = document.createElement("div");
	brokerOfficeMapTooltipLayer.className = "broker-office-map-tooltip-layer";
	brokerOfficeMapTooltipLayer.addEventListener("mouseenter", cancelBrokerOfficeMapTooltipHide);
	brokerOfficeMapTooltipLayer.addEventListener("mouseleave", scheduleBrokerOfficeMapTooltipHide);
	brokerOfficeMapTooltipLayer.addEventListener("click", async (event) => {
		const roadviewButton = event.target.closest("[data-broker-office-roadview]");
		if (roadviewButton) {
			event.preventDefault();
			event.stopPropagation();
			hideBrokerOfficeMapTooltip();
			const lat = Number(roadviewButton.dataset.lat);
			const lng = Number(roadviewButton.dataset.lng);
			if (Number.isFinite(lat) && Number.isFinite(lng) && typeof showRoadview === "function") {
				showRoadview(lat, lng);
			}
			return;
		}
		const row = event.target.closest("[data-broker-office-tooltip-index]");
		const professionalRow = event.target.closest("[data-local-professional-tooltip]");
		if (professionalRow) {
			const business = brokerOfficeMapTooltipLayer.__professionalBusiness;
			if (!business) return;
			event.preventDefault();
			event.stopPropagation();
			hideBrokerOfficeMapTooltip();
			await showLocalProfessionalBusinessCard(business);
			return;
		}
		if (!row) return;
		const index = Number(row.dataset.brokerOfficeTooltipIndex);
		const offices = brokerOfficeMapTooltipLayer.__brokerOffices || [];
		const selected = offices[index];
		if (!selected) return;
		event.preventDefault();
		event.stopPropagation();
		hideBrokerOfficeMapTooltip();
		await openBrokerOfficeFromMapInteraction(selected, {
			title: selected.officeName || "중개업체",
			summary: selected.address || ""
		});
	});
	document.body.appendChild(brokerOfficeMapTooltipLayer);
	return brokerOfficeMapTooltipLayer;
}

function showBrokerOfficeMapTooltip(anchor, office)
{
	if (!anchor || !office) return;
	// 4.995: 중개사 카드가 열린 상태에서도 사용자가 실제로 다른 원형 뱃지를
	// 가리키면 툴팁을 표시한다. 카드 열기 자체로 툴팁을 자동 표시하지는 않는다.
	const offices = rankBrokerOfficesForSharedAddress(Array.isArray(office.offices) && office.offices.length ? office.offices : [office]);
	const layer = ensureBrokerOfficeMapTooltipLayer();
	layer.__brokerOffices = offices;
	layer.__professionalBusiness = null;
	cancelBrokerOfficeMapTooltipHide();
	const roadviewPosition = normalizeJejuLatLngPair(office.lat, office.lng)
		|| normalizeJejuLatLngPair(offices[0] && offices[0].lat, offices[0] && offices[0].lng);
	const officeRows = offices.map((item, index) => {
		const profileImage = getBrokerOfficeListingProfileImage(item);
		const brokerUserId = normalizeItemId(item.userId || item.user_id);
		const avatarHtml = profileImage
			? '<img class="broker-office-map-marker-photo broker-office-map-tooltip-avatar-img" src="' + escapeHtml(profileImage) + '" data-broker-user-id="' + escapeHtml(brokerUserId) + '" alt="" decoding="async">'
			: '<i class="fa-solid fa-user-tie" aria-hidden="true"></i>';
		return '<button type="button" class="broker-office-map-tooltip-row' + (index === 0 ? ' is-primary' : '') + '" data-broker-office-tooltip-index="'
			+ index
			+ '"><span class="broker-office-map-tooltip-title"><span class="broker-office-map-tooltip-avatar" aria-hidden="true">'
			+ avatarHtml
			+ '</span><strong>'
			+ escapeHtml(item.officeName)
			+ '</strong></span>'
			+ '</button>';
	}).join("");
	const displayAddress = formatBrokerOfficeDisplayAddress((offices[0] && offices[0].address) || office.address || "");
	const addressHtml = displayAddress ? '<span class="broker-office-map-tooltip-address">' + escapeHtml(displayAddress) + '</span>' : '';
	const roadviewButton = roadviewPosition
		? '<button type="button" class="broker-office-map-tooltip-roadview" data-broker-office-roadview data-lat="'
			+ String(roadviewPosition.lat)
			+ '" data-lng="'
			+ String(roadviewPosition.lng)
			+ '"><span>로드뷰</span></button>'
		: "";
	layer.innerHTML = '<span class="broker-office-map-marker-list">'
		+ officeRows
		+ '</span>'
		+ addressHtml
		+ roadviewButton;
	attachBrokerOfficeMarkerImageFallback(layer);
	const rect = anchor.getBoundingClientRect();
	layer.classList.add("open");
	layer.style.visibility = "visible";
	layer.style.pointerEvents = "auto";
	const tooltipRect = layer.getBoundingClientRect();
	const left = Math.min(Math.max(rect.left + rect.width / 2 - tooltipRect.width / 2, 8), window.innerWidth - tooltipRect.width - 8);
	const top = Math.max(rect.top - tooltipRect.height - 10, 8);
	layer.style.left = left + "px";
	layer.style.top = top + "px";
}

function showLocalProfessionalBusinessMapTooltip(anchor, business)
{
	if (!anchor || !business) return;
	const layer = ensureBrokerOfficeMapTooltipLayer();
	layer.__brokerOffices = [];
	layer.__professionalBusiness = business;
	cancelBrokerOfficeMapTooltipHide();
	const position = normalizeJejuLatLngPair(business.lat, business.lng);
	const officeName = String(business.officeName || business.categoryLabel || "전문업체").trim();
	const displayAddress = formatBrokerOfficeDisplayAddress(business.address || "");
	const iconHtml = '<i class="fa-solid ' + escapeHtml(business.iconClass || "fa-briefcase") + '" aria-hidden="true"></i>';
	const titleHtml = '<button type="button" class="broker-office-map-tooltip-row is-primary" data-local-professional-tooltip>'
		+ '<span class="broker-office-map-tooltip-title"><span class="broker-office-map-tooltip-avatar" aria-hidden="true">'
		+ iconHtml
		+ '</span><strong>'
		+ escapeHtml(officeName)
		+ '</strong></span></button>';
	const addressHtml = displayAddress
		? '<span class="broker-office-map-tooltip-address">' + escapeHtml(displayAddress) + '</span>'
		: "";
	const roadviewButton = position
		? '<button type="button" class="broker-office-map-tooltip-roadview" data-broker-office-roadview data-lat="'
			+ String(position.lat)
			+ '" data-lng="'
			+ String(position.lng)
			+ '"><span>로드뷰</span></button>'
		: "";
	layer.innerHTML = '<span class="broker-office-map-marker-list">'
		+ titleHtml
		+ '</span>'
		+ addressHtml
		+ roadviewButton;
	const rect = anchor.getBoundingClientRect();
	layer.classList.add("open");
	layer.style.visibility = "visible";
	layer.style.pointerEvents = "auto";
	const tooltipRect = layer.getBoundingClientRect();
	const left = Math.min(Math.max(rect.left + rect.width / 2 - tooltipRect.width / 2, 8), window.innerWidth - tooltipRect.width - 8);
	const top = Math.max(rect.top - tooltipRect.height - 10, 8);
	layer.style.left = left + "px";
	layer.style.top = top + "px";
}

function getBrokerOfficeListingCount(office)
{
	const exactCount = getBrokerOfficeListingCountFromCache(office);
	if (exactCount !== null) return exactCount;
	const stat = getBrokerOfficeSpecialtyStatsFromCache(office);
	if (stat) return Math.max(0, Number(stat.total) || 0);
	return 0;
}

function rankBrokerOfficesForSharedAddress(offices)
{
	return getUniqueBrokerOfficeList(offices).sort((first, second) => {
		const countDifference = getBrokerOfficeListingCount(second) - getBrokerOfficeListingCount(first);
		if (countDifference) return countDifference;
		return String(first && first.officeName || "").localeCompare(String(second && second.officeName || ""), "ko");
	});
}

function isUsableBrokerOfficeProfileImageUrl(url)
{
	const text = String(url || "").trim();
	if (!text) return false;
	const lower = text.toLowerCase();
	if (
		lower.includes("placeholder")
		|| lower.includes("default-avatar")
		|| lower.includes("default_profile")
		|| lower.includes("default-profile")
	) return false;
	if (lower.startsWith("data:image/svg+xml") && (lower.includes("e5e7eb") || lower.includes("%23e5e7eb")) && (lower.includes("9ca3af") || lower.includes("%239ca3af"))) return false;
	return true;
}

function getBrokerOfficeListingProfileImage(office)
{
	const directImage = String(
		office && (
			office.profileImage ||
			office.profile_image ||
			office.profilePhoto ||
			office.profile_photo ||
			office.avatarUrl ||
			office.avatar_url ||
			office.agentImage ||
			office.agent_image ||
			office.image
		) || ""
	).trim();
	if (isUsableBrokerOfficeProfileImageUrl(directImage)) return toRemotePath(directImage);
	const sourceItems = Array.isArray(state.all) && state.all.length
		? state.all
		: (Array.isArray(state.filtered) ? state.filtered : []);
	for (const item of sourceItems) {
		if (!brokerOfficeMatchesListingForSpecialty(office, item)) continue;
		const payload = item && item.payload && typeof item.payload === "object" ? item.payload : {};
		const registrant = payload.registrant && typeof payload.registrant === "object" ? payload.registrant : {};
		const image = String(
			item?.agentImage
			|| payload.agent_image
			|| payload.agentImage
			|| registrant.agent_image
			|| registrant.profile_image
			|| registrant.agentImage
			|| ""
		).trim();
		if (isUsableBrokerOfficeProfileImageUrl(image)) return toRemotePath(image);
	}
	return "";
}

function getBrokerOfficeTopListingRankCount(office)
{
	const stat = getBrokerOfficeSpecialtyStatsFromCache(office);
	const serverTotal = Math.max(0, Number(stat && stat.total) || 0);
	if (serverTotal > 0) return serverTotal;
	return getBrokerOfficeListingCount(office);
}

function refreshBrokerOfficeTopListingCrownKeys(rows)
{
	const topKeys = new Set();
	const filterKey = String(state.brokerOfficeMapFilter || "none");
	if (filterKey !== "all") {
		state.brokerOfficeTopListingCrownKeys = topKeys;
		return topKeys;
	}
	const entries = getUniqueBrokerOfficeList(rows || []).map((office) => {
		const lookupKeys = getBrokerSpecialtyStatsLookupKeys(office);
		if (!lookupKeys.length) return null;
		const count = getBrokerOfficeTopListingRankCount(office);
		if (!Number.isFinite(count) || count <= 0) return null;
		return {
			office,
			lookupKeys,
			count,
			name: String(office && office.officeName || "")
		};
	}).filter(Boolean);
	entries.sort((a, b) => {
		if (b.count !== a.count) return b.count - a.count;
		return a.name.localeCompare(b.name, "ko");
	});
	entries.slice(0, 5).forEach((entry) => {
		entry.lookupKeys.forEach(key => topKeys.add(key));
	});
	state.brokerOfficeTopListingCrownKeys = topKeys;
	return topKeys;
}

