const brokerOfficeLatestProfileImagePromiseByUserId = new Map();

function getBrokerProfileUserIdFromStorageUrl(url)
{
	const text = String(url || "").trim();
	const match = text.match(/\/storage\/v1\/object\/public\/profiles\/([^/]+)\/profile-/i);
	return match && match[1] ? normalizeItemId(decodeURIComponent(match[1])) : "";
}

async function resolveLatestBrokerProfileImageFromStorage(userId)
{
	const normalizedUserId = normalizeItemId(userId);
	if (!normalizedUserId) return "";
	if (brokerOfficeLatestProfileImagePromiseByUserId.has(normalizedUserId)) {
		return brokerOfficeLatestProfileImagePromiseByUserId.get(normalizedUserId);
	}
	const promise = (async () => {
		let client = getRealjejuSupabaseClient();
		if (!client && typeof loadSupabaseScript === "function") {
			try {
				await loadSupabaseScript();
				client = getRealjejuSupabaseClient();
			} catch (error) {
				client = null;
			}
		}
		if (!client || !client.storage) return "";
		const bucket = client.storage.from("profiles");
		const { data, error } = await bucket.list(normalizedUserId, {
			limit: 20,
			offset: 0,
			sortBy: { column: "created_at", order: "desc" }
		});
		if (error) throw error;
		const latest = (Array.isArray(data) ? data : []).find((item) => item && /^profile-/i.test(String(item.name || "")));
		if (!latest || !latest.name) return "";
		const path = `${normalizedUserId}/${latest.name}`;
		const { data: publicUrlData } = bucket.getPublicUrl(path);
		return String(publicUrlData && publicUrlData.publicUrl || "").trim();
	})().catch((error) => {
		console.warn("중개사 최신 프로필 사진 복구 실패:", error);
		return "";
	});
	brokerOfficeLatestProfileImagePromiseByUserId.set(normalizedUserId, promise);
	return promise;
}

function applyRecoveredBrokerProfileImage(userId, imageUrl)
{
	const normalizedUserId = normalizeItemId(userId);
	const profileImage = String(imageUrl || "").trim();
	if (!normalizedUserId || !profileImage) return;
	const updateOffice = (office) => {
		if (!office || typeof office !== "object") return;
		if (normalizeItemId(office.userId || office.user_id) === normalizedUserId) {
			office.profileImage = profileImage;
			office.profile_image = profileImage;
		}
		if (Array.isArray(office.offices)) office.offices.forEach(updateOffice);
	};
	if (typeof state !== "undefined" && state) {
		(Array.isArray(state.brokerOfficeRows) ? state.brokerOfficeRows : []).forEach(updateOffice);
		const autoRows = state.localBusinessAutoRows && Array.isArray(state.localBusinessAutoRows.brokerOffice)
			? state.localBusinessAutoRows.brokerOffice
			: [];
		autoRows.forEach(updateOffice);
	}
	if (typeof window !== "undefined" && window.realjejuCurrentBrokerOffice) {
		updateOffice(window.realjejuCurrentBrokerOffice);
	}
}

async function recoverBrokerOfficeProfileImageElement(img, fallbackUrl = REALJEJU_AGENT_FALLBACK_IMAGE)
{
	if (!img) return;
	const useFallback = () => {
		img.onerror = null;
		if (fallbackUrl) img.src = fallbackUrl;
	};
	if (img.dataset.realjejuProfileRecovery === "done") {
		useFallback();
		return;
	}
	const failedUrl = String(img.currentSrc || img.src || "").trim();
	const userId = normalizeItemId(img.dataset && img.dataset.brokerUserId)
		|| getBrokerProfileUserIdFromStorageUrl(failedUrl);
	if (!userId) {
		useFallback();
		return;
	}
	img.dataset.realjejuProfileRecovery = "loading";
	const recoveredUrl = await resolveLatestBrokerProfileImageFromStorage(userId);
	if (!recoveredUrl || recoveredUrl === failedUrl) {
		img.dataset.realjejuProfileRecovery = "done";
		useFallback();
		return;
	}
	applyRecoveredBrokerProfileImage(userId, recoveredUrl);
	img.dataset.realjejuProfileRecovery = "done";
	img.src = recoveredUrl;
}

if (typeof window !== "undefined") {
	window.realjejuRecoverBrokerProfileImageElement = recoverBrokerOfficeProfileImageElement;
}

function attachBrokerOfficeMarkerImageFallback(root)
{
	if (!root || typeof root.querySelectorAll !== "function") return;
	root.querySelectorAll(".broker-office-map-marker-photo").forEach((img) => {
		if (img.__realjejuBrokerImageFallbackBound) return;
		img.__realjejuBrokerImageFallbackBound = true;
		img.addEventListener("error", async () => {
			const failedUrl = String(img.currentSrc || img.src || "").trim();
			const userId = normalizeItemId(img.dataset && img.dataset.brokerUserId)
				|| getBrokerProfileUserIdFromStorageUrl(failedUrl);
			const recoveredUrl = userId ? await resolveLatestBrokerProfileImageFromStorage(userId) : "";
			if (recoveredUrl && recoveredUrl !== failedUrl) {
				applyRecoveredBrokerProfileImage(userId, recoveredUrl);
				img.addEventListener("error", () => {
					const icon = img.closest(".broker-office-map-marker-icon, .broker-office-map-tooltip-avatar");
					const marker = img.closest(".broker-office-map-marker");
					if (marker) marker.classList.remove("has-profile-image");
					if (icon) icon.innerHTML = '<i class="fa-solid fa-user-tie" aria-hidden="true"></i>';
				}, { once: true });
				img.src = recoveredUrl;
				return;
			}
			const icon = img.closest(".broker-office-map-marker-icon, .broker-office-map-tooltip-avatar");
			const marker = img.closest(".broker-office-map-marker");
			if (marker) marker.classList.remove("has-profile-image");
			if (icon) icon.innerHTML = '<i class="fa-solid fa-user-tie" aria-hidden="true"></i>';
		}, { once: true });
	});
}

