function getEducationFacilityOverlapGroupKey(row)
{
	const lat = Number(row && row.lat);
	const lng = Number(row && row.lng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return "";
	if (state.map && typeof state.map.getProjection === "function" && window.kakao && kakao.maps && kakao.maps.LatLng) {
		try {
			const projection = state.map.getProjection();
			const point = projection && typeof projection.pointFromCoords === "function"
				? projection.pointFromCoords(new kakao.maps.LatLng(lat, lng))
				: null;
			const x = Number(point && point.x);
			const y = Number(point && point.y);
			if (Number.isFinite(x) && Number.isFinite(y)) {
				return "px:" + Math.round(x / 24) + ":" + Math.round(y / 24);
			}
		} catch (e) {}
	}
	return "ll:" + lat.toFixed(5) + ":" + lng.toFixed(5);
}

function getEducationFacilityOverlapOffsetMap(rows)
{
	const counts = new Map();
	const offsets = new WeakMap();
	(rows || []).forEach((row) => {
		const key = getEducationFacilityOverlapGroupKey(row);
		const index = key ? (counts.get(key) || 0) : 0;
		if (key) counts.set(key, index + 1);
		offsets.set(row, index * 34);
	});
	return offsets;
}

function createEducationFacilityOverlay(row, options = {})
{
	const el = document.createElement("button");
	el.type = "button";
	el.className = "education-facility-map-marker";
	el.dataset.category = row.category || "";
	const offsetX = Number(options.offsetX || 0);
	const markerOffsetX = Number.isFinite(offsetX) ? offsetX : 0;
	const overlayKey = getEducationFacilityOverlayKey(row, markerOffsetX);
	el.dataset.educationFacilityOverlayKey = overlayKey;
	if (state.selectedEducationFacilityOverlayKey === overlayKey) el.classList.add("selected");
	if (markerOffsetX !== 0) el.dataset.overlapOffsetX = String(markerOffsetX);
	el.innerHTML = getEducationFacilityMarkerHtml(row) + '<span class="education-facility-map-marker-tooltip"><strong>'
		+ escapeHtml(row.name)
		+ '</strong><small>'
		+ escapeHtml(row.address)
		+ (row.phone ? ' · ' + escapeHtml(row.phone) : '')
		+ '</small></span>';
	el.setAttribute("aria-label", row.name + " " + row.address);
	const overlay = new kakao.maps.CustomOverlay({
		position: new kakao.maps.LatLng(row.lat, row.lng),
		content: el,
		xAnchor: 0.5 - (markerOffsetX / 36),
		yAnchor: 0.5,
		zIndex: getFacilityOverlayZIndex("education") + Math.min(Math.round(markerOffsetX), 90)
	});
	overlay.__realjejuMarkerElement = el;
	el.addEventListener("mouseenter", () => {
		overlay.setZIndex(FACILITY_OVERLAY_Z_INDEX_HOVER);
		showEducationFacilityMapTooltip(el, row);
	});
	el.addEventListener("focus", () => {
		overlay.setZIndex(FACILITY_OVERLAY_Z_INDEX_HOVER);
		showEducationFacilityMapTooltip(el, row);
	});
	el.addEventListener("click", async (event) => {
		event.preventDefault();
		event.stopPropagation();
		overlay.setZIndex(FACILITY_OVERLAY_Z_INDEX_HOVER);
		setSelectedEducationFacilityMarker(overlayKey);
		await openEducationFacilityDetailPanel(row, { preserveTooltip: true });
		setSelectedEducationFacilityMarker(overlayKey);
	});
	el.addEventListener("mouseleave", () => {
		overlay.setZIndex(getFacilityOverlayZIndex("education"));
		scheduleEducationFacilityMapTooltipHide();
	});
	el.addEventListener("blur", () => {
		overlay.setZIndex(getFacilityOverlayZIndex("education"));
		scheduleEducationFacilityMapTooltipHide();
	});
	return overlay;
}

function applyEducationFacilityOverlayEntries(entries)
{
	const previous = state.educationFacilityOverlayMap instanceof Map ? state.educationFacilityOverlayMap : new Map();
	const next = new Map();
	const overlays = [];
	(entries || []).forEach((entry) => {
		if (!entry || !entry.key) return;
		let overlay = previous.get(entry.key);
		if (!overlay) overlay = entry.createOverlay();
		if (!overlay) return;
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(state.map);
		if (overlay && typeof overlay.setZIndex === "function") overlay.setZIndex(entry.zIndex || getFacilityOverlayZIndex("education"));
		next.set(entry.key, overlay);
		overlays.push(overlay);
	});
	previous.forEach((overlay, key) => {
		if (!next.has(key) && overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	state.educationFacilityOverlayMap = next;
	state.educationFacilityOverlays = overlays;
	syncSelectedEducationFacilityMarkers();
}

async function renderEducationFacilityOverlays()
{
	if (!state.map || !window.kakao || !kakao.maps) return;
	if (!shouldRenderEducationFacilityOverlays()) {
		clearEducationFacilityOverlays();
		return;
	}
	const rows = await fetchEducationFacilityRows();
	if (!rows.length) {
		clearEducationFacilityOverlays();
		console.warn("표시할 교육시설 좌표 데이터가 없습니다. education_facilities 데이터를 확인하세요.");
		return;
	}
	const selectedCategories = getSelectedEducationFacilityCategories();
	const mapLevel = getFacilityMapLevel();
	const mapBounds = getExpandedMapBounds();
	const rowsByCategory = new Map();
	rows.forEach((row) => {
		if (!shouldShowEducationFacilityRowAtLevel(row, mapLevel)) return;
		if (!isLatLngInsideBounds(row.lat, row.lng, mapBounds)) return;
		const key = row.category || "";
		if (!rowsByCategory.has(key)) rowsByCategory.set(key, []);
		rowsByCategory.get(key).push(row);
	});
	const renderRows = [];
	selectedCategories.forEach((category) => {
		const categoryRows = rowsByCategory.get(category) || [];
		categoryRows.forEach((row) => renderRows.push(row));
	});
	if (isEducationFacilityFilterPanelOpen()) renderEducationFacilityFilterPanel();
	const offsetMap = getEducationFacilityOverlapOffsetMap(renderRows);
	const entries = renderRows.map((row) => {
		const offsetX = offsetMap.get(row) || 0;
		return {
			key: getEducationFacilityOverlayKey(row, offsetX),
			zIndex: getFacilityOverlayZIndex("education") + Math.min(Math.round(offsetX), 90),
			createOverlay: () => createEducationFacilityOverlay(row, { offsetX })
		};
	});
	applyEducationFacilityOverlayEntries(entries);
	syncFacilityOverlayZIndexes();
}


function isEducationFacilityFilterPanelOpen()
{
	return !!(educationFacilityFilterPanel && educationFacilityFilterPanel.classList.contains("open"));
}

function isAnyFacilityFilterPanelOpen()
{
	return !!(
		(typeof isEducationFacilityFilterPanelOpen === "function" && isEducationFacilityFilterPanelOpen())
		|| (typeof isConvenienceFacilityFilterPanelOpen === "function" && isConvenienceFacilityFilterPanelOpen())
		|| (typeof isDevelopmentFacilityFilterPanelOpen === "function" && isDevelopmentFacilityFilterPanelOpen())
		|| (typeof isBrokerOfficeFilterPanelOpen === "function" && isBrokerOfficeFilterPanelOpen())
		|| (typeof isMapSettingsFilterPanelOpen === "function" && isMapSettingsFilterPanelOpen())
	);
}

function closeEducationFacilityFilterPanel()
{
	if (!educationFacilityFilterPanel) return;
	educationFacilityFilterPanel.classList.remove("open");
	updateEducationFacilityToolActiveState();
	if (typeof syncLocationAnalysisUI === "function") syncLocationAnalysisUI();
}

function positionEducationFacilityFilterPanel()
{
	if (!educationFacilityFilterPanel || !mapEducationToolBtn) return;
	const rect = mapEducationToolBtn.getBoundingClientRect();
	const panelRect = educationFacilityFilterPanel.getBoundingClientRect();
	const left = Math.max(8, rect.left - panelRect.width - 8);
	const top = Math.min(Math.max(8, rect.top - 12), window.innerHeight - panelRect.height - 8);
	educationFacilityFilterPanel.style.left = left + "px";
	educationFacilityFilterPanel.style.top = top + "px";
}

function ensureEducationFacilityFilterPanel()
{
	if (educationFacilityFilterPanel) return educationFacilityFilterPanel;
	educationFacilityFilterPanel = document.createElement("div");
	educationFacilityFilterPanel.className = "education-facility-filter-panel";
	educationFacilityFilterPanel.setAttribute("role", "dialog");
	educationFacilityFilterPanel.setAttribute("aria-label", "학교 표시 선택");
	educationFacilityFilterPanel.addEventListener("click", async (event) => {
		const option = event.target.closest("[data-education-category]");
		if (option) {
			event.preventDefault();
			event.stopPropagation();
			const key = option.dataset.educationCategory || "";
			if (!(state.educationFacilityCategories instanceof Set)) state.educationFacilityCategories = new Set();
			if (state.educationFacilityCategories.has(key)) state.educationFacilityCategories.delete(key);
			else state.educationFacilityCategories.add(key);
			state.educationFacilityRows = null;
			const hasSelected = getSelectedEducationFacilityCategories().length > 0;
			state.isEducationFacilitiesVisible = hasSelected;
			renderEducationFacilityFilterPanel();
			if (hasSelected) {
				bringFacilityOverlayLayerToFront("education");
				await renderEducationFacilityOverlays();
				syncFacilityOverlayZIndexes();
			}
			else clearEducationFacilityOverlays();
			updateEducationFacilityToolActiveState();
			return;
		}
		const clearBtn = event.target.closest("[data-education-clear]");
		if (clearBtn) {
			event.preventDefault();
			event.stopPropagation();
			state.educationFacilityCategories = new Set();
			state.educationFacilityRows = null;
			clearEducationFacilityOverlays();
			renderEducationFacilityFilterPanel();
			updateEducationFacilityToolActiveState();
		}
	});
	document.body.appendChild(educationFacilityFilterPanel);
	return educationFacilityFilterPanel;
}

function getEducationFacilityFilterFooterHtml()
{
	return "레벨 : 어린이집·유치원·학원 6단계<br>초·중·고등학교 9단계";
}

function renderEducationFacilityFilterPanel()
{
	const panel = ensureEducationFacilityFilterPanel();
	const selected = state.educationFacilityCategories instanceof Set ? state.educationFacilityCategories : new Set();
	const options = getEducationFacilityCategoryOptions();
	const hasSelected = selected.size > 0;
	const footerHtml = getEducationFacilityFilterFooterHtml();
	panel.innerHTML = '<div class="education-facility-filter-grid">'
		+ options.map((option) => '<button type="button" class="education-facility-filter-option '
			+ (selected.has(option.key) ? 'active' : '')
			+ '" data-education-category="'
			+ escapeHtml(option.key)
			+ '" data-category="'
			+ escapeHtml(option.key)
			+ '">'
			+ getEducationFacilityFilterOptionIconHtml(option)
			+ '<span>'
			+ escapeHtml(option.label)
			+ '</span></button>').join("")
		+ '</div><button type="button" class="education-facility-filter-clear '
		+ (!hasSelected ? 'is-disabled' : '')
		+ '" data-education-clear '
		+ (!hasSelected ? 'disabled aria-disabled="true"' : '')
		+ '>전체 선택해제</button><div class="education-facility-filter-radius">'
		+ footerHtml
		+ '</div>';
	positionEducationFacilityFilterPanel();
}

