function clearPublicParkingOverlays()
{
	const overlays = state.publicParkingOverlayMap instanceof Map
		? Array.from(state.publicParkingOverlayMap.values())
		: (state.publicParkingOverlays || []);
	overlays.forEach((overlay) => {
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	state.publicParkingOverlays = [];
	state.publicParkingOverlayMap = new Map();
	state.publicParkingRows = [];
}

function getPublicParkingOverlayKey(row)
{
	if (!row) return "";
	return ["public-parking", normalizeItemId(row.id || row.name || ""), row.lat, row.lng].join(":");
}

function normalizePublicParkingPlace(place)
{
	if (!place) return null;
	const lat = Number(place.y);
	const lng = Number(place.x);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
	return {
		id: String(place.id || `${place.place_name || ""}-${place.x || ""}-${place.y || ""}`).trim(),
		category: "public-parking",
		name: String(place.place_name || "공영주차장").trim(),
		address: String(place.road_address_name || place.address_name || "").trim(),
		phone: String(place.phone || "").trim(),
		placeUrl: String(place.place_url || "").trim(),
		lat,
		lng
	};
}

function searchPublicParkingPlaces()
{
	const cacheKey = getLocalBusinessPlaceSearchCacheKey("public-parking");
	if (!(state.publicParkingSearchCache instanceof Map)) state.publicParkingSearchCache = new Map();
	if (!(state.publicParkingSearchInflight instanceof Map)) state.publicParkingSearchInflight = new Map();
	const cachedRows = getLocalBusinessPlaceSearchCache(state.publicParkingSearchCache, cacheKey);
	if (cachedRows) return Promise.resolve(cachedRows);
	if (cacheKey && state.publicParkingSearchInflight.has(cacheKey)) {
		return state.publicParkingSearchInflight.get(cacheKey).then(cloneLocalBusinessRows);
	}
	const request = new Promise((resolve) => {
		if (!state.map || !window.kakao || !kakao.maps || !kakao.maps.services || !kakao.maps.services.Places) {
			resolve([]);
			return;
		}
		const places = new kakao.maps.services.Places();
		const bounds = typeof state.map.getBounds === "function" ? state.map.getBounds() : null;
		const rows = [];
		const seen = new Set();
		const callback = (result, status, pagination) => {
			if (status !== kakao.maps.services.Status.OK || !Array.isArray(result)) {
				resolve(rows);
				return;
			}
			result.forEach((place) => {
				const row = normalizePublicParkingPlace(place);
				if (!row) return;
				const key = getPublicParkingOverlayKey(row);
				if (seen.has(key)) return;
				seen.add(key);
				rows.push(row);
			});
			if (pagination && pagination.hasNextPage && pagination.current < 3) {
				pagination.nextPage();
				return;
			}
			resolve(rows);
		};
		try {
			places.keywordSearch("공영주차장", callback, bounds ? { bounds } : {});
		} catch (err) {
			console.warn("공영주차장 검색 실패:", err);
			resolve(rows);
		}
	}).then((rows) => {
		setLocalBusinessPlaceSearchCache(state.publicParkingSearchCache, cacheKey, rows);
		return cloneLocalBusinessRows(rows);
	}).finally(() => {
		if (cacheKey && state.publicParkingSearchInflight.get(cacheKey) === request) {
			state.publicParkingSearchInflight.delete(cacheKey);
		}
	});
	if (cacheKey) state.publicParkingSearchInflight.set(cacheKey, request);
	return request;
}

function getPublicParkingMarkerHtml()
{
	return '<span class="education-facility-map-marker-icon public-parking-marker-icon" aria-hidden="true"><span class="public-parking-marker-label">P</span></span>';
}

function createPublicParkingOverlay(row)
{
	const el = document.createElement("button");
	el.type = "button";
	el.className = "education-facility-map-marker public-parking-map-marker";
	el.dataset.category = "public-parking";
	const overlayKey = getPublicParkingOverlayKey(row);
	el.dataset.publicParkingOverlayKey = overlayKey;
	el.innerHTML = getPublicParkingMarkerHtml() + '<span class="education-facility-map-marker-tooltip"><strong>'
		+ escapeHtml(row.name)
		+ '</strong><small>'
		+ escapeHtml(row.address || "주소 정보 없음")
		+ '</small>'
		+ (row.phone ? '<small>' + escapeHtml(row.phone) + '</small>' : '')
		+ '</span>';
	el.setAttribute("aria-label", row.name + " " + (row.address || ""));
	const overlay = new kakao.maps.CustomOverlay({
		position: new kakao.maps.LatLng(row.lat, row.lng),
		content: el,
		xAnchor: 0.5,
		yAnchor: 0.5,
		zIndex: getFacilityOverlayZIndex("convenience")
	});
	overlay.__realjejuMarkerElement = el;
	const showTooltip = () => {
		overlay.setZIndex(FACILITY_OVERLAY_Z_INDEX_HOVER);
		showEducationFacilityMapTooltip(el, row);
	};
	const hideTooltip = () => {
		overlay.setZIndex(getFacilityOverlayZIndex("convenience"));
		scheduleEducationFacilityMapTooltipHide();
	};
	el.addEventListener("mouseenter", showTooltip);
	el.addEventListener("focus", showTooltip);
	el.addEventListener("mouseleave", hideTooltip);
	el.addEventListener("blur", hideTooltip);
	el.addEventListener("click", (event) => {
		event.preventDefault();
		event.stopPropagation();
		showTooltip();
	});
	return overlay;
}

async function renderPublicParkingOverlays()
{
	if (!state.isPublicParkingVisible || !state.map || !window.kakao || !kakao.maps) {
		clearPublicParkingOverlays();
		return;
	}
	const mapLevel = getFacilityMapLevel();
	if (!Number.isFinite(mapLevel) || mapLevel > DENSE_CONVENIENCE_MAP_VISIBLE_LEVEL) {
		clearPublicParkingOverlays();
		return;
	}
	const rows = await searchPublicParkingPlaces();
	const latestMapLevel = getFacilityMapLevel();
	if (!state.isPublicParkingVisible || !Number.isFinite(latestMapLevel) || latestMapLevel > DENSE_CONVENIENCE_MAP_VISIBLE_LEVEL) {
		clearPublicParkingOverlays();
		return;
	}
	state.publicParkingRows = rows;
	const previous = state.publicParkingOverlayMap instanceof Map ? state.publicParkingOverlayMap : new Map();
	const next = new Map();
	const overlays = [];
	rows.forEach((row) => {
		const key = getPublicParkingOverlayKey(row);
		let overlay = previous.get(key);
		if (!overlay) overlay = createPublicParkingOverlay(row);
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(state.map);
		if (overlay && typeof overlay.setZIndex === "function") overlay.setZIndex(getFacilityOverlayZIndex("convenience"));
		next.set(key, overlay);
		overlays.push(overlay);
	});
	previous.forEach((overlay, key) => {
		if (!next.has(key) && overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	state.publicParkingOverlayMap = next;
	state.publicParkingOverlays = overlays;
	syncFacilityOverlayZIndexes();
}

async function setPublicParkingVisible(visible)
{
	state.isPublicParkingVisible = !!visible;
	if (!state.isPublicParkingVisible) {
		clearPublicParkingOverlays();
		hideEducationFacilityMapTooltip();
		updateConvenienceToolActiveState();
		return;
	}
	bringFacilityOverlayLayerToFront("convenience");
	await renderPublicParkingOverlays();
	updateConvenienceToolActiveState();
}

