function getConvenienceCategoryPlaceConfig(category)
{
	return CONVENIENCE_CATEGORY_PLACE_CONFIGS[category] || null;
}

function normalizeEvChargerApiStation(station)
{
	if (!station) return null;
	const lat = Number(station.lat);
	const lng = Number(station.lng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
	const totalCount = Math.max(0, Math.trunc(Number(station.totalCount) || 0));
	const availableCount = Math.max(0, Math.trunc(Number(station.availableCount) || 0));
	const chargingCount = Math.max(0, Math.trunc(Number(station.chargingCount) || 0));
	const unavailableCount = Math.max(0, Math.trunc(Number(station.unavailableCount) || 0));
	return {
		id: String(station.statId || station.id || `${station.name || ""}-${lat}-${lng}`).trim(),
		category: "ev-charger",
		name: String(station.name || "전기차 충전소").trim(),
		address: String(station.address || "").trim(),
		location: String(station.location || "").trim(),
		phone: String(station.operatorPhone || "").trim(),
		operator: String(station.operator || "").trim(),
		useTime: String(station.useTime || "").trim(),
		parkingFree: String(station.parkingFree || "").trim(),
		limitYn: String(station.limitYn || "").trim(),
		limitDetail: String(station.limitDetail || "").trim(),
		totalCount,
		availableCount,
		chargingCount,
		unavailableCount,
		statusUpdatedAt: String(station.statusUpdatedAt || "").trim(),
		statusSource: "official",
		chargers: Array.isArray(station.chargers) ? station.chargers : [],
		lat,
		lng
	};
}

function getEvChargerStatusSummary(row)
{
	if (!row || row.category !== "ev-charger" || row.statusSource !== "official") return "";
	const totalCount = Math.max(0, Math.trunc(Number(row.totalCount) || 0));
	const availableCount = Math.max(0, Math.trunc(Number(row.availableCount) || 0));
	const chargingCount = Math.max(0, Math.trunc(Number(row.chargingCount) || 0));
	const notActiveCount = Math.max(0, Math.trunc(Number(row.unavailableCount) || 0));
	const chargers = Array.isArray(row.chargers) ? row.chargers : [];
	const unknownCount = chargers.length
		? chargers.filter(charger => String(charger && charger.statusCode || "").trim() === "9").length
		: notActiveCount;
	const unavailableCount = Math.max(0, notActiveCount - unknownCount);
	if (totalCount <= 0) return `사용 가능 ${availableCount} · 충전 중 ${chargingCount}`;
	if (totalCount > 0 && availableCount === 0 && chargingCount === 0 && unknownCount >= totalCount) {
		return `충전기 ${totalCount}대 · 상태 미확인`;
	}
	const summary = [
		`총 ${totalCount}대`,
		`사용 가능 ${availableCount}`,
		`충전 중 ${chargingCount}`
	];
	if (unavailableCount > 0) summary.push(`이용 불가 ${unavailableCount}`);
	if (unknownCount > 0) summary.push(`상태 미확인 ${unknownCount}`);
	return summary.join(" · ");
}

function getEvChargerChargingSpecSummary(row)
{
	if (!row || row.category !== "ev-charger" || row.statusSource !== "official") return "";
	const fastOutputs = new Set();
	const slowOutputs = new Set();
	(Array.isArray(row.chargers) ? row.chargers : []).forEach((charger) => {
		const output = Number(charger && charger.capacity);
		if (!Number.isFinite(output) || output <= 0) return;
		const normalizedOutput = Number.isInteger(output) ? String(output) : String(Number(output.toFixed(1)));
		const typeLabel = String(charger && charger.typeLabel || "");
		if (output <= 22 || typeLabel.includes("완속")) slowOutputs.add(normalizedOutput);
		else fastOutputs.add(normalizedOutput);
	});
	const specs = [];
	if (fastOutputs.size) specs.push(`급속 ${Array.from(fastOutputs).sort((a, b) => Number(a) - Number(b)).join("·")}kW`);
	if (slowOutputs.size) specs.push(`완속 ${Array.from(slowOutputs).sort((a, b) => Number(a) - Number(b)).join("·")}kW`);
	return specs.join(" · ");
}

function getEvChargerUseTimeSummary(row)
{
	const useTime = String(row && row.useTime || "").trim();
	if (!useTime) return "";
	return useTime.replace(/24시간\s*이용\s*가능/gi, "24시간").replace(/\s+/g, " ").trim();
}

function getEvChargerSpecAndTimeSummary(row)
{
	return [getEvChargerChargingSpecSummary(row), getEvChargerUseTimeSummary(row)].filter(Boolean).join(" · ");
}

function getEvChargerParkingSummary(row)
{
	if (!row || row.category !== "ev-charger" || row.statusSource !== "official") return "";
	const parkingFree = String(row.parkingFree || "").trim().toUpperCase();
	if (parkingFree === "Y") return "무료 주차";
	if (parkingFree === "N") return "유료 주차";
	return "";
}

function getEvChargerViewportQuery()
{
  const bounds = getExpandedMapBounds();
  if (!bounds) return null;
  const south = Number(bounds.swLat);
  const west = Number(bounds.swLng);
  const north = Number(bounds.neLat);
  const east = Number(bounds.neLng);
  if (![south, west, north, east].every(Number.isFinite)) return null;
  return {
    south,
    west,
    north,
    east,
    key: [south, west, north, east].map(value => value.toFixed(5)).join(":")
  };
}

function normalizeEvChargerDbStation(row)
{
  return normalizeEvChargerApiStation({
    id: row && row.stat_id,
    statId: row && row.stat_id,
    name: row && row.name,
    address: row && row.address,
    location: row && row.location,
    lat: row && row.lat,
    lng: row && row.lng,
    useTime: row && row.use_time,
    operator: row && row.operator_name,
    operatorPhone: row && row.operator_phone,
    parkingFree: row && row.parking_free,
    limitYn: row && row.limit_yn,
    limitDetail: row && row.limit_detail,
    totalCount: row && row.total_count,
    availableCount: row && row.available_count,
    chargingCount: row && row.charging_count,
    unavailableCount: row && row.unavailable_count,
    statusUpdatedAt: row && row.status_updated_at,
    chargers: row && row.chargers
  });
}

function queueEvChargerDbSyncRefresh(client)
{
  const attemptedAt = Number(state.evChargerDbSyncAttemptedAt || 0);
  if (!client || !client.functions || Date.now() - attemptedAt < EV_CHARGER_SYNC_REFRESH_MS) return;
  state.evChargerDbSyncAttemptedAt = Date.now();
  Promise.resolve(client.functions.invoke("ev-chargers", {
    body: { action: "refresh-if-stale" }
  })).catch(() => {});
}

async function queryEvChargerMapRows(client, viewport)
{
  const params = {
    p_south: viewport.south,
    p_west: viewport.west,
    p_north: viewport.north,
    p_east: viewport.east,
    p_limit: EV_CHARGER_DB_QUERY_LIMIT
  };
  const markerResult = await client.rpc("get_ev_charger_markers_in_bounds", params);
  if (!markerResult.error) return markerResult;
  const errorCode = String(markerResult.error.code || "");
  const errorMessage = String(markerResult.error.message || "");
  const markerFunctionMissing = errorCode === "PGRST202"
    || errorMessage.includes("get_ev_charger_markers_in_bounds");
  if (!markerFunctionMissing) return markerResult;
  return client.rpc("get_ev_chargers_in_bounds", {
    ...params,
    p_limit: EV_CHARGER_LEGACY_QUERY_LIMIT
  });
}

async function loadEvChargerApiRows(force = false)
{
  const viewport = getEvChargerViewportQuery();
  if (!viewport) return [];
  const hasCachedResult = Array.isArray(state.evChargerApiRows)
    && Number(state.evChargerApiRowsLoadedAt || 0) > 0
    && state.evChargerApiRowsBoundsKey === viewport.key;
  if (!force && hasCachedResult
    && Date.now() - Number(state.evChargerApiRowsLoadedAt || 0) < EV_CHARGER_API_CACHE_MS) {
    return state.evChargerApiRows;
  }
  if (state.evChargerApiRowsLoadPromise) {
    if (state.evChargerApiRowsLoadPromiseKey === viewport.key) return state.evChargerApiRowsLoadPromise;
    try {
      await state.evChargerApiRowsLoadPromise;
    } catch (error) {}
    return loadEvChargerApiRows(force);
  }
  const client = getMapListingsSupabaseClient();
  if (!client || typeof client.rpc !== "function") {
		console.warn("[realjeju ev charger] Supabase client is not loaded.");
		return [];
	}
  state.evChargerApiRowsAttemptedAt = Date.now();
  state.evChargerApiRowsLoadPromiseKey = viewport.key;
  const requestPromise = (async () => {
    const result = await queryEvChargerMapRows(client, viewport);
    if (result.error) throw result.error;
    const rows = (Array.isArray(result.data) ? result.data : [])
      .map(normalizeEvChargerDbStation)
      .filter(Boolean);
    state.evChargerApiRows = rows;
    state.evChargerApiRowsBoundsKey = viewport.key;
    state.evChargerApiRowsLoadedAt = Date.now();
    queueEvChargerDbSyncRefresh(client);
    return rows;
  })();
  state.evChargerApiRowsLoadPromise = requestPromise;
  try {
    return await requestPromise;
  } catch (error) {
    console.warn("[realjeju ev charger] Supabase 지도 범위 조회 실패:", error);
    if (state.evChargerApiRowsBoundsKey === viewport.key && Array.isArray(state.evChargerApiRows)) {
      return state.evChargerApiRows;
    }
    return [];
  } finally {
    if (state.evChargerApiRowsLoadPromise === requestPromise) {
      state.evChargerApiRowsLoadPromise = null;
      state.evChargerApiRowsLoadPromiseKey = "";
    }
  }
}

function refreshEvChargerApiRowsInBackground()
{
  const previousLoadedAt = Number(state.evChargerApiRowsLoadedAt || 0);
  Promise.resolve(loadEvChargerApiRows(true)).then(() => {
    if (Number(state.evChargerApiRowsLoadedAt || 0) <= previousLoadedAt) return;
    if (!state.isEvChargerVisible || typeof renderEvChargerOverlays !== "function") return;
    void renderEvChargerOverlays();
  }).catch(() => {});
}

function clearConvenienceCategoryPlaceOverlays(category)
{
	const config = getConvenienceCategoryPlaceConfig(category);
	if (!config) return;
	if (!state.convenienceCategoryRenderSeq || typeof state.convenienceCategoryRenderSeq !== "object") {
		state.convenienceCategoryRenderSeq = {};
	}
	state.convenienceCategoryRenderSeq[category] = (Number(state.convenienceCategoryRenderSeq[category]) || 0) + 1;
	const overlays = state[config.overlayMapKey] instanceof Map
		? Array.from(state[config.overlayMapKey].values())
		: (state[config.overlaysKey] || []);
	overlays.forEach((overlay) => {
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	state[config.overlaysKey] = [];
	state[config.overlayMapKey] = new Map();
	state[config.rowsKey] = [];
}

function getConvenienceCategoryPlaceOverlayKey(row)
{
	if (!row) return "";
	return [row.category || "convenience-place", normalizeItemId(row.id || row.name || ""), row.lat, row.lng].join(":");
}

function normalizeConvenienceCategoryPlace(place, config)
{
	if (!place || !config) return null;
	const lat = Number(place.y);
	const lng = Number(place.x);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
	return {
		id: String(place.id || `${place.place_name || ""}-${place.x || ""}-${place.y || ""}`).trim(),
		category: Object.keys(CONVENIENCE_CATEGORY_PLACE_CONFIGS).find(key => CONVENIENCE_CATEGORY_PLACE_CONFIGS[key] === config) || "",
		name: String(place.place_name || config.label || "편의시설").trim(),
		address: String(place.road_address_name || place.address_name || "").trim(),
		phone: String(place.phone || "").trim(),
		placeUrl: String(place.place_url || "").trim(),
		lat,
		lng
	};
}

function getConvenienceCategorySearchBoundsList(config)
{
	const bounds = typeof state.map.getBounds === "function" ? state.map.getBounds() : null;
	if (!bounds || !config || !Number.isFinite(Number(config.searchGridSize)) || Number(config.searchGridSize) <= 1) return bounds ? [bounds] : [null];
	if (!window.kakao || !kakao.maps || !kakao.maps.LatLng || !kakao.maps.LatLngBounds) return [bounds];
	const sw = typeof bounds.getSouthWest === "function" ? bounds.getSouthWest() : null;
	const ne = typeof bounds.getNorthEast === "function" ? bounds.getNorthEast() : null;
	if (!sw || !ne || typeof sw.getLat !== "function" || typeof sw.getLng !== "function" || typeof ne.getLat !== "function" || typeof ne.getLng !== "function") return [bounds];
	const south = Number(sw.getLat());
	const west = Number(sw.getLng());
	const north = Number(ne.getLat());
	const east = Number(ne.getLng());
	if (![south, west, north, east].every(Number.isFinite) || south >= north || west >= east) return [bounds];
	const gridSize = Math.max(1, Math.min(4, Math.trunc(Number(config.searchGridSize))));
	const latStep = (north - south) / gridSize;
	const lngStep = (east - west) / gridSize;
	const list = [];
	for (let y = 0; y < gridSize; y += 1) {
		for (let x = 0; x < gridSize; x += 1) {
			const cellSouth = south + (latStep * y);
			const cellNorth = y === gridSize - 1 ? north : south + (latStep * (y + 1));
			const cellWest = west + (lngStep * x);
			const cellEast = x === gridSize - 1 ? east : west + (lngStep * (x + 1));
			list.push(new kakao.maps.LatLngBounds(
				new kakao.maps.LatLng(cellSouth, cellWest),
				new kakao.maps.LatLng(cellNorth, cellEast)
			));
		}
	}
	return list.length ? list : [bounds];
}

function createConvenienceCategoryPlacesService()
{
	if (!window.kakao || !kakao.maps || !kakao.maps.services || typeof kakao.maps.services.Places !== "function") {
		return null;
	}
	try {
		return new kakao.maps.services.Places();
	} catch (error) {
		return null;
	}
}

function searchConvenienceCategoryPlacesInBounds(places, config, bounds)
{
	return new Promise((resolve) => {
		const rows = [];
		const canCategorySearch = !!(places && typeof places.categorySearch === "function");
		const canKeywordSearch = !!(places && typeof places.keywordSearch === "function");
		if (!config || (!canCategorySearch && !canKeywordSearch)) {
			resolve(rows);
			return;
		}
		const seen = new Set();
		const options = bounds ? { bounds } : {};
		const pageLimit = Math.max(1, Math.trunc(Number(config.searchPageLimit) || 3));
		const callback = (result, status, pagination) => {
			if (status !== kakao.maps.services.Status.OK || !Array.isArray(result)) {
				resolve(rows);
				return;
			}
			result.forEach((place) => {
				const row = normalizeConvenienceCategoryPlace(place, config);
				if (!row) return;
				const key = getConvenienceCategoryPlaceOverlayKey(row);
				if (seen.has(key)) return;
				seen.add(key);
				rows.push(row);
			});
			if (pagination && pagination.hasNextPage && pagination.current < pageLimit) {
				pagination.nextPage();
				return;
			}
			resolve(rows);
		};
		try {
			if (config.categoryGroupCode && canCategorySearch) {
				places.categorySearch(config.categoryGroupCode, callback, options);
			} else if (canKeywordSearch) {
				places.keywordSearch(config.keyword || config.label, callback, options);
			} else {
				resolve(rows);
			}
		} catch (err) {
			console.warn(config.label + " 검색 실패:", err);
			resolve(rows);
		}
	});
}

async function searchConvenienceCategoryPlaces(category)
{
	const config = getConvenienceCategoryPlaceConfig(category);
	if (!config || !state.map) return [];
	if (category === "ev-charger") {
		const officialRows = await loadEvChargerApiRows();
		return Array.isArray(officialRows) ? officialRows : [];
	}
	if (!window.kakao || !kakao.maps || !kakao.maps.services || !kakao.maps.services.Places) return [];
	if (!state.convenienceCategorySearchCache || typeof state.convenienceCategorySearchCache !== "object") {
		state.convenienceCategorySearchCache = {};
	}
	if (!state.convenienceCategorySearchInflight || typeof state.convenienceCategorySearchInflight !== "object") {
		state.convenienceCategorySearchInflight = {};
	}
	if (!(state.convenienceCategorySearchCache[category] instanceof Map)) {
		state.convenienceCategorySearchCache[category] = new Map();
	}
	if (!(state.convenienceCategorySearchInflight[category] instanceof Map)) {
		state.convenienceCategorySearchInflight[category] = new Map();
	}
	const cacheKey = getLocalBusinessPlaceSearchCacheKey(category);
	const cachedRows = getLocalBusinessPlaceSearchCache(state.convenienceCategorySearchCache[category], cacheKey);
	if (cachedRows) return cachedRows;
	if (cacheKey && state.convenienceCategorySearchInflight[category].has(cacheKey)) {
		return state.convenienceCategorySearchInflight[category].get(cacheKey).then(cloneLocalBusinessRows);
	}
	const searchPromise = (async () => {
		const places = createConvenienceCategoryPlacesService();
		if (!places) return [];
		const rows = [];
		const seen = new Set();
		const boundsList = getConvenienceCategorySearchBoundsList(config);
		for (const bounds of boundsList) {
			const chunk = await searchConvenienceCategoryPlacesInBounds(places, config, bounds);
			chunk.forEach((row) => {
				const key = getConvenienceCategoryPlaceOverlayKey(row);
				if (seen.has(key)) return;
				seen.add(key);
				rows.push(row);
			});
		}
		return rows;
	})().then((rows) => {
		setLocalBusinessPlaceSearchCache(state.convenienceCategorySearchCache[category], cacheKey, rows);
		return cloneLocalBusinessRows(rows);
	}).finally(() => {
		if (cacheKey && state.convenienceCategorySearchInflight[category] instanceof Map) {
			state.convenienceCategorySearchInflight[category].delete(cacheKey);
		}
	});
	if (cacheKey) state.convenienceCategorySearchInflight[category].set(cacheKey, searchPromise);
	return searchPromise;
}

function getConvenienceCategoryMarkerHtml(config)
{
	return '<span class="education-facility-map-marker-icon '
		+ escapeHtml(config.markerClass)
		+ '" aria-hidden="true"><i class="fa-solid '
		+ escapeHtml(config.icon)
		+ '"></i></span>';
}

function createConvenienceCategoryOverlay(row)
{
	const config = getConvenienceCategoryPlaceConfig(row && row.category);
	if (!config) return null;
	const el = document.createElement("button");
	el.type = "button";
	el.className = "education-facility-map-marker " + row.category + "-map-marker";
	el.dataset.category = row.category;
	const overlayKey = getConvenienceCategoryPlaceOverlayKey(row);
	el.dataset.conveniencePlaceOverlayKey = overlayKey;
	const recentKey = `${row.category}:${overlayKey}`;
	el.dataset.categoryRecentKey = recentKey;
	const evChargerStatusSummary = getEvChargerStatusSummary(row);
	const evChargerSpecAndTimeSummary = getEvChargerSpecAndTimeSummary(row);
	const evChargerParkingSummary = getEvChargerParkingSummary(row);
	el.innerHTML = getConvenienceCategoryMarkerHtml(config) + '<span class="education-facility-map-marker-tooltip"><strong>'
		+ escapeHtml(row.name)
		+ '</strong><small>'
		+ escapeHtml(row.address || "주소 정보 없음")
		+ '</small>'
		+ (evChargerStatusSummary ? '<small class="ev-charger-status-line">' + escapeHtml(evChargerStatusSummary) + '</small>' : '')
		+ (evChargerSpecAndTimeSummary ? '<small>' + escapeHtml(evChargerSpecAndTimeSummary) + '</small>' : '')
		+ (evChargerParkingSummary ? '<small>' + escapeHtml(evChargerParkingSummary) + '</small>' : '')
		+ (row.category !== "ev-charger" && row.phone ? '<small>' + escapeHtml(row.phone) + '</small>' : '')
		+ '</span>';
	el.setAttribute("aria-label", row.name + " " + (row.address || ""));
	const overlay = new kakao.maps.CustomOverlay({
		position: new kakao.maps.LatLng(row.lat, row.lng),
		content: el,
		xAnchor: 0.5,
		yAnchor: 0.5,
		zIndex: getFacilityOverlayZIndex("convenience")
	});
	overlay.__realjejuMarkerElement = el;
	const showTooltip = () => {
		overlay.setZIndex(FACILITY_OVERLAY_Z_INDEX_HOVER);
		showEducationFacilityMapTooltip(el, row);
	};
	const hideTooltip = () => {
		overlay.setZIndex(getFacilityOverlayZIndex("convenience"));
		scheduleEducationFacilityMapTooltipHide();
	};
	el.addEventListener("mouseenter", showTooltip);
	el.addEventListener("focus", showTooltip);
	el.addEventListener("mouseleave", hideTooltip);
	el.addEventListener("blur", hideTooltip);
	el.addEventListener("click", (event) => {
		event.preventDefault();
		event.stopPropagation();
		if (typeof window.realjejuRecordCategoryRecent === "function") {
			window.realjejuRecordCategoryRecent("local-business", {
				id: recentKey,
				title: row.name || config.label || "동네업체",
				summary: row.address || "",
				action: "map-marker",
				markerKey: recentKey,
				lat: row.lat || "",
				lng: row.lng || "",
				phone: row.phone || ""
			});
		}
		showTooltip();
	});
	return overlay;
}

async function renderConvenienceCategoryPlaceOverlays(category)
{
	const config = getConvenienceCategoryPlaceConfig(category);
	if (!config || !state[config.stateVisibleKey] || !state.map || !window.kakao || !kakao.maps) {
		clearConvenienceCategoryPlaceOverlays(category);
		return;
	}
	const mapLevel = getFacilityMapLevel();
	if (!Number.isFinite(mapLevel) || mapLevel > config.visibleLevel) {
		clearConvenienceCategoryPlaceOverlays(category);
		return;
	}
	if (!state.convenienceCategoryRenderSeq || typeof state.convenienceCategoryRenderSeq !== "object") {
		state.convenienceCategoryRenderSeq = {};
	}
	const renderSeq = (Number(state.convenienceCategoryRenderSeq[category]) || 0) + 1;
	state.convenienceCategoryRenderSeq[category] = renderSeq;
	const rows = await searchConvenienceCategoryPlaces(category);
	if (renderSeq !== state.convenienceCategoryRenderSeq[category]) return;
	if (!state[config.stateVisibleKey]) return;
	const latestMapLevel = getFacilityMapLevel();
	if (!Number.isFinite(latestMapLevel) || latestMapLevel > config.visibleLevel) {
		clearConvenienceCategoryPlaceOverlays(category);
		return;
	}
	state[config.rowsKey] = rows;
	const previous = state[config.overlayMapKey] instanceof Map ? state[config.overlayMapKey] : new Map();
	const next = new Map();
	const overlays = [];
	rows.forEach((row) => {
		const key = getConvenienceCategoryPlaceOverlayKey(row);
		let overlay = previous.get(key);
		if (!overlay) overlay = createConvenienceCategoryOverlay(row);
		if (!overlay) return;
		if (typeof overlay.setMap === "function") overlay.setMap(state.map);
		if (typeof overlay.setZIndex === "function") overlay.setZIndex(getFacilityOverlayZIndex("convenience"));
		next.set(key, overlay);
		overlays.push(overlay);
	});
	previous.forEach((overlay, key) => {
		if (!next.has(key) && overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	state[config.overlayMapKey] = next;
	state[config.overlaysKey] = overlays;
	syncFacilityOverlayZIndexes();
}

async function setConvenienceCategoryPlaceVisible(category, visible)
{
	const config = getConvenienceCategoryPlaceConfig(category);
	if (!config) return;
	state[config.stateVisibleKey] = !!visible;
	if (!state[config.stateVisibleKey]) {
		clearConvenienceCategoryPlaceOverlays(category);
		hideEducationFacilityMapTooltip();
		updateConvenienceToolActiveState();
		return;
	}
	bringFacilityOverlayLayerToFront("convenience");
	await renderConvenienceCategoryPlaceOverlays(category);
	updateConvenienceToolActiveState();
}

