const CLEAN_HOUSE_CITY_DATA_PATHS = {
	jeju: "/data/clean_houses/jeju_city.json",
	seogwipo: "/data/clean_houses/seogwipo_city.json"
};
const CLEAN_HOUSE_GEOCODE_CACHE_KEY = "realjeju.cleanHouseGeocodes.v1";

