function normalizeCleanHousePendingRow(row)
{
	if (!row) return null;
	return {
		...row,
		category: "clean-house",
		id: String(row.id || "").trim(),
		name: String(row.name || "클린하우스").trim() || "클린하우스",
		address: String(row.address || "").trim(),
		eupmyeondong: String(row.eupmyeondong || "").trim(),
		city: String(row.city || "").trim()
	};
}

function getCleanHouseGeocodeCache()
{
	if (state.cleanHouseGeocodeCache && typeof state.cleanHouseGeocodeCache === "object") return state.cleanHouseGeocodeCache;
	let cache = {};
	try {
		const raw = window.localStorage && window.localStorage.getItem(CLEAN_HOUSE_GEOCODE_CACHE_KEY);
		cache = raw ? JSON.parse(raw) : {};
	} catch (error) {
		cache = {};
	}
	state.cleanHouseGeocodeCache = cache && typeof cache === "object" ? cache : {};
	return state.cleanHouseGeocodeCache;
}

function scheduleCleanHouseGeocodeCacheSave()
{
	if (state.cleanHouseGeocodeSaveTimer) window.clearTimeout(state.cleanHouseGeocodeSaveTimer);
	state.cleanHouseGeocodeSaveTimer = window.setTimeout(() => {
		try {
			if (window.localStorage) {
				window.localStorage.setItem(CLEAN_HOUSE_GEOCODE_CACHE_KEY, JSON.stringify(getCleanHouseGeocodeCache()));
			}
		} catch (error) {
			// Ignore storage quota/private mode failures; the in-memory cache still works for this session.
		}
	}, 250);
}

function getCleanHouseGeocodeKey(row)
{
	if (!row) return "";
	return String(row.id || row.address || row.name || "").trim();
}

function getCleanHouseCurrentRegionMeta()
{
	const current = window.realjejuCurrentMapCenterRegion && typeof window.realjejuCurrentMapCenterRegion === "object"
		? window.realjejuCurrentMapCenterRegion
		: mapRegionFilterState;
	return {
		province: normalizeJejuProvinceName(current && current.province || "제주도"),
		city: normalizeJejuCityName(current && current.city || ""),
		dong: normalizeRegionDongName(current && current.dong || "")
	};
}

function getCleanHouseCityKeyFromName(city)
{
	const normalized = normalizeJejuCityName(city || "");
	if (normalized === "서귀포시") return "seogwipo";
	return "jeju";
}

function getCleanHouseCityKeyFromMeta(meta)
{
	return getCleanHouseCityKeyFromName(meta && meta.city || "");
}

async function resolveCleanHouseCurrentRegionMeta()
{
	const current = getCleanHouseCurrentRegionMeta();
	if (!state.map || !window.kakao || !kakao.maps || !kakao.maps.services) return current;
	const center = state.map.getCenter && state.map.getCenter();
	if (!center || typeof center.getLat !== "function" || typeof center.getLng !== "function") return current;
	const lat = Number(center.getLat());
	const lng = Number(center.getLng());
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return current;
	const meta = await resolveMapCenterRegionMeta(lat, lng);
	return meta || current;
}

function applyCachedCleanHouseGeocode(row)
{
	const key = getCleanHouseGeocodeKey(row);
	const cached = key ? getCleanHouseGeocodeCache()[key] : null;
	const lat = cached ? Number(cached.lat) : NaN;
	const lng = cached ? Number(cached.lng) : NaN;
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
	return normalizeCleanHouseRow({ ...row, lat, lng });
}

async function loadCleanHouseCityData(cityKey)
{
	const key = CLEAN_HOUSE_CITY_DATA_PATHS[cityKey] ? cityKey : "jeju";
	if (state.cleanHouseRowsCacheByCity && state.cleanHouseRowsCacheByCity[key]) return state.cleanHouseRowsCacheByCity[key];
	if (state.cleanHouseRowsPromiseByCity && state.cleanHouseRowsPromiseByCity[key]) return state.cleanHouseRowsPromiseByCity[key];
	const path = CLEAN_HOUSE_CITY_DATA_PATHS[key];
	const cleanHouseDataUrls = [path, toRemotePath(path)].filter((url, index, list) => url && list.indexOf(url) === index);
	state.cleanHouseRowsPromiseByCity[key] = (async () => {
		let lastError = null;
		for (const url of cleanHouseDataUrls) {
			try {
				const response = await fetch(url, { cache: "no-cache" });
				if (!response.ok) throw new Error("클린하우스 데이터 로드 실패: " + response.status);
				return response.json();
			} catch (error) {
				lastError = error;
			}
		}
		throw lastError || new Error("클린하우스 데이터 로드 실패");
	})()
		.then((response) => {
			const data = response;
			const rows = Array.isArray(data && data.rows) ? data.rows.map(normalizeCleanHouseRow).filter(Boolean) : [];
			const pendingRows = [];
			(Array.isArray(data && data.geocodingPending) ? data.geocodingPending : []).forEach((rawRow) => {
				const pendingRow = normalizeCleanHousePendingRow(rawRow);
				if (!pendingRow) return;
				const cachedRow = applyCachedCleanHouseGeocode(pendingRow);
				if (cachedRow) rows.push(cachedRow);
				else pendingRows.push(pendingRow);
			});
			const cityData = { rows, pendingRows, geocodePromisesByScope: {} };
			state.cleanHouseRowsCacheByCity[key] = cityData;
			return cityData;
		})
		.catch((error) => {
			console.warn("클린하우스 데이터 로드 실패:", error);
			const cityData = { rows: [], pendingRows: [], geocodePromisesByScope: {} };
			state.cleanHouseRowsCacheByCity[key] = cityData;
			return cityData;
		})
		.finally(() => {
			if (state.cleanHouseRowsPromiseByCity) state.cleanHouseRowsPromiseByCity[key] = null;
		});
	return state.cleanHouseRowsPromiseByCity[key];
}

function addressSearchCleanHouse(geocoder, address)
{
	return new Promise((resolve) => {
		if (!geocoder || !address) {
			resolve(null);
			return;
		}
		geocoder.addressSearch(address, (result, status) => {
			if (status !== kakao.maps.services.Status.OK || !Array.isArray(result) || !result.length) {
				resolve(null);
				return;
			}
			const first = result[0] || {};
			const lat = Number(first.y);
			const lng = Number(first.x);
			resolve(Number.isFinite(lat) && Number.isFinite(lng) ? { lat, lng } : null);
		});
	});
}

function getCleanHousePendingRowsForRegion(cityData, regionMeta)
{
	const pendingRows = cityData && Array.isArray(cityData.pendingRows) ? cityData.pendingRows : [];
	const dong = normalizeRegionDongName(regionMeta && regionMeta.dong || "");
	if (!dong) return pendingRows.filter((row) => !row.__geocodeFailed);
	return pendingRows.filter((row) => {
		if (row.__geocodeFailed) return false;
		const rowDong = normalizeRegionDongName(row.eupmyeondong || "");
		return rowDong === dong || String(row.address || "").includes(dong);
	});
}

async function hydrateCleanHousePendingRowsForRegion(cityKey, cityData, regionMeta)
{
	if (!cityData || !Array.isArray(cityData.pendingRows) || !cityData.pendingRows.length) return;
	if (!window.kakao || !kakao.maps || !kakao.maps.services) return;
	const scope = normalizeRegionDongName(regionMeta && regionMeta.dong || "") || "all";
	if (!cityData.geocodePromisesByScope) cityData.geocodePromisesByScope = {};
	if (cityData.geocodePromisesByScope[scope]) {
		await cityData.geocodePromisesByScope[scope];
		return;
	}
	const candidates = getCleanHousePendingRowsForRegion(cityData, regionMeta);
	if (!candidates.length) return;
	cityData.geocodePromisesByScope[scope] = (async () => {
		const geocoder = null;
		const cache = getCleanHouseGeocodeCache();
		for (const row of candidates) {
			const key = getCleanHouseGeocodeKey(row);
			if (!key) continue;
			const cachedRow = applyCachedCleanHouseGeocode(row);
			let nextRow = cachedRow;
			if (!nextRow) {
				const position = await addressSearchCleanHouse(geocoder, row.address);
				if (!position) {
					row.__geocodeFailed = true;
					continue;
				}
				cache[key] = position;
				nextRow = normalizeCleanHouseRow({ ...row, ...position });
			}
			if (!nextRow) continue;
			if (!cityData.rows.some((item) => getCleanHouseGeocodeKey(item) === key)) {
				cityData.rows.push(nextRow);
			}
			cityData.pendingRows = cityData.pendingRows.filter((item) => getCleanHouseGeocodeKey(item) !== key);
		}
		scheduleCleanHouseGeocodeCacheSave();
	})()
		.finally(() => {
			if (cityData.geocodePromisesByScope) cityData.geocodePromisesByScope[scope] = null;
		});
	await cityData.geocodePromisesByScope[scope];
	if (cityKey && state.isCleanHouseVisible) window.setTimeout(() => { renderCleanHouseOverlays(); }, 0);
}

async function loadCleanHouseRows()
{
	const regionMeta = await resolveCleanHouseCurrentRegionMeta();
	const cityKey = getCleanHouseCityKeyFromMeta(regionMeta);
	const cityData = await loadCleanHouseCityData(cityKey);
	await hydrateCleanHousePendingRowsForRegion(cityKey, cityData, regionMeta);
	const rows = cityData && Array.isArray(cityData.rows) ? cityData.rows : [];
	return rows.map((row) => ({ ...row }));
}

function getCleanHouseMarkerHtml()
{
	return '<span class="education-facility-map-marker-icon clean-house-marker-icon" aria-hidden="true"><i class="fa-solid fa-recycle"></i></span>';
}

function createCleanHouseOverlay(row)
{
	const el = document.createElement("button");
	el.type = "button";
	el.className = "education-facility-map-marker clean-house-map-marker";
	el.dataset.category = "clean-house";
	const overlayKey = getCleanHouseOverlayKey(row);
	el.dataset.cleanHouseOverlayKey = overlayKey;
	el.innerHTML = getCleanHouseMarkerHtml() + '<span class="education-facility-map-marker-tooltip"><strong>'
		+ escapeHtml(row.name)
		+ '</strong><small>'
		+ escapeHtml([row.city, row.eupmyeondong].filter(Boolean).join(" ") || "클린하우스")
		+ '</small><small>'
		+ escapeHtml(row.address || "주소 정보 없음")
		+ '</small></span>';
	el.setAttribute("aria-label", row.name + " " + (row.address || ""));
	const overlay = new kakao.maps.CustomOverlay({
		position: new kakao.maps.LatLng(row.lat, row.lng),
		content: el,
		xAnchor: 0.5,
		yAnchor: 0.5,
		zIndex: getFacilityOverlayZIndex("convenience")
	});
	overlay.__realjejuMarkerElement = el;
	const showTooltip = () => {
		overlay.setZIndex(FACILITY_OVERLAY_Z_INDEX_HOVER);
		showEducationFacilityMapTooltip(el, row);
	};
	const hideTooltip = () => {
		overlay.setZIndex(getFacilityOverlayZIndex("convenience"));
		scheduleEducationFacilityMapTooltipHide();
	};
	el.addEventListener("mouseenter", showTooltip);
	el.addEventListener("focus", showTooltip);
	el.addEventListener("mouseleave", hideTooltip);
	el.addEventListener("blur", hideTooltip);
	el.addEventListener("click", (event) => {
		event.preventDefault();
		event.stopPropagation();
		showTooltip();
	});
	return overlay;
}

async function renderCleanHouseOverlays()
{
	if (!state.isCleanHouseVisible || !state.map || !window.kakao || !kakao.maps) {
		clearCleanHouseOverlays();
		return;
	}
	const mapLevel = getFacilityMapLevel();
	if (!Number.isFinite(mapLevel) || mapLevel > DENSE_CONVENIENCE_MAP_VISIBLE_LEVEL) {
		clearCleanHouseOverlays();
		return;
	}
	const rows = await loadCleanHouseRows();
	const latestMapLevel = getFacilityMapLevel();
	if (!state.isCleanHouseVisible || !Number.isFinite(latestMapLevel) || latestMapLevel > DENSE_CONVENIENCE_MAP_VISIBLE_LEVEL) {
		clearCleanHouseOverlays();
		return;
	}
	const mapBounds = typeof state.map.getBounds === "function" ? state.map.getBounds() : null;
	const visibleRows = rows.filter((row) => !mapBounds || isLatLngInsideBounds(row.lat, row.lng, mapBounds));
	state.cleanHouseRows = visibleRows;
	const previous = state.cleanHouseOverlayMap instanceof Map ? state.cleanHouseOverlayMap : new Map();
	const next = new Map();
	const overlays = [];
	visibleRows.forEach((row) => {
		const key = getCleanHouseOverlayKey(row);
		let overlay = previous.get(key);
		if (!overlay) overlay = createCleanHouseOverlay(row);
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(state.map);
		if (overlay && typeof overlay.setZIndex === "function") overlay.setZIndex(getFacilityOverlayZIndex("convenience"));
		next.set(key, overlay);
		overlays.push(overlay);
	});
	previous.forEach((overlay, key) => {
		if (!next.has(key) && overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	state.cleanHouseOverlayMap = next;
	state.cleanHouseOverlays = overlays;
	syncFacilityOverlayZIndexes();
	syncLocationAnalysisUI();
}

async function setCleanHouseVisible(visible)
{
	state.isCleanHouseVisible = !!visible;
	if (!state.isCleanHouseVisible) {
		clearCleanHouseOverlays();
		hideEducationFacilityMapTooltip();
		syncLocationAnalysisUI();
		updateConvenienceToolActiveState();
		return;
	}
	bringFacilityOverlayLayerToFront("convenience");
	await renderCleanHouseOverlays();
	updateConvenienceToolActiveState();
}

const PLAYGROUND_PARK_DATA_PATH = "/data/playgrounds_parks/jeju_playgrounds_parks.json";
const PLAYGROUND_PARK_GEOCODE_CACHE_KEY = "realjeju.playgroundParkGeocodes.v1";

function clearPlaygroundParkOverlays()
{
	const overlays = state.playgroundParkOverlayMap instanceof Map
		? Array.from(state.playgroundParkOverlayMap.values())
		: (state.playgroundParkOverlays || []);
	overlays.forEach((overlay) => {
		if (overlay && typeof overlay.setMap === "function") overlay.setMap(null);
	});
	state.playgroundParkOverlays = [];
	state.playgroundParkOverlayMap = new Map();
}

function normalizePlaygroundParkRow(row)
{
	if (!row) return null;
	const lat = Number(row.lat);
	const lng = Number(row.lng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
	return {
		...row,
		category: "playground-park",
		id: String(row.id || "").trim(),
		name: String(row.name || "놀이터/공원").trim() || "놀이터/공원",
		kind: String(row.kind || "놀이터").trim() || "놀이터",
		address: String(row.address || row.road_address || row.lot_address || "").trim(),
		phone: String(row.phone || "").trim(),
		lat,
		lng
	};
}

function getPlaygroundParkGeocodeCache()
{
	if (state.playgroundParkGeocodeCache && typeof state.playgroundParkGeocodeCache === "object") return state.playgroundParkGeocodeCache;
	let cache = {};
	try {
		const raw = window.localStorage && window.localStorage.getItem(PLAYGROUND_PARK_GEOCODE_CACHE_KEY);
		cache = raw ? JSON.parse(raw) : {};
	} catch (error) {
		cache = {};
	}
	state.playgroundParkGeocodeCache = cache && typeof cache === "object" ? cache : {};
	return state.playgroundParkGeocodeCache;
}

function schedulePlaygroundParkGeocodeCacheSave()
{
	if (state.playgroundParkGeocodeSaveTimer) window.clearTimeout(state.playgroundParkGeocodeSaveTimer);
	state.playgroundParkGeocodeSaveTimer = window.setTimeout(() => {
		try {
			if (window.localStorage) window.localStorage.setItem(PLAYGROUND_PARK_GEOCODE_CACHE_KEY, JSON.stringify(getPlaygroundParkGeocodeCache()));
		} catch (error) {}
	}, 250);
}

async function hydratePlaygroundParkPendingRows(rows, pendingRows)
{
	if (!Array.isArray(pendingRows) || !pendingRows.length || !window.kakao || !kakao.maps || !kakao.maps.services) return rows;
	const geocoder = null;
	const cache = getPlaygroundParkGeocodeCache();
	for (const pendingRow of pendingRows) {
		const key = String(pendingRow.id || pendingRow.address || pendingRow.name || "").trim();
		if (!key) continue;
		let position = cache[key];
		if (!position) {
			position = await addressSearchCleanHouse(geocoder, String(pendingRow.address || "").trim());
			if (position) cache[key] = position;
		}
		const normalized = position ? normalizePlaygroundParkRow({ ...pendingRow, ...position }) : null;
		if (normalized) rows.push(normalized);
	}
	schedulePlaygroundParkGeocodeCacheSave();
	return rows;
}

async function loadPlaygroundParkRows()
{
	if (Array.isArray(state.playgroundParkRows)) return state.playgroundParkRows;
	if (state.playgroundParkRowsLoadPromise) return state.playgroundParkRowsLoadPromise;
	const dataUrls = [
		resolveRealjejuLocalAssetUrl(PLAYGROUND_PARK_DATA_PATH),
		toRemotePath(PLAYGROUND_PARK_DATA_PATH)
	].filter((url, index, list) => url && list.indexOf(url) === index);
	state.playgroundParkRowsLoadPromise = (async () => {
		let lastError = null;
		for (const url of dataUrls) {
			try {
				const response = await fetch(url, { cache: "no-cache" });
				if (!response.ok) throw new Error("놀이터/공원 데이터 로드 실패: " + response.status);
				return response.json();
			} catch (error) {
				lastError = error;
			}
		}
		throw lastError || new Error("놀이터/공원 데이터를 불러오지 못했습니다.");
	})()
		.then(async (payload) => {
			const rows = (Array.isArray(payload && payload.rows) ? payload.rows : []).map(normalizePlaygroundParkRow).filter(Boolean);
			await hydratePlaygroundParkPendingRows(rows, Array.isArray(payload && payload.geocoding_pending) ? payload.geocoding_pending : []);
			state.playgroundParkRows = rows;
			return rows;
		})
		.catch((error) => {
			console.warn("놀이터/공원 데이터 로드 실패:", error);
			state.playgroundParkRows = [];
			return state.playgroundParkRows;
		})
		.finally(() => {
			state.playgroundParkRowsLoadPromise = null;
		});
	return state.playgroundParkRowsLoadPromise;
}

function getPlaygroundParkOverlayKey(row)
{
	if (!row) return "";
	return ["playground-park", normalizeItemId(row.id || row.name || ""), row.lat, row.lng].join(":");
}

function getPlaygroundParkMarkerHtml()
