function isConvenienceFacilityFilterPanelOpen()
{
	return !!(convenienceFacilityFilterPanel && convenienceFacilityFilterPanel.classList.contains("open"));
}

function closeConvenienceFacilityFilterPanel()
{
	if (!convenienceFacilityFilterPanel) return;
	convenienceFacilityFilterPanel.classList.remove("open");
	if (convenienceFacilityFilterPanel.dataset.panelMode === "life-safety" || !isLifeSafetyOverlayVisible) {
		isLifeSafetyRegionFilterExpanded = false;
	}
	syncLocationAnalysisUI();
	syncMapPropertyToggleButton();
}

function isParcelLifeSafetyFilterPanelOpen()
{
	return !!(convenienceFacilityFilterPanel
		&& convenienceFacilityFilterPanel.classList.contains("open")
		&& convenienceFacilityFilterPanel.dataset.panelMode === "life-safety");
}

function positionConvenienceFacilityFilterPanel()
{
	if (!convenienceFacilityFilterPanel) return;
	const anchorBtn = convenienceFacilityFilterPanel.dataset.panelMode === "life-safety"
		? mapPropertyToggleBtn
		: (mapEducationToolBtn || mapConvenienceToolBtn);
	if (!anchorBtn) return;
	const rect = anchorBtn.getBoundingClientRect();
	const panelRect = convenienceFacilityFilterPanel.getBoundingClientRect();
	const left = Math.max(8, rect.left - panelRect.width - 8);
	const requestedTop = convenienceFacilityFilterPanel.dataset.panelMode === "life-safety"
		? rect.top
		: rect.top - 12;
	const top = Math.min(Math.max(8, requestedTop), window.innerHeight - panelRect.height - 8);
	convenienceFacilityFilterPanel.style.left = left + "px";
	convenienceFacilityFilterPanel.style.top = top + "px";
}

function ensureConvenienceFacilityFilterPanel()
{
	if (convenienceFacilityFilterPanel) return convenienceFacilityFilterPanel;
	convenienceFacilityFilterPanel = document.createElement("div");
	convenienceFacilityFilterPanel.className = "education-facility-filter-panel convenience-facility-filter-panel";
	convenienceFacilityFilterPanel.setAttribute("role", "dialog");
	convenienceFacilityFilterPanel.setAttribute("aria-label", "편의 표시 선택");
	convenienceFacilityFilterPanel.addEventListener("change", async (event) => {
		const input = event.target && event.target.closest ? event.target.closest("input[data-life-safety-region]") : null;
		if (!input) return;
		event.stopPropagation();
		setLifeSafetyRegionSelected(input.dataset.lifeSafetyRegion, input.checked);
		isLifeSafetyRegionFilterExpanded = true;
		if (!hasLifeSafetySelectedRegions()) {
			await setLifeSafetyOverlayVisible(false);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		if (!isLifeSafetyOverlayVisible && input.checked) {
			await setLifeSafetyOverlayVisible(true);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		if (isLifeSafetyOverlayVisible) {
			isLifeSafetyOverlayRenderComplete = false;
			syncLocationAnalysisUI();
			await renderLifeSafetyOverlay();
		} else {
			syncLocationAnalysisUI();
		}
	});
	convenienceFacilityFilterPanel.addEventListener("click", async (event) => {
		const clickTarget = event.target && event.target.closest ? event.target : (event.target && event.target.parentElement ? event.target.parentElement : null);
		const regionResetBtn = clickTarget && clickTarget.closest ? clickTarget.closest("[data-life-safety-region-reset]") : null;
		if (regionResetBtn) {
			event.preventDefault();
			event.stopPropagation();
			lifeSafetySelectedRegionKeys.clear();
			isLifeSafetyRegionFilterExpanded = true;
			isLifeSafetyOverlayRenderComplete = false;
			await setLifeSafetyOverlayVisible(false);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		const clearBtn = clickTarget && clickTarget.closest ? clickTarget.closest("[data-convenience-clear]") : null;
		if (clearBtn) {
			event.preventDefault();
			event.stopPropagation();
			lifeSafetySelectedRegionKeys.clear();
			isLifeSafetyRegionFilterExpanded = false;
			if (isLifeSafetyOverlayVisible) await setLifeSafetyOverlayVisible(false);
			else syncLocationAnalysisUI();
			if (state.isPublicParkingVisible) await setPublicParkingVisible(false);
			if (state.isLargeMartVisible) await setLargeMartVisible(false);
			if (state.isConvenienceStoreVisible) await setConvenienceStoreVisible(false);
			if (state.isCleanHouseVisible) await setCleanHouseVisible(false);
			if (state.isPlaygroundParkVisible) await setPlaygroundParkVisible(false);
			if (state.isBankVisible) await setBankVisible(false);
			if (state.isPublicOfficeVisible) await setPublicOfficeVisible(false);
			if (state.isEvChargerVisible) await setEvChargerVisible(false);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		const option = clickTarget && clickTarget.closest ? clickTarget.closest("[data-convenience-option]") : null;
		if (!option || option.disabled) return;
		event.preventDefault();
		event.stopPropagation();
		if (option.dataset.convenienceOption === "life-safety") {
			isLifeSafetyRegionFilterExpanded = !isLifeSafetyRegionFilterExpanded;
			if (isLifeSafetyRegionFilterExpanded && hasLifeSafetySelectedRegions() && !isLifeSafetyOverlayVisible) await setLifeSafetyOverlayVisible(true);
			else syncLocationAnalysisUI();
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		if (option.dataset.convenienceOption === "public-parking") {
			await setPublicParkingVisible(!state.isPublicParkingVisible);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		if (option.dataset.convenienceOption === "large-mart") {
			await setLargeMartVisible(!state.isLargeMartVisible);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		if (option.dataset.convenienceOption === "convenience-store") {
			await setConvenienceStoreVisible(!state.isConvenienceStoreVisible);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		if (option.dataset.convenienceOption === "clean-house") {
			await setCleanHouseVisible(!state.isCleanHouseVisible);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		if (option.dataset.convenienceOption === "playground-park") {
			await setPlaygroundParkVisible(!state.isPlaygroundParkVisible);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		if (option.dataset.convenienceOption === "bank") {
			await setBankVisible(!state.isBankVisible);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
		if (option.dataset.convenienceOption === "public-office") {
			await setPublicOfficeVisible(!state.isPublicOfficeVisible);
			renderConvenienceFacilityFilterPanel();
			updateConvenienceToolActiveState();
			return;
		}
	});
	document.body.appendChild(convenienceFacilityFilterPanel);
	return convenienceFacilityFilterPanel;
}

function renderLifeSafetyRegionFilterMarkup()
{
	if (!isLifeSafetyRegionFilterExpanded) return "";
	return '<div class="life-safety-region-filter" data-life-safety-region-accordion>'
		+ '<div class="life-safety-region-filter-title">생활안전 참고지표</div>'
		+ '<div class="life-safety-region-filter-subtitle">제공 지역</div>'
		+ '<div class="life-safety-region-filter-list">'
		+ LIFE_SAFETY_REGION_OPTIONS.map(option => '<label class="life-safety-region-filter-item">'
			+ '<input type="checkbox" data-life-safety-region="'
			+ escapeHtml(option.key)
			+ '" '
			+ (lifeSafetySelectedRegionKeys.has(option.key) ? 'checked' : '')
			+ '><span>'
			+ escapeHtml(option.label)
			+ '</span></label>').join("")
		+ '<button type="button" class="life-safety-region-reset" data-life-safety-region-reset>초기화</button>'
		+ '</div></div>';
}

function renderConvenienceFacilityFilterPanel()
{
	const panel = ensureConvenienceFacilityFilterPanel();
	if (getCurrentRealjejuGlobalCategoryKey() === "parcel") {
		panel.dataset.panelMode = "life-safety";
		panel.setAttribute("aria-label", "생활안전 지표 지역 선택");
		isLifeSafetyRegionFilterExpanded = true;
		panel.innerHTML = '<div class="education-facility-filter-grid">'
			+ renderLifeSafetyRegionFilterMarkup()
			+ '</div>'
			+ '<p class="life-safety-update-note">※ 나머지 지역은 추후 업데이트 됩니다.</p>';
		positionConvenienceFacilityFilterPanel();
		syncMapPropertyToggleButton();
		return;
	}
	panel.dataset.panelMode = "convenience";
	panel.setAttribute("aria-label", "편의 표시 선택");
	isLifeSafetyRegionFilterExpanded = false;
	const canClearConvenienceSelection = isLifeSafetyOverlayVisible || state.isPublicParkingVisible || state.isLargeMartVisible || state.isConvenienceStoreVisible || state.isCleanHouseVisible || state.isPlaygroundParkVisible || state.isBankVisible || state.isPublicOfficeVisible || state.isEvChargerVisible;
	const publicParkingOption = { key: "public-parking", label: "공영주차장", icon: "fa-square-parking", active: state.isPublicParkingVisible };
	const convenienceStoreOption = { key: "convenience-store", label: "편의점", icon: "fa-store", active: state.isConvenienceStoreVisible };
	const cleanHouseOption = { key: "clean-house", label: "클린하우스", icon: "fa-recycle", active: state.isCleanHouseVisible };
	const playgroundParkOption = { key: "playground-park", label: "놀이터/공원", icon: "fa-tree", active: state.isPlaygroundParkVisible };
	const bankOption = { key: "bank", label: "은행", icon: "fa-piggy-bank", active: state.isBankVisible };
	const publicOfficeOption = { key: "public-office", label: "공공기관", icon: "fa-building-circle-check", active: state.isPublicOfficeVisible };
	const lifeSafetyOption = { key: "life-safety", label: "생활안전 지표", icon: "fa-shield-heart", active: isLifeSafetyOverlayVisible || isLifeSafetyRegionFilterExpanded };
	const publicParkingButton = '<button type="button" class="education-facility-filter-option convenience-facility-filter-option public-parking-filter-option '
		+ (publicParkingOption.active ? 'active' : '')
		+ '" data-convenience-option="'
		+ escapeHtml(publicParkingOption.key)
		+ '"><i class="fa-solid '
		+ escapeHtml(publicParkingOption.icon)
		+ '" aria-hidden="true"></i><span>'
		+ escapeHtml(publicParkingOption.label)
		+ '</span></button>';
	const convenienceStoreButton = '<button type="button" class="education-facility-filter-option convenience-facility-filter-option convenience-store-filter-option '
		+ (convenienceStoreOption.active ? 'active' : '')
		+ '" data-convenience-option="'
		+ escapeHtml(convenienceStoreOption.key)
		+ '"><i class="fa-solid '
		+ escapeHtml(convenienceStoreOption.icon)
		+ '" aria-hidden="true"></i><span>'
		+ escapeHtml(convenienceStoreOption.label)
		+ '</span></button>';
	const bankButton = '<button type="button" class="education-facility-filter-option convenience-facility-filter-option bank-filter-option '
		+ (bankOption.active ? 'active' : '')
		+ '" data-convenience-option="'
		+ escapeHtml(bankOption.key)
		+ '"><i class="fa-solid '
		+ escapeHtml(bankOption.icon)
		+ '" aria-hidden="true"></i><span>'
		+ escapeHtml(bankOption.label)
		+ '</span></button>';
	const publicOfficeButton = '<button type="button" class="education-facility-filter-option convenience-facility-filter-option public-office-filter-option '
		+ (publicOfficeOption.active ? 'active' : '')
		+ '" data-convenience-option="'
		+ escapeHtml(publicOfficeOption.key)
		+ '"><i class="fa-solid '
		+ escapeHtml(publicOfficeOption.icon)
		+ '" aria-hidden="true"></i><span>'
		+ escapeHtml(publicOfficeOption.label)
		+ '</span></button>';
	const lifeSafetyButton = '<button type="button" class="education-facility-filter-option convenience-facility-filter-option '
		+ (lifeSafetyOption.active ? 'active' : '')
		+ '" data-convenience-option="'
		+ escapeHtml(lifeSafetyOption.key)
		+ '"><i class="fa-solid '
		+ escapeHtml(lifeSafetyOption.icon)
		+ '" aria-hidden="true"></i><span>'
		+ escapeHtml(lifeSafetyOption.label)
		+ '</span></button>';
	const cleanHouseButton = '<button type="button" class="education-facility-filter-option convenience-facility-filter-option clean-house-filter-option '
		+ (cleanHouseOption.active ? 'active' : '')
		+ '" data-convenience-option="'
		+ escapeHtml(cleanHouseOption.key)
		+ '"><i class="fa-solid '
		+ escapeHtml(cleanHouseOption.icon)
		+ '" aria-hidden="true"></i><span>'
		+ escapeHtml(cleanHouseOption.label)
		+ '</span></button>';
	const playgroundParkButton = '<button type="button" class="education-facility-filter-option convenience-facility-filter-option playground-park-filter-option '
		+ (playgroundParkOption.active ? 'active' : '')
		+ '" data-convenience-option="'
		+ escapeHtml(playgroundParkOption.key)
		+ '"><i class="fa-solid '
		+ escapeHtml(playgroundParkOption.icon)
		+ '" aria-hidden="true"></i><span>'
		+ escapeHtml(playgroundParkOption.label)
		+ '</span></button>';
	panel.innerHTML = '<div class="education-facility-filter-grid">'
		+ publicParkingButton
		+ bankButton
		+ convenienceStoreButton
		+ publicOfficeButton
		+ lifeSafetyButton
		+ renderLifeSafetyRegionFilterMarkup()
		+ cleanHouseButton
		+ playgroundParkButton
		+ '</div>'
		+ '<button type="button" class="education-facility-filter-clear '
		+ (!canClearConvenienceSelection ? 'is-disabled' : '')
		+ '" data-convenience-clear '
		+ (!canClearConvenienceSelection ? 'disabled aria-disabled="true"' : '')
		+ '>전체 선택해제</button><div class="education-facility-filter-radius convenience-facility-level-note">레벨 : 클린하우스·놀이터/공원·공영주차장 5단계<br>편의점·생활안전·은행 6단계<br>공공기관 9단계</div>';
	positionConvenienceFacilityFilterPanel();
}

function openConvenienceFacilityFilterPanel()
{
	if (typeof window.closeRealjejuFloatingMenusExcept === "function") window.closeRealjejuFloatingMenusExcept("map-tools");
	closeMapTypePopover();
	closeEducationFacilityFilterPanel();
	closeDevelopmentFacilityFilterPanel();
	closeBrokerOfficeFilterPanel();
	closeMapSettingsFilterPanel();
	renderConvenienceFacilityFilterPanel();
	document.body.appendChild(convenienceFacilityFilterPanel);
	convenienceFacilityFilterPanel.classList.add("open");
	syncMapToolPopoverZOrder(convenienceFacilityFilterPanel);
	positionConvenienceFacilityFilterPanel();
	syncLocationAnalysisUI();
}

function toggleParcelLifeSafetyPanel()
{
	if (getCurrentRealjejuGlobalCategoryKey() !== "parcel") return false;
	if (isParcelLifeSafetyFilterPanelOpen()) {
		closeConvenienceFacilityFilterPanel();
	} else {
		isLifeSafetyRegionFilterExpanded = true;
		openConvenienceFacilityFilterPanel();
	}
	syncMapPropertyToggleButton();
	return false;
}

window.toggleParcelLifeSafetyPanel = toggleParcelLifeSafetyPanel;

function updateConvenienceToolActiveState()
{
	if (!mapConvenienceToolBtn) return;
	if (syncParcelRegulationToolActiveState()) return;
	const isConfiguring = isConvenienceFacilityFilterPanelOpen();
	mapConvenienceToolBtn.classList.toggle("configuring", isConfiguring);
	mapConvenienceToolBtn.classList.toggle("active", !isConfiguring && (state.isPublicParkingVisible || state.isLargeMartVisible || state.isConvenienceStoreVisible || state.isCleanHouseVisible || state.isPlaygroundParkVisible || state.isBankVisible || state.isPublicOfficeVisible || state.isEvChargerVisible));
}


function isDevelopmentFacilityFilterPanelOpen()
{
	return !!(developmentFacilityFilterPanel && developmentFacilityFilterPanel.classList.contains("open"));
}

function closeDevelopmentFacilityFilterPanel()
{
	if (!developmentFacilityFilterPanel) return;
	developmentFacilityFilterPanel.classList.remove("open");
	updateDevelopmentToolActiveState();
	if (typeof syncLocationAnalysisUI === "function") syncLocationAnalysisUI();
}

function positionDevelopmentFacilityFilterPanel()
{
	if (!developmentFacilityFilterPanel) return;
	const anchorBtn = mapEducationToolBtn || mapDevelopmentToolBtn;
	if (!anchorBtn) return;
	const rect = anchorBtn.getBoundingClientRect();
	const panelRect = developmentFacilityFilterPanel.getBoundingClientRect();
	const left = Math.max(8, rect.left - panelRect.width - 8);
	const top = Math.min(Math.max(8, rect.top - 12), window.innerHeight - panelRect.height - 8);
	developmentFacilityFilterPanel.style.left = left + "px";
	developmentFacilityFilterPanel.style.top = top + "px";
}

function ensureDevelopmentFacilityFilterPanel()
{
	if (developmentFacilityFilterPanel) return developmentFacilityFilterPanel;
	developmentFacilityFilterPanel = document.createElement("div");
	developmentFacilityFilterPanel.className = "education-facility-filter-panel development-facility-filter-panel";
	developmentFacilityFilterPanel.setAttribute("role", "dialog");
	developmentFacilityFilterPanel.setAttribute("aria-label", "개발 표시 선택");
	developmentFacilityFilterPanel.addEventListener("click", (event) => {
		event.stopPropagation();
		const clearBtn = event.target.closest("[data-development-clear]");
		if (clearBtn) {
			clearNationalLandPlanSelections();
			setFactoryRestrictionOverlayVisible(false);
			setSewerTreatmentAreaOverlayVisible(false);
			setCulturalHeritageProtectionOverlayVisible(false);
			setLivestockBreedingRestrictionOverlayVisible(false);
			return;
		}
		const nationalLandPlanBtn = event.target.closest("[data-national-land-plan-layer]");
		if (nationalLandPlanBtn) {
			const key = String(nationalLandPlanBtn.dataset.nationalLandPlanLayer || "");
			if (!NATIONAL_LAND_PLAN_DEVELOPMENT_OPTIONS.some((option) => option.key === key)) return;
			setNationalLandPlanOverlayVisible(key, !selectedNationalLandPlanDevelopmentLayers.has(key));
			return;
		}
		const layerBtn = event.target.closest("[data-development-layer]");
		if (!layerBtn) return;
		const isActive = !layerBtn.classList.contains("active");
		if (layerBtn.dataset.developmentLayer === "factory-restriction") setFactoryRestrictionOverlayVisible(isActive);
		if (layerBtn.dataset.developmentLayer === "sewer-treatment-area") setSewerTreatmentAreaOverlayVisible(isActive);
		if (layerBtn.dataset.developmentLayer === "cultural-heritage-protection") setCulturalHeritageProtectionOverlayVisible(isActive);
		if (layerBtn.dataset.developmentLayer === "livestock-breeding-restriction") setLivestockBreedingRestrictionOverlayVisible(isActive);
	});
	document.body.appendChild(developmentFacilityFilterPanel);
	return developmentFacilityFilterPanel;
}

function renderDevelopmentFactoryRestrictionOption()
{
	return '<button type="button" class="education-facility-filter-option development-facility-filter-option '
		+ (isFactoryRestrictionOverlayVisible ? 'active' : '')
		+ '" data-development-layer="factory-restriction" aria-pressed="' + (isFactoryRestrictionOverlayVisible ? 'true' : 'false') + '">'
		+ '<i class="fa-solid fa-industry" aria-hidden="true"></i>'
		+ '<span>공장설립제한</span>'
		+ '</button>';
}

function renderDevelopmentCulturalHeritageProtectionOption()
{
	return '<button type="button" class="education-facility-filter-option development-facility-filter-option '
		+ (isCulturalHeritageProtectionOverlayVisible ? 'active' : '')
		+ '" data-development-layer="cultural-heritage-protection" aria-pressed="' + (isCulturalHeritageProtectionOverlayVisible ? 'true' : 'false') + '">'
		+ '<i class="fa-solid fa-landmark" aria-hidden="true"></i>'
		+ '<span>문화재보호구역</span>'
		+ '</button>';
}

function renderDevelopmentSewerTreatmentAreaOption()
{
	return '<button type="button" class="education-facility-filter-option development-facility-filter-option '
		+ (isSewerTreatmentAreaOverlayVisible ? 'active' : '')
		+ '" data-development-layer="sewer-treatment-area" aria-pressed="' + (isSewerTreatmentAreaOverlayVisible ? 'true' : 'false') + '">'
		+ '<i class="fa-solid fa-droplet" aria-hidden="true"></i>'
		+ '<span>하수처리구역</span>'
		+ '</button>';
}

function renderDevelopmentLivestockBreedingRestrictionOption()
{
	return '<button type="button" class="education-facility-filter-option development-facility-filter-option '
		+ (isLivestockBreedingRestrictionOverlayVisible ? 'active' : '')
		+ '" data-development-layer="livestock-breeding-restriction" aria-pressed="' + (isLivestockBreedingRestrictionOverlayVisible ? 'true' : 'false') + '">'
		+ '<i class="fa-solid fa-cow" aria-hidden="true"></i>'
		+ '<span>가축사육제한</span>'
		+ '</button>';
}

function renderDevelopmentNationalLandPlanOption(option)
{
	const isActive = selectedNationalLandPlanDevelopmentLayers.has(option.key);
	return '<button type="button" class="education-facility-filter-option development-facility-filter-option '
		+ (isActive ? 'active' : '')
		+ '" data-national-land-plan-layer="' + escapeHtml(option.key) + '" aria-pressed="' + (isActive ? 'true' : 'false') + '">'
		+ '<i class="fa-solid ' + escapeHtml(option.icon) + '" aria-hidden="true"></i>'
		+ '<span>' + escapeHtml(option.label) + '</span>'
		+ '</button>';
}

function hasActiveDevelopmentSelection()
{
	return isFactoryRestrictionOverlayVisible
		|| isSewerTreatmentAreaOverlayVisible
		|| isCulturalHeritageProtectionOverlayVisible
		|| isLivestockBreedingRestrictionOverlayVisible
		|| selectedNationalLandPlanDevelopmentLayers.size > 0;
}

function renderDevelopmentFacilityFilterPanel()
{
	const panel = ensureDevelopmentFacilityFilterPanel();
	const hasActiveLayer = hasActiveDevelopmentSelection();
	panel.innerHTML = '<div class="education-facility-filter-grid">'
		+ renderDevelopmentSewerTreatmentAreaOption()
		+ renderDevelopmentCulturalHeritageProtectionOption()
		+ renderDevelopmentFactoryRestrictionOption()
		+ renderDevelopmentLivestockBreedingRestrictionOption()
		+ '</div>'
		+ '<div class="development-facility-filter-section-label">국토계획</div>'
		+ '<div class="education-facility-filter-grid development-national-land-plan-grid">'
		+ NATIONAL_LAND_PLAN_DEVELOPMENT_OPTIONS.map(renderDevelopmentNationalLandPlanOption).join("")
		+ '</div>'
		+ '<button type="button" class="education-facility-filter-clear '
		+ (hasActiveLayer ? '' : 'is-disabled')
		+ '" data-development-clear '
		+ (hasActiveLayer ? 'aria-disabled="false"' : 'disabled aria-disabled="true"')
		+ '>전체 선택해제</button>';
	positionDevelopmentFacilityFilterPanel();
}

function syncDevelopmentFacilityPanelUI()
{
	if (!developmentFacilityFilterPanel) return;
	const layerStates = {
		"factory-restriction": isFactoryRestrictionOverlayVisible,
		"sewer-treatment-area": isSewerTreatmentAreaOverlayVisible,
		"cultural-heritage-protection": isCulturalHeritageProtectionOverlayVisible,
		"livestock-breeding-restriction": isLivestockBreedingRestrictionOverlayVisible
	};
	Object.entries(layerStates).forEach(([layer, active]) => {
		const layerBtn = developmentFacilityFilterPanel.querySelector(`[data-development-layer="${layer}"]`);
		if (!layerBtn) return;
		layerBtn.classList.toggle("active", active);
		layerBtn.setAttribute("aria-pressed", active ? "true" : "false");
	});
	developmentFacilityFilterPanel.querySelectorAll("[data-national-land-plan-layer]").forEach((layerBtn) => {
		const active = selectedNationalLandPlanDevelopmentLayers.has(String(layerBtn.dataset.nationalLandPlanLayer || ""));
		layerBtn.classList.toggle("active", active);
		layerBtn.setAttribute("aria-pressed", active ? "true" : "false");
	});
	const hasActiveLayer = hasActiveDevelopmentSelection();
	const clearBtn = developmentFacilityFilterPanel.querySelector("[data-development-clear]");
	if (clearBtn) {
		clearBtn.classList.toggle("is-disabled", !hasActiveLayer);
		clearBtn.disabled = !hasActiveLayer;
		clearBtn.setAttribute("aria-disabled", hasActiveLayer ? "false" : "true");
	}
}

function openDevelopmentFacilityFilterPanel()
{
	if (typeof window.closeRealjejuFloatingMenusExcept === "function") window.closeRealjejuFloatingMenusExcept("map-tools");
	closeMapTypePopover();
	closeEducationFacilityFilterPanel();
	closeConvenienceFacilityFilterPanel();
	closeBrokerOfficeFilterPanel();
	closeMapSettingsFilterPanel();
	renderDevelopmentFacilityFilterPanel();
	document.body.appendChild(developmentFacilityFilterPanel);
	developmentFacilityFilterPanel.classList.add("open");
	syncMapToolPopoverZOrder(developmentFacilityFilterPanel);
	positionDevelopmentFacilityFilterPanel();
	updateDevelopmentToolActiveState();
	if (typeof syncLocationAnalysisUI === "function") syncLocationAnalysisUI();
}

function updateDevelopmentToolActiveState()
{
	if (!mapDevelopmentToolBtn) return;
	if (syncParcelRegulationToolActiveState()) return;
	mapDevelopmentToolBtn.classList.toggle("configuring", isDevelopmentFacilityFilterPanelOpen());
	mapDevelopmentToolBtn.classList.toggle("active", !isDevelopmentFacilityFilterPanelOpen() && hasActiveDevelopmentSelection());
}

function isMapHomeWorkspaceVisible()
{
	if (!document.body) return true;
	const nonHomeClasses = [
		"auth-page-open",
		"auth-recovery-page-open",
		"payment-page-open",
		"profile-page-open",
		"myinfo-page-open",
		"profile-edit-page-open",
		"broker-office-info-page-open",
		"broker-office-apply-page-open",
		"broker-office-edit-page-open",
		"property-register-page-open",
		"admin-page-open",
		"broker-home-page-open",
		"my-suite-page-open",
		"notice-page-open",
		"presale-page-open",
		"detail-page-panel-open"
	];
	return !nonHomeClasses.some((className) => document.body.classList.contains(className));
}

function closeFacilityFilterPanelsOutsideMapHome()
{
	if (isMapHomeWorkspaceVisible()) {
		scheduleWeeklySpecialistBrokerPanelRender(240);
		return;
	}
	closeEducationFacilityFilterPanel();
	closeConvenienceFacilityFilterPanel();
	closeDevelopmentFacilityFilterPanel();
	closeBrokerOfficeFilterPanel();
	closeMapSettingsFilterPanel();
	hideWeeklySpecialistBrokerPanel();
}

if (document.body && window.MutationObserver)
{
	const facilityPanelPageObserver = new MutationObserver(closeFacilityFilterPanelsOutsideMapHome);
	facilityPanelPageObserver.observe(document.body, { attributes: true, attributeFilter: ["class"] });
	closeFacilityFilterPanelsOutsideMapHome();
}

async function renderBrokerOfficeOverlays(options = {})
{
	if (!state.map || !window.kakao || !kakao.maps) return false;
	if (state.localBusinessAutoMapMode && !hasUsableBrokerSpecialtyStats()) {
		clearBrokerOfficeOverlays();
	}
	const specialtyStatsPromise = state.localBusinessAutoMapMode
		? loadBrokerSpecialtyStats({ force: !!options.force })
		: null;
	let rows = await fetchBrokerOfficeMapRows({ force: !!options.force });
	if (!rows.length) {
		const entries = applyBrokerOfficeEntriesWithLocalProfessionals([]);
		return entries.length > 0;
	}
	if (rows.some(office => !normalizeJejuLatLngPair(office.lat, office.lng))) {
		rows = await backfillBrokerOfficeLatLngRows(rows);
		state.brokerOfficeRows = rows;
	}
	if (specialtyStatsPromise) await specialtyStatsPromise;
	else await loadBrokerSpecialtyStats({ force: !!options.force });
	if (state.localBusinessAutoMapMode && !(await ensureBrokerSpecialtyStatsMatchOffices(rows))) {
		applyBrokerOfficeEntriesWithLocalProfessionals([]);
		state.localBusinessAutoRowsReady = false;
		if (!state.brokerSpecialtyStatsRenderWarningShown) {
			state.brokerSpecialtyStatsRenderWarningShown = true;
			console.warn("동네업체 중개사 매물 수 통계를 준비하지 못해 뱃지 렌더를 미룹니다.");
		}
		return false;
	}
	if (ENABLE_BROKER_OFFICE_MARKER_SPECIALTY) {
		await loadBrokerSpecialtyAwardCounts({ force: !!options.force });
	}
	scheduleWeeklySpecialistBrokerPanelRender(240, { force: !!options.force });
	rows = rows.filter(brokerOfficeMatchesSelectedMapFilter);
	if (ENABLE_BROKER_OFFICE_MARKER_SPECIALTY) refreshBrokerOfficeTopListingCrownKeys(rows);
	if (!rows.length) {
		applyBrokerOfficeEntriesWithLocalProfessionals([]);
		return true;
	}
	const mapBounds = getExpandedMapBounds();
	const visibleRows = rows.map((office) => {
		const normalized = normalizeJejuLatLngPair(office.lat, office.lng);
		return normalized ? { ...office, ...normalized } : null;
	}).filter(office => office && isLatLngInsideBounds(office.lat, office.lng, mapBounds));
	if (!visibleRows.length) {
		applyBrokerOfficeEntriesWithLocalProfessionals([], mapBounds);
		if (!rows.some(office => normalizeJejuLatLngPair(office.lat, office.lng))) {
			console.warn("중개사무소 위치를 표시할 DB 좌표가 없습니다. broker_office_locations lat/lng 값을 확인하세요.", rows.map(office => ({
				officeName: office.officeName,
				address: office.address,
				agencyId: office.agencyId,
				userId: office.userId,
				lat: office.lat,
				lng: office.lng
			})));
		}
		return true;
	}
	if (!(await loadBrokerOfficeListingCountsForOffices(visibleRows, { force: !!options.force }))) {
		applyBrokerOfficeEntriesWithLocalProfessionals([], mapBounds);
		console.warn("동네업체 중개사 공개 매물 수를 준비하지 못해 뱃지 렌더를 미룹니다.");
		return false;
	}

	const entries = spreadBrokerOfficeOverlaysByAddress(visibleRows).map((office) => ({
		key: getBrokerOfficeOverlayKey(office),
		dataKey: getBrokerOfficeOverlayDataKey(office),
		zIndex: getFacilityOverlayZIndex("broker"),
		position: normalizeJejuLatLngPair(office.lat, office.lng),
		createOverlay: () => createBrokerOfficeOverlay(office)
	}));
	applyBrokerOfficeEntriesWithLocalProfessionals(entries, mapBounds);
	syncFacilityOverlayZIndexes();
	return true;
}

function isBrokerOfficeFilterPanelOpen()
{
	return !!(brokerOfficeFilterPanel && brokerOfficeFilterPanel.classList.contains("open"));
}

function closeBrokerOfficeFilterPanel()
{
	if (!brokerOfficeFilterPanel) return;
	brokerOfficeFilterPanel.classList.remove("open");
	updateBrokerOfficeToolActiveState();
	if (typeof syncLocationAnalysisUI === "function") syncLocationAnalysisUI();
}

function positionBrokerOfficeFilterPanel()
{
	if (!brokerOfficeFilterPanel || !mapBrokerToolBtn) return;
	const rect = mapBrokerToolBtn.getBoundingClientRect();
	const topAnchorBtn = mapEducationToolBtn || mapBrokerToolBtn;
	const topRect = topAnchorBtn.getBoundingClientRect();
	const panelRect = brokerOfficeFilterPanel.getBoundingClientRect();
	const left = Math.max(8, rect.left - panelRect.width - 8);
	const top = Math.min(Math.max(8, topRect.top - 12), window.innerHeight - panelRect.height - 8);
	brokerOfficeFilterPanel.style.left = left + "px";
	brokerOfficeFilterPanel.style.top = top + "px";
}

// 4.972: 중개 > 내 매물만은 기존 목록 표면을 비워 둔 채 재사용하지 않습니다.
// 동네업체 카드, 중개사 매물 목록, 일반 매물 목록, 상세 패널을 모두 닫고
// 서버 소유 범위가 적용된 지도 결과만 남깁니다.
function closeListingPanelsForBrokerMineScope()
{
	if (typeof hideLocalBusinessRecentCard === "function") hideLocalBusinessRecentCard();
	if (typeof hideWeeklySpecialistBrokerPanel === "function") hideWeeklySpecialistBrokerPanel();
	if (typeof hideBrokerOfficeMapTooltip === "function") hideBrokerOfficeMapTooltip();

	const listSurfaceOpen = !!(
		state.isListOpen
		|| state.agentListFilter
		|| state.leftListRemoteAgent
		|| !document.body.classList.contains("sidebar-list-collapsed")
	);
	const detailSurfaceOpen = !!(
		(sidebar && sidebar.classList.contains("expanded"))
		|| document.body.classList.contains("detail-page-panel-open")
		|| document.body.classList.contains("shared-detail-mode")
	);

	if (listSurfaceOpen && typeof closeSidebarList === "function") {
		closeSidebarList();
	} else if (detailSurfaceOpen && typeof closeDetailPanel === "function") {
		closeDetailPanel();
	}
	closeBrokerOfficeFilterPanel();
}

function ensureBrokerOfficeFilterPanel()
{
	if (brokerOfficeFilterPanel) return brokerOfficeFilterPanel;
	brokerOfficeFilterPanel = document.createElement("div");
	brokerOfficeFilterPanel.className = "education-facility-filter-panel broker-office-filter-panel";
	brokerOfficeFilterPanel.setAttribute("role", "dialog");
	brokerOfficeFilterPanel.setAttribute("aria-label", "중개 표시 선택");
	brokerOfficeFilterPanel.addEventListener("click", async (event) => {
		const option = event.target.closest("[data-broker-office-filter-option]");
		if (option) {
			event.preventDefault();
			event.stopPropagation();
			const key = option.dataset.brokerOfficeFilterOption || "all";
			if (key === "mine" || key === "office") {
				state.brokerListingMapScope = state.brokerListingMapScope === key ? "all" : key;
				state.brokerOfficeMapFilter = "none";
				state.isBrokerOfficesVisible = false;
				selectAllTopPropertyTypeFilters({ apply: false });
				clearBrokerOfficeOverlays();
				if (key === "mine") closeListingPanelsForBrokerMineScope();
				applyFilter();
				renderBrokerOfficeFilterPanel();
				updateBrokerOfficeToolActiveState();
				return;
			}
			const didResetBrokerListingScope = state.brokerListingMapScope !== "all";
			state.brokerListingMapScope = "all";
			const isSameActiveFilter = state.isBrokerOfficesVisible && state.brokerOfficeMapFilter === key;
			state.brokerOfficeMapFilter = isSameActiveFilter ? "none" : key;
			state.isBrokerOfficesVisible = !isSameActiveFilter;
			// 중개사 전문분야 선택은 매물 필터가 아니므로 열린 지역 목록과 선택 박스를 유지한다.
			// 내 매물/우리 사무소 범위에서 넘어온 경우에만 실제 매물 범위를 전체로 되돌린다.
			if (didResetBrokerListingScope) applyFilter();
			if (state.isBrokerOfficesVisible) {
				bringFacilityOverlayLayerToFront("broker");
				await renderBrokerOfficeOverlays();
			} else {
				clearBrokerOfficeOverlays();
			}
			renderBrokerOfficeFilterPanel();
			updateBrokerOfficeToolActiveState();
			return;
		}
		const clearBtn = event.target.closest("[data-broker-office-filter-clear]");
		if (clearBtn) {
			event.preventDefault();
			event.stopPropagation();
			const didResetBrokerListingScope = state.brokerListingMapScope !== "all";
			state.brokerOfficeMapFilter = "none";
			state.brokerListingMapScope = "all";
			state.isBrokerOfficesVisible = false;
			clearBrokerOfficeOverlays();
			if (didResetBrokerListingScope) applyFilter();
			renderBrokerOfficeFilterPanel();
			updateBrokerOfficeToolActiveState();
		}
	});
	document.body.appendChild(brokerOfficeFilterPanel);
	return brokerOfficeFilterPanel;
}

function syncPropertyBadgeStylePopover(popover, style)
{
	if (!popover) return;
	const normalized = {
		color: normalizePropertyBadgeStyleColor(style && style.color),
		textColor: normalizePropertyBadgeTextColor(style && style.textColor),
		textOpacity: normalizePropertyBadgeTextOpacity(style && style.textOpacity),
		opacity: normalizePropertyBadgeStyleOpacity(style && style.opacity)
	};
	popover.dataset.draftColor = normalized.color;
	popover.dataset.draftOpacity = String(normalized.opacity);
	popover.querySelectorAll("[data-property-badge-style-color]").forEach((button) => {
		const isActive = String(button.dataset.propertyBadgeStyleColor || "").toUpperCase() === normalized.color;
		button.classList.toggle("active", isActive);
		button.setAttribute("aria-pressed", isActive ? "true" : "false");
	});
	const opacityInput = popover.querySelector("[data-property-badge-style-opacity]");
	if (opacityInput) opacityInput.value = String(Math.round(normalized.opacity * 100));
	const opacityValue = popover.querySelector("[data-property-badge-style-opacity-value]");
	if (opacityValue) opacityValue.textContent = `${Math.round(normalized.opacity * 100)}%`;
	const preview = popover.querySelector("[data-property-badge-style-preview]");
	if (preview) {
		preview.style.background = hexToRgba(normalized.color, normalized.opacity);
		preview.style.color = getResolvedPropertyBadgeTextColor(normalized);
		preview.style.borderColor = getResolvedPropertyBadgeBorderColor(normalized);
	}
}

