async function hydrateFavoriteListingSnapshotsByIds(ids)
{
	const listingIds = [...new Set((Array.isArray(ids) ? ids : [])
		.map(normalizeItemId)
		.filter(Boolean))];
	if (!listingIds.length || typeof fetchLeftListRowsByIds !== "function") return 0;

	const snapshots = getFavoriteSnapshotMap();
	const liveItems = Array.isArray(state && state.all) ? state.all : [];
	const liveById = new Map(liveItems
		.map((item) => [normalizeItemId(item && item.id), item])
		.filter(([id]) => !!id));
	let hydratedCount = 0;
	listingIds.forEach((id) => {
		if (snapshots[id] || !liveById.has(id)) return;
		const snapshot = makeFavoriteListingSnapshot(liveById.get(id));
		if (!snapshot) return;
		snapshots[id] = snapshot;
		hydratedCount += 1;
	});
	const missingIds = listingIds.filter((id) => !liveById.has(id) && !snapshots[id]);
	if (!missingIds.length) {
		saveFavoriteSnapshotMap(snapshots);
		return hydratedCount;
	}

	// 관심 목록은 현재 지도 범위와 무관해야 한다. 전체 공개 매물을 받지 않고
	// 사용자가 저장한 ID에 해당하는 목록 요약만 50건씩 조회해 전용 스냅샷에 보관한다.
	const batchSize = 50;
	for (let offset = 0; offset < missingIds.length; offset += batchSize) {
		const batchIds = missingIds.slice(offset, offset + batchSize);
		let rows = [];
		try {
			rows = await fetchLeftListRowsByIds(batchIds);
		} catch (error) {
			console.warn("관심매물 목록 요약 불러오기 실패:", error);
			continue;
		}
		(Array.isArray(rows) ? rows : []).forEach((item) => {
			const snapshot = makeFavoriteListingSnapshot(item);
			if (!snapshot) return;
			snapshots[snapshot.id] = snapshot;
			hydratedCount += 1;
		});
	}
	saveFavoriteSnapshotMap(snapshots);
	return hydratedCount;
}

function makeFavoriteListingSnapshot(item)
{
	if (!item || typeof item !== "object") return null;
	const listingId = normalizeItemId(item.id);
	if (!listingId) return null;
	return {
		...item,
		id: listingId,
		listingNo: normalizePropertyListingNoCandidate(item.listingNo),
		title: item.title || "",
		dealType: item.dealType || "",
		type: item.type || item.typeFilter || "",
		typeFilter: item.typeFilter || item.type || "",
		price: item.price || "",
		area: item.area || "",
		address: item.address || "",
		image: item.image || "",
		date: item.date || "",
		dateLabel: item.dateLabel || "",
		maintenance: item.maintenance || {}
	};
}

function saveFavoriteListingSnapshot(item)
{
	const snapshot = makeFavoriteListingSnapshot(item);
	if (!snapshot) return false;
	const snapshots = getFavoriteSnapshotMap();
	snapshots[snapshot.id] = snapshot;
	saveFavoriteSnapshotMap(snapshots);
	return true;
}

function getFavoriteRefreshedAtMap()
{
	syncFavoriteStateUserBoundary();
	return { ...realjejuFavoriteRefreshedAt };
}

function saveFavoriteRefreshedAtMap(map)
{
	realjejuFavoriteRefreshedAt = map && typeof map === "object" && !Array.isArray(map) ? { ...map } : {};
}

async function getFavoriteSupabaseUser()
{
	const client = getRealjejuSupabaseClient();
	if (!client) return null;
	try {
		const { data: sessionData, error: sessionError } = await client.auth.getSession();
		if (sessionError) return null;
		const sessionUser = sessionData && sessionData.session ? sessionData.session.user : null;
		if (!sessionUser || !sessionUser.id) {
			clearFavoriteListingState();
			return null;
		}
		const cachedUser = getFavoriteCachedAuthUser();
		if (cachedUser && cachedUser.id === sessionUser.id) return cachedUser;
		const { data, error } = await client.auth.getUser();
		if (error) return null;
		const user = data && data.user ? data.user : null;
		if (user && user.id) {
			setFavoriteCachedAuthUser(user);
		}
		return user;
	} catch (err) {
		return null;
	}
}

