function getFavoriteSectionOptionLabel(sections, value)
{
	const option = (Array.isArray(sections) ? sections : [])
		.flatMap((section) => Array.isArray(section.options) ? section.options : [])
		.find((item) => item.value === value);
	return option?.label || value;
}

function getFavoriteCompactFilterLabel(values, fallback, labelGetter, visibleCount = 2)
{
	const list = Array.from(values || []).map((value) => labelGetter ? labelGetter(value) : value).filter(Boolean);
	if (!list.length) return fallback;
	if (list.length <= visibleCount) return list.join(", ");
	return `${list.slice(0, visibleCount).join(", ")} +${list.length - visibleCount}`;
}

function getFavoriteAreaMaxM2(range = getFavoriteAreaRange())
{
	return range && range.land === true ? AREA_FILTER_LAND_MAX_M2 : AREA_FILTER_MAX_M2;
}

function getFavoriteAreaUnit(range = getFavoriteAreaRange())
{
	return range && range.unit === "py" ? "py" : "m2";
}

function getFavoriteAreaUnitLabel(range = getFavoriteAreaRange())
{
	return getFavoriteAreaUnit(range) === "py" ? "평" : "㎡";
}

function getFavoriteAreaNextUnitLabel(range = getFavoriteAreaRange())
{
	return getFavoriteAreaUnit(range) === "py" ? "㎡" : "평";
}

function getFavoriteAreaUnitMax(range = getFavoriteAreaRange())
{
	const unit = getFavoriteAreaUnit(range);
	return range && range.land === true
		? (unit === "py" ? AREA_FILTER_LAND_MAX_PY : AREA_FILTER_LAND_MAX_M2)
		: (unit === "py" ? AREA_FILTER_MAX_PY : AREA_FILTER_MAX_M2);
}

function getFavoriteAreaThumbGapValue()
{
	const rail = document.getElementById("favoriteAreaFilterSliderRail");
	const railWidth = rail ? rail.getBoundingClientRect().width : 0;
	if (!railWidth) return 1;
	return Math.max(0.01, (FILTER_RANGE_THUMB_GAP_PX / railWidth) * getFavoriteAreaUnitMax());
}

function getFavoriteAreaValueFromTrackPointer(event)
{
	const rail = document.getElementById("favoriteAreaFilterSliderRail");
	if (!event || !rail) return 0;
	const unitMax = getFavoriteAreaUnitMax();
	const rect = rail.getBoundingClientRect();
	const width = Math.max(1, rect.width);
	const ratio = Math.max(0, Math.min(1, (event.clientX - rect.left) / width));
	return ratio * unitMax;
}

function isFavoriteAreaPointerNearHandle(event)
{
	const rail = document.getElementById("favoriteAreaFilterSliderRail");
	const minInput = document.getElementById("favoriteAreaFilterMinRange");
	const maxInput = document.getElementById("favoriteAreaFilterMaxRange");
	if (!event || !rail || !minInput || !maxInput) return false;
	const rect = rail.getBoundingClientRect();
	const width = Math.max(1, rect.width);
	const pointerX = event.clientX;
	const handleRadius = Math.max(18, FILTER_RANGE_THUMB_GAP_PX * 0.5);
	const unitMax = getFavoriteAreaUnitMax();
	return [minInput, maxInput].some(input => {
		const value = Number(input.value);
		const safeValue = Number.isFinite(value) ? Math.max(0, Math.min(unitMax, value)) : 0;
		const handleX = rect.left + (safeValue / unitMax) * width;
		return Math.abs(pointerX - handleX) <= handleRadius;
	});
}

function getNearestFavoriteAreaHandle(value)
{
	const minInput = document.getElementById("favoriteAreaFilterMinRange");
	const maxInput = document.getElementById("favoriteAreaFilterMaxRange");
	if (!minInput || !maxInput) return null;
	const unitMax = getFavoriteAreaUnitMax();
	const min = Number(minInput.value) || 0;
	const max = Number(maxInput.value) || unitMax;
	if (value <= min) return minInput;
	if (value >= max) return maxInput;
	return Math.abs(value - min) <= Math.abs(max - value) ? minInput : maxInput;
}

function favoriteAreaToM2(value, unit = getFavoriteAreaUnit())
{
	return areaFilterToM2(value, unit);
}

function favoriteAreaFromM2(value, unit = getFavoriteAreaUnit())
{
	return areaFilterFromM2(value, unit);
}

function getFavoriteAreaRange()
{
	const range = mySuiteFavoriteAreaRange && typeof mySuiteFavoriteAreaRange === "object" ? mySuiteFavoriteAreaRange : {};
	const land = range.land === true;
	const maxM2 = getFavoriteAreaMaxM2({ land });
	const min = Math.max(0, Math.min(maxM2, Number(range.min) || 0));
	const rawMax = Number(range.max);
	const max = Math.max(0, Math.min(maxM2, Number.isFinite(rawMax) ? rawMax : maxM2));
	mySuiteFavoriteAreaRange = {
		min: Math.min(min, max),
		max: Math.max(min, max),
		exclusive: !land,
		land,
		unit: range.unit === "py" ? "py" : "m2"
	};
	return mySuiteFavoriteAreaRange;
}

function isFavoriteAreaRangeActive(range = getFavoriteAreaRange())
{
	const maxM2 = getFavoriteAreaMaxM2(range);
	return Number(range.min) > 0 || Number(range.max) < maxM2 - AREA_FILTER_MAX_EDGE_EPSILON_M2 || range.land === true;
}

function formatFavoriteAreaRangeSummary(range = getFavoriteAreaRange())
{
	if (!isFavoriteAreaRangeActive(range)) return "전체";
	const unit = getFavoriteAreaUnit(range);
	const unitLabel = getFavoriteAreaUnitLabel(range);
	const maxM2 = getFavoriteAreaMaxM2(range);
	const minLabel = Number(range.min) <= 0 ? "최소" : `${Math.round(favoriteAreaFromM2(range.min, unit)).toLocaleString("ko-KR")}${unitLabel}`;
	const maxLabel = Number(range.max) >= maxM2 - AREA_FILTER_MAX_EDGE_EPSILON_M2 ? "최대" : `${Math.round(favoriteAreaFromM2(range.max, unit)).toLocaleString("ko-KR")}${unitLabel}`;
	const prefix = range.exclusive && !range.land ? "전용 " : "";
	return `${prefix}${minLabel}~${maxLabel}`;
}

function getFavoriteAreaScaleHtml(range = getFavoriteAreaRange())
{
	const unit = getFavoriteAreaUnit(range);
	const unitLabel = getFavoriteAreaUnitLabel(range);
	const values = range.land
		? (unit === "py" ? [100, 200, 300, 400] : [330, 660, 990, 1320])
		: (unit === "py" ? [10, 20, 30, 40] : [33, 66, 99, 132]);
	const labels = ["최소", ...values.map(value => `${value}${unitLabel}`), "최대"];
	const lastIndex = Math.max(1, labels.length - 1);
	return labels
		.map((label, index) => `<span style="left:${(index / lastIndex) * 100}%;">${label}</span>`)
		.join("");
}

function syncFavoriteAreaFilterUi()
{
	const range = getFavoriteAreaRange();
	const minInput = document.getElementById("favoriteAreaFilterMinRange");
	const maxInput = document.getElementById("favoriteAreaFilterMaxRange");
	const fill = document.getElementById("favoriteAreaFilterSliderFill");
	const summary = document.getElementById("favoriteAreaFilterSummaryText");
	const exclusive = document.getElementById("favoriteAreaFilterExclusiveChk");
	const land = document.getElementById("favoriteAreaFilterLandChk");
	const reset = document.getElementById("favoriteAreaFilterResetBtn");
	const unitText = document.getElementById("favoriteAreaFilterUnitToggleText");
	const scale = document.getElementById("favoriteAreaFilterScale");
	const unit = getFavoriteAreaUnit(range);
	const unitMax = getFavoriteAreaUnitMax(range);
	const maxM2 = getFavoriteAreaMaxM2(range);
	const minUnitValue = Number.isFinite(range.min) ? favoriteAreaFromM2(range.min, unit) : 0;
	const maxUnitValue = Number(range.max) >= maxM2 - AREA_FILTER_MAX_EDGE_EPSILON_M2 ? unitMax : favoriteAreaFromM2(range.max, unit);
	[minInput, maxInput].forEach(input => {
		if (!input) return;
		input.min = "0";
		input.max = String(unitMax);
		input.step = "0.01";
	});
	if (minInput) minInput.value = String(Math.max(0, Math.min(unitMax, minUnitValue || 0)));
	if (maxInput) maxInput.value = String(Math.max(0, Math.min(unitMax, maxUnitValue || unitMax)));
	if (fill) {
		const left = unitMax > 0 ? ((minUnitValue || 0) / unitMax) * 100 : 0;
		const right = unitMax > 0 ? ((maxUnitValue || unitMax) / unitMax) * 100 : 100;
		fill.style.left = `${left}%`;
		fill.style.width = `${Math.max(0, right - left)}%`;
	}
	if (summary) summary.textContent = formatFavoriteAreaRangeSummary(range);
	if (exclusive) exclusive.checked = range.exclusive;
	if (land) land.checked = range.land;
	if (unitText) unitText.textContent = getFavoriteAreaNextUnitLabel(range);
	if (scale) scale.innerHTML = getFavoriteAreaScaleHtml(range);
	if (reset) {
		const active = isFavoriteAreaRangeActive(range);
		reset.hidden = !active;
		reset.classList.toggle("is-visible", active);
	}
}

function updateFavoriteAreaRangeFromControls(activeInput = document.activeElement)
{
	const minInput = document.getElementById("favoriteAreaFilterMinRange");
	const maxInput = document.getElementById("favoriteAreaFilterMaxRange");
	const exclusive = document.getElementById("favoriteAreaFilterExclusiveChk");
	const land = document.getElementById("favoriteAreaFilterLandChk");
	const current = getFavoriteAreaRange();
	let nextLand = current.land === true;
	if (activeInput === land) nextLand = true;
	else if (activeInput === exclusive) nextLand = false;
	const nextRangeShape = { ...current, land: nextLand };
	const modeChanged = nextLand !== current.land;
	const unit = getFavoriteAreaUnit(current);
	const unitMax = getFavoriteAreaUnitMax(nextRangeShape);
	const maxM2 = getFavoriteAreaMaxM2(nextRangeShape);
	let min = Number(minInput?.value ?? favoriteAreaFromM2(current.min, unit));
	let max = Number(maxInput?.value ?? favoriteAreaFromM2(current.max, unit));
	if (!Number.isFinite(min)) min = 0;
	if (!Number.isFinite(max)) max = unitMax;
		const gap = getFavoriteAreaThumbGapValue();
	if (modeChanged) {
		min = 0;
		max = unitMax;
	}
	else if (activeInput === minInput) {
		min = Math.min(min, Math.max(0, max - gap));
		if (minInput) minInput.value = String(min);
	}
	else if (activeInput === maxInput) {
		max = Math.max(max, Math.min(unitMax, min + gap));
		if (maxInput) maxInput.value = String(max);
	}
	else if (min + gap > max) {
		max = Math.min(unitMax, min + gap);
		if (max >= unitMax) min = Math.max(0, max - gap);
		if (minInput) minInput.value = String(min);
		if (maxInput) maxInput.value = String(max);
	}
	const minM2 = modeChanged ? 0 : favoriteAreaToM2(min, unit);
	const maxM2Value = modeChanged || max >= unitMax - 0.01 ? maxM2 : favoriteAreaToM2(max, unit);
	mySuiteFavoriteAreaRange = {
		min: Math.max(0, Math.min(maxM2, Number(minM2) || 0)),
		max: Math.max(0, Math.min(maxM2, Number(maxM2Value) || maxM2)),
		exclusive: !nextLand,
		land: nextLand,
		unit: current.unit
	};
	syncFavoriteAreaFilterUi();
}

function resetFavoriteAreaRange()
{
	const unit = getFavoriteAreaRange().unit;
	mySuiteFavoriteAreaRange = { min: 0, max: AREA_FILTER_MAX_M2, exclusive: true, land: false, unit };
}

function getFavoriteAreaValuesM2(item, range = getFavoriteAreaRange())
{
	if (range.land && typeof isAreaFilterLandItem === "function" && !isAreaFilterLandItem(item)) return [];
	const prevLand = selectedAreaLandOnly;
	const prevExclusive = selectedAreaExclusiveOnly;
	try {
		selectedAreaLandOnly = !!range.land;
		selectedAreaExclusiveOnly = !range.land;
		return typeof getItemAreaFilterValuesM2 === "function" ? getItemAreaFilterValuesM2(item, !range.land) : [];
	}
	finally {
		selectedAreaLandOnly = prevLand;
		selectedAreaExclusiveOnly = prevExclusive;
	}
}

function matchesFavoriteAreaRange(item)
{
	const range = getFavoriteAreaRange();
	if (!isFavoriteAreaRangeActive(range)) return true;
	if (range.land && typeof isAreaFilterLandItem === "function" && !isAreaFilterLandItem(item)) return false;
	const values = getFavoriteAreaValuesM2(item, range);
	if (!values.length) return false;
	const min = Number(range.min) || 0;
	const maxM2 = getFavoriteAreaMaxM2(range);
	const max = Number(range.max) >= maxM2 - AREA_FILTER_MAX_EDGE_EPSILON_M2 ? Infinity : Number(range.max);
	return values.some((value) => Number.isFinite(value) && value >= min && value <= max);
}

function normalizeFavoriteTypeText(value)
{
	return String(value || "").replace(/\s+/g, "").trim();
}

function matchesFavoritePropertyFilter(item)
{
	if (!mySuiteFavoritePropertyFilter.size) return true;
	const itemType = normalizeFavoriteTypeText(getFavoritePropertyFilterValue(item));
	if (!itemType) return false;
	return Array.from(mySuiteFavoritePropertyFilter).some((value) => {
		const filter = normalizeFavoriteTypeText(value);
		if (filter === itemType) return true;
		if (filter === "토지") return ["토지", "토지ㆍ임야", "임야", "전", "답", "대", "대지", "과수원", "목장용지"].includes(itemType);
		if (filter === "빌라") return ["빌라", "연립", "다세대", "다세대주택"].includes(itemType);
	if (filter === "원룸/투룸") return ["원룸", "투룸", "원룸ㆍ투룸", "원룸/투룸"].includes(itemType);
	if (filter === "원룸 / 투룸") return ["원룸", "투룸", "원룸ㆍ투룸", "원룸/투룸", "원룸 / 투룸"].includes(itemType);
		if (filter === "단독주택") return ["주택", "단독", "단독주택"].includes(itemType);
		if (filter === "다가구주택") return ["다가구", "다가구주택"].includes(itemType);
		if (filter === "공장/창고") return ["공장", "창고", "공장/창고", "공장ㆍ창고", "창고시설"].includes(itemType);
		return false;
	});
}

function getFilteredFavoriteListingItems(items)
{
	const list = Array.isArray(items) ? items : [];
	const dealFilter = mySuiteFavoriteDealFilter instanceof Set ? mySuiteFavoriteDealFilter : new Set();
	return list.filter((item) => {
		if (!matchesFavoritePropertyFilter(item)) return false;
		if (!dealFilter.size) return false;
		if (!getFavoriteDealFilterValues(item).some((deal) => dealFilter.has(deal))) return false;
		if (!matchesFavoriteAreaRange(item)) return false;
		if (mySuiteFavoriteLandTypeFilter.size && !matchesLandTypeFilter(item, mySuiteFavoriteLandTypeFilter)) return false;
		if (mySuiteFavoriteLandUseZoneFilter.size && !matchesLandUseZoneFilter(item, mySuiteFavoriteLandUseZoneFilter)) return false;
		return true;
	});
}

function renderFavoriteFilterTile(type, option, selectedSet)
{
	const value = option?.value || "";
	const label = option?.label || value;
	const active = selectedSet instanceof Set && selectedSet.has(value);
	const landTypeClass = type === "landType" ? " land-type-filter-tile" : "";
	return `<label class="extra-filter-option type-filter-option type-filter-tile${landTypeClass} broker-home-filter-option ${active ? "active" : ""}"><input type="checkbox" class="broker-home-filter-check" data-favorite-filter-option="${escapeHtml(type)}" data-value="${escapeHtml(value)}" ${active ? "checked" : ""} /><span>${escapeHtml(label)}</span></label>`;
}

function renderFavoriteFilterSection(type, section, selectedSet)
{
	const options = Array.isArray(section?.options) ? section.options : [];
	return [
		'<section class="type-filter-section">',
		section?.title ? `<h3 class="type-filter-section-title">${escapeHtml(section.title)}</h3>` : "",
		`<div class="type-filter-grid ${escapeHtml(section?.className || "")}">`,
		...options.map((option) => renderFavoriteFilterTile(type, option, selectedSet)),
		"</div>",
		"</section>"
	].join("");
}

function renderFavoriteFilterMenu(type, sections, selectedSet, menuTitle = "")
{
	const list = Array.isArray(sections) ? sections : [];
	return [
		menuTitle ? `<h3 class="broker-home-filter-menu-title">${escapeHtml(menuTitle)}</h3>` : "",
		'<div class="broker-home-type-buttons">',
		...list.map((section) => renderFavoriteFilterSection(type, section, selectedSet)),
		"</div>",
		`<div class="extra-filter-reset-row broker-home-filter-reset-row"><button type="button" class="extra-filter-reset-btn broker-home-filter-reset-btn" data-favorite-filter-reset="${escapeHtml(type)}"><i class="fa-solid fa-rotate-right" aria-hidden="true"></i><span>초기화</span></button></div>`
	].join("");
}

function renderFavoriteAreaFilterMenu()
{
	return `
		<h3 class="area-filter-title">면적</h3>
		<div class="area-filter-summary-row">
			<strong class="area-filter-summary" id="favoriteAreaFilterSummaryText">전체</strong>
			<button type="button" class="area-filter-icon-btn area-filter-manual-btn" aria-label="면적 직접 입력">
				<i class="fa-solid fa-pen" aria-hidden="true"></i>
			</button>
			<button type="button" class="area-filter-unit-btn" id="favoriteAreaFilterUnitToggleBtn" aria-label="면적 단위 전환">
				<i class="fa-solid fa-arrows-rotate" aria-hidden="true"></i>
				<span id="favoriteAreaFilterUnitToggleText">평</span>
			</button>
			<button type="button" class="area-filter-icon-btn area-filter-reset-btn" id="favoriteAreaFilterResetBtn" aria-label="면적 초기화" hidden>
				<i class="fa-solid fa-rotate-right" aria-hidden="true"></i>
			</button>
		</div>
		<div class="area-filter-slider-wrap">
			<div class="area-filter-slider-rail" id="favoriteAreaFilterSliderRail">
				<div class="area-filter-slider-fill" id="favoriteAreaFilterSliderFill"></div>
				<input type="range" class="area-filter-range area-filter-range-min" id="favoriteAreaFilterMinRange" min="0" max="${AREA_FILTER_MAX_M2}" step="1" value="0" aria-label="최소 면적" />
				<input type="range" class="area-filter-range area-filter-range-max" id="favoriteAreaFilterMaxRange" min="0" max="${AREA_FILTER_MAX_M2}" step="1" value="${AREA_FILTER_MAX_M2}" aria-label="최대 면적" />
			</div>
			<div class="area-filter-scale" id="favoriteAreaFilterScale">${getFavoriteAreaScaleHtml()}</div>
		</div>
		<div class="area-filter-target-options">
			<label class="area-filter-exclusive-option">
				<input type="checkbox" id="favoriteAreaFilterExclusiveChk" checked />
				<span>전용면적 기준으로 찾기</span>
			</label>
			<label class="area-filter-exclusive-option">
				<input type="checkbox" id="favoriteAreaFilterLandChk" />
				<span>토지</span>
			</label>
		</div>
	`;
}

function getFavoriteFilterTargetSet(type)
{
	return {
		property: mySuiteFavoritePropertyFilter,
		deal: mySuiteFavoriteDealFilter,
		landType: mySuiteFavoriteLandTypeFilter,
		landUseZone: mySuiteFavoriteLandUseZoneFilter
	}[type] || mySuiteFavoritePropertyFilter;
}

function normalizeFavoriteFilterType(value)
{
	return ["property", "deal", "landType", "landUseZone"].includes(value) ? value : "property";
}

function reopenFavoriteFilterMenu(type)
{
	const normalizedType = type === "area" ? "area" : normalizeFavoriteFilterType(type);
	const menu = document.querySelector(`[data-favorite-filter-panel="${CSS.escape(normalizedType)}"]`);
	if (menu) menu.classList.add("open");
	if (normalizedType === "area") syncFavoriteAreaFilterUi();
	syncFavoriteFilterArrows();
}

function applyFavoriteFilterOptionChange(input)
{
	if (!input) return;
	const type = normalizeFavoriteFilterType(input.dataset.favoriteFilterOption);
	const value = getFavoriteFilterLabel(input.dataset.value);
	const targetSet = getFavoriteFilterTargetSet(type);
	if (input.checked) targetSet.add(value);
	else targetSet.delete(value);
	setMySuiteFavoriteListingPage(1);
	renderRealjejuMySuiteFavoritesContent();
	reopenFavoriteFilterMenu(type);
}

function getLeftListSourceKey(items)
{
	return (Array.isArray(items) ? items : [])
	.map(item => normalizeItemId(item && item.id))
	.filter(Boolean)
	.join(",");
}

function resetLeftListPagination(items = [], options = {})
{
	const list = Array.isArray(items) ? items : [];
	if (!options.preserveRemoteRegion) state.leftListRemoteRegion = null;
	if (!options.preserveRemoteAgent) state.leftListRemoteAgent = null;
	state.leftListSourceIds = list.map(item => normalizeItemId(item && item.id)).filter(Boolean);
	state.leftListSourceKey = getLeftListSourceKey(list);
	state.leftListItems = [];
	state.leftListSeq += 1;
	state.leftListVisibleCount = LEFT_LIST_PAGE_SIZE;
	state.leftListRenderedCount = 0;
	state.leftListTotalCount = Number.isFinite(Number(options.totalCount))
		? Math.max(0, Number(options.totalCount))
		: state.leftListSourceIds.length;
	setLeftListLoading(false);
}

function ensureLeftListSource(items)
{
	const list = Array.isArray(items) ? items : [];
	const key = getLeftListSourceKey(list);
	if (key !== state.leftListSourceKey) {
		resetLeftListPagination(list);
		return true;
	}
	state.leftListTotalCount = state.leftListSourceIds.length;
	return false;
}

function getCurrentLeftListSourceItems()
{
	const agentItems = getAgentFilteredListItems();
	if (agentItems) return agentItems;
	const lockedItems = getLockedListItems();
	if (lockedItems) return sortItems(lockedItems);
	return sortItems(getViewportFilteredItems(state.filtered));
}

function setPagedListInfo(total, rendered)
{
	const totalCount = Number(total) || 0;
	const renderedCount = Number(rendered) || 0;
	if (!totalCount) {
		setResultInfo("총 0건");
		setListInfo("총 0개 매물");
		return;
	}
	setResultInfo(`총 ${totalCount}건`);
	setListInfo(renderedCount < totalCount ? `${totalCount}개 중 ${renderedCount}개` : `총 ${totalCount}개 매물`);
}

function setLeftListLoading(isLoading)
{
	state.leftListLoading = !!isLoading;
	if (propertyList) propertyList.classList.toggle("is-loading-more", !!isLoading);
}

function applyPropertyScaleRegionPageResult(remote, result, requestSeq, requestedLimit)
{
	if (!state.leftListRemoteRegion || state.leftListRemoteRegion.seq !== requestSeq) {
		return { stale: true, added: 0 };
	}
	const knownIds = new Set(remote.items.map((item) => normalizeItemId(item && item.id)).filter(Boolean));
	const nextItems = (Array.isArray(result.items) ? result.items : []).filter((item) => {
		const id = normalizeItemId(item && item.id);
		if (!id || knownIds.has(id)) return false;
		knownIds.add(id);
		return true;
	});
	remote.items.push(...nextItems);
	remote.items = sortItems(remote.items);

	// 첫 8건 전용 RPC는 전체 count를 생략하므로 null을 유지한다.
	// 뒤이어 받은 기존 지역 페이지 응답에 실제 count가 있을 때만 뱃지의 잠정값을 교체한다.
	if (result.totalCount !== null
		&& result.totalCount !== undefined
		&& Number.isFinite(Number(result.totalCount))) {
		remote.totalCount = Math.max(0, Number(result.totalCount));
	}
	remote.exhausted = nextItems.length < requestedLimit || remote.items.length >= remote.totalCount;
	state.leftListItems = remote.items.slice();
	state.leftListSourceIds = remote.items.map((item) => normalizeItemId(item && item.id)).filter(Boolean);
	state.leftListSourceKey = `remote-region:${remote.regionCode}:${getPropertyScaleFilterKey()}:${getPropertyScaleSortValue()}`;
	state.leftListRenderedCount = remote.items.length;
	state.leftListTotalCount = remote.totalCount;
	lockListToItems(remote.items, { keepOnMapClick: true });
	// 지역 목록에 받은 ID는 목록 고정에만 사용하고 원형 마커 선택으로 전달하지 않는다.
	updateMarkerSelection(null, []);
	renderList(state.leftListItems);
	setPagedListInfo(remote.totalCount, remote.items.length);
	if (state.leftListItems.length) state.lastViewportListIds = state.leftListSourceIds.slice();
	return { stale: false, added: nextItems.length };
}

async function loadMorePropertyScaleRegionItems()
{
	const remote = state.leftListRemoteRegion;
	if (!remote || remote.loading || remote.exhausted) return;
	remote.loading = true;
	setLeftListLoading(true);
	const requestSeq = remote.seq;
	try {
		if (!remote.items.length) {
			// 1차: 전체 count 계산을 생략한 첫 8건을 먼저 받아 즉시 목록에 표시한다.
			const firstResult = await fetchPropertyScaleRegionFirstPage(remote.regionCode, {
				totalCount: remote.totalCount,
				sort: remote.sourceSort || getPropertyScaleSortValue()
			});
			const firstApplied = applyPropertyScaleRegionPageResult(
				remote,
				firstResult,
				requestSeq,
				REGION_LIST_FIRST_PAINT_SIZE
			);
			if (firstApplied.stale || remote.exhausted) return;

			// 2차: 첫 화면이 보인 다음 같은 첫 페이지의 나머지 22건을 이어 받는다.
			const tailLimit = LEFT_LIST_PAGE_SIZE - REGION_LIST_FIRST_PAINT_SIZE;
			const tailResult = await fetchPropertyScaleRegionPage(remote.regionCode, {
				offset: REGION_LIST_FIRST_PAINT_SIZE,
				limit: tailLimit,
				totalCount: remote.totalCount,
				sort: remote.sourceSort || getPropertyScaleSortValue()
			});
			applyPropertyScaleRegionPageResult(remote, tailResult, requestSeq, tailLimit);
			return;
		}

		// 첫 8건 뒤 22건 요청이 일시 실패했다면 다음 스크롤에서 30건 경계까지만 복구한다.
		// 첫 30건이 완성된 뒤부터는 기존과 동일하게 다음 30건씩 요청한다.
		const offset = remote.items.length;
		const limit = offset < LEFT_LIST_PAGE_SIZE
			? LEFT_LIST_PAGE_SIZE - offset
			: LEFT_LIST_PAGE_SIZE;
		const result = await fetchPropertyScaleRegionPage(remote.regionCode, {
			offset,
			limit,
			totalCount: remote.totalCount,
			sort: remote.sourceSort || getPropertyScaleSortValue()
		});
		applyPropertyScaleRegionPageResult(remote, result, requestSeq, limit);
	} catch (error) {
		console.error("행정구역 매물 단계별 추가 로딩 실패:", error);
		if (!remote.items.length && propertyList
			&& state.leftListDetailMode !== "parcel-area-measure"
			&& !propertyList.querySelector(".parcel-area-measure-panel")) {
			propertyList.innerHTML = `
			<div class="card" style="padding:18px; cursor:default; border-bottom:0;">
			<div class="card-body" style="padding:0; text-align:left;">
			<div class="map-empty-state-desc">
			<div class="empty-title">매물 목록을 불러오지 못했습니다.</div>
			<div class="empty-sub">잠시 후 다시 시도해 주세요.</div>
			</div>
			</div>
			</div>`;
		}
	} finally {
		if (state.leftListRemoteRegion && state.leftListRemoteRegion.seq === requestSeq) {
			state.leftListRemoteRegion.loading = false;
		}
		setLeftListLoading(false);
	}
}

async function loadMorePropertyScaleAgentItems()
{
	const remote = state.leftListRemoteAgent;
	if (!remote || remote.loading || remote.exhausted) return;
	remote.loading = true;
	setLeftListLoading(true);
	const requestSeq = remote.seq;
	try {
		const result = await fetchPropertyScaleAgentPage(remote.filter, {
			offset: remote.items.length,
			limit: LEFT_LIST_PAGE_SIZE,
			totalCount: remote.totalCount
		});
		if (!state.leftListRemoteAgent || state.leftListRemoteAgent.seq !== requestSeq) return;
		const knownIds = new Set(remote.items.map((item) => normalizeItemId(item && item.id)).filter(Boolean));
		const nextItems = (Array.isArray(result.items) ? result.items : []).filter((item) => {
			const id = normalizeItemId(item && item.id);
			if (!id || knownIds.has(id)) return false;
			knownIds.add(id);
			return true;
		});
		remote.items.push(...nextItems);
		remote.totalCount = Math.max(remote.totalCount, Number(result.totalCount) || 0);
		remote.exhausted = nextItems.length < LEFT_LIST_PAGE_SIZE || remote.items.length >= remote.totalCount;
		state.leftListItems = remote.items.slice();
		state.leftListSourceIds = remote.items.map((item) => normalizeItemId(item && item.id)).filter(Boolean);
		state.leftListSourceKey = `remote-agent:${remote.filterKey}:${getPropertyScaleAgentSortValue()}`;
		state.leftListRenderedCount = remote.items.length;
		state.leftListTotalCount = remote.totalCount;
		state.leftListTitle = getBrokerOfficePanelHeaderTitle(
			getAgentListPanelTitle(remote.filter, state.agentListCard),
			remote.totalCount
		);
		syncSidebarListTitle();
		lockListToItems(remote.items, { keepOnMapClick: true });
		updateMarkerSelection(null, state.leftListSourceIds);
		renderList(state.leftListItems);
		setPagedListInfo(remote.totalCount, remote.items.length);
		const agentLabel = remote.filter?.label || "공인중개사";
		setResultInfo(`${agentLabel} 매물 ${remote.totalCount}건`);
		setListInfo(remote.items.length < remote.totalCount
			? `${remote.totalCount}개 중 ${remote.items.length}개`
			: `총 ${remote.totalCount}개 매물`);
		if (state.leftListItems.length) state.lastViewportListIds = state.leftListSourceIds.slice();
		if (nextItems.length) refreshSidebarAgentEngagementCounts(nextItems);
	} catch (error) {
		console.error("중개사 매물 30개 추가 로딩 실패:", error);
		if (!remote.items.length) renderList([]);
	} finally {
		if (state.leftListRemoteAgent && state.leftListRemoteAgent.seq === requestSeq) {
			state.leftListRemoteAgent.loading = false;
		}
		setLeftListLoading(false);
	}
}

async function loadMoreLeftListItems(options = {})
{
	if (state.leftListDetailMode === "parcel-area-measure"
		|| !!propertyList?.querySelector(".parcel-area-measure-panel")) return;
	if (state.leftListDetailMode === "parcel-region-stats") return;
	if (state.leftListDetailMode === "parcel-land-info" && propertyList && propertyList.querySelector(".parcel-land-info-panel")) return;
	if (document.body.classList.contains("sidebar-list-collapsed")) return;
	// 목록에서 상세를 연 동안 왼쪽 표면은 상세 패널로 교체된다.
	if (document.body.classList.contains("list-shared-detail-mode")) return;
	if (state.leftListLoading) return;
	// 4.924: 행정구역ㆍ중개사 목록은 전체 ID를 자르지 않고 서버에서 다음 30개를 직접 받는다.
	if (state.leftListRemoteAgent) return loadMorePropertyScaleAgentItems();
	if (state.leftListRemoteRegion) return loadMorePropertyScaleRegionItems();
	const sourceItems = Array.isArray(options.sourceItems) ? options.sourceItems : getCurrentLeftListSourceItems();
	ensureLeftListSource(sourceItems);
	const total = Number(state.leftListTotalCount || 0);
	const rendered = Number(state.leftListRenderedCount || 0);
	if (!total) {
		setLeftListLoading(false);
		renderList([]);
		return;
	}
	if (rendered >= total) return;
	const nextIds = state.leftListSourceIds.slice(rendered, rendered + LEFT_LIST_PAGE_SIZE);
	if (!nextIds.length) return;
	const seq = state.leftListSeq;
	const sourceById = new Map(sourceItems.map(item => [normalizeItemId(item && item.id), item]).filter(([id]) => !!id));
	const previousItems = state.leftListItems.slice(0, rendered);
	const shouldRenderImmediately = options.renderImmediately === true && rendered === 0;

	// 4.998: 원형 뱃지는 지도에 이미 목록용 요약을 가지고 있습니다.
	// DB 상세ㆍ중개사 정보 보강을 기다리며 빈 패널을 노출하지 않고, 요약 카드를 먼저 그린 뒤 같은 ID로 교체합니다.
	if (shouldRenderImmediately) {
		const previewItems = nextIds.map(id => sourceById.get(id)).filter(Boolean);
		state.leftListItems = [...previousItems, ...previewItems];
		state.leftListRenderedCount = Math.min(total, rendered + nextIds.length);
		renderList(state.leftListItems);
		setPagedListInfo(total, state.leftListItems.length);
		if (state.leftListItems.length) {
			state.lastViewportListIds = state.leftListItems.map(item => normalizeItemId(item && item.id)).filter(Boolean);
		}
	}
	setLeftListLoading(true);
	try {
		const fetchedItems = await fetchLeftListRowsByIds(nextIds);
		const fetchedById = new Map(fetchedItems.map(item => [normalizeItemId(item && item.id), item]).filter(([id]) => !!id));
		const nextItems = nextIds.map((id) => fetchedById.get(id) || sourceById.get(id)).filter(Boolean).map((item) => {
			const id = normalizeItemId(item && item.id);
			const sourceItem = id ? sourceById.get(id) : null;
			const sourceArea = String(sourceItem && sourceItem.area || "").trim();
			if (id && sourceArea && sourceArea !== "-") leftListAreaDisplayRawCache.set(id, sourceArea);
			return item;
		});
		if (seq !== state.leftListSeq) return;
		state.leftListItems = [...previousItems, ...nextItems];
		state.leftListRenderedCount = Math.min(total, rendered + nextIds.length);
		setLeftListLoading(false);
		renderList(state.leftListItems);
		setPagedListInfo(total, state.leftListItems.length);
		if (state.leftListItems.length) {
			state.lastViewportListIds = state.leftListItems.map(item => normalizeItemId(item.id));
		}
	} catch (error) {
		console.error(
			"왼쪽 매물 목록 추가 로딩 실패:",
			error?.message || error,
			error?.code || "",
			error?.details || ""
		);
		setLeftListLoading(false);
		if (!state.leftListItems.length
			&& state.leftListDetailMode !== "parcel-area-measure"
			&& !propertyList?.querySelector(".parcel-area-measure-panel")) {
			propertyList.innerHTML = `
			<div class="card" style="padding:18px; cursor:default; border-bottom:0;">
			<div class="card-body" style="padding:0; text-align:left;">
			<div class="map-empty-state-desc">
			<div class="empty-title">매물 목록을 불러오지 못했습니다.</div>
			<div class="empty-sub">잠시 후 다시 시도해 주세요.</div>
			</div>
			</div>
			</div>
			`;
		}
	}
}

function syncFavoriteHeartButtons()
{
	document.querySelectorAll(".favorite-heart-btn[data-favorite-id]").forEach((btn) => {
		const active = isFavoriteListing(btn.dataset.favoriteId);
		btn.classList.toggle("active", active);
		btn.setAttribute("aria-label", active ? "관심 부동산 해제" : "관심 부동산 추가");
		btn.setAttribute("aria-pressed", active ? "true" : "false");
	});
}

function closeFavoriteListingMenus(exceptId)
{
	document.querySelectorAll("[data-favorite-menu-panel].open").forEach((menu) => {
		if (exceptId && menu.dataset.favoriteMenuPanel === exceptId) return;
		menu.classList.remove("open");
	});
}

function syncFavoriteFilterArrows()
{
	document.querySelectorAll("[data-favorite-filter-menu]").forEach((btn) => {
		const type = btn.dataset.favoriteFilterMenu || "";
		const menu = document.querySelector(`[data-favorite-filter-panel="${CSS.escape(type)}"]`);
		const icon = btn.querySelector("i.fa-solid");
		if (!icon) return;
		const isOpen = !!(menu && menu.classList.contains("open"));
		icon.classList.toggle("fa-chevron-up", isOpen);
		icon.classList.toggle("fa-chevron-down", !isOpen);
	});
}

function closeFavoriteFilterMenus(exceptType)
{
	document.querySelectorAll("[data-favorite-filter-panel].open").forEach((menu) => {
		if (exceptType && menu.dataset.favoriteFilterPanel === exceptType) return;
		menu.classList.remove("open");
		if (typeof window.realjejuRestoreManagementFilterMenuOrigin === "function") {
			window.realjejuRestoreManagementFilterMenuOrigin(menu);
		}
	});
	syncFavoriteFilterArrows();
}

function normalizeFavoriteFilterMenuType(value)
{
	return ["property", "deal", "area", "landType", "landUseZone"].includes(value) ? value : "property";
}

function toggleFavoriteFilterMenu(type)
{
	const normalizedType = normalizeFavoriteFilterMenuType(type);
	const menu = document.querySelector(`[data-favorite-filter-panel="${CSS.escape(normalizedType)}"]`);
	const willOpen = !(menu && menu.classList.contains("open"));
	closeFavoriteFilterMenus(willOpen ? normalizedType : null);
	if (menu) {
		menu.classList.toggle("open", willOpen);
		if (willOpen && normalizedType === "area") syncFavoriteAreaFilterUi();
	}
	if (typeof window.realjejuSyncOpenManagementFilterMenusForViewport === "function") {
		window.realjejuSyncOpenManagementFilterMenusForViewport();
	}
	syncFavoriteFilterArrows();
}

function handleFavoriteFilterMenuButtonClick(event)
{
	const btn = event.target && event.target.closest ? event.target.closest("[data-favorite-filter-menu]") : null;
	if (!btn) return;
	if (!btn.closest(".my-suite-favorites-filterbar")) return;
	event.preventDefault();
	event.stopPropagation();
	if (typeof event.stopImmediatePropagation === "function") event.stopImmediatePropagation();
	toggleFavoriteFilterMenu(btn.dataset.favoriteFilterMenu);
}

if (document.documentElement.dataset.favoriteFilterToggleBound !== "true") {
	document.documentElement.dataset.favoriteFilterToggleBound = "true";
	document.addEventListener("click", handleFavoriteFilterMenuButtonClick, true);
}

function getSidebarAgentCardScore(card)
{
	if (!card || typeof card !== "object") return 0;
	return (String(card.image || "").trim() ? 100 : 0)
		+ (String(card.name || "").trim() ? 20 : 0)
		+ (String(card.phone || "").trim() ? 10 : 0)
		+ (String(card.address || "").trim() ? 6 : 0)
		+ (String(card.regNo || "").trim() ? 6 : 0)
		+ (String(card.kakaoUrl || "").trim() ? 4 : 0)
		+ (String(card.office || "").trim() ? 2 : 0);
}

function mergeSidebarAgentCards(baseCard, detailCard)
{
	const base = baseCard && typeof baseCard === "object" ? baseCard : {};
	const detail = detailCard && typeof detailCard === "object" ? detailCard : {};
	return {
		publicId: normalizeRealjejuAgencyPublicId(detail.publicId || detail.public_id || base.publicId || base.public_id || ""),
		userId: normalizeItemId(detail.userId || detail.user_id || base.userId || base.user_id),
		name: String(detail.name || base.name || "").trim(),
		title: String(detail.title || base.title || "").trim(),
		office: String(detail.office || base.office || "").trim(),
		phone: String(detail.phone || base.phone || "").trim(),
		phoneLink: String(detail.phoneLink || detail.phone || base.phoneLink || base.phone || "").trim(),
		address: String(detail.address || base.address || "").trim(),
		regNo: String(detail.regNo || base.regNo || "").trim(),
		image: String(detail.image || base.image || "").trim(),
		kakaoUrl: String(detail.kakaoUrl || base.kakaoUrl || "").trim()
	};
}

function buildSidebarAgentCardFromItems(baseCard, items)
{
	const list = (Array.isArray(items) ? items : [])
		.map(mergeCachedLeftListDetailItem)
		.filter(item => item && (!state.agentListFilter || itemMatchesAgentListFilter(item, state.agentListFilter)));
	let bestCard = null;
	let bestScore = -1;
	list.forEach((item) => {
		const card = buildAgentListCardFromItem(item);
		const score = getSidebarAgentCardScore(card);
		if (score > bestScore) {
			bestScore = score;
			bestCard = card;
		}
	});
	return mergeSidebarAgentCards(baseCard, bestCard);
}

function getSidebarAgentCardForRender(items)
{
	if (!state.agentListFilter) return null;
	const baseCard = state.agentListCard || {};
	const sourceItems = [
		...(Array.isArray(items) ? items : []),
		...(Array.isArray(state.leftListItems) ? state.leftListItems : []),
		...(getAgentFilteredListItems() || [])
	];
	const nextCard = buildSidebarAgentCardFromItems(baseCard, sourceItems);
	if (getSidebarAgentCardScore(nextCard) > getSidebarAgentCardScore(baseCard)) {
		state.agentListCard = nextCard;
	}
	return state.agentListCard || nextCard;
}

function renderSidebarAgentCard(card)
{
	if (!card || typeof card !== "object") return "";
	const categoryLabel = String(card.categoryLabel || "공인중개사").trim() || "공인중개사";
	const name = String(card.name || "").trim();
	const title = String(card.title || "").trim();
	const office = String(card.office || "").trim();
	const phone = String(card.phone || "").trim();
	const phoneLink = String(card.phoneLink || phone || "").trim();
	const address = formatBrokerOfficeDisplayAddress(card.address);
	const regNo = normalizeBrokerOfficeRegNo(card.regNo);
	const image = String(card.image || "").trim();
	const brokerUserId = normalizeItemId(card.userId || card.user_id);
	const kakaoUrl = String(card.kakaoUrl || "").trim();
	const showListingsAction = !!card.showListingsAction;
	const avatarHtml = image
		? `<img src="${escapeHtml(image)}" data-broker-user-id="${escapeHtml(brokerUserId)}" alt="" onerror="window.realjejuRecoverBrokerProfileImageElement(this);">`
		: `<span>${escapeHtml(makeAgentInitial(name || office || "담당"))}</span>`;
	const phoneDigits = phoneLink.replace(/[^0-9+]/g, "");
	const actionHtml = [
		kakaoUrl ? `<button type="button" class="sidebar-list-agent-action detail-agent-cta-btn kakao" data-sidebar-agent-kakao="${escapeHtml(kakaoUrl)}"><i class="fa-solid fa-comment" aria-hidden="true"></i><span>카톡상담</span></button>` : "",
		phoneDigits ? `<button type="button" class="sidebar-list-agent-action detail-agent-cta-btn phone" data-sidebar-agent-phone="${escapeHtml(phoneDigits)}"><i class="fa-solid fa-phone" aria-hidden="true"></i><span>문의전화</span></button>` : "",
		showListingsAction ? `<button type="button" class="sidebar-list-agent-action detail-agent-cta-btn listings" data-local-business-card-listings><i class="fa-solid fa-list-ul" aria-hidden="true"></i><span>매물 보기</span></button>` : ""
	].filter(Boolean).join("");
	return `
	<section class="sidebar-list-agent-card detail-agent-card" aria-label="${escapeHtml(categoryLabel)} 정보">
		<div class="detail-agent-card-head">
			<h3 class="detail-agent-section-title">${escapeHtml(categoryLabel)}</h3>
		</div>
		<div class="sidebar-list-agent-card-inner detail-agent-top">
			<div class="sidebar-list-agent-avatar detail-agent-avatar">${avatarHtml}</div>
			<div class="sidebar-list-agent-body detail-agent-main">
				<div class="sidebar-list-agent-title-row detail-agent-name-row">
					${name ? `<strong class="sidebar-list-agent-name detail-agent-name">${escapeHtml(name)}</strong>` : ""}
					${title ? `<span class="sidebar-list-agent-role detail-agent-title">${escapeHtml(title)}</span>` : ""}
				</div>
				${office ? `<div class="sidebar-list-agent-line detail-agent-office">${escapeHtml(office)}</div>` : ""}
				${phone ? `<div class="sidebar-list-agent-line detail-agent-phone-inline">${escapeHtml(phone)}</div>` : ""}
				${address ? `<div class="sidebar-list-agent-line detail-agent-address">${escapeHtml(address)}</div>` : ""}
				${regNo ? `<div class="sidebar-list-agent-line detail-agent-regno">등록번호 ${escapeHtml(regNo)}</div>` : ""}
				${actionHtml ? `<div class="sidebar-list-agent-actions detail-agent-cta-row">${actionHtml}</div>` : ""}
			</div>
		</div>
	</section>`;
}

function syncSidebarListHeaderActions()
{
	if (!sidebarListShareBtn) return;
	const showShare = !!state.agentListFilter;
	sidebarListShareBtn.hidden = !showShare;
	sidebarListShareBtn.setAttribute("aria-hidden", showShare ? "false" : "true");
}

function getSidebarAgentListSharePayload()
{
	const card = state.agentListCard || {};
	const sourceItems = getAgentFilteredListItems() || [];
	const office = String(card.office || state.agentListFilter?.label || "").trim();
	const name = String(card.name || "").trim();
	const title = [office || name || "중개사무소", "매물 목록"].filter(Boolean).join(" ");
	const countText = sourceItems.length ? `${sourceItems.length}개 매물` : "REALJEJU.APP 매물 목록";
	const address = String(card.address || "").trim();
	const shareUrl = getSidebarAgentListShareUrl();
	return {
		title: title || "REALJEJU.APP 매물 목록",
		description: [countText, address].filter(Boolean).join(" · "),
		text: [`[REALJEJU.APP] ${title || "매물 목록"}`, countText, address, shareUrl].filter(Boolean).join("\n"),
		url: shareUrl,
		imageUrl: String(card.image || "").trim()
	};
}

function buildLegacySidebarAgentListShareUrl(filter = {}, card = {})
{
	const url = new URL("/properties", window.location.origin);
	url.searchParams.set("agentList", "1");
	[
		["agentUser", filter.userId],
		["agentAgency", filter.agencyId],
		["agentOffice", filter.officeName || filter.rawOfficeName],
		["agentLabel", filter.label || card.office],
		["agentName", card.name],
		["agentAddress", card.address]
	].forEach(([key, value]) => {
		const text = String(value || "").trim();
		if (text) url.searchParams.set(key, text);
	});
	return url.href;
}

function getSidebarAgentListShareUrl()
{
	const filter = state.agentListFilter || {};
	const card = state.agentListCard || {};
	const publicId = normalizeRealjejuAgencyPublicId(filter.publicId || card.publicId || "");
	return publicId
		? getRealjejuAgencyPublicUrl(publicId).href
		: buildLegacySidebarAgentListShareUrl(filter, card);
}

async function ensureSidebarAgentPublicId()
{
	const filter = state.agentListFilter || {};
	const card = state.agentListCard || {};
	let publicId = normalizeRealjejuAgencyPublicId(filter.publicId || card.publicId || "");
	if (!publicId && filter.agencyId) publicId = await resolveRealjejuAgencyPublicIdByAgencyId(filter.agencyId);
	if (!publicId) return "";
	filter.publicId = publicId;
	card.publicId = publicId;
	state.agentListFilter = filter;
	state.agentListCard = card;
	return publicId;
}

async function shareSidebarAgentList(event)
{
	if (event) {
		event.preventDefault();
		event.stopPropagation();
	}
	if (!state.agentListFilter) return;
	await ensureSidebarAgentPublicId();
	const payload = getSidebarAgentListSharePayload();
	if (typeof window.openDetailShareMenuForPayload === "function") {
		window.openDetailShareMenuForPayload(payload, sidebarListShareBtn);
		return;
	}
	copyTextWithFallback(payload.text || payload.url);
}

