async function updateSidebarAgentSort(action)
{
	if (!state.agentListFilter) return;
	preserveVisibleLeftListAreaUnit();
	if (action === "price") {
		state.agentListSort = state.agentListSort === "priceAsc" ? "priceDesc" : "priceAsc";
	} else if (action === "area") {
		state.agentListSort = state.agentListSort === "areaAsc" ? "areaDesc" : "areaAsc";
	} else if (action === "latest") {
		state.agentListSort = "latest";
	} else {
		state.agentListSort = "popular";
	}
	if (state.leftListRemoteAgent) {
		const filter = state.leftListRemoteAgent.filter;
		const filterKey = state.leftListRemoteAgent.filterKey;
		const totalCount = Math.max(0, Number(state.leftListRemoteAgent.totalCount) || 0);
		clearListLock();
		resetLeftListPagination([], { totalCount, preserveRemoteAgent: true });
		state.leftListRemoteAgent = {
			filter,
			filterKey,
			totalCount,
			items: [],
			exhausted: false,
			loading: false,
			seq: state.leftListSeq
		};
		if (propertyList) {
			propertyList.innerHTML = "";
			propertyList.scrollTop = 0;
		}
		await loadMoreLeftListItems();
		return;
	}
	let sourceItems = getAgentFilteredListItems() || [];
	if (action === "price" || action === "area") {
		try {
			sourceItems = await getHydratedAgentFilteredListItems() || sourceItems;
		} catch (error) {
			console.warn("중개사 매물 정렬용 상세 데이터 불러오기 실패:", error);
		}
		if (!state.agentListFilter) return;
	}
	resetLeftListPagination(sourceItems);
	if (propertyList) propertyList.scrollTop = 0;
	loadMoreLeftListItems({ sourceItems });
}

