function collectParcelRecommendationCoordinates(value, output)
{
	if (!Array.isArray(value)) return;
	if (value.length >= 2 && Number.isFinite(Number(value[0])) && Number.isFinite(Number(value[1]))) {
		const lng = Number(value[0]);
		const lat = Number(value[1]);
		if (lat >= 32 && lat <= 35 && lng >= 125 && lng <= 128) output.push({ lat, lng });
		return;
	}
	value.forEach((child) => collectParcelRecommendationCoordinates(child, output));
}

function getParcelRecommendationCenter(feature)
{
	const props = feature && feature.properties && typeof feature.properties === "object" ? feature.properties : {};
	const directPairs = [
		[feature && feature.selectionLat, feature && feature.selectionLng],
		[props.lat ?? props.latitude ?? props.centerLat, props.lng ?? props.longitude ?? props.centerLng],
		[feature && (feature.lat ?? feature.latitude), feature && (feature.lng ?? feature.longitude)]
	];
	for (const pair of directPairs) {
		const direct = normalizeJejuLatLngPair(pair[0], pair[1]);
		if (direct) return direct;
	}
	const points = [];
	collectParcelRecommendationCoordinates(feature && feature.geometry && feature.geometry.coordinates, points);
	if (!points.length) return null;
	const total = points.reduce((sum, point) => ({ lat: sum.lat + point.lat, lng: sum.lng + point.lng }), { lat: 0, lng: 0 });
	return { lat: total.lat / points.length, lng: total.lng / points.length };
}

function getParcelRecommendationDistanceMeters(a, b)
{
	if (!a || !b) return Number.POSITIVE_INFINITY;
	const toRadians = (value) => Number(value) * Math.PI / 180;
	const lat1 = toRadians(a.lat);
	const lat2 = toRadians(b.lat);
	const deltaLat = lat2 - lat1;
	const deltaLng = toRadians(b.lng) - toRadians(a.lng);
	const value = Math.sin(deltaLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(deltaLng / 2) ** 2;
	return 6371000 * 2 * Math.atan2(Math.sqrt(value), Math.sqrt(1 - value));
}

function getParcelRecommendationCandidates(feature)
{
	const center = getParcelRecommendationCenter(feature);
	if (!center) return [];
	const sourceItems = [].concat(
		Array.isArray(state.all) ? state.all : [],
		Array.isArray(state.filtered) ? state.filtered : [],
		Array.isArray(state.leftListItems) ? state.leftListItems : []
	);
	const seen = new Set();
	const candidates = [];
	sourceItems.forEach((item) => {
		const id = normalizeItemId(item && item.id);
		if (!id || seen.has(id)) return;
		seen.add(id);
		const position = getListingDisplayPosition(item);
		const lat = Number(position && (position.lat ?? (typeof position.getLat === "function" ? position.getLat() : NaN)));
		const lng = Number(position && (position.lng ?? (typeof position.getLng === "function" ? position.getLng() : NaN)));
		if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
		const distance = getParcelRecommendationDistanceMeters(center, { lat, lng });
		if (distance > 1000) return;
		candidates.push({ item, distance });
	});
	return candidates;
}

async function renderRecommendedListingCard(target, feature)
{
	if (!target) return false;
	if (typeof target.__realjejuRecommendedListingCleanup === "function") {
		target.__realjejuRecommendedListingCleanup();
	}
	const candidates = getParcelRecommendationCandidates(feature);
	if (!candidates.length) return false;
	const shuffled = candidates.slice();
	for (let index = shuffled.length - 1; index > 0; index -= 1) {
		const swapIndex = Math.floor(Math.random() * (index + 1));
		[shuffled[index], shuffled[swapIndex]] = [shuffled[swapIndex], shuffled[index]];
	}
	let selectedItems = shuffled.slice(0, 3).map((candidate) => candidate.item);
	try {
		const fetchedRows = await fetchLeftListRowsByIds(selectedItems.map((item) => item.id));
		const hydratedRows = hydrateLeftListRenderItems(fetchedRows);
		const hydratedById = new Map(hydratedRows.map((item) => [normalizeItemId(item && item.id), item]));
		selectedItems = selectedItems.map((item) => hydratedById.get(normalizeItemId(item.id)) || item);
	} catch (error) {
		console.warn("추천 매물 상세 보완 실패:", error);
	}
	selectedItems = selectedItems.filter(Boolean);
	if (!selectedItems.length) return false;
	rememberLeftListDetailItems(selectedItems);
	target.classList.remove("parcel-property-loading");
	target.innerHTML = '<div class="parcel-recommended-listing-slider" data-parcel-recommended-slider>'
		+ '<div class="parcel-recommended-listing-viewport"><div class="parcel-recommended-listing-track">'
		+ selectedItems.map((item, index) => '<div class="parcel-recommended-listing-slide" data-parcel-recommended-slide="' + index + '">' + renderListingCardHtml(item, { selectedId: "" }) + '</div>').join("")
		+ '</div></div>'
		+ (selectedItems.length > 1 ? '<div class="parcel-recommended-listing-dots" role="tablist" aria-label="추천 매물 선택">'
			+ selectedItems.map((item, index) => '<button type="button" class="parcel-recommended-listing-dot' + (index === 0 ? ' is-active' : '') + '" data-parcel-recommended-dot="' + index + '" role="tab" aria-selected="' + (index === 0 ? 'true' : 'false') + '" aria-label="추천 매물 ' + (index + 1) + '"></button>').join("")
			+ '</div>' : '')
		+ '</div>';
	target.dataset.recommendedListingIds = selectedItems.map((item) => normalizeItemId(item.id)).join(",");
	refreshCardViewCounts(selectedItems);
	void refreshCardFavoriteCounts(selectedItems);

	const itemById = new Map(selectedItems.map((item) => [normalizeItemId(item && item.id), item]));
      const keepParcelInfoBesideRecommendedDetail = (preservedParcelPanel, preservedScrollTop) => {
        if (preservedParcelPanel && propertyList && !propertyList.contains(preservedParcelPanel)) {
          propertyList.replaceChildren(preservedParcelPanel);
        }
        state.leftListDetailMode = "parcel-land-info";
        state.leftListTitle = "부동산 정보";
        state.selectionMode = "parcel-land-info";
        state.isListOpen = true;
        document.body.classList.remove(
          "detail-page-panel-open",
          "direct-detail-list-mode",
          "recent-shared-detail-mode",
          "map-panels-collapsed",
          "map-detail-panel-active",
          "sidebar-list-collapsed"
        );
        document.body.classList.add("shared-detail-mode", "list-shared-detail-mode");
        if (sidebar) sidebar.classList.add("expanded");
        if (propertyList) propertyList.scrollTop = preservedScrollTop;
        if (typeof syncSidebarListTitle === "function") syncSidebarListTitle();
        if (typeof syncSidebarListHeaderActions === "function") syncSidebarListHeaderActions();
        if (typeof updateSidebarWidth === "function") updateSidebarWidth();
        if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
        if (typeof refreshMapLayout === "function") refreshMapLayout();
      };

      target.querySelectorAll(".card[data-id]").forEach((card) => {
        card.addEventListener("click", async (event) => {
          if (event.target.closest("a, button")) return;
          event.preventDefault();
          const selectedItem = itemById.get(normalizeItemId(card.dataset.id));
          if (!selectedItem) return;
          const preservedParcelPanel = target.closest(".parcel-land-info-panel");
          const preservedScrollTop = propertyList ? propertyList.scrollTop : 0;
          keepParcelInfoBesideRecommendedDetail(preservedParcelPanel, preservedScrollTop);
          try {
            await openDetailPanel(selectedItem, {
              syncUrl: true,
              forceOpen: true,
              overlayPage: false,
              sharedMode: true
            });
          } finally {
            keepParcelInfoBesideRecommendedDetail(preservedParcelPanel, preservedScrollTop);
          }
        });
      });

	target.querySelectorAll(".favorite-heart-btn[data-favorite-id]").forEach((favoriteButton) => {
		favoriteButton.addEventListener("click", async (event) => {
			event.preventDefault();
			event.stopPropagation();
			if (favoriteButton.disabled) return;
			const selectedItem = itemById.get(normalizeItemId(favoriteButton.dataset.favoriteId));
			if (!selectedItem) return;
			favoriteButton.disabled = true;
			const active = await setFavoriteListing(selectedItem.id, !isFavoriteListing(selectedItem.id), selectedItem);
			favoriteButton.classList.toggle("active", active);
			favoriteButton.setAttribute("aria-label", active ? "관심 부동산 해제" : "관심 부동산 추가");
			favoriteButton.setAttribute("aria-pressed", active ? "true" : "false");
			favoriteButton.disabled = false;
		});
	});

	const slider = target.querySelector("[data-parcel-recommended-slider]");
	const track = slider && slider.querySelector(".parcel-recommended-listing-track");
	const dots = slider ? Array.from(slider.querySelectorAll("[data-parcel-recommended-dot]")) : [];
	let activeIndex = 0;
	let autoplayTimer = 0;
	const reducedMotion = typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
	const stopAutoplay = () => {
		if (!autoplayTimer) return;
		window.clearInterval(autoplayTimer);
		autoplayTimer = 0;
	};
	const showSlide = (index) => {
		if (!track || !selectedItems.length) return;
		activeIndex = (Number(index) + selectedItems.length) % selectedItems.length;
		track.style.transform = 'translate3d(-' + (activeIndex * 100) + '%, 0, 0)';
		dots.forEach((dot, dotIndex) => {
			const isActive = dotIndex === activeIndex;
			dot.classList.toggle("is-active", isActive);
			dot.setAttribute("aria-selected", isActive ? "true" : "false");
		});
	};
	const startAutoplay = () => {
		stopAutoplay();
		if (!slider || selectedItems.length < 2 || reducedMotion) return;
		autoplayTimer = window.setInterval(() => {
			if (!slider.isConnected) {
				stopAutoplay();
				return;
			}
			if (document.hidden) return;
			showSlide(activeIndex + 1);
		}, 2500);
	};
	dots.forEach((dot) => {
		dot.addEventListener("click", (event) => {
			event.preventDefault();
			event.stopPropagation();
			showSlide(Number(dot.dataset.parcelRecommendedDot));
			startAutoplay();
		});
	});
	if (slider) {
		slider.addEventListener("mouseenter", stopAutoplay);
		slider.addEventListener("mouseleave", startAutoplay);
		slider.addEventListener("focusin", stopAutoplay);
		slider.addEventListener("focusout", (event) => {
			if (!slider.contains(event.relatedTarget)) startAutoplay();
		});
	}
	target.__realjejuRecommendedListingCleanup = stopAutoplay;
	showSlide(0);
	startAutoplay();
	return true;
}

window.realjejuRenderRecommendedListingCard = renderRecommendedListingCard;

function renderList(data)
{
	// 필지정보에서 열린 토지정보ㆍ지역통계ㆍ면적측정을 늦게 완료된 매물 목록 갱신이 덮지 못하게 한다.
	const hasParcelLandInfo = !!(propertyList && propertyList.querySelector(".parcel-land-info-panel"));
	const hasParcelRegionStats = !!(propertyList && propertyList.querySelector(".parcel-region-trade-stats-panel"));
	const hasParcelAreaMeasure = !!(propertyList && propertyList.querySelector(".parcel-area-measure-panel"));
	const hasLockedParcelInfoMode = state.leftListDetailMode === "parcel-land-info"
		|| state.leftListDetailMode === "parcel-region-stats"
		|| state.leftListDetailMode === "parcel-area-measure";
	if (hasParcelLandInfo || hasParcelRegionStats || hasParcelAreaMeasure || hasLockedParcelInfoMode) {
		state.leftListDetailMode = hasParcelAreaMeasure
			? "parcel-area-measure"
			: (hasParcelLandInfo ? "parcel-land-info" : "parcel-region-stats");
		state.leftListTitle = state.leftListDetailMode === "parcel-area-measure"
			? "면적 측정"
			: (state.leftListDetailMode === "parcel-region-stats" ? "부동산 통계" : "부동산 정보");
		syncSidebarListTitle();
		syncSidebarListHeaderActions();
		return;
	}
	const sourceData = data;
	data = hydrateLeftListRenderItems(data);
	if (sourceData === state.leftListItems) state.leftListItems = data;
	const agentCard = state.agentListFilter ? getSidebarAgentCardForRender(data) : null;
	if (state.agentListFilter) state.leftListTitle = getAgentListPanelTitle(state.agentListFilter, agentCard);
	else if (state.leftListDetailMode !== "region-count") state.leftListTitle = "";
	syncSidebarListTitle();
	syncSidebarListHeaderActions();
	const agentCardHtml = state.agentListFilter ? renderSidebarAgentCard(agentCard) : "";
	const agentSortHtml = state.agentListFilter ? renderSidebarAgentSortBar(state.leftListTotalCount || data.length) : "";
	const listSortHtml = state.agentListFilter ? "" : renderSidebarListSortBar(state.leftListTotalCount || data.length);
	const agentHeaderHtml = agentCardHtml + agentSortHtml + listSortHtml;
	if (!data.length) {
		propertyList.innerHTML = `${agentHeaderHtml}
		<div class="card" style="padding:18px; cursor:default; border-bottom:0;">
		<div class="card-body" style="padding:0; text-align:left;">
		<div class="map-empty-state-desc">
		<div class="empty-title">조건에 맞는 매물이 없습니다.</div>
		<div class="empty-sub">지도를 이동 하거나 필터를 변경해 보세요.</div>
		</div>
		</div>
		</div>
		`;
		return;
	}

		const hasMoreListItems = Number(state.leftListRenderedCount || 0) < Number(state.leftListTotalCount || 0);
		const selectedListId = normalizeItemId(state.selectedMarkerId);
		propertyList.innerHTML = agentHeaderHtml + data.map(item => renderListingCardHtml(item, { selectedId: selectedListId })).join("") + (hasMoreListItems ? '<div class="left-list-loading" aria-live="polite">불러오는 중...</div>' : "");

	refreshCardViewCounts(data);
	void refreshCardFavoriteCounts(data);

	const sidebarAgentKakaoBtn = propertyList.querySelector("[data-sidebar-agent-kakao]");
	if (sidebarAgentKakaoBtn) {
		sidebarAgentKakaoBtn.addEventListener("click", (e) => {
			e.preventDefault();
			e.stopPropagation();
			const url = String(sidebarAgentKakaoBtn.dataset.sidebarAgentKakao || "").trim();
			if (url) window.open(url, "_blank", "noopener,noreferrer");
		});
	}

	const sidebarAgentPhoneBtn = propertyList.querySelector("[data-sidebar-agent-phone]");
	if (sidebarAgentPhoneBtn) {
		sidebarAgentPhoneBtn.addEventListener("click", (e) => {
			e.preventDefault();
			e.stopPropagation();
			const phone = String(sidebarAgentPhoneBtn.dataset.sidebarAgentPhone || "").trim();
			if (phone) window.location.href = `tel:${phone}`;
		});
	}

	propertyList.querySelectorAll("[data-sidebar-agent-sort]").forEach((button) => {
		button.addEventListener("click", (e) => {
			e.preventDefault();
			e.stopPropagation();
			updateSidebarAgentSort(button.dataset.sidebarAgentSort || "popular")
			.catch(error => console.warn("중개사 매물 정렬 실패:", error));
		});
	});

	propertyList.querySelectorAll("[data-sidebar-list-sort]").forEach((button) => {
		button.addEventListener("click", (e) => {
			e.preventDefault();
			e.stopPropagation();
			updateSidebarListSort(button.dataset.sidebarListSort || "latest");
		});
	});

	document.querySelectorAll(".card").forEach(card => {
		card.addEventListener("click", async function (e) {
			if (e.target.closest("a, button")) return;

			const item = data.find(v => normalizeItemId(v.id) === normalizeItemId(card.dataset.id));
			if (!item) return;

			const normalizedId = normalizeItemId(item.id);

			if (state.leftListDetailMode === "map-region") {
				await openListSharedDetailFromItem(item);
			} else {
				closeEducationFacilityDetailForPropertyInteraction();
				if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
					await closeRoadviewPanelForPropertyInteraction();
				} else if (typeof hideRoadview === "function") {
					await hideRoadview();
				}
				const preserveBadgeListLock = state.keepLockedListOnMapClick
					&& Array.isArray(state.lockedListIds)
					&& state.lockedListIds.map(normalizeItemId).includes(normalizedId);

				if (preserveBadgeListLock) {
					state.selectionMode = "single";
					state.selectedClusterKey = null;
					state.selectedClusterAnchor = null;
					state.selectedMarkerId = normalizedId;
				} else {
					state.selectionMode = "single";
					state.selectedClusterKey = null;
					state.selectedClusterAnchor = null;
					state.selectedMarkerId = normalizedId;
					clearListLock();
				}

				highlightCard(normalizedId);
				updateMarkerSelection(normalizedId, [normalizedId]);

				if (detailScroll) detailScroll.scrollTop = 0;
				allowDetailOpenFromListClick = true;
				try {
					await openDetailPanel(item, { syncUrl: false });
				} finally {
					allowDetailOpenFromListClick = false;
				}

				syncDetailUrl(item.id);
				if (detailScroll) detailScroll.scrollTop = 0;
				await focusProperty(item.id);
			}

			setTimeout(() => {
				highlightCard(normalizedId);
				refreshClusterBadges();
			}, 0);
		});
	});

		document.querySelectorAll(".favorite-heart-btn[data-favorite-id]").forEach((btn) => {
			btn.addEventListener("click", async (e) => {
				e.preventDefault();
				e.stopPropagation();
				if (btn.disabled) return;
				btn.disabled = true;
				const listingItem = data.find((item) => normalizeItemId(item.id) === normalizeItemId(btn.dataset.favoriteId));
				const active = await setFavoriteListing(btn.dataset.favoriteId, !isFavoriteListing(btn.dataset.favoriteId), listingItem);
				btn.classList.toggle("active", active);
				btn.setAttribute("aria-label", active ? "관심 부동산 해제" : "관심 부동산 추가");
				btn.setAttribute("aria-pressed", active ? "true" : "false");
				if (currentDetailItem && getItemViewKey(currentDetailItem) === getViewCountKey(btn.dataset.favoriteId)) {
					refreshDetailEngagementCounts(currentDetailItem);
				}
				btn.disabled = false;
			const mySuitePanel = document.getElementById("mySuitePanel");
				const activeFavoriteTab = document.querySelector('.my-suite-tab.active[data-my-suite-tab="favorites"]');
				if (mySuitePanel && mySuitePanel.getAttribute("aria-hidden") === "false" && activeFavoriteTab) {
					renderRealjejuMySuiteFavoritesContent();
				}
		});
	});
}

function syncLeftAllButtonToMapFilters()
{
	const leftAllBtn = document.querySelector('#featureButtons button[data-value="all"]');
	if (!leftAllBtn) return;
	const isTypeAll = isDefaultTypeFilterSelection();
	const isDealAll = isDefaultDealFilterSelection();
	const isMethodAll = !selectedDealMethod || selectedDealMethod === "all";
	const isPriceAll = !isAnyPriceFilterActive();
	const isAreaAll = !Number.isFinite(selectedAreaMinM2) && (!Number.isFinite(selectedAreaMaxM2) || isAreaFilterMaxUnbounded());
	const isApprovalYearAll = !Number.isFinite(selectedApprovalYearMinAge) && !Number.isFinite(selectedApprovalYearMaxAge);
	const isLandTypeAll = !(selectedLandTypeFilter instanceof Set) || selectedLandTypeFilter.size === 0;
	const isLandUseZoneAll = !(selectedLandUseZoneFilter instanceof Set) || selectedLandUseZoneFilter.size === 0;
	const isRoomAll = !(selectedRoomFilter instanceof Set) || selectedRoomFilter.size === 0;
	const isBathAll = !(selectedBathFilter instanceof Set) || selectedBathFilter.size === 0;
	const isFloorAll = !(selectedFloorFilter instanceof Set) || selectedFloorFilter.size === 0;
	const isDirectionAll = !(selectedDirectionFilter instanceof Set) || selectedDirectionFilter.size === 0;
	const isAllState = isTypeAll && isDealAll && isMethodAll && isPriceAll && isAreaAll && isApprovalYearAll && isLandTypeAll && isLandUseZoneAll && isRoomAll && isBathAll && isFloorAll && isDirectionAll;
	leftAllBtn.classList.toggle('all-active', isAllState && state.selectedFeatures.size === 0);
}

function syncFeatureButtons()
{
	const isAll = state.selectedFeatures.size === 0;

	(featureButtons || []).forEach(btn => {
		const value = btn.dataset.value;

		if (value === "all") {
			btn.classList.toggle("all-active", isAll);
			btn.classList.remove("active");
		} else {
			btn.classList.toggle("active", state.selectedFeatures.has(value));
			btn.classList.remove("all-active");
		}
	});
}

function scrollListToTop()
{
	if (sidebarListPanel) sidebarListPanel.scrollTop = 0;
	if (propertyList) propertyList.scrollTop = 0;
	requestAnimationFrame(() => {
		if (sidebarListPanel) sidebarListPanel.scrollTop = 0;
		if (propertyList) propertyList.scrollTop = 0;
	});
	setTimeout(() => {
		if (sidebarListPanel) sidebarListPanel.scrollTop = 0;
		if (propertyList) propertyList.scrollTop = 0;
	}, 0);
}

function isInitialAllListMode()
{
	const keyword = String(keywordInput?.value || "").trim();
	return !keyword
		&& isDefaultDealFilterSelection()
		&& isDefaultTypeFilterSelection()
	&& (!selectedDealMethod || selectedDealMethod === "all")
		&& !isAnyPriceFilterActive()
	&& !Number.isFinite(selectedAreaMinM2)
	&& (!Number.isFinite(selectedAreaMaxM2) || isAreaFilterMaxUnbounded())
	&& !Number.isFinite(selectedApprovalYearMinAge)
	&& !Number.isFinite(selectedApprovalYearMaxAge)
	&& (!selectedLandTypeFilter || selectedLandTypeFilter.size === 0)
	&& (!selectedLandUseZoneFilter || selectedLandUseZoneFilter.size === 0)
	&& (!selectedRoomFilter || selectedRoomFilter.size === 0)
	&& (!selectedBathFilter || selectedBathFilter.size === 0)
	&& (!selectedFloorFilter || selectedFloorFilter.size === 0)
	&& (!selectedDirectionFilter || selectedDirectionFilter.size === 0)
	&& state.selectedFeatures.size === 0
	&& !selectedPetOnly
	&& !selectedParkingOnly
	&& !selectedCityGasOnly
	&& !selectedDuplexOnly
	&& !selectedVerandaOnly
	&& !selectedElevatorOnly
	&& !selectedFullOptionOnly
	&& !selectedImmediateMoveInOnly
	&& !selectedOceanViewOnly;
}

state.initialRandomListActive = true;
state.initialRandomListIds = [];

function applyFilter()
{
	ensureTypeFilterHasSelection();
	if (isPresaleMapMode()) {
		renderPresaleEmptyMap();
		return;
	}

	if (PROPERTY_SCALE_REMOTE_DATA_ENABLED && mapListingsInitialDataApplied && shouldUsePropertyMapLevelPresentation()) {
		// 4.924: 필터가 바뀌면 현재 브라우저에 우연히 들어 있는 일부 행을 다시 거르지 않는다.
		// 같은 필터 JSON을 지역 숫자ㆍ지역 30건ㆍ현재 화면 RPC에 전달해 세 결과의 기준을 일치시킨다.
		clearAgentListFilter();
		state.selectedMarkerId = null;
		state.selectedClusterKey = null;
		state.selectedMarkerIds = new Set();
		state.selectionMode = null;
		clearListLock();
		state.leftListRemoteRegion = null;
		resetLeftListPagination([]);
		if (propertyList) propertyList.innerHTML = "";
		schedulePropertyScaleDataRefresh(0, { source: "filter" });
		return;
	}

	clearAgentListFilter();
	const keyword = String(keywordInput?.value || "").trim().toLowerCase();
	const dealValues = selectedDeal instanceof Set ? selectedDeal : new Set();
	const typeValues = selectedType instanceof Set ? selectedType : new Set();
	const landTypeValues = selectedLandTypeFilter instanceof Set ? selectedLandTypeFilter : new Set();
	const landUseZoneValues = selectedLandUseZoneFilter instanceof Set ? selectedLandUseZoneFilter : new Set();
	const roomValues = selectedRoomFilter instanceof Set ? selectedRoomFilter : new Set();
	const bathValues = selectedBathFilter instanceof Set ? selectedBathFilter : new Set();
	const floorValues = selectedFloorFilter instanceof Set ? selectedFloorFilter : new Set();
	const directionValues = selectedDirectionFilter instanceof Set ? selectedDirectionFilter : new Set();
		const hasTypeFilter = typeValues.size > 0;
	const isRoomAll = roomValues.size === 0;
	const isLandTypeAll = landTypeValues.size === 0;
	const isLandUseZoneAll = landUseZoneValues.size === 0;
	const isBathAll = bathValues.size === 0;
	const isFloorAll = floorValues.size === 0;
	const isDirectionAll = directionValues.size === 0;
	const methodValue = selectedDealMethod || "all";

	state.filtered = state.all.filter(item => {
		const text = [
		item.title ?? "",
		item.listingNo ?? "",
		item.region ?? "",
		item.address ?? "",
		item.desc ?? "",
		item.type ?? "",
		item.agentName ?? "",
		item.agentOffice ?? "",
		item.date ?? "",
		item.dateLabel ?? "",
		...(item.features ?? [])
		].join(" ").toLowerCase();
		const rawItemText = JSON.stringify(item ?? {}).toLowerCase();
		const searchableText = `${text} ${rawItemText}`.replace(/\s+/g, " ");

		const okKeyword = !keyword || searchableText.includes(keyword);
		const okDeal = matchesSelectedDealFilter([item.dealType, ...(Array.isArray(item.dealTypes) ? item.dealTypes : [])], dealValues);
		const okPrice = matchesSelectedPriceFilters(item);
		const okArea = matchesAreaFilter(item);
		const okApprovalYear = matchesApprovalYearFilter(item);
		const okLandType = isLandTypeAll || matchesLandTypeFilter(item, landTypeValues);
		const okLandUseZone = isLandUseZoneAll || matchesLandUseZoneFilter(item, landUseZoneValues);

		const itemType = (item.type ?? "").trim();
		const isSaleDeal = item.dealType === "매매";

		const matchesTypeValue = (typeValue) =>
		(typeValue === "아파트" && ["아파트", "아파트ㆍ빌라"].includes(itemType)) ||
		(typeValue === "오피스텔" && itemType === "오피스텔") ||
		(typeValue === "빌라" && ["빌라", "연립", "다세대", "다세대주택", "다가구ㆍ다세대"].includes(itemType)) ||
		(typeValue === "단독주택" && ["주택", "단독", "단독주택"].includes(itemType)) ||
			(typeValue === "다가구주택" && ["다가구", "다가구주택"].includes(itemType)) ||
			(typeValue === "원룸 / 투룸" && (itemType === "room" || ["원룸", "투룸", "원룸ㆍ투룸", "원룸/투룸", "원룸 / 투룸"].includes(itemType))) ||
			(typeValue === "생활형숙박시설" && isLivingAccommodationType(itemType)) ||
			(typeValue === "상가" && ["상가", "상가건물", "상가ㆍ사무실"].includes(itemType)) ||
		(typeValue === "사무실" && ["사무실", "상가ㆍ사무실"].includes(itemType)) ||
		(typeValue === "건물" && ["건물", "빌딩", "상가건물", "통건물"].includes(itemType)) ||
		(typeValue === "공장 / 창고" && ["공장", "창고", "공장/창고", "공장 / 창고", "공장ㆍ창고", "창고시설"].includes(itemType)) ||
		(typeValue === "호텔" && (["hotel", "호텔"].includes(itemType) || isHotelPensionType(itemType) && String(itemType).toLowerCase().includes("hotel"))) ||
		(typeValue === "펜션" && (["pension", "펜션"].includes(itemType) || isHotelPensionType(itemType) && String(itemType).toLowerCase().includes("pension"))) ||
		(typeValue === "토지" && ["토지", "임야", "토지ㆍ임야", "전", "대", "답", "과수원", "목장용지"].includes(itemType)) ||
		(typeValue === "아파트오피스텔" && (["아파트", "아파트ㆍ빌라"].includes(itemType) || (itemType === "오피스텔" && isSaleDeal))) ||
		(typeValue === "빌라주택" && ["빌라", "연립", "단독", "단독주택", "다가구", "다세대", "다가구ㆍ다세대", "다세대주택"].includes(itemType)) ||
		(typeValue === "호텔펜션" && (["hotel", "호텔", "pension", "펜션"].includes(itemType) || isHotelPensionType(itemType)));

			const okType = hasTypeFilter && [...typeValues].some(matchesTypeValue);

		const rawMethodText = String(
		item.dealMethod ?? item.listingMethod ?? item.tradeMethod ?? item.ownerType ?? item.sellerType ?? item.listingType ?? item.userType ?? ""
		).trim().toLowerCase();
		const isDirectListing = rawMethodText.includes("direct")
		|| rawMethodText.includes("private")
		|| rawMethodText.includes("owner")
		|| rawMethodText.includes("personal")
		|| rawMethodText.includes("개인")
		|| rawMethodText.includes("직거래");
		const isBrokerListing = !isDirectListing && (
		rawMethodText.includes("broker")
		|| rawMethodText.includes("agent")
		|| rawMethodText.includes("agency")
		|| rawMethodText.includes("공인")
		|| rawMethodText.includes("중개")
		|| !!item.agent_folder
		|| !!item.agentOffice
		|| !!item.agentName
		);
		const okDealMethod = methodValue === "all"
		|| (methodValue === "broker" && isBrokerListing)
		|| (methodValue === "direct" && isDirectListing);

		const roomBathCounts = (!isRoomAll || !isBathAll) ? getItemRoomBathCounts(item) : null;
		const okRoom = isRoomAll || matchesRoomBathCountFilter(roomBathCounts?.room, roomValues);
		const okBath = isBathAll || matchesRoomBathCountFilter(roomBathCounts?.bath, bathValues);
		const itemFloorTokens = isFloorAll ? null : getItemFloorFilterTokens(item);
		const itemDirectionToken = isDirectionAll ? "" : getItemDirectionFilterToken(item);
		const okFloor = isFloorAll || [...floorValues].some(value => itemFloorTokens && itemFloorTokens.has(value));
		const okDirection = isDirectionAll || directionValues.has(itemDirectionToken);


		const okFeature =
		state.selectedFeatures.size === 0 ||
		[...state.selectedFeatures].every(feature => hasFeatureLabel(item, feature));

		const hasPetAllow = hasFeatureLabel(item, "반려동물");
		const hasParking = hasFeatureLabel(item, "주차 가능");
		const hasCityGas = hasFeatureLabel(item, "도시가스");
		const hasDuplex = hasFeatureLabel(item, "복층형");
		const hasVeranda = hasFeatureLabel(item, "베란다");
		const hasElevator = hasFeatureLabel(item, "엘리베이터");
		const hasFullOption = hasFeatureLabel(item, "풀옵션");
		const hasImmediateMoveIn = Array.isArray(item?.featuresNormalized)
		? item.featuresNormalized.includes(normalizeFeatureToken("즉시입주"))
		: normalizeFeatureList(item?.features).includes(normalizeFeatureToken("즉시입주"));
		const hasNegotiableMoveIn = hasFeatureLabel(item, "협의입주") || /협의\s*(입주|가능)|입주\s*협의/.test(searchableText);
		const hasOceanView = hasFeatureLabel(item, "오션뷰");

		const okPet = !selectedPetOnly || hasPetAllow;
		const okParking = !selectedParkingOnly || hasParking;
		const okCityGas = !selectedCityGasOnly || hasCityGas;
		const okDuplex = !selectedDuplexOnly || hasDuplex;
		const okVeranda = !selectedVerandaOnly || hasVeranda;
		const okElevator = !selectedElevatorOnly || hasElevator;
		const okFullOption = !selectedFullOptionOnly || hasFullOption;
		const okImmediateMoveIn = !selectedImmediateMoveInOnly || hasImmediateMoveIn;
		const okNegotiableMoveIn = !selectedNegotiableMoveInOnly || hasNegotiableMoveIn;
		const okOceanView = !selectedOceanViewOnly || hasOceanView;
		const okBrokerListingScope = matchesBrokerListingMapScope(item);
		return okKeyword && okDeal && okPrice && okArea && okApprovalYear && okLandType && okLandUseZone && okType && okDealMethod && okRoom && okBath && okFloor && okDirection && okFeature && okPet && okParking && okCityGas && okDuplex && okVeranda && okElevator && okFullOption && okImmediateMoveIn && okNegotiableMoveIn && okOceanView && okBrokerListingScope;
	});

	state.selectedMarkerId = null;
	state.selectedClusterKey = null;
	state.selectionMode = null;
	clearListLock();

	const viewportItems = getViewportFilteredItems(state.filtered);
	const shouldHideInitialList = state.initialRandomListActive !== false && isInitialAllListMode();
	const sortedViewportItems = sortItems(viewportItems);
	resetLeftListPagination(sortedViewportItems);
	scrollListToTop();
	if (shouldHideInitialList) {
		propertyList.innerHTML = "";
	} else if (sortedViewportItems.length) {
		if (!state.leftListItems.length) propertyList.innerHTML = "";
		loadMoreLeftListItems({ sourceItems: sortedViewportItems });
	} else {
		renderList([]);
	}
	scrollListToTop();
	preventMapViewportChange = true;
	renderMarkers(state.filtered, { preserveViewport: true });
	preventMapViewportChange = false;
	updateMapEmptyState(sortedViewportItems);

	if (shouldHideInitialList) {
		setResultInfo(`총 ${state.filtered.length}건`);
		setListInfo(`총 ${state.filtered.length}개 매물`);
	} else {
		setPagedListInfo(sortedViewportItems.length, state.leftListItems.length);
	}
	syncLeftAllButtonToMapFilters();

	if (!shouldHideInitialList && !sortedViewportItems.length) {
		closeDetailPanel({ preserveMapFilterDropdowns: true });
		return;
	}
}

function getSortDateValue(item)
{
	const value = item?.date ? new Date(item.date).getTime() : NaN;
	return Number.isFinite(value) ? value : 0;
}

function sortItems(items)
{
	const list = Array.isArray(items) ? [...items] : [];

	if (currentSort === "popular") {
		list.sort((a, b) => {
			const popularDiff = getAgentListPopularityValue(b) - getAgentListPopularityValue(a);
			if (popularDiff !== 0) return popularDiff;
			return getSortDateValue(b) - getSortDateValue(a);
		});
		return list;
	}

	if (currentSort === "price-desc") {
		list.sort((a, b) => {
			const priceDiff = (parsePriceTextToWon(b?.price || "") ?? -1) - (parsePriceTextToWon(a?.price || "") ?? -1);
			if (priceDiff !== 0) return priceDiff;
			return getSortDateValue(b) - getSortDateValue(a);
		});
		return list;
	}

	if (currentSort === "price-asc") {
		list.sort((a, b) => {
			const aPrice = parsePriceTextToWon(a?.price || "");
			const bPrice = parsePriceTextToWon(b?.price || "");
			if (aPrice == null && bPrice == null) return getSortDateValue(b) - getSortDateValue(a);
			if (aPrice == null) return 1;
			if (bPrice == null) return -1;
			const priceDiff = aPrice - bPrice;
			if (priceDiff !== 0) return priceDiff;
			return getSortDateValue(b) - getSortDateValue(a);
		});
		return list;
	}

	if (currentSort === "area-desc" || currentSort === "area-asc") {
		const direction = currentSort === "area-desc" ? "desc" : "asc";
		list.sort((a, b) => compareAgentListNumbers(getAgentListAreaValue(a), getAgentListAreaValue(b), direction) || getSortDateValue(b) - getSortDateValue(a));
		return list;
	}

	list.sort((a, b) => getSortDateValue(b) - getSortDateValue(a));
	return list;
}

function getAgentListNumericValue(value)
{
	if (typeof value === "string") {
		const match = value.replace(/,/g, "").match(/-?\d+(?:\.\d+)?/);
		if (!match) return null;
		const parsedValue = Number(match[0]);
		return Number.isFinite(parsedValue) ? parsedValue : null;
	}
	const numberValue = Number(value);
	return Number.isFinite(numberValue) ? numberValue : null;
}

function getAgentListPriceValue(item)
{
	return getAgentListNumericValue(parsePriceTextToWon(item?.price || ""));
}

function getAgentListAreaValue(item)
{
	const areaValue = getPrimaryAreaForUnitPrice(item?.area || "", item?.type || "");
	const primaryValue = getAgentListNumericValue(areaValue);
	if (primaryValue != null) return primaryValue;

	const payload = item && item.payload && typeof item.payload === "object" ? item.payload : {};
	const areas = payload.areas && typeof payload.areas === "object" ? payload.areas : {};
	const directCandidates = [
		item?.area_m2,
		item?.exclusive_m2,
		item?.supply_m2,
		item?.land_m2,
		areas.exclusive_m2,
		areas.supply_m2,
		areas.land_m2,
		areas.total_m2,
		areas.building_m2
	];

	for (const candidate of directCandidates) {
		const numericValue = getAgentListNumericValue(candidate);
		if (numericValue != null) return numericValue;
	}

	const rows = getMapListingAreaInfoRows(item);
	for (const row of rows) {
		const numericValue = getAgentListNumericValue(row?.value);
		if (numericValue != null) return numericValue;
	}

	return null;
}

function getAgentListPopularityValue(item)
{
	const key = getItemViewKey(item);
	const viewKey = getViewCountKey(key);
	const favoriteValue = Number(favoriteCountMap[viewKey] ?? getDetailFavoriteCount(item) ?? 0);
	const favoriteCount = Number.isFinite(favoriteValue) ? favoriteValue : 0;
	return favoriteCount;
}

function compareAgentListNumbers(aValue, bValue, direction = "asc")
{
	if (aValue == null && bValue == null) return 0;
	if (aValue == null) return 1;
	if (bValue == null) return -1;
	const diff = direction === "desc" ? bValue - aValue : aValue - bValue;
	return diff || 0;
}

function getAgentListTieBreak(a, b)
{
	return getSortDateValue(b) - getSortDateValue(a);
}

function sortAgentListItems(items)
{
	const list = Array.isArray(items) ? [...items] : [];
	const mode = state.agentListSort || "popular";

	if (mode === "priceAsc" || mode === "priceDesc") {
		const direction = mode === "priceDesc" ? "desc" : "asc";
		list.sort((a, b) => compareAgentListNumbers(getAgentListPriceValue(a), getAgentListPriceValue(b), direction) || getAgentListTieBreak(a, b));
		return list;
	}

	if (mode === "areaAsc" || mode === "areaDesc") {
		const direction = mode === "areaDesc" ? "desc" : "asc";
		list.sort((a, b) => compareAgentListNumbers(getAgentListAreaValue(a), getAgentListAreaValue(b), direction) || getAgentListTieBreak(a, b));
		return list;
	}

	if (mode === "latest") {
		list.sort((a, b) => getAgentListTieBreak(a, b));
		return list;
	}

	list.sort((a, b) => {
		const popularDiff = getAgentListPopularityValue(b) - getAgentListPopularityValue(a);
		return popularDiff || getAgentListTieBreak(a, b);
	});
	return list;
}

function syncSortLabelUI()
{
	if (!sortLabel) return;

	sortLabel.classList.remove("sort-latest", "sort-price-desc", "sort-price-asc");

	if (currentSort === "popular") {
		sortLabel.textContent = "인기순";
		sortLabel.title = "인기순";
		return;
	}

	if (currentSort === "area-desc") {
		sortLabel.textContent = "면적순";
		sortLabel.title = "면적 넓은 순";
		return;
	}

	if (currentSort === "area-asc") {
		sortLabel.textContent = "면적순";
		sortLabel.title = "면적 좁은 순";
		return;
	}

	if (currentSort === "latest") {
		sortLabel.textContent = "최신순";
		sortLabel.title = "최신 등록순";
		sortLabel.classList.add("sort-latest");
		return;
	}

	sortLabel.textContent = "가격순";

	if (currentSort === "price-desc") {
		sortLabel.title = "가격 높은 순";
		sortLabel.classList.add("sort-price-desc");
	} else {
		sortLabel.title = "가격 낮은 순";
		sortLabel.classList.add("sort-price-asc");
	}
}


	function setAddressSearchStatus(message, isError = false)
	{
		if (!subAddressSearchStatus) return;
		clearTimeout(addressSearchStatusTimer);
		if (typeof message === "string") {
			const suppressAddressMoveMessage =
				message.includes(" 위치로 이동했습니다.") ||
				message.includes("위치로 이동했습니다.");
			if (suppressAddressMoveMessage) {
				message = "";
			}
		}
		if (!message) {
			subAddressSearchStatus.textContent = "";
			subAddressSearchStatus.classList.remove("show", "error");
			return;
		}
		subAddressSearchStatus.textContent = message;
		subAddressSearchStatus.classList.toggle("error", !!isError);
		subAddressSearchStatus.classList.add("show");
		addressSearchStatusTimer = setTimeout(() => {
			subAddressSearchStatus.classList.remove("show", "error");
		}, isError ? 2600 : 1800);
	}

function focusMapByAddress(lat, lng, label = "", options = {})
{
	const opts = options || {};
	const requestedMapLevel = Number(opts.mapLevel);
	const targetMapLevel = Number.isFinite(requestedMapLevel) ? requestedMapLevel : 4;
	if (!state.map || !window.kakao || !kakao.maps) return;
	if (Object.prototype.hasOwnProperty.call(opts, "leftListDetailMode")) {
		state.leftListDetailMode = opts.leftListDetailMode || "";
	}
	const latNum = Number(lat);
	const lngNum = Number(lng);
	const isStatusSuppressed = !!opts.silent || !!shouldSuppressAddressSearchStatus;
	if (!Number.isFinite(latNum) || !Number.isFinite(lngNum)) {
		if (!isStatusSuppressed) {
			setAddressSearchStatus("검색 위치 좌표를 확인하지 못했습니다.", true);
		} else {
			setAddressSearchStatus("");
		}
		return;
	}
	const latLng = new kakao.maps.LatLng(latNum, lngNum);
	const viewportSeq = ++mapViewportIntentSeq;
	state.suppressClusterMapMove = false;
	const applySearchCenter = () => {
		if (viewportSeq !== mapViewportIntentSeq || !state.map) return;
		if (typeof state.map.relayout === "function") state.map.relayout();
		state.map.setLevel(targetMapLevel, { animate: false, __allowClusterRestore: true });
		state.map.setCenter(latLng, { __allowClusterRestore: true });
	};
	applySearchCenter();
	if (typeof requestAnimationFrame === "function") requestAnimationFrame(applySearchCenter);
	setTimeout(applySearchCenter, 80);
	setTimeout(applySearchCenter, 240);
	setTimeout(applySearchCenter, 520);
	const shouldShowAddressMarker = opts.showAddressMarker !== false;
	if (shouldShowAddressMarker) {
		if (!addressSearchMarker) {
			addressSearchMarker = new kakao.maps.CustomOverlay({
				map: state.map,
				position: latLng,
				content: createRoadviewIconMarkerElement("address-search-roadview-marker"),
				xAnchor: 0.5,
				yAnchor: 1.32,
				zIndex: 240
			});
		} else {
			addressSearchMarker.setPosition(latLng);
			addressSearchMarker.setMap(state.map);
		}
	} else if (addressSearchMarker) {
		addressSearchMarker.setMap(null);
	}
		setAddressSearchStatus("");
		return { restoreIfCurrent: applySearchCenter };
	}

function buildSubAddressSearchQueries(query)
{
	const value = String(query || "").trim().replace(/\s+/g, " ");
	if (!value) return [];
	const values = [value];
	const withoutCommaDetail = value.replace(/\s*,.*$/, "").trim();
	const withoutParenDetail = value.replace(/\s*\([^)]*\)\s*$/, "").trim();
	const withoutFloorDetail = value.replace(/\s*,?\s*\d+\s*(?:\uCE35|\uD638)\b.*$/, "").trim();
	const roadMatch = value.match(/^(.+?(?:\uB300\uB85C|\uB85C|\uAE38)(?:\d+\uBC88\uAE38)?\s*\d+(?:-\d+)?)/);
	if (withoutCommaDetail) values.push(withoutCommaDetail);
	if (withoutParenDetail) values.push(withoutParenDetail);
	if (withoutFloorDetail) values.push(withoutFloorDetail);
	if (roadMatch && roadMatch[1]) values.push(roadMatch[1].trim());
	const queries = [];
	values.forEach((item) => {
		if (!item) return;
		if (/\uC81C\uC8FC|\uC11C\uADC0\uD3EC/.test(item)) {
			queries.push(item);
		} else {
			queries.push(`\uC81C\uC8FC\uD2B9\uBCC4\uC790\uCE58\uB3C4 ${item}`, `\uC81C\uC8FC ${item}`, item);
		}
	});
	return [...new Set(queries)];
}

async function searchAddressFromOwnDatabase(query)
{
  const normalizedQuery = String(query || "").trim();
  if (!normalizedQuery) return [];

  const client = getMapListingsSupabaseClient();
  if (!client || typeof client.rpc !== "function") {
    console.warn("[realjeju address] Supabase client unavailable");
    return [];
  }

  const { data, error } = await client.rpc("search_jeju_addresses", {
    p_query: normalizedQuery,
    p_limit: 10
  });

  if (error) {
    console.warn("[realjeju address] own DB search failed", error);
    return [];
  }

  return (Array.isArray(data) ? data : []).map((row) => {
    const lng = Number(row && row.lng);
    const lat = Number(row && row.lat);
    const roadAddress = String((row && row.road_address) || "").trim();
    const jibunAddress = String((row && row.jibun_address) || "").trim();
    return {
      x: Number.isFinite(lng) ? lng : null,
      y: Number.isFinite(lat) ? lat : null,
      address_name: jibunAddress || roadAddress,
      road_address_name: roadAddress,
      jibun_address_name: jibunAddress,
      place_name: String((row && row.building_name) || "").trim(),
      pnu: String((row && row.pnu) || "").trim(),
      building_management_no: String((row && row.building_management_no) || "").trim()
    };
  }).filter((item) => Number.isFinite(Number(item.x)) && Number.isFinite(Number(item.y)));
}

function searchAddressByGeocoder(geocoder, query)
{
	return new Promise(resolve => {
		if (!geocoder || typeof geocoder.addressSearch !== "function") {
			resolve(null);
			return;
		}
		geocoder.addressSearch(query, (result, status) => {
			if (status === kakao.maps.services.Status.OK && Array.isArray(result) && result.length) {
				resolve(result[0]);
				return;
			}
			resolve(null);
		});
	});
}

function searchAddressByKeyword(places, query)
{
	return new Promise(resolve => {
		if (!places || typeof places.keywordSearch !== "function") {
			resolve(null);
			return;
		}
		places.keywordSearch(query, (result, status) => {
			if (status === kakao.maps.services.Status.OK && Array.isArray(result) && result.length) {
				resolve(result[0]);
				return;
			}
			resolve(null);
		});
	});
}

function isParcelAddressSearchMode()
{
  return typeof getCurrentRealjejuGlobalCategoryKey === "function"
    && getCurrentRealjejuGlobalCategoryKey() === "parcel";
}

async function applySubAddressSearchResult(found, query, parcelMode)
{
  if (!found || !isParcelBoundaryJejuCoordinate(found.y, found.x)) {
    return { matched: false, completed: false };
  }

  const label = found.address_name || found.road_address_name || found.place_name || query;
  const currentSearchCategory = typeof getCurrentRealjejuGlobalCategoryKey === "function"
    ? getCurrentRealjejuGlobalCategoryKey()
    : String(document.body?.dataset?.globalCategory || "realestate");
  const realestateMode = currentSearchCategory === "realestate";
  if (!parcelMode && !realestateMode) {
    if (typeof clearParcelBoundaryOverlays === "function") clearParcelBoundaryOverlays();
    focusMapByAddress(found.y, found.x, label, {
      mapLevel: 2,
      showAddressMarker: true
    });
    setAddressSearchStatus("");
    return { matched: true, completed: true };
  }

  if (realestateMode) {
    selectedPropertyRegionCountKey = "";
    selectedPropertyRegionBoundaryFeature = null;
    selectedAdminBoundaryFeature = null;
    adminBoundarySelectedPoint = null;
    clearAdminBoundaryOverlay();
  }
  const searchViewport = focusMapByAddress(found.y, found.x, label, {
    mapLevel: 2,
    showAddressMarker: realestateMode
  });
  if (realestateMode) {
    clearParcelBoundaryRenderState();
    searchViewport?.restoreIfCurrent();
    return { matched: true, completed: true };
  }
  const parcelOpened = parcelMode
    ? await showParcelBoundaryForSearchLocation(found.y, found.x, {
        openLandInfoPanel: true,
        fromAddressSearch: true
      })
    : false;
  searchViewport?.restoreIfCurrent();
  return { matched: true, completed: parcelOpened };
}

async function handleSubAddressSearch()
{
  const query = String(subAddressSearchInput?.value || "").trim();
  if (!query) {
    setAddressSearchStatus("검색할 주소지를 입력하세요.", true);
    if (subAddressSearchInput) subAddressSearchInput.focus();
    return;
  }

  const parcelMode = isParcelAddressSearchMode();
  if (parcelMode) {
    state.leftListSeq = Number(state.leftListSeq || 0) + 1;
    state.leftListDetailMode = "parcel-land-info";
    state.leftListTitle = "부동산 정보";
    state.agentListFilter = null;
    state.agentListCard = null;
    state.leftListRemoteAgent = null;
    state.leftListRemoteRegion = null;
    state.leftListSourceIds = [];
    if (propertyList) {
      if (!state.isListOpen && typeof openSidebarList === "function") openSidebarList();
      propertyList.innerHTML = '<article class="parcel-land-info-panel"><div class="parcel-land-info-status">토지 정보를 불러오는 중입니다.</div></article>';
      propertyList.scrollTop = 0;
    }
    if (typeof syncSidebarListTitle === "function") syncSidebarListTitle();
    if (typeof syncSidebarListHeaderActions === "function") syncSidebarListHeaderActions();
  }

  setAddressSearchStatus("주소를 검색하는 중입니다.");
  const ownDatabaseResults = await searchAddressFromOwnDatabase(query);
  for (const found of ownDatabaseResults) {
    const result = await applySubAddressSearchResult(found, query, parcelMode);
    if (result.completed) return;
  }

  if (!window.kakao || !kakao.maps || !kakao.maps.services) {
    setAddressSearchStatus("검색 결과가 없습니다.", true);
    return;
  }

  const geocoder = new kakao.maps.services.Geocoder();
  const places = kakao.maps.services.Places ? new kakao.maps.services.Places() : null;
  const queries = buildSubAddressSearchQueries(query);

  for (const q of queries) {
    const found = await searchAddressByGeocoder(geocoder, q);
    const result = await applySubAddressSearchResult(found, query, parcelMode);
    if (result.matched) {
      if (!result.completed) setAddressSearchStatus("해당 주소의 필지 정보를 불러오지 못했습니다.", true);
      return;
    }
  }

  for (const q of queries) {
    const found = await searchAddressByKeyword(places, q);
    const result = await applySubAddressSearchResult(found, query, parcelMode);
    if (result.matched) {
      if (!result.completed) setAddressSearchStatus("해당 주소의 필지 정보를 불러오지 못했습니다.", true);
      return;
    }
  }

  setAddressSearchStatus("검색 결과가 없습니다.", true);
}

