	if (detailSimilarGrid) {
		detailSimilarGrid.addEventListener("click", async (e) => {
			const favoriteBtn = e.target.closest(".detail-similar-favorite-btn[data-favorite-id]");
			if (favoriteBtn) {
				e.preventDefault();
				e.stopPropagation();
				if (favoriteBtn.disabled) return;
				favoriteBtn.disabled = true;
				const favoriteId = normalizeItemId(favoriteBtn.dataset.favoriteId);
				const favoriteItem = detailSimilarItemById.get(favoriteId)
					|| (state.all || []).find(candidate => normalizeItemId(candidate.id) === favoriteId);
				const active = await setFavoriteListing(favoriteId, !isFavoriteListing(favoriteId), favoriteItem);
				favoriteBtn.classList.toggle("active", active);
				favoriteBtn.setAttribute("aria-label", active ? "관심 부동산 해제" : "관심 부동산 추가");
				favoriteBtn.setAttribute("aria-pressed", active ? "true" : "false");
				favoriteBtn.disabled = false;
				return;
			}

			const btn = e.target.closest("[data-similar-id]");
			if (!btn) return;
			e.preventDefault();
			e.stopPropagation();

			const id = normalizeItemId(btn.dataset.similarId);
			// 4.928: 비슷한 매물은 현재 지도 일부인 state.all에 없을 수 있습니다.
			// 서버에서 이미 받은 전용 캐시를 바로 사용해 클릭이 무응답ㆍ지연되지 않게 합니다.
			const item = detailSimilarItemById.get(id)
				|| (state.all || []).find(candidate => normalizeItemId(candidate.id) === id);
			if (!item) return;

			const movePromise = moveMapToProperty(item).catch((error) => console.warn("비슷한 매물 지도 이동 실패:", error));
			await openDetailPanel(item, { syncUrl: true, forceOpen: true });
			await movePromise;
			if (detailScroll) detailScroll.scrollTop = 0;
		});
	}

