function getDetailShareUrl()
{
	if (activeDetailSharePayload && activeDetailSharePayload.url) {
		return String(activeDetailSharePayload.url);
	}
	if (currentDetailItem && currentDetailItem.id != null) {
		return getDetailUrlById(currentDetailItem.id).href;
	}
	if (currentDetailItem && currentDetailItem.link && currentDetailItem.link !== "#") {
		try {
			return new URL(currentDetailItem.link, location.href).href;
		} catch (err) {
			return currentDetailItem.link;
		}
	}
	return location.href;
}

function getDetailShareTitle()
{
	if (activeDetailSharePayload && activeDetailSharePayload.title) {
		return String(activeDetailSharePayload.title);
	}
	return currentDetailItem && currentDetailItem.title
	? currentDetailItem.title
	: "제주 프리미엄 부동산";
}

function getDetailShareText()
{
	if (activeDetailSharePayload && activeDetailSharePayload.text) {
		return String(activeDetailSharePayload.text);
	}
	const parts = [];
	const title = getDetailShareTitle();
	const deal = currentDetailItem?.dealType || currentDetailItem?.deal || "";
	const price = currentDetailItem?.priceText || currentDetailItem?.price || "";
	const address = currentDetailItem?.address || currentDetailItem?.roadAddress || "";

	parts.push(`[REALJEJU.APP] ${title}`);
	if (deal || price) {
		parts.push([deal, price].filter(Boolean).join(" "));
	}
	if (address) {
		parts.push(address);
	}
	parts.push(getDetailShareUrl());
	return parts.filter(Boolean).join("\n");
}

function getDetailShareDescription()
{
	if (activeDetailSharePayload && activeDetailSharePayload.description) {
		return String(activeDetailSharePayload.description);
	}
	const deal = currentDetailItem?.dealType || currentDetailItem?.deal || "";
	const price = currentDetailItem?.priceText || currentDetailItem?.price || "";
	const address = currentDetailItem?.address || currentDetailItem?.roadAddress || "";
	return [[deal, price].filter(Boolean).join(" "), address].filter(Boolean).join(" · ") || "REALJEJU.APP 매물 정보";
}

function getDetailShareImageUrl()
{
	if (activeDetailSharePayload && activeDetailSharePayload.imageUrl) {
		return String(activeDetailSharePayload.imageUrl);
	}
	const image = Array.isArray(currentDetailItem?.images) && currentDetailItem.images.length
		? currentDetailItem.images[0]
		: currentDetailItem?.image;
	if (!image) return "";
	try {
		const url = new URL(image, location.href);
		return /^https?:$/i.test(url.protocol) ? url.href : "";
	} catch (err) {
		return "";
	}
}

function getDetailShareButtonTitle()
{
	if (activeDetailSharePayload && activeDetailSharePayload.buttonTitle) {
		return String(activeDetailSharePayload.buttonTitle);
	}
	return "매물 보기";
}

function ensureKakaoShareReady()
{
	if (!window.Kakao) return false;
	try {
		if (typeof window.Kakao.isInitialized === "function" && !window.Kakao.isInitialized()) {
			window.Kakao.init(REALJEJU_KAKAO_JS_KEY);
		}
		return !!(window.Kakao.Share && typeof window.Kakao.Share.sendDefault === "function");
	} catch (err) {
		console.error("카카오 공유 초기화 실패:", err);
		return false;
	}
}

async function copyTextWithFallback(textToCopy)
{
	const text = String(textToCopy || "");
	let clipboardError = null;
	try {
		if (navigator.clipboard && window.isSecureContext) {
			await navigator.clipboard.writeText(text);
			return true;
		}
	} catch (err) {
		clipboardError = err;
	}

	let textarea = null;
	try {
		textarea = document.createElement("textarea");
		textarea.value = text;
		textarea.setAttribute("readonly", "");
		textarea.style.position = "fixed";
		textarea.style.top = "-9999px";
		textarea.style.left = "-9999px";
		textarea.style.opacity = "0";
		document.body.appendChild(textarea);
		textarea.focus();
		textarea.select();
		textarea.setSelectionRange(0, textarea.value.length);

		const ok = document.execCommand("copy");
		if (textarea.parentNode) textarea.parentNode.removeChild(textarea);
		return !!ok;
	} catch (err) {
		if (textarea && textarea.parentNode) textarea.parentNode.removeChild(textarea);
		console.warn("링크 복사 실패:", clipboardError || err, err);
		return false;
	}
}

function showShareCopiedFeedback(success)
{
	if (!detailShareFeedback) return;
	detailShareFeedback.textContent = success ? "복사됨" : "실패";
	setTimeout(() => {
		detailShareFeedback.textContent = "";
	}, 1200);
}

window.shareDetailCopy = async function (event) {
	if (event) {
		event.preventDefault();
		event.stopPropagation();
	}
	const ok = await copyTextWithFallback(getDetailShareUrl());
	showShareCopiedFeedback(ok);
};

window.shareDetailKakao = async function (event) {
	if (event) {
		event.preventDefault();
		event.stopPropagation();
	}

	const shareUrl = getDetailShareUrl();
	try {
		if (!window.Kakao && typeof window.realjejuPreloadKakaoShare === "function") {
			await window.realjejuPreloadKakaoShare();
		}
		if (/^https?:\/\//i.test(shareUrl) && ensureKakaoShareReady()) {
			const title = getDetailShareTitle();
			const description = getDetailShareDescription();
			const imageUrl = getDetailShareImageUrl();
			const buttonTitle = getDetailShareButtonTitle();
			const link = {
				mobileWebUrl: shareUrl,
				webUrl: shareUrl
			};

			window.Kakao.Share.sendDefault({
				objectType: "feed",
				content: {
					title,
					description,
					imageUrl: imageUrl || "https://제주도부동산.닷컴/img/landingpage_1.jpg",
					link
				},
				buttons: [
					{
						title: buttonTitle,
						link
					}
				]
			});
			if (typeof closeShareMenu === "function") closeShareMenu();
			return;
		}

		if (navigator.share) {
			await navigator.share({
				title: getDetailShareTitle(),
				text: getDetailShareDescription(),
				url: shareUrl
			});
			if (typeof closeShareMenu === "function") closeShareMenu();
			return;
		}
	} catch (err) {
		console.error("카카오톡 공유 실패:", err);
	}

	const ok = await copyTextWithFallback(shareUrl);
	showShareCopiedFeedback(ok);
	if (typeof closeShareMenu === "function") closeShareMenu();
};

window.shareDetailNative = async function (event) {
	if (event) {
		event.preventDefault();
		event.stopPropagation();
	}
	try {
		if (navigator.share) {
			await navigator.share({
				title: getDetailShareTitle(),
				text: getDetailShareText(),
				url: getDetailShareUrl()
			});
			if (typeof closeShareMenu === "function") closeShareMenu();
			return;
		}
	} catch (err) {
		console.error("공유 실패:", err);
	}
	const ok = await copyTextWithFallback(getDetailShareText());
	showShareCopiedFeedback(ok);
	if (typeof closeShareMenu === "function") closeShareMenu();
};

window.shareDetailSms = function (event) {
	if (event) {
		event.preventDefault();
		event.stopPropagation();
	}
	const body = encodeURIComponent(getDetailShareText());
	const smsUrl = /iPhone|iPad|iPod/.test(navigator.userAgent) ? `sms:&body=${body}` : `sms:?body=${body}`;
	if (typeof closeShareMenu === "function") closeShareMenu();
	location.href = smsUrl;
};

// The current-location control must select the administrative region from the
// device GPS coordinate itself. Waiting for a later map-idle event would make the
// user place the GPS point at the screen center before the region label updates.
function setMapRegionFromCurrentLocation(lat, lng)
{
	const requestSeq = ++mapCenterRegionRequestSeq;
	resolveMapCenterRegionMeta(lat, lng).then((meta) => {
		if (requestSeq !== mapCenterRegionRequestSeq || !meta) return;
		mapRegionFilterState.mode = "list";
		setMapCenterRegionLabel(meta);
	});
}

function moveMapToCurrentLocation()
{
	if (!state.map || !window.kakao || !kakao.maps) return;
	if (!navigator.geolocation) {
		alert("이 브라우저에서는 현위치를 사용할 수 없습니다.");
		return;
	}

	navigator.geolocation.getCurrentPosition(
	(position) => {
		if (!state.map) return;

		const lat = Number(position.coords && position.coords.latitude);
		const lng = Number(position.coords && position.coords.longitude);

		if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
			alert("현위치를 가져오지 못했습니다.");
			return;
		}

		const currentLatLng = new kakao.maps.LatLng(lat, lng);
		setMapRegionFromCurrentLocation(lat, lng);
		state.map.setCenter(currentLatLng);
		state.map.setLevel(GEOLOCATION_MAP_LEVEL, { animate: { duration: 300 } });
	},
	() => {
		alert("현위치를 가져오지 못했습니다. 브라우저 위치 권한을 확인해 주세요.");
	},
	{
		enableHighAccuracy: false,
		timeout: 8000,
		maximumAge: 0
	}
	);
}

function initCustomZoomButtons()
{
	const currentLocationBtn = document.getElementById("currentLocationBtn");
	if (!currentLocationBtn) return;

	currentLocationBtn.addEventListener("click", function (e) {
		e.preventDefault();
		e.stopPropagation();
		moveMapToCurrentLocation();
	});
}

function shouldLoadInitialPropertyMapDataForCurrentRoute()
{
	const pathname = String(
		window.realjejuInitialNormalizedRoutePath
		|| window.location.pathname
		|| "/"
	).replace(/\/{2,}/g, "/").replace(/\/+$/, "") || "/";
	return /^\/properties(?:\/|$)/i.test(pathname)
		|| /^\/admin\/properties(?:\/|$)/i.test(pathname);
}

function shouldPrefetchLandingPropertyViewportForCurrentRoute()
{
	const pathname = String(
		window.realjejuInitialNormalizedRoutePath
		|| window.location.pathname
		|| "/"
	).replace(/\/{2,}/g, "/").replace(/\/+$/, "") || "/";
	return pathname === "/";
}

let initialMapDataPromise = null;
let initialMapDataScheduled = false;

async function bootstrap()
{
	if (!window.kakao || !window.kakao.maps) {
		handleBootstrapError(new Error("카카오맵 SDK가 로드되지 않았습니다. appkey를 확인하세요."));
		return;
	}

	updateSidebarWidth();
	initMap();
	applyMapTypeMode("roadmap");
	observeSatelliteLabelServiceChanges();
	await applyInitialMapCenter();

	const featuresLoaded = typeof window.realjejuPreloadAppFeatures === "function"
		? await window.realjejuPreloadAppFeatures()
		: false;
	if (!featuresLoaded || typeof window.realjejuFinishAppBootstrap !== "function") {
		throw new Error("앱 기능 모듈을 불러오지 못했습니다.");
	}
	await window.realjejuFinishAppBootstrap();

	await signalRealjejuAppShellReady();
	if (typeof window.realjejuStartInitialMapData === "function") {
		window.realjejuStartInitialMapData();
	}

	
	// runtime-tail은 계속 즉시 로드하되, 더 이상 첫 지도 데이터 시작을 가로막지 않는다.
	if (typeof window.realjejuScheduleRuntimeTailAfterFirstPaint === "function") {
		window.realjejuScheduleRuntimeTailAfterFirstPaint();
	} else if (typeof window.realjejuPreloadRuntimeTail === "function") {
		void window.realjejuPreloadRuntimeTail();
	}
}

window.realjejuFinishAppBootstrap = async function ()
{
	// 4.924부터는 이전 버전의 전체 매물 IndexedDB 배열을 첫 화면에 적용하지 않는다.
	const initialPropertyCachePromise = Promise.resolve(false);
	if (isEvChargerServiceRouteActive()) {
		await activateEvChargerServiceMap();
	}
	initCustomZoomButtons();
	// 6.140: the 298KB event binder no longer blocks the first map/data paint.
	// Capture-phase interaction initializes it before the following click/input event, and idle is the fallback.
	const initializeAppEvents = () => {
		const rootElement = document.documentElement;
		if (rootElement.dataset.realjejuAppEventsInitialized === "true") return;
		rootElement.dataset.realjejuAppEventsInitialized = "true";
		try {
			initEvents();
		} catch (error) {
			delete rootElement.dataset.realjejuAppEventsInitialized;
			throw error;
		}
	};
	const initializeAppEventsSafely = () => {
		try {
			initializeAppEvents();
		} catch (error) {
			console.error("[realjeju] event initialization failed", error);
		}
	};
	document.addEventListener("pointerdown", initializeAppEventsSafely, { capture: true, once: true });
	document.addEventListener("keydown", initializeAppEventsSafely, { capture: true, once: true });
	document.addEventListener("focusin", initializeAppEventsSafely, { capture: true, once: true });
	const queueEventInitialization = () => {
		if (typeof window.requestIdleCallback === "function") {
			window.requestIdleCallback(initializeAppEventsSafely, { timeout: 350 });
		} else {
			window.setTimeout(initializeAppEventsSafely, 0);
		}
	};
	if (document.visibilityState === "hidden" || typeof window.requestAnimationFrame !== "function") {
		window.setTimeout(initializeAppEventsSafely, 0);
	} else {
		window.requestAnimationFrame(queueEventInitialization);
	}
	selectedDeal = selectedDeal instanceof Set ? selectedDeal : new Set();
	selectedType = selectedType instanceof Set ? selectedType : new Set();
	ensureTypeFilterHasSelection();
	syncFeatureButtons();
	if (shouldPrefetchLandingPropertyViewportForCurrentRoute()) {
		scheduleLandingPropertyViewportPrefetch();
	}
	await initialPropertyCachePromise;
};

window.realjejuStartInitialMapData = function ()
{
	scheduleInitialMapDataAfterFirstPaint();
};

async function signalRealjejuAppShellReady()
{
	if (window.realjejuAppShellReady === true) return;
	window.realjejuAppShellReady = true;
	if (window.realjejuRouter && typeof window.realjejuRouter.onAppReady === "function") {
		await window.realjejuRouter.onAppReady();
	}
}

function scheduleInitialMapDataAfterFirstPaint()
{
	if (initialMapDataScheduled) return;
	initialMapDataScheduled = true;

	const run = () => {
		loadInitialMapData().catch((error) => {
			console.error("초기 지도 데이터 지연 처리 실패:", error);
		});
	};
	const queueAfterPaint = () => {
		if (typeof window.requestIdleCallback === "function") {
			window.requestIdleCallback(run, { timeout: 250 });
		} else {
			window.setTimeout(run, 0);
		}
	};

	if (document.visibilityState === "hidden" || typeof window.requestAnimationFrame !== "function") {
		queueAfterPaint();
		return;
	}

	window.requestAnimationFrame(() => {
		window.requestAnimationFrame(queueAfterPaint);
	});
}

function loadInitialMapData()
{
	if (initialMapDataPromise) return initialMapDataPromise;

	initialMapDataPromise = (async () => {
		const shouldLoadPropertyMapData = shouldLoadInitialPropertyMapDataForCurrentRoute();
		const shouldLoadLandingRecommendations = shouldPrefetchLandingPropertyViewportForCurrentRoute();

		if (shouldLoadPropertyMapData || shouldLoadLandingRecommendations) {
			loadRecommendData();
		}
		syncFeatureButtons();

		try {
			if (shouldLoadPropertyMapData) await loadProperties();
			syncFeatureButtons();
		} catch (err) {
			console.error("초기 지도 데이터 처리 실패:", err);
			syncFeatureButtons();
		} finally {
			window.realjejuMapDataReady = true;
			if (window.realjejuRouter && typeof window.realjejuRouter.onMapDataReady === "function") {
				await window.realjejuRouter.onMapDataReady();
			} else {
				await openDetailFromUrl({ replaceHistory: true });
			}
		}
	})();

	return initialMapDataPromise;
}

function handleBootstrapError(err)
{
	console.error("앱 초기화 실패:", err);
	window.realjejuMapDataReady = true;
	signalRealjejuAppShellReady()
		.then(() => {
			if (window.realjejuRouter && typeof window.realjejuRouter.onMapDataReady === "function") {
				return window.realjejuRouter.onMapDataReady();
			}
			return null;
		})
		.catch((routeError) => console.warn("초기 경로 복구 실패:", routeError));
}

let realjejuAppStartRequested = false;

function startRealjejuApp()
{
	if (realjejuAppStartRequested) return;
	realjejuAppStartRequested = true;
	scheduleNonBlockingExternalAssets();

	if (!window.kakao || !window.kakao.maps) {
		handleBootstrapError(new Error("카카오맵 SDK가 로드되지 않았습니다. appkey를 확인하세요."));
		return;
	}

	if (typeof window.kakao.maps.load === "function") {
		window.kakao.maps.load(() => {
			bootstrap().catch(handleBootstrapError);
		});
		return;
	}

	bootstrap().catch(handleBootstrapError);
}

/* REALJEJU app start is scheduled by runtime-tail after all ordered modules are ready. */


/* REALJEJU 6.273: 모바일 상단 프로필로 공통 메뉴 서랍을 엽니다. */
;(function bindMobileProfileSideDrawer6237()
{
  const profileTrigger = document.getElementById("detailAuthTrigger");
  const drawerTrigger = document.getElementById("realjejuMobileSideNavTrigger");
  const mobileQuery = window.matchMedia("(max-width: 850px)");
  if (!profileTrigger || !drawerTrigger) return;

  profileTrigger.addEventListener("click", function(event)
  {
    if (!mobileQuery.matches || !document.body) return;
    const category = String(document.body.dataset.globalCategory || "realestate");
    const canOpenDrawer = !document.body.classList.contains("main-landing-page-open")
      && ["realestate", "parcel", "local-business", "ev-charger"].includes(category);
    if (!canOpenDrawer) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    drawerTrigger.click();
  }, true);
})();





/* REALJEJU 6.273: 모바일 단일 메뉴가 열리면 계정 목록의 접근성 상태도 펼침으로 동기화합니다. */
;(function syncMobileFlatAccountMenu6245()
{
  const mobileQuery = window.matchMedia("(max-width: 850px)");
  const menu = document.getElementById("realjejuSideAccountMenu");
  if (!menu || !document.body) return;
  function sync()
  {
    const isVisible = mobileQuery.matches && document.body.classList.contains("realjeju-mobile-side-nav-open");
    menu.setAttribute("aria-hidden", isVisible ? "false" : "true");
  }
  new MutationObserver(sync).observe(document.body, { attributes: true, attributeFilter: ["class"] });
  window.addEventListener("resize", sync, { passive: true });
  sync();
})();

/* REALJEJU 6.648: responsive topbar search button and full-screen recent address search. */
;(function installResponsiveTopbarSearch6281()
{
  const RECENT_SEARCH_KEY = "realjeju.mobileRecentAddressSearch.v1";
  const RECENT_SEARCH_LIMIT = 20;

  function readRecentSearches()
  {
    try {
      const parsed = JSON.parse(localStorage.getItem(RECENT_SEARCH_KEY) || "[]");
      return Array.isArray(parsed)
        ? parsed.map(function(item) {
            return {
              query: String(item && item.query || "").trim(),
              savedAt: Number(item && item.savedAt || 0)
            };
          }).filter(function(item) { return item.query; }).slice(0, RECENT_SEARCH_LIMIT)
        : [];
    } catch (_error) {
      return [];
    }
  }

  function writeRecentSearches(items)
  {
    try {
      localStorage.setItem(RECENT_SEARCH_KEY, JSON.stringify(items.slice(0, RECENT_SEARCH_LIMIT)));
    } catch (_error) {}
  }

  function rememberSearch(query)
  {
    const normalized = String(query || "").trim();
    if (!normalized) return;
    const next = readRecentSearches().filter(function(item) {
      return item.query !== normalized;
    });
    next.unshift({ query: normalized, savedAt: Date.now() });
    writeRecentSearches(next);
  }

  function init()
  {
    const topbarRight = document.getElementById("globalTopbarRight");
    const profileTrigger = document.getElementById("detailAuthTrigger");
    const originalForm = document.getElementById("subAddressSearchForm");
    const originalInput = document.getElementById("subAddressSearchInput");
    if (!topbarRight || !profileTrigger || !originalForm || !originalInput) return;
    if (document.getElementById("mobileTopbarSearchTrigger")) return;

    const searchTrigger = document.createElement("button");
    searchTrigger.type = "button";
    searchTrigger.id = "mobileTopbarSearchTrigger";
    searchTrigger.className = "mobile-topbar-square-button mobile-topbar-search-trigger";
    searchTrigger.setAttribute("aria-label", "주소 검색");
    searchTrigger.setAttribute("aria-haspopup", "dialog");
    searchTrigger.setAttribute("aria-expanded", "false");
    searchTrigger.innerHTML = [
      '<span class="mobile-topbar-search-icon" aria-hidden="true">',
      '<i class="fa-solid fa-magnifying-glass"></i>',
      '</span>'
    ].join("");
    topbarRight.insertBefore(searchTrigger, profileTrigger);

    profileTrigger.setAttribute("aria-label", "메뉴");
    profileTrigger.setAttribute("title", "메뉴");

    const overlay = document.createElement("section");
    overlay.id = "mobileAddressSearchOverlay";
    overlay.className = "mobile-address-search-overlay";
    overlay.setAttribute("role", "dialog");
    overlay.setAttribute("aria-modal", "true");
    overlay.setAttribute("aria-label", "주소 검색");
    overlay.hidden = true;
    overlay.innerHTML = [
      '<div class="mobile-address-search-head">',
      '  <button type="button" class="mobile-address-search-back" data-mobile-address-search-close aria-label="검색 닫기">',
      '    <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M15 5 8 12l7 7"></path></svg>',
      '  </button>',
      '  <form class="mobile-address-search-form" id="mobileAddressSearchForm">',
      '    <input type="search" id="mobileAddressSearchInput" placeholder="건물명, 지번, 도로명 검색" autocomplete="off" enterkeyhint="search" aria-label="주소 검색어">',
      '    <button type="submit" class="mobile-address-search-submit" aria-label="검색">',
      '      <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.2"></circle><path d="m15.5 15.5 4 4"></path></svg>',
      '    </button>',
      '  </form>',
      '</div>',
      '<div class="mobile-address-search-recent-head">',
      '  <strong>최근 검색</strong>',
      '  <button type="button" data-mobile-address-search-clear>전체삭제</button>',
      '</div>',
      '<div class="mobile-address-search-recent-list" id="mobileAddressSearchRecentList"></div>'
    ].join("");
    document.body.appendChild(overlay);

    const overlayForm = overlay.querySelector("#mobileAddressSearchForm");
    const overlayInput = overlay.querySelector("#mobileAddressSearchInput");
    const recentList = overlay.querySelector("#mobileAddressSearchRecentList");
    const clearButton = overlay.querySelector("[data-mobile-address-search-clear]");

    function renderRecentSearches()
    {
      const items = readRecentSearches();
      recentList.replaceChildren();
      clearButton.hidden = items.length === 0;

      if (!items.length) {
        const empty = document.createElement("p");
        empty.className = "mobile-address-search-empty";
        empty.textContent = "최근 검색 내역이 없습니다.";
        recentList.appendChild(empty);
        return;
      }

      items.forEach(function(item) {
        const row = document.createElement("div");
        row.className = "mobile-address-search-recent-row";

        const openButton = document.createElement("button");
        openButton.type = "button";
        openButton.className = "mobile-address-search-recent-open";
        openButton.textContent = item.query;
        openButton.addEventListener("click", function() {
          runSearch(item.query);
        });

        const deleteButton = document.createElement("button");
        deleteButton.type = "button";
        deleteButton.className = "mobile-address-search-recent-delete";
        deleteButton.setAttribute("aria-label", item.query + " 삭제");
        deleteButton.textContent = "×";
        deleteButton.addEventListener("click", function() {
          writeRecentSearches(readRecentSearches().filter(function(saved) {
            return saved.query !== item.query;
          }));
          renderRecentSearches();
        });

        row.append(openButton, deleteButton);
        recentList.appendChild(row);
      });
    }

    function openOverlay()
    {
      overlay.hidden = false;
      document.body.classList.add("mobile-address-search-open");
      searchTrigger.setAttribute("aria-expanded", "true");
      overlayInput.value = "";
      renderRecentSearches();
      requestAnimationFrame(function() {
        overlayInput.focus({ preventScroll: true });
      });
    }

    function closeOverlay()
    {
      overlay.hidden = true;
      document.body.classList.remove("mobile-address-search-open");
      searchTrigger.setAttribute("aria-expanded", "false");
    }

    function runSearch(query)
    {
      const normalized = String(query || "").trim();
      if (!normalized) {
        overlayInput.focus();
        return;
      }
      rememberSearch(normalized);
      originalInput.value = normalized;
      originalInput.dispatchEvent(new Event("input", { bubbles: true }));
      closeOverlay();
      if (typeof originalForm.requestSubmit === "function") {
        originalForm.requestSubmit();
      } else {
        originalForm.dispatchEvent(new Event("submit", { bubbles: true, cancelable: true }));
      }
    }

    originalForm.addEventListener("submit", function() {
      rememberSearch(originalInput.value);
    }, true);

    searchTrigger.addEventListener("click", openOverlay);
    overlayForm.addEventListener("submit", function(event) {
      event.preventDefault();
      runSearch(overlayInput.value);
    });
    overlay.querySelector("[data-mobile-address-search-close]").addEventListener("click", closeOverlay);
    clearButton.addEventListener("click", function() {
      writeRecentSearches([]);
      renderRecentSearches();
    });
    overlay.addEventListener("keydown", function(event) {
      if (event.key === "Escape") closeOverlay();
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, { once: true });
  } else {
    init();
  }
})();

